-- ============================================================
-- Ereb3c (3/7) — DB kontentinin AR tərcüməsi
-- COALESCE + guarded UPDATE — mövcud/əl tərcümələri qorunur (idempotent).
-- Cəmi: 6170 UPDATE (day-notifications İSTİSNA — ayrıca faylda)
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين أن طفلكِ يستيقظ صارخًا، وخصوصًا ليلًا بعد مرور بعض الوقت على نومه. ويُعد الخوف الليلي، المعروف أيضًا باسم رعب النوم، أحد اضطرابات النوم. وتحدث هذه الحالة عادةً خلال مرحلة النوم nREM، بعد نحو 90 دقيقة من نوم الطفل. وتظهر هذه الحالة بدءًا من عمر 2.5-3 سنوات وحتى مرحلة المراهقة، وغالبًا ما يخلط الآباء بينها وبين الكوابيس. إذا كان طفلكِ يعاني نوبات الخوف الليلي، فحافظي على هدوئكِ أولًا. وقد تستمر هذه النوبات من بضع دقائق إلى 20 دقيقة. وبعد أن يهدأ الطفل، سيعود تدريجيًا إلى نومه الطبيعي.') WHERE id = '076a6ccb-3a8e-4030-a673-d4b097978807';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نقدم لكِ نشاطًا ممتعًا لتنمية قدرة طفلكِ على مطابقة الأشياء وحل المشكلات وتطوير حاسة اللمس! 😊 اسم لعبتنا اليوم: ما الذي يوجد داخل الكيس؟. ستحتاجين إلى كيس غير شفاف، وألعاب طفلكِ، وبعض الأغراض المنزلية الصغيرة. ضعي الأغراض داخل الكيس وأغلقيه. من المهم جدًا ألا يكون محتوى الكيس مرئيًا. اطلبي من طفلكِ إدخال يده في الكيس وتحسس أشكال الأشياء الموجودة فيه. اسأليه عمّا يشعر به وما الشيء الذي يظن أنه يلمسه. وإذا واجه صعوبة، يمكنكِ إعطاؤه تلميحات بسيطة حول استخدام ذلك الشيء. وبفضل هذا النشاط، نضمن لكِ، بصفتنا عائلة Anacan، أن تقضي وقتًا ممتعًا وقيّمًا مع طفلكِ! 😊') WHERE id = 'ebefcc6f-edb8-4dbf-a46a-4627d454ebec';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين أن نوبات بكاء طفلكِ وتحفّظه تجاه الغرباء قد بدأت تقل. في هذه المرحلة، تمثل نظارتكِ أو حقيبتكِ في نظره رمزًا لعالم الكبار، وهذا يسعده كثيرًا. تساعده هذه الأنواع من الألعاب على فهم الحياة. فهو يقلّدكِ في الأعمال المنزلية باستخدام ألعابه، ويحب أداء الأدوار. لذلك يمكنكِ إعطاؤه بعض أغراضكِ مؤقتًا. وبما أن تقليد الأعمال المنزلية من أدواره المفضلة، فسيرغب في الطهي والتنظيف مثل الكبار. ويُعد تقليد طفلكِ للكبار ووضع نفسه مكان الآخرين من أهم أشكال اللعب. سيحاول تقمّص دور كل شخص يراقبه تقريبًا، لكنه لا يهتم بعد بهويات مهنية محددة، مثل الجندي أو مضيفة الطيران. وبدلًا من ذلك، يمكنكِ إعطاؤه حقيبتكِ القديمة أو نظارتكِ أو حذاءكِ. تتيح له هذه الأدوار اكتشاف العالم وتساعد خياله على التطور في الاتجاه الصحيح.') WHERE id = 'df956a39-da9f-4532-82ec-209edcca5b25';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يبدأ طفلكِ في هذه الأسابيع باستخدام صيغ الجمع والكلمات بصورة صحيحة. ويمكنه في المتوسط استخدام نحو 300 كلمة مختلفة، وذكر جنسه وعمره واسمه، وسرد الأحداث بالتسلسل. لكن هذه المؤشرات قد تختلف بحسب مدى اهتمامكِ ومشاركتكِ في تنمية لغته؛ إذ تختلف المهارات اللغوية لدى الطفل الذي يقضي معظم وقته أمام التلفاز أو الجهاز اللوحي عن مهارات الطفل الذي يمارس أنشطة لغوية بانتظام. ولتطوير قدرة طفلكِ على الكلام، يمكنكِ الرقص والغناء معه والاستماع إلى الموسيقى. راقبي كيفية إحساسه بالإيقاع، فالإحساس بالإيقاع فطري. أما ترديد كلمات الأغاني وابتكار الموسيقى بنفسه، فسيتعلمهما بمرور الوقت.') WHERE id = '4c057f5d-1f83-4813-a64a-8ad2927711c6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا يكفي تقديم نوع واحد من الطعام لطفلكِ كي ينمو بصحة جيدة. إن تقديم أطعمة متنوعة له يوميًا من المجموعات الغذائية الأربع الأساسية، حتى إن لم يرغب فيها في البداية، سيساعده مع الوقت على الاعتياد عليها واتباع نظام غذائي متوازن. احرصي على انتظام مواعيد الوجبات، وأعطي الأولوية للأطعمة ذات القيمة الغذائية العالية. وبما أن طفلكِ يحتاج إلى تناول كميات صغيرة على فترات متقاربة، فمن الأنسب تقديم حصص صغيرة له في أطباق صغيرة. كما أن الجلوس معه إلى المائدة، ومشاركته أعمال المطبخ، وإعداد المائدة معًا أمور ذات أهمية خاصة. وإذا رفض طفلكِ بعض الأطعمة المهمة، فيمكنكِ تقديم طعام بديل يوفر العناصر الغذائية نفسها. فمثلًا، يُعد الكالسيوم بالغ الأهمية لصحة العظام والأسنان. وإذا كان طفلكِ لا يحب شرب الحليب، فيمكنكِ أن تقدمي له بدلًا منه العيران أو الجبن أو الزبادي أو حبوب الإفطار مع الحليب.') WHERE id = 'f14350f9-b48d-4bfb-88a6-d4e850319819';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لكِ دور كبير في مساعدة طفلكِ على التكيف مع الحياة الاجتماعية. ادعمي الأنشطة التي يمارسها بحماس، ولا تقولي له عبارات محبطة مثل: «لن تستطيع فعل ذلك»، فقد يؤدي ذلك إلى ضعف ثقته بنفسه مستقبلًا. أتيحي لطفلكِ فرصًا أكبر للوجود في بيئات تضم أطفالًا من عمره، وعززي لديه مفاهيم المشاركة والتعاون والعمل الجماعي. وعندما يستمع إليكِ ويطبّق ما تقولينه في سلوكه، اشكريه وأخبريه أن ما فعله سلوك جميل. ومهما كثرت ألعابه، فسيظل يفضّل دائمًا الألعاب التي يلعبها معكِ. بل إن تقليده لحركاتكِ في المنزل دليل على أنه بدأ يشعر بأنه أصبح كبيرًا. لذلك فكري مرة أخرى قبل القيام بأي تصرف، لأنه أصبح الآن مرآتكِ.') WHERE id = 'e8b1c2b9-b8f2-4e27-b070-1a99713d7661';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، يعرف طفلكِ جيدًا كيف يدفع الأشخاص من حوله، بمن فيهم أنتِ، إلى التصرف بالطريقة التي يريدها. وقد تلاحظين اهتمامه بالحالة النفسية للآخرين ورغبته في معرفة سبب غضب الجار أو حزن والده. إن تقديم تفسيرات بلغة يستطيع فهمها يساعده على إدراك أن المشاعر طبيعية، وأن من الصواب التحدث عنها. خلال هذه الفترة، سيبدأ طفلكِ بتكوين أنماط عاطفية أساسية، مثل الحب والثقة. فهو يدرك أنكِ وأفراد الأسرة الآخرين تحمونه وتقفون إلى جانبه. وقد تعلّم هذه المفاهيم المهمة ضمن هذا الشعور بالأمان، بفضل الطريقة التي تعاملتِ بها معه خلال العامين الأولين. ويُعد إظهار حبكِ له، والاستجابة لاحتياجاته في الوقت المناسب، وتوفير بيئة آمنة له من أهم العوامل التي تساعده على فهم المشاعر بصورة صحيحة.') WHERE id = 'e0588130-112a-43d1-a91a-610ac0b19398';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'وفقًا لنظرية الذكاءات المتعددة، لا يمتلك الفرد نوعًا واحدًا فقط من الذكاء (IQ)، بل مجموعة من مجالات الذكاء والقدرات المختلفة. في هذه المرحلة، يمكنكِ البدء بملاحظة نوع الذكاء الذي يميل إليه طفلكِ أكثر. فمثلًا، إذا تطورت لديه القدرة على فهم علاقات السبب والنتيجة، وطرح الأسئلة، وإجراء العمليات المجردة، فهذا يعني أن قدرته الرياضية والمنطقية أكثر بروزًا. وإذا كان يميل إلى الاستكشاف البصري، وملاحظة الاختلافات، وتكوين تشبيهات خيالية، فتكون قدرته البصرية المكانية أقوى. وإذا كان يدرك الأنماط الموسيقية ويميّز بينها ويعبّر عن نفسه بالموسيقى، فيُعد ذكاؤه الموسيقي الإيقاعي أو السمعي أكثر تطورًا. إضافة إلى ذلك، إذا كان طفلكِ يستخدم جسده ويديه بكثرة للتعبير عن مشاعره وأفكاره، فيمكن القول إن ذكاءه الجسدي الحركي هو الأكثر بروزًا. وقد تظهر هذه القدرة في رغبته الدائمة في استخدام يديه بنشاط لابتكار أشياء جديدة، أو بناء نماذج، أو تشكيل عجينة اللعب باستمرار.') WHERE id = '9eabf6e3-daca-46d0-9e1c-7b73da5a85a6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا يمكن للتلفاز أبدًا أن يكون لطفلكِ جليسًا أو معلمًا أو رفيق لعب جيدًا مثلكِ. وإذا كان سيشاهده، فينبغي أن يكون ذلك لفترة قصيرة وأنتِ بجانبه، لا أن يشاهده بمفرده لساعات. ومن المهم ألا تتجاوز مدة المشاهدة اليومية نصف ساعة. تأكدي من أن البرامج التي يشاهدها مناسبة لعمره وتثقيفية وممتعة. فالإفراط في مشاهدة التلفاز يحدّ من أنشطة الطفل الاجتماعية وقدراته. يسمح كثير من الآباء لأطفالهم بمشاهدة التلفاز لإشغالهم عندما تكون لديهم طاقة كبيرة، لكن الألعاب تكون أكثر فائدة في هذه الحالة. وعند اختيار الألعاب، يُفضّل أن تختاري نماذج تشجّع طفلكِ على النشاط البدني والذهني وتحفّز قدراته العقلية المتنامية.') WHERE id = 'f2588707-ed76-4381-a46a-51f910d91358';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مرحبًا بكِ وبطفلكِ في الشهر 32! 😊 لقد اكتسب طفلكِ، مع دخوله الشهر 32، العديد من المهارات الجديدة. فعلى سبيل المثال، يمكنه رسم دائرة بالقلم، لكنه لا يزال بحاجة إلى بعض الوقت ليتمكن من رسم مربع أو مثلث. ويمكنه ارتداء قميصه وخلعه بمفرده، وإن كان يرتديه بالمقلوب في كثير من الأحيان. أما الملابس ذات الأزرار، فقد يحتاج إلى المساعدة فيها. ويستطيع الوقوف على قدم واحدة لبعض الوقت والقفز إلى الأمام بسهولة. كما يمكنه رمي الكرات المناسبة لحجمه والتقاطها. وكلما كان طفلكِ أكثر نشاطًا، كان أكثر نجاحًا في تجربة أشياء جديدة تدعم نموه البدني. ينبغي ألا يبقى طفلكِ البالغ من العمر 32 شهرًا دون حركة لأكثر من 60 دقيقة، باستثناء وقت النوم. لا تُبقيه جالسًا في عربة الأطفال أو مقعد السيارة لفترات طويلة. وإذا رفض أن تحمليه أو أن يركب العربة، فاسمحي له بالمشي بمفرده في مكان آمن.') WHERE id = '70fac899-c576-4661-823a-c8e6d7ab1f20';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع أن من أكثر الأمور التي تشكو منها العائلات التي لديها أطفال في هذا العمر كثرة أسئلة أطفالها وحديثهم المتواصل، فإن بعض الآباء يقلقون أيضًا لأن أطفالهم لم يبدأوا الكلام بعد. إذا لاحظتِ هذه الحالة لدى طفلكِ، فعليكِ الانتباه إلى بعض الأمور قبل مراجعة الطبيب. ومن أهمها التأخر اللغوي العائلي؛ فإذا بدأتِ أنتِ أو زوجكِ الكلام في سن متأخرة، فقد يعني ذلك أن طفلكِ سيتأخر في الكلام أيضًا، وغالبًا لا يكون وراء ذلك سبب خطير. وقد تتأخر المهارات اللغوية أيضًا لدى الأطفال المولودين مبكرًا (الخُدّج) أو الذين يعانون من تأخر في النمو. كما قد تؤدي عوامل مثل التحدث بلغتين في المنزل، وعدم ثبات استخدام اليد اليمنى أو اليسرى، وضعف السمع، ورباط اللسان، وشق الحنك أو الشفة إلى تأخر الطفل مقارنة بأقرانه. إضافة إلى ذلك، قد تعوق قلة التواصل في البيئة المحيطة بالطفل كلامه، وكذلك المبالغة في حمايته وتلبية احتياجاته قبل أن يعبّر عنها. وغالبًا ما تنشأ هذه المشكلة لأن الطفل لا يُمنح فرصة للكلام، لكن سرعان ما يظهر التحسن عند توفير الظروف المناسبة له.') WHERE id = '142a2085-8e97-430d-aa1a-76d048b9f3e3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'الإحساس بالإيقاع فطري لدى طفلكِ، كما هو الحال لدى جميع الأطفال. لذلك يمكنكِ الاستماع معه إلى أغاني الأطفال، إلى جانب أي نوع من الموسيقى يعجبكما. ولمساعدته على تفريغ طاقته بطريقة مناسبة، يمكنكما الرقص والغناء والتصفيق على الإيقاع معًا. إن مساعدة طفلكِ على الإحساس بارتفاع اللحن وانخفاضه والتعبير عنه بحركات جسده ستنمّي حسّه الموسيقي. وعندما يبدأ بدندنة أغنية مألوفة، يمكنكِ أن تدركي أنه أصبح مستعدًا لتجربة آلات موسيقية أخرى. حتى غطاءا قدر أو طبل بسيط في المنزل يمكن أن يؤديا دور آلة موسيقية. ومع ذلك، قد يحتاج طفلكِ أيضًا إلى آلة تتيح له سماع النغمات الحقيقية. وفي هذا السياق، سيكون لمس مفاتيح بيانو تعليمي مخصص للأطفال أو أوتار غيتار، ثم تقليد الصوت الصادر، نشاطًا ممتعًا جدًا لكليكما.') WHERE id = '72d5321b-8667-4786-a0a9-55391cfc58eb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ ترددين كثيرًا عبارات مثل "لا أستطيع إطعام طفلي أي شيء" أو "لا يبالي حتى لو بقي جائعًا لساعات"، فلا تحزني. فكثير من الأمهات يعانين المشكلة نفسها في هذه المرحلة العمرية: أطفال ضعيفو الشهية! رغم أن رغبة طفلكِ في تناول الطعام تختلف باختلاف معدل نموه وحالته الفردية، فإن الفترة بين عمر 1-3 سنوات تحديدًا هي المرحلة التي تكون فيها الشهية في أدنى مستوياتها. ومن الطبيعي في هذا العمر أن يأكل طفلكِ قليلًا في بعض الأيام وكثيرًا في أيام أخرى، لذلك لا داعي للقلق المفرط. كذلك، إذا كان الطفل معتادًا على تناول كميات صغيرة على فترات متقاربة، فقد تكون القيمة الغذائية التي يحصل عليها بهذه الطريقة مفيدة بقدر الوجبة الرئيسية. لكن إذا استمر ضعف الشهية مدة طويلة ولم يكتسب طفلكِ وزنًا كافيًا، فقد يكون السبب طفيليات الأمعاء أو الإمساك أو فقر الدم أو التهاب المسالك البولية. وفي هذه الحالات، لا بد من استشارة الطبيب.') WHERE id = '8eb704da-d3e4-4f40-a1ec-24b231c52cba';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا راقبتِ طفلكِ في مكان يجتمع فيه مع أقرانه، فقد تلاحظين أن بعض الأطفال يلعبون بمفردهم بينما يلعب آخرون ضمن مجموعة. وعلى الرغم من أن اللعب الجماعي يصبح أكثر شيوعًا في هذه المرحلة، فإن بعض الأطفال يكونون أكثر سعادة عند اللعب بمفردهم. إذا كان طفلكِ يحب قضاء الوقت بمفرده، فلا تجبريه ولا تقلقي. فسرعان ما سيجد هو أيضًا رفيقًا للعب مثل الأطفال الآخرين، ويبدأ في بناء علاقات الصداقة. وكجزء من النمو الاجتماعي، قد يميل بعض الأطفال إلى السيطرة على الآخرين والضغط عليهم. ويُعد السلوك المتسلط شائعًا في هذه المرحلة العمرية. فإذا لاحظتِ لدى طفلكِ مثل هذه التصرفات تجاه أقرانه، فمن المهم جدًا أن تنمّي لديه الشعور بالتعاطف، أي القدرة على وضع نفسه مكان الآخرين.') WHERE id = '13173885-9e0a-4abe-ab99-a5202cd0d97c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ الاستفادة من أنشطة مونتيسوري المتنوعة والممتعة لدعم نمو طفلكِ خلال مرحلة ما قبل المدرسة. ويمكنكِ بسهولة تطبيق مفهوم مونتيسوري في المنزل، رغم أن كثيرًا من الأمهات لم يسمعن به قبل أن يصبحن أمهات. ولا تحتاجين إلى أدوات باهظة الثمن، بل على العكس، تُستخدم في أنشطة مونتيسوري أشياء يسهل العثور عليها من حولكِ. تحوّل هذه الطريقة الأشياء التي يصادفها طفلكِ في حياته اليومية أثناء نموه، ويهتم بها ويرغب في فهم كيفية عملها، إلى ألعاب. وعندما يلعب طفلكِ بهذه الأشياء، فإنه يتعلم في الواقع مهارات أساسية سيحتاج إليها طوال حياته. على سبيل المثال، أثناء قيامكِ بأعمالكِ اليومية في المطبخ، افردي قطعة قماش نظيفة على الأرض وضعي فوقها ملاعق شاي وحلوى وطعام بأحجام مختلفة. واطلبي من طفلكِ ترتيب هذه الملاعق من الأصغر إلى الأكبر ثم بالعكس. الأمر بهذه السهولة! 😊') WHERE id = 'da312752-586a-4921-9553-2181d873da6f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المتوقع خلال هذه المرحلة أن يفهم طفلكِ أسئلة مثل «ما هذا؟»، و«أين الكرة؟»، و«من أنا؟»، وأن يقدم إجابات ذات معنى. ويُفترض أن يتمكن كل طفل لا يعاني من أي مشكلة صحية من تكوين جمل تتألف من كلمتين أو 3 كلمات بحلول عمر 36 شهرًا على أقصى تقدير. لكن إذا لم تلاحظي هذه المهارات لدى طفلكِ، فلا يعني ذلك دائمًا وجود مشكلة خطيرة. يُعرَّف تأخر النطق بأنه عدم امتلاك الطفل مهارات كلام مماثلة لأقرانه. وإذا كان الطفل لا يتحدث بما يتناسب مع عمره، فقد يكون ذلك «اضطرابًا في النطق» أو «تأخرًا في النمو». ويُعد ضعف السمع أحد أهم أسباب تأخر النطق، وقد يكون خلقيًا أو مكتسبًا لاحقًا. لذلك، إذا كانت لديكِ أي مخاوف، فننصحكِ باستشارة طبيب مختص.') WHERE id = '8b57d158-736c-4f31-9161-27c88480c843';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من أكثر الأمور التي تُربك الوالدين كيفية التمييز بين الكوابيس ونوبات الذعر الليلي. تختلف هذه الحالة، التي تُصنَّف ضمن اضطرابات الفزع أثناء النوم، عن الكوابيس العادية. إذ يستيقظ الطفل فجأة ويبدأ بالصراخ بعد نحو 90 دقيقة من نومه. ويمكنكِ معرفة أن طفلكِ يمر بنوبة ذعر ليلي من خلال العلامات الآتية: قد يقف في سريره أو يحاول الركض بلا هدف. ويبدو خائفًا ومذعورًا للغاية، ويصرخ مطلقًا أصواتًا غير مفهومة. وحتى إذا حاولتِ تهدئته، فقد لا يتعرف إليكِ، ولا يفهم ما يقال له، ولا يجيب عن الأسئلة. وقد تلاحظين خفقان القلب وسرعة التنفس والتعرق. ورغم أن الذعر الليلي لا يسبب للطفل أذى جسديًا، فقد تكون له آثار نفسية إذا أصبح مستمرًا. ومهمتكِ في هذه الحالة هي منع الطفل من إيذاء نفسه جسديًا. فقد يؤدي لمسه أو احتضانه إلى زيادة حدة النوبة.') WHERE id = '649c5984-28bb-41d3-857b-4e0043a7b040';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ربما اكتمل ظهور أسنان طفلكِ اللبنية، التي يبلغ عددها الإجمالي 20 سنًا. وإذا لم يكتمل ظهورها بعد، فمن المتوقع أن يظهر الضرسان الثانيان خلال الشهر أو الشهرين المقبلين. وبعد ذلك، ستكون أولى الأسنان الدائمة التي تظهر هي الأضراس الكبيرة الأولى، ابتداءً من عمر 6 سنوات. وقد تلاحظين لدى طفلكِ أثناء التسنين أعراضًا مثل ارتفاع درجة الحرارة والغثيان والإسهال. ومن الطبيعي أيضًا أن يكون الطفل أكثر انزعاجًا وأن تقل شهيته خلال هذه الفترة. ومن المتوقع كذلك احمرار اللثة وزيادة سيلان اللعاب عند ظهور الضرس الثاني. لذلك، ينبغي أن تتفهمي لفترة مؤقتة عدم رغبة طفلكِ في تناول الطعام وضعف شهيته.') WHERE id = '4caba1ee-fe4e-4f39-9676-eeb0deb3ad9f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أتاح تطور قدرات طفلكِ الجسدية الفرصة لمزيد من التحسن في مهاراته. فقد أصبح الآن قويًا بما يكفي لصعود الدرج ونزوله من دون مساعدتكِ. كما صارت حركات يديه أكثر اتزانًا، وأصبح أكثر مهارة في استخدامهما. لكن حتى إذا كان طفلكِ يستطيع صعود الدرج بمفرده، فعليكِ الاستمرار في توخي الحذر. ومن أجل سلامته، لا تتركيه من دون مراقبة إلا عند الضرورة. فطفلكِ، شأنه شأن جميع الأطفال، قد يحاول أحيانًا القيام بأكثر مما تسمح به قدراته كي يكتشف حدود إمكاناته. ومن أمثلة ذلك صعود الدرج درجتين في كل خطوة أو النزول بالقفز.') WHERE id = '84c09dfd-750f-4d20-9c62-31f373486223';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تحدث نحو 44% من أكثر الحوادث المنزلية شيوعًا في العالم وفي بلدنا بسبب السقوط. وإذا كنتِ تعيشين في منزل متعدد الطوابق، فلا تنسي تركيب حواجز مناسبة أو بوابات أمان عند أعلى الدرج وأسفله. كما يُعد السقوط من النوافذ من الحوادث الشائعة بين الأطفال. ولا تكفي شبكات الحماية من الحشرات لحماية طفلكِ. وإذا أردتِ توفير أقصى درجات الأمان لطفلكِ المفعم بالطاقة، لا سيما خلال هذه المرحلة، فيمكنكِ تركيب حواجز حماية مخصصة للنوافذ. وحاولي أيضًا إبعاد قطع الأثاث التي يمكن لطفلكِ تسلقها عن النوافذ. ومن الأسباب الأخرى للسقوط أن تكون الأرضية زلقة. ويمكنكِ تقليل الخطر بوضع بطانات مانعة للانزلاق تحت السجاد في المنزل. كما يمكنكِ الوقاية من الإصابات المحتملة بتركيب واقيات على زوايا الطاولات والرفوف.') WHERE id = '8d8068ce-d413-4155-9f05-19664d00e5b9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك بعض النقاط التي ينبغي لكِ مراعاتها لمساعدة طفلكِ على اكتساب عادات منتظمة في تناول الطعام. وأهمها الانتباه إلى الأوقات التي يكون فيها طفلكِ مرهقًا ونعسانًا بشدة، فقد يرفض الطعام لعدم شعوره بالشهية في هذه الحالة. وقد يساعد اللعب مع طفلكِ قبل الجلوس إلى المائدة على تحسين مزاجه وتقليل مقاومته للطعام. ويجب ألا تقدمي له بين الوجبات السكر أو الشوكولاتة أو الكعك أو المشروبات الغازية وغيرها من المشروبات شديدة الحلاوة مطلقًا، إذ إن شرب نصف كوب فقط من عصير الفاكهة الجاهز قد يفقده شهيته. كما ينبغي ألا تلحّي عليه ليأكل في أثناء الوجبة. وعلى عكس ما هو شائع، فإن مكافأته أو معاقبته تؤثر سلبًا في عاداته الغذائية. إضافة إلى ذلك، قد يشكل عدم جلوس إخوته الأكبر سنًا أو كبار العائلة إلى المائدة وانتقاؤهم لأنواع معينة من الطعام قدوة سيئة تؤثر في عاداته. لذلك ينبغي، قدر الإمكان، أن يجلس جميع أفراد الأسرة حول المائدة في أوقات الوجبات.') WHERE id = 'b0de3f60-3586-4525-93f5-131c4993a7dc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يشعر طفلكِ في هذه المرحلة بحزن وقلق عميقين بعد قضاء حاجته. وهذا في الواقع رد فعل طبيعي تمامًا، لأنه لا يزال صغيرًا ولا يدرك الأمر جيدًا، فيظن عند خروج البراز أن جزءًا من جسمه قد انفصل عنه وذهب. ونتيجة لذلك، قد يقلق من احتمال فقدان أجزاء أخرى من جسمه، مثل ذراعه أو ساقه. في مثل هذه الحالات، ينبغي ألا تعامليه بقسوة مطلقًا أو تكرري عليه بإلحاح عبارات مثل «لا!» و«لا تخف!». وبدلًا من ذلك، حاولي أن تشرحي له آلية هذه العملية الفسيولوجية بلغة يفهمها. يمكنكِ أن توضحي له أن البراز هو فضلات الطعام الذي تناوله، وأن تطلبي منه أن يتخيل المرحاض كسلة للمهملات. ويمكنكِ حتى السماح له برؤية البراز في حفاضه، ثم التخلص منه معًا في المكان المخصص للنفايات أو في المرحاض.') WHERE id = '8c882e96-3609-47c5-bc42-d3ee39abdda4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين في هذه المرحلة من نمو طفلكِ أنه يحاول مساعدتكِ في الأعمال المنزلية بصرف النظر عن جنسه. فتقليده لكِ وللأشخاص المحيطين به في هذه المرحلة جزء طبيعي من نموه. ومن خلال ذلك يتعلم طفلكِ، من دون أن يدرك، كيف يتصرف في المواقف والأماكن المختلفة. وهنا تقع مسؤولية مهمة عليكِ وعلى الأشخاص المحيطين به؛ إذ ينبغي لكم الانتباه إلى تصرفاتكم، لأن الطفل إذا سمع من أحدهم كلمة سيئة لا تناسب عمره، فسيبدأ فورًا بتكرارها. لذلك عليكِ أن تكوني أكثر انتباهًا من أي وقت مضى. وعندما يرغب طفلكِ في مساعدتكِ في الأعمال المنزلية، لا تمنعيه، بل تأكدي من أنه لن يؤذي نفسه. وباختصار، بدلًا من أن تقولي له: "لا تفعل ذلك، ستؤذي نفسك!"، يمكنكِ تشجيعه بقولكِ: "ستنجح إذا كنت حذرًا!".') WHERE id = 'a8b1ba6a-e9b7-4b18-8bee-81c98164dc1d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُظهر الأبحاث أن الأطفال الذين لم يعتادوا مذاق السكر يمكن إبعادهم حتى سن المدرسة عن الأطعمة المحلاة بالسكر المضاف، مثل البسكويت والشوكولاتة والكعك. ويُعد السكر مهمًا لنمو طفلكِ وحصوله على الطاقة التي يحتاج إليها خلال اليوم. ولكن بدلًا من تلبية هذه الحاجة بالسكر البسيط الخالي من القيمة الغذائية، يمكنكِ تلبية احتياجات طفلكِ من الكربوهيدرات بأطعمة منزلية مثل الكعك والبسكويت المُحضّرين بدبس الفاكهة أو العسل. وعندما يلتحق بالمدرسة ويختلط بالأطفال الآخرين، سيصادف هذه الأطعمة لا محالة، حتى لو لم ترغبي في ذلك. لكن المهم أن تكوني قد ساعدته بحلول ذلك العمر على اكتساب نمط غذائي صحي. وكلما ازداد ميل طفلكِ إلى الأطعمة الحلوة، زاد احتمال تعرضه لمشكلات صحية في المستقبل. لذلك من المهم جدًا ألا تتساهلي خلال هذه المرحلة التي تتشكل فيها العادات.') WHERE id = '35e2d7ef-3499-43c9-ac1b-a5604e2b87d4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'كان يُعتقد سابقًا أن نمو الدماغ يعتمد على العوامل الوراثية وحدها. لكن العلماء توصلوا مؤخرًا إلى أن العوامل البيئية تؤدي دورًا مهمًا في نموه. ويولد كل طفل بنحو 100 مليار خلية عصبية، ولا تتكون خلايا عصبية جديدة في مراحل الحياة اللاحقة. لذلك فإن كل دقيقة ممتعة ومفيدة تقضينها مع طفلكِ هي بمثابة بذرة تزرعينها من أجل نجاحه في المستقبل. وقد أثبتت الأبحاث أن المحفزات اللفظية والبصرية والسمعية التي يتلقاها الأطفال تؤثر إيجابيًا في نمو الدماغ والذكاء. وكلما زاد تنوع هذه المحفزات، ازدادت فائدتها. لذلك ينبغي لكِ اصطحاب طفلكِ في نزهات في الطبيعة قدر الإمكان، وإتاحة الفرصة له لتصفح الكتب الملونة والمصورة، ومحاولة ممارسة أنشطة تعليمية معه.') WHERE id = 'ea041f70-a712-4618-a072-ebd4e18f986e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تبلغ حاجة الطفل اليومية إلى الملح في هذه المرحلة نحو 1500 مليغرام، وهو ما يعادل 1.5 غرام من الملح يوميًا. ووفقًا للمعايير التي حددتها منظمة الصحة العالمية، يُعد تناول الملح المُعالج باليود ضروريًا لإنتاج هرمونات الغدة الدرقية. وقد يؤدي الامتناع التام عن الملح إلى اضطرابات هرمونية لدى طفلكِ، وفي مقدمتها قصور الغدة الدرقية. وفي المقابل، قد يؤدي تناول الملح بكميات تفوق المعدل الطبيعي إلى مضاعفات خطيرة أيضًا. وحتى إذا لم تضيفي الملح إلى طعامه، فقد يحصل طفلكِ على كمية تفوق حاجته منه إذا كان يتناول المنتجات الجاهزة والمعبأة. ويؤدي الإفراط في تناول الملح إلى انخفاض كمية الماء في الجسم، ومن ثم الإصابة بالجفاف. لذلك من المهم جدًا إبعاد طفلكِ عن المنتجات المعبأة وتفضيل الأطعمة المنزلية قدر الإمكان.') WHERE id = 'f91b2ae4-510c-4199-8db1-8954345d3297';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين خلال هذه المرحلة تغيرًا في سلوك طفلكِ تجاه أقرانه. فقد يبدأ باللعب معهم ضمن مجموعة، لكنه قد لا يرغب بعد في مشاركة ألعابه وأغراضه بالكامل. لا تنظري إلى ذلك على أنه بخل، بل تقبّليه بوصفه سمة طبيعية لهذه المرحلة العمرية. سيتعلم مع الوقت المشاركة بصورة أفضل. امنحيه بعض الوقت ولا تجبريه، لأن طفلكِ سيستمر فترةً أخرى في رؤية نفسه محور العالم. وقد تتقلب مشاعره أيضًا خلال هذه المرحلة؛ فبينما يكون سعيدًا جدًا، قد يغضب فجأة عندما يُطلب منه فعل شيء لا يريده. وحتى إن تجاوزتما إلى حدّ ما مرحلة نوبات الغضب، فهذا لا يعني أنها انتهت تمامًا، وقد تواجهين مثل هذه المواقف أحيانًا.') WHERE id = 'a6115683-f3cb-4edb-9c84-9bf3b5c64952';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لاحظتِ تضخمًا في خصيتي ابنكِ أو نموًا في ثديي ابنتكِ، فهناك بعض الأمور التي ينبغي الانتباه إليها. البلوغ مرحلة بيولوجية تشمل التغيرات الهرمونية والجسدية التي تحدث أثناء الانتقال من الطفولة إلى الرشد. يتراوح العمر الطبيعي للبلوغ بين 9-11 عامًا لدى الفتيات، وبين 10-12 عامًا لدى الفتيان. ويُعد بدء النمو قبل سن 8 سنوات لدى الفتيات وقبل سن 9 سنوات لدى الفتيان بلوغًا مبكرًا. ومن أولى علاماته بروز الثديين لدى الفتيات وتضخم الخصيتين لدى الفتيان. وفي السنوات الأخيرة، ازدادت حالات البلوغ المبكر لدى الأطفال بسبب زيادة الأغذية المعدلة وراثيًا والتغيرات الهرمونية. كما تتأثر هذه الحالة بالعوامل الوراثية والظروف الجغرافية والتغذية والحالة الصحية العامة. وقد يؤدي إهمال هذه المشكلة، رغم توفر العلاج لها، إلى مضاعفات خطيرة. لذلك من المهم جدًا أن تراقبي طفلكِ بعناية.') WHERE id = '96217fde-5713-4fe7-acb8-719f4d28185d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين أن طفلكِ يُظهر أحيانًا سلوكيات عدوانية خلال هذه المرحلة. لكن السلوك العدواني الذي يظهر في هذا العمر يكون عادةً سلوكًا مكتسبًا. وإذا لم يسبق أن تصرف بهذه الطريقة، فيمكنكِ البحث عن السبب. فعلى سبيل المثال، إذا كان هناك شخص في الأسرة يتصرف بعدوانية، فمن المرجح جدًا أن يتأثر طفلكِ به. ولأن طفلكِ شديد الاستعداد للتعلم، فقد يرسخ في ذهنه حتى السلوك العدواني الذي يراه في الحديقة أو المتجر. ومن المهم جدًا خلال هذه المرحلة إبعاد طفلكِ عن مثل هذه التصرفات غير المألوفة والسلبية. لذلك عليكِ مراقبة العوامل التي تثير لديه السلوك العدواني، والاستعانة بمختص عند الحاجة.') WHERE id = 'f6c4c1fb-2085-4620-b3dd-958a42acbbb4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ندرك أن طفلكِ يكون كثير النشاط خلال هذه المرحلة، ويمكنكِ تحويل ذلك إلى فرصة! فعلى سبيل المثال، يمكنكِ إعطاؤه مهام بسيطة يستطيع إنجازها، لمساعدته على تنمية إحساسه بالمسؤولية. ففي هذه المرحلة، يبدأ طفلكِ بفهم مشاعركِ ومشاعر الآخرين وإدراك ما إذا كانوا بحاجة إلى المساعدة. وإضافة إلى ذلك، قد يكون من المخيف لطفلكِ، الذي بدأت تتكون لديه مخاوف وأنواع رهاب خاصة به، تجربة أشياء جديدة ومختلفة. عليكِ أن تتهيئي لهذا التغيير وأن تساعديه على تخفيف مخاوفه. ومن أكثر العوامل التي تسبب له التوتر خلال هذه المرحلة خوفه من الانفصال عنكِ. لذلك، عندما تذهبين إلى مكان ما، احرصي على إخباره بموعد عودتكِ. وإذا كان واثقًا من أنكِ ستعودين، فسيتمكن من البقاء بعيدًا عنكِ مدة أطول.') WHERE id = '333574d8-98a5-4257-9524-278228cb207c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ في هذه المرحلة قادرًا على غسل يديه ووجهه وتجفيفهما بسهولة من دون مساعدتكِ. كما أصبحت عضلات قدميه وساقيه أقوى من السابق، ما يتيح له القفز والهبوط بسهولة. وبالطبع، قد تختلف قدرات النمو البدني من طفل إلى آخر خلال هذه المرحلة. ولن تفيدكِ مقارنة طفلكِ بالأطفال الآخرين. تذكري أن لكل طفل أسلوبه الخاص في التصرف وشخصيته المختلفة. وتبدأ هذه الاختلافات في الظهور بوضوح أكبر، خصوصًا بعد سن عامين. أما مرحلة سن 3 سنوات التي دخلتماها الآن، فهي مرحلة تتجلى فيها هذه الاختلافات بصورة كاملة. لذلك ادعمي طفلكِ بناءً على ما يستطيع فعله، بدلًا من التركيز على ما لا يستطيع فعله. وسيُسهم تشجيعكِ له في بناء ثقته بنفسه وتعزيز تقديره لذاته.') WHERE id = '2736628c-47d5-4efe-8544-30f307dcafe3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد المرحلة الممتدة حتى سن 6 سنوات، حين يبدأ طفلكِ المدرسة، الفترة التي تتشكل فيها عاداته الغذائية بصورة شبه كاملة. فالعادات الغذائية السليمة التي يكتسبها في هذا العمر تمهد ليصبح شخصًا أكثر صحة في المستقبل. وتُعد مواعيد الوجبات غير المنتظمة، والحلويات، والأطعمة غير الصحية (الوجبات السريعة) مؤشرات إلى احتمال معاناة طفلكِ من السمنة مستقبلًا. وتُظهر الدراسات التي أُجريت خلال الأعوام الـ20 الماضية أن نسبة كبيرة من الأطفال الذين يعاني والداهم من زيادة الوزن يواجهون المشكلة نفسها في مرحلتي الطفولة والرشد. وهذا يثبت أن الطفل يقلد مباشرةً العادات الغذائية السائدة داخل الأسرة. أما الأطفال الذين يبتعدون عن الأطعمة الضارة حتى سن المدرسة، فلن تصبح هذه المنتجات جزءًا أساسيًا من نظامهم الغذائي طوال حياتهم. لذلك، إذا أردتِ أن يتمتع طفلكِ بوزن صحي، فعليكِ أولًا اتباع نظام غذائي صحي.') WHERE id = '70039ed8-6ea5-4eb9-9e14-4db990b7a7b1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تشير الدراسات إلى أن نسبة كبيرة من الأمهات لا يمتلكن معلومات كافية عن أهمية النوم. فالنوم الليلي الجيد يساعد طفلكِ على تنظيم ما تعلّمه طوال اليوم، وتجديد طاقته، وبدء يوم جديد بسعادة ونشاط، والأهم من ذلك، باستعداد للتعلّم، مما يسرّع نموه العقلي. وقد تؤدي معاناة طفلكِ من مشكلات النوم على المدى الطويل إلى تأخر نمو الدماغ وإعاقة نموه الصحي؛ لأن مرحلته العمرية الحالية شديدة الأهمية للنمو العقلي والجسدي السليم. ففي هذه المرحلة، يمتص دماغ طفلكِ المعلومات كالإسفنجة، ويكتمل نحو 75-80% من نمو الدماغ، كما يكاد حجمه يصل إلى حجمه لدى البالغين. وقد يتعذر تدارك الأخطاء والإهمال خلال هذه المرحلة مستقبلًا. لذلك، يؤدي النوم الليلي المتواصل، ولا سيما نوم حركة العين السريعة (REM)، دورًا حيويًا في تمكين دماغ طفلكِ من بلوغ كامل إمكاناته التنموية.') WHERE id = '295fa9e3-3754-4afa-a728-c53e7964be12';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'طفلكِ الآن مستكشف حقيقي للمشاعر. وهو يبني ذكاءه من خلال التعرّف إلى محيطه ولغته وثقافته من جميع الجوانب. وفي هذه المرحلة، يمتلك طفلكِ بنية ذهنية خاصة تختلف عما لدى البالغين، فهو لا يتبع طريقة تفكيرهم. ويُطلق على هذه المرحلة في الأوساط العلمية اسم "مرحلة العقل الباطن"، بينما تُسمى في منهج مونتيسوري "العقل المستوعب". ومن أجمل الأمثلة على ذلك الطريقة التي يتعلم بها طفلكِ اللغة؛ إذ يراقب بصمت مدة عامين من حوله وهم يتحدثون بلغة لا يعرفها، ثم يبدأ فجأة في التحدث بها بقواعد ونطق متقنين، وهذا دليل على عمل "العقل المستوعب". لذلك، من المهم جدًا أن تنظّمي لطفلكِ خلال هذه المرحلة "المتلقية" أنشطة تناسب نموه. فكل دقيقة نوعية تخصصينها لنمو طفلكِ تضع أساس نجاحه في المستقبل.') WHERE id = 'd731faa5-02e6-48b2-9d1d-d0e589f45abc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين هذه الأيام أن طفلكِ يرغب في قضاء وقت أطول معكِ ويطلب احتضانكِ كثيرًا. بل قد يأتي إليكِ فجأة بينما تكونين منشغلة، فيعانقكِ أو يرغب في أن تحمليه بين ذراعيكِ. ومن الطبيعي، خصوصًا عند الخروج، أن يتعب سريعًا ويطلب منكِ حمله. حاولي قدر الإمكان ألّا ترفضي طلبه في مثل هذه اللحظات؛ فهو يخشى المخاطر المحتملة من حوله ولا يشعر بالأمان إلا بين ذراعيكِ. وقبل أن تحمليه، يمكنكِ الاتفاق معه على أمر بسيط؛ اشرحي له أن حمله فترة طويلة قد يسبب لكِ ألمًا في الظهر، وأن عليه المشي عندما تحتاجين إلى الراحة. إن ظهور مشاعر الخوف جزء طبيعي من النمو، لكنها قد تكون مرهقة لكِ أحيانًا. أخبري طفلكِ خلال اليوم بأنكِ تحبينه كثيرًا، ولا تنسي احتضانه عندما تشعرين بأنه يحتاج إلى ذلك.') WHERE id = '158d8d1e-7cf7-43eb-ab2b-077ae8698a3a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'رغم أن الأطفال الهادئين يُعدّون عادة أكثر "تهذيبًا" في نظر المجتمع، ينبغي لطفلكِ في الواقع أن يكون نشيطًا وكثير الحركة خلال هذه المرحلة. فرشاقته مهمة جدًا لاكتساب مهارات جديدة وترسيخها في الدماغ على نحو صحيح. ولكي يتمكن طفلكِ من تصريف طاقته بطريقة سليمة، ينبغي أن تعتمدي أنشطة مخططة. وتؤدي البيئة والألعاب والوقت دورًا كبيرًا في تطوير المهارات الحركية. وكلما كانت الأنشطة في هذه المرحلة مدروسة وأكثر تنوعًا، ازدادت قدرة طفلكِ على الحركة. كما أن توفير بيئة مناسبة للتدريب مهم لبدء ممارسة الرياضة باستعداد جيد. ويتمثل الهدف الحالي في إتقان الحركات الأساسية إتقانًا كاملًا. وبناءً على هذه المعلومات، يمكنكِ توجيه طفلكِ إلى رياضات بسيطة ومفيدة مثل السباحة.') WHERE id = 'dfcc6d4e-9df3-4f70-83ad-b2044dc2b08d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح النظام الغذائي لطفلكِ في مرحلة اللعب الحالية قريبًا من النظام الغذائي للبالغين. وفي هذه المرحلة، لا داعي لأن تخشي الدهون كثيرًا، كما هو الحال في النظام الغذائي للبالغين؛ لأن معدة طفلكِ صغيرة، وهو يحتاج إلى الدهون التي توفر قدرًا أكبر من الطاقة بكميات أقل. ويحتوي 1 غرام من الدهون على 9 سعرات حرارية، ما يسهم إلى حد كبير في تلبية احتياجات طفلكِ اليومية من الطاقة. لكن ينبغي عدم الإفراط في الكمية، إذ قد يزيد تناول كميات كبيرة من الدهون خطر الإصابة بأمراض القلب والأوعية الدموية مستقبلًا. لذلك، اختاري الدهون المفيدة كي تكتسبي أنتِ وطفلكِ عادات غذائية صحية. ومن أفضل الخيارات استخدام زيت الزيتون في الطعام، وتقديم الأفوكادو والبذور والمكسرات الغنية بالدهون، مثل اللوز والبندق والجوز.') WHERE id = '6a9442ee-d5d9-453f-a3b4-67e47e360e31';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد الأنشطة الدرامية التي انتشرت على نطاق واسع في جميع أنحاء العالم خلال السنوات الأخيرة ضرورية لنمو الأطفال، ولا سيما في مرحلة ما قبل المدرسة. وتُستخدم فيها أساليب مثل اللعب وتمثيل الأدوار وتأليف القصص. فاللعب أهم وسيلة لتعليم الطفل، وطفلكِ يتعلم كل شيء من خلال التقليد. لنستعرض مثالًا ممتعًا لنشاط درامي يمكنكِ ممارسته معه: 1. أنا رضيع (التكور مثل الرضيع). 2. زحفت أولًا (تمثيل حركة الزحف). 3. ثم مشيت (تمثيل حركة المشي). 4. ثم تكلمت (تمثيل الكلام). 5. كبرت وكبرت وكبرت (الوقوف وإظهار الطول). 6. بدأت الذهاب إلى المدرسة، وعمري الآن 3 سنوات (إظهار 3 أصابع). وإلى جانب كون هذه الأنشطة ممتعة، فإنها تعزز إبداع طفلكِ وتساعده على تعلّم مفاهيم جديدة بسهولة.') WHERE id = 'b977ef12-87df-48c3-93a8-39c832b155c7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'العناية بأسنان طفلكِ موضوع مهم للغاية ويتطلب اهتمامًا خاصًا. فإهمال العناية بها بحجة أنها «أسنان لبنية وستسقط على أي حال!» قد يؤدي إلى مضاعفات مثل التهاب اللثة وتسوس الأسنان. وللوقاية من ذلك، يُعد تعويد طفلكِ على تنظيف أسنانه بانتظام من أفضل العادات التي يمكنكِ إكسابه إياها. ومع أن معجون الأسنان هو أول ما يتبادر إلى الذهن عند الحديث عن تنظيف الأسنان، فإنه لا يُنصح باستخدامه للأطفال في المرحلة الأولى. خلال هذه الفترة، يمكن لطفلكِ تنظيف أسنانه بالفرشاة من دون معجون. ولا ينصح بعض المتخصصين باستخدام معجون الأسنان حتى سن 3 سنوات تقريبًا. وبعد هذا العمر، يمكن استخدام كمية من المعجون بحجم حبة البازلاء. ويتمثل دوركِ في أن تكوني قدوة له، فتفرشي أسنانكِ أمامه بعد الوجبات وقبل النوم ليلًا. تذكّري أن طفلكِ سيكتسب هذه العادة من خلال تقليدكِ.') WHERE id = '8d37727a-164c-4cf0-b23a-460dee8cf99d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد أتممتِ مع طفلكِ 33 شهرًا، تهانينا! 😊 ابتداءً من هذا الشهر، ومع ازدياد حصيلته اللغوية، يصبح قادرًا على التعبير عن نفسه بسهولة أكبر. كما يستمر تطوره اللغوي في التحسن يومًا بعد يوم. في هذه المرحلة، يستخدم طفلكِ الضمائر وأدوات الربط بصورة صحيحة، ويبدأ بطرح أسئلة مثل: مَن، وماذا، ولماذا، وأين بشكل متكرر. كما يقدم إجابات مناسبة عن أسئلة «لماذا» و«لأي سبب». ويمكنه التعرف على الأشخاص في الصور والإشارة إليهم وذكر أسمائهم. كذلك يستطيع تغيير نبرة صوته أثناء الحديث، وعندما يُسأل يمكنه ذكر اسمه وعمره وجنسه. وإذا كنتِ قد علّمته، فقد يتمكن من عد الأرقام حتى 10 عن ظهر قلب. ولن يملّ من الاستماع إلى قصصه المفضلة مرارًا وتكرارًا. وعلى الرغم من قدرته على إجراء حوارات بسيطة مع الآخرين، فمن الطبيعي تمامًا أن يرتكب بعض أخطاء النطق.') WHERE id = '0ad387e8-b68f-42e3-a771-8b717ee81176';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد تطورت المهارات الحركية لطفلكِ البالغ من العمر 33 شهرًا بشكل ملحوظ. فقد أصبح ماهرًا في استخدام يديه وأصابعه، أي إنه بات قادرًا على استخدامهما في حركات أكثر تعقيدًا. ويمكنه بسهولة تكديس 5-6 مكعبات فوق بعضها، واللعب بأحجيات مكوّنة من 6-12 قطعة، ورمي الكرة في الهواء. وبفضل تطور قدرته على التوازن، يستطيع الوقوف بسهولة على قدم واحدة واللعب بالكرة. كما يمكنه استكشاف جميع الأشياء تقريبًا واللعب بها. وتُعد اليدان من أكثر مناطق الجسم تمثيلًا وظيفيًا في المراكز الحركية والحسية بدماغ طفلكِ. وترتبط قدرته على استخدام يديه بمهارة ارتباطًا مباشرًا بمدى تطور جهازه العصبي. لذلك، من المهم جدًا أن تمارسي مع طفلكِ الكثير من الأنشطة التي تنمّي المهارات الحركية الدقيقة.') WHERE id = '3bca3dac-612d-48d3-8788-6c23c8d4b4e8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يُظهر طفلكِ البالغ من العمر 33 شهرًا في هذه المرحلة اهتمامًا مفرطًا بأطعمة مثل رقائق البطاطس والشوكولاتة والبسكويت. وإذا كان بعض أقرانه يتناولونها، فسيرغب هو أيضًا في تذوقها. في هذه الحالة، يمكنكِ إعداد أطعمة ذات مذاق مشابه لطفلكِ بطرق طبيعية أكثر. فعلى سبيل المثال، إذا أراد رقائق البطاطس، يمكنكِ إعداد شرائح بطاطس قليلة الدهون في الفرن. كما يمكنكِ تلبية رغبته من خلال تقديم الكعك أو البسكويت المحضّر بطرق طبيعية وصحية. والهدف الأساسي هنا هو تجنّب تناول طفلكِ الأطعمة الجاهزة التي تُباع في المتاجر. فقد تتسبب الأطعمة الجاهزة المجمدة، والمشروبات شديدة السكر، ورقائق البطاطس الغنية بالدهون والملح في إصابته بالسمنة مستقبلًا. ويؤثر نمط تغذية طفلكِ الحالي في حياته المستقبلية، لذا يمكنكِ اعتبار الجهد الذي تبذلينه في هذه المرحلة استثمارًا في مستقبله.') WHERE id = 'e6a1b900-7219-4ca0-ae6e-83f3e11c466a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد دخل طفلكِ الآن مرحلة جديدة. فمن هذه الفترة وحتى بلوغه 7 سنوات، يبدأ باكتساب المهارات الأساسية اللازمة للحياة. وتشمل هذه المهارات الجري بنشاط ومن دون مساعدة، والقفز، والوثب، والقفز على قدم واحدة، والإمساك بالأشياء، ورميها، وركل الكرة. وتُسمى هذه المهارات «أساسية» لأنها متشابهة لدى جميع الأطفال تقريبًا وذات أهمية كبيرة في حياتهم. خلال هذه الأشهر، تظهر الحركات المذكورة بصورة غير متقنة إلى حد ما، لأن طفلكِ يحاول أولًا فهم إمكانات جسمه الحركية وتجربتها. ثم تصبح حركاته أكثر تناسقًا وتحكمًا مع ازدياد قدرته على السيطرة على جسمه. وفي نهاية هذه المرحلة، سيتمكن طفلكِ من أداء هذه الحركات بكفاءة ميكانيكية أكبر. وعند بلوغه سن 5-6 سنوات، تكون مهاراته الأساسية قد نضجت بالكامل.') WHERE id = '35b98740-6814-45cf-ad4b-cc3187b7b7a4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ ترغبين في تعزيز ثقة طفلكِ بنفسه وشعوره بالإنجاز، وتنمية عضلاته الدقيقة ومعرفته بالألوان وفهمه للعلاقة بين الجزء والكل، فلدينا اقتراح رائع لكِ: نشاط نظم الخرز! ستحتاجين لهذا النشاط إلى خيوط صوفية ملوّنة، وخرز ذي ثقوب كبيرة، وغطاء مناسب لفرشه على الأرض. يمكنكِ تشجيع طفلكِ على نظم الخرز في الخيط مع مراقبته بعناية. وخلال هذا النشاط، سيرى طفلكِ كيف يمكن لحبات الخرز المنفصلة أن تكوّن غرضًا واحدًا عند جمعها معًا، مما يساعده على فهم العلاقة بين الجزء والكل. كما يُعد هذا النشاط الممتع مفيدًا جدًا لتعزيز انتباه طفلكِ وتركيزه. وهو يساعد أيضًا على تطوير التناسق بين اليد والعين والقدرة على إكمال المهمة التي بدأها، ما يتيح لطفلكِ التعلم أثناء الاستمتاع. ومن المهم جدًا ألا تتركي طفلكِ بمفرده خلال هذا النشاط، تجنبًا لخطر ابتلاع الخرز.') WHERE id = 'e89e203c-f03d-42bd-adfb-e246026e0afe';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ، الذي يقترب الآن من عمر 3 سنوات، أكثر فهمًا للعالم من حوله. لقد تعلّم روتينه اليومي بالكامل، وبدأ يطرح المزيد من الأسئلة عن الحياة. وقد تلاحظين في هذه المرحلة ازدياد حاجته إلى اللعب. إذا لم تكوني متأكدة من الأنشطة التي يمكنكِ ممارستها معه، فلدينا بعض الاقتراحات لكِ: 😊 يمكنكما الرقص على أنغام الموسيقى، وعندما تتوقف الموسيقى، تلعبان لعبة التوقف المفاجئ أو تغيير الاتجاه. كما ينبغي أن تكون الألعاب التي تنمّي الذكاء والمناسبة لعمر 3 سنوات جزءًا من حياتكما اليومية خلال هذه المرحلة. يمكنكما ترتيب أشياء مختلفة معًا من الأكبر إلى الأصغر، أو من الأطول إلى الأقصر. ففي هذا العمر، يكون طفلكِ مستعدًا لتعلّم المفاهيم المتضادة مثل طويل وقصير، وكبير وصغير. ويمكنكما أيضًا ممارسة لعبة سرد القصص معًا، إذ قد يكون تبادل الأدوار في رواية قصص قصيرة من خيالكما أمرًا ممتعًا للغاية! 😊') WHERE id = 'f3002e6d-b300-436f-b377-ff336ed0acaa';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ البالغ من العمر 33 شهرًا قادرًا على تفكيك الألعاب ذات القطع المتداخلة ثم إعادة تركيبها، كما يمكنه فك براغي الألعاب. وقد بدأ يرتدي ملابسه بمفرده إلى حدٍّ ما. ويمكنه ركوب دراجة ثلاثية العجلات وقيادتها بتحريك الدواسات. كما يستطيع صعود الدرج مثل البالغين، بوضع قدم مختلفة على كل درجة، والوقوف على قدم واحدة. وإضافة إلى ذلك، بدأت مدة تركيز طفلكِ تزداد، وقد يتمكن من اللعب بمفرده لفترة أطول. ومع ذلك، قد يظل يفضّل وجودكِ إلى جانبه أثناء اللعب. يواصل طفلكِ تعلّم تفاصيل الحياة اليومية من خلال مراقبتكِ. وخلال هذه المرحلة التي يزداد فيها التقليد ولعب الأدوار بشكل خاص، قد تلاحظين أنه يحرّك ألعابه ويوجّه إليها التعليمات. تشير هذه الألعاب إلى أن عالمه الخيالي يزداد عمقًا، وتؤدي دورًا مهمًا في فهمه للحياة. وإذا انتبهتِ من وقت إلى آخر إلى الرسائل التي يعبّر عنها من خلال ألعابه، فستتمكنين بسهولة من فهم مخاوفه وقلقه ورغباته.') WHERE id = '312c2aaa-2210-4dfd-80d6-b0c1928bed26';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد أصبحت المرحلة الأسرع من نمو طفلكِ وتطوره وراءكما. ومن الآن فصاعدًا، سيستمر نموه بوتيرة أبطأ نسبيًا حتى مرحلة المراهقة. لكن هذا لا يغيّر كمية البروتين التي ينبغي أن يحصل عليها يوميًا. يجب أن يبلغ متوسط كمية اللحوم التي يتناولها طفلكِ خلال اليوم نحو 100 غرام. وقد تختلف هذه الكمية بحسب عمره ووزنه. يمكنكِ التنويع في وجباته بين الدجاج والسمك واللحوم الحمراء. ولتفادي فقدان الفيتامينات وضمان استفادة طفلكِ القصوى من البروتين، حاولي قدر الإمكان عدم قلي اللحوم. وعند تناول هذه الأطعمة بطريقة صحية، فإنها تلبّي احتياجات طفلكِ من الحديد والبروتين بالكامل. وفي موسم السمك، احرصي على أن يتناول طفلكِ السمك بوفرة قدر الإمكان، فهو غني بجميع العناصر المفيدة اللازمة لنموه العقلي والجسدي.') WHERE id = '31476911-a7ea-4f5e-a49b-77486ebc31c9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'احرصي على عدم وصف طفلكِ بعبارات مثل «خجول» أو «مشاغب» أو «سيئ المزاج»، لا سيما أمام الآخرين. وحتى إن ظننتِ أن طفلكِ لا يسمعكِ أو لا يهتم بما تقولينه، فإنه يفهم كل شيء من خلال لغة جسدكِ أثناء نطق هذه الكلمات. فالتعامل مع شخصيته بهذه الطريقة سيؤثر سلبًا في تطور مفهومه عن ذاته. وإذا كان طفلكِ يتمتع بمثل هذه السمات، فعليكِ التصرف مع مراعاة احتياجاته. فعلى سبيل المثال، ليس من الصواب وضع طفل خجول وسط 10 أطفال وتوقّع أن يتولى دور القائد. يمكنكِ إعداده للحياة الاجتماعية تدريجيًا، بخطوات صغيرة. وتذكّري أننا نولد بطباع معينة، لكن تأثير البيئة المحيطة يمكن أن يصوغ هذه الطباع ويغيّرها.') WHERE id = '35e3ed0f-aad4-4c45-9de0-b5a3eebc1289';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ الآن تقديم بعض منتجات النحل، مثل حبوب لقاح الأزهار، لطفلكِ الذي يقترب من عمر 3 سنوات. تُعد حبوب لقاح الأزهار غذاءً طبيعيًا يحتوي على 22 نوعًا من الأحماض الأمينية، إضافة إلى الكربوهيدرات والكالسيوم والزنك والعديد من الفيتامينات. كما تتمتع مركبات الفلافونويد الموجودة فيها بخصائص قوية مضادة للأكسدة. وبفضل تأثيرها المضاد للأكسدة، فإنها تعزّز المناعة، وتساعد على الوقاية من الأمراض وتجديد الجسم. كما تدعم النمو الجسدي والعقلي لطفلكِ بفضل ما تحتويه من أحماض أمينية وكربوهيدرات وفيتامينات. وفي هذه المرحلة، يكفي أن يتناول طفلكِ نحو 10-15 غرامًا من حبوب لقاح الأزهار يوميًا. لكن إذا كان طفلكِ يعاني حساسية تجاه العسل أو منتجات النحل، فعليكِ تجنّب هذه المنتجات. وأخيرًا، من المهم جدًا الحصول على حبوب لقاح الأزهار من مصادر موثوقة وطبيعية وعضوية.') WHERE id = 'e2dc9a31-e473-4137-a35c-bba202f969bf';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تواجهين خلال هذه المرحلة نوبات عناد شديدة مع طفلكِ. فعلى سبيل المثال، قد يكون الطقس جميلًا وترغبين في الخروج، لكن طفلكِ يصرّ على ارتداء ملابس غير مناسبة للطقس. وإذا اعترضتِ، مثل أي أم، فقد يتحول الموقف إلى نوبة بكاء تستمر دقائق. ويعبّر المتخصصون عن هذه الحلقة المفرغة بقولهم: "لا يوجد طفل عنيد، بل يوجد والد عنيد". وبالطبع، لا يعني هذا ضرورة تنفيذ كل ما يريده الطفل. فإذا لُبّيت جميع رغباته، فقد تواجهين حالة من الفوضى وسلوكًا يصعب التحكم فيه. في مثل هذه اللحظات، عليكِ التعامل مع طفلكِ وفق مفهوم "الحرية ضمن حدود". وبالعودة إلى المثال نفسه، يمكنكِ أن تعرضي على طفلكِ، الذي يرغب في اختيار ملابسه بنفسه، عدة خيارات مناسبة للطقس، ثم تسمحي له بالاختيار من بينها. سيساعد هذا الأسلوب على حل المشكلة قبل أن تتفاقم.') WHERE id = '89f175d2-1f56-4a45-a902-ade3acc28e69';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ لا يزال يستخدم اللهاية في هذه المرحلة، وكنتِ تقولين إنكِ جربتِ كل شيء ولم تتمكني من فطامه عنها، فلدينا نصيحة من أحد المتخصصين لكِ! 😊 يقترح أحد المتخصصين في مثل هذه الحالات تعريف الطفل بمفهوم تلف الأشياء. فمن وجهة نظره، العالم مكان غير مثالي يمكن أن تتعطل فيه اللهايات وتتوقف عن العمل. وانطلاقًا من ذلك، يمكنكِ أن تطرحي أثناء حديثكِ مع طفلكِ احتمال تلف أي غرض. على سبيل المثال، عندما تجدين لعبة أو قلمًا لم يعد صالحًا للاستخدام، يمكنكِ أن تقولي: لقد تلف هذا ولا يمكننا إصلاحه، لذا علينا التخلص منه. واصلي خلال اليوم الحديث عن الأشياء التي تتلف. وعندما تشعرين بأنكِ مستعدة، يمكنكِ إنهاء دور اللهاية. أري طفلكِ اللهاية وقولي له: انظر، لقد تلفت، ثم تخلّصا منها معًا.') WHERE id = '77122e18-58c2-4599-aad9-dbc48d22e09c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نعلم أنكِ تحاولين التعامل مع ضعف شهية طفلكِ. خلال هذه المرحلة، تلجأ الأمهات إلى وسائل مختلفة لتحفيز شهية أطفالهن. ويُعد دبس الخروب من أكثر الأغذية التكميلية استخدامًا. ورغم عدم وجود دراسات علمية كافية تثبت أن دبس الخروب يزيد الشهية، فإنه غني بعناصر غذائية مفيدة للصحة، مثل الحديد والكالسيوم والبوتاسيوم والمغنيسيوم والفوسفور والزنك والعديد من الفيتامينات. وبفضل احتوائه على حمض الغاليك، يُعتقد أن له تأثيرًا إيجابيًا في حالات الربو والحساسية والتهاب الشعب الهوائية، كما يدعم الجهازين المناعي والهضمي. ويسهم في دعم النمو الذهني لطفلكِ، وبفضل محتواه من مضادات الأكسدة يساعد على طرد البلغم في حالات عدوى الجهاز التنفسي العلوي. كما يساعد البيتا كاروتين الموجود فيه على مقاومة الجذور الحرة. ويسهم أيضًا في تنظيم الجهاز الهضمي، ويُعتقد أنه مفيد خصوصًا في حالات الإسهال.') WHERE id = '0f76d1dc-d8f6-44ec-b73b-3a61bf8f4885';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا أردتِ اجتياز مرحلة متلازمة سن 3 سنوات بصورة أكثر توازنًا، فعليكِ البدء بنفسكِ. على سبيل المثال، لا تبدئي أي جملة بعبارات مثل: «لا» أو «لكن» أو «هذا غير ممكن». وبدلًا من ذلك، تواصلي مع طفلكِ بلغة محبة تتضمن حدودًا واضحة. يمكنكِ مثلًا أن تقولي: «يمكنك تناول هذا بعد إنهاء طعامك»، أو «يمكنني شراء تلك اللعبة عندما يحين يوم شراء الألعاب»، أو «أعرف أنك تحب هذا الثوب كثيرًا وأتفهمك. يمكنك ارتداؤه مجددًا عندما يصبح الطقس دافئًا». ستفيدكِ مثل هذه التوضيحات. إذا بدأتِ جملكِ بكلمة «لا»، فسيصبح التواصل أكثر صعوبة، لأنه سيجيبكِ بدوره فورًا بكلمة «لا» عندما تطلبين منه شيئًا. اشرحي لطفلكِ سبب تعذر تحقيق ما يريده وقدّمي له بدائل. وإذا ظل غاضبًا رغم حديثكِ الهادئ، فحافظي على هدوئكِ وقولي: «حسنًا، سأنتظر حتى تهدأ. عندما تختار أحد الخيارات، يمكننا متابعة لعبتنا من حيث توقفنا»، ثم انتظري. سيساعد هدوؤكِ واتزانكِ طفلكِ على الهدوء أيضًا.') WHERE id = '72c2f63f-5be1-4b2b-b6e5-eaccc64d9c5d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد البيض، بعد حليب الأم، ثاني أهم غذاء يجمع مختلف المغذيات الكبرى والصغرى. ونعلم أنكِ تولين البيض أهمية كبيرة في تغذية طفلكِ. لكن مصطلحات مثل البيض الطبيعي وبيض المزارع والبيض العضوي قد تسبب بعض الالتباس أحيانًا. فعندما يُقال «بيض الدجاج الحر»، يتبادر إلى أذهان معظم الناس دجاج يتجول بحرية في الريف، لكن الأمر ليس كذلك دائمًا. فهذا المصطلح يشير ببساطة إلى نمط إنتاج يُسمح فيه للدجاج بالحركة في مساحة مفتوحة محددة بدلًا من البقاء في أقفاص ضيقة، وقد لا تختلف قيمته الغذائية كثيرًا عن البيض العادي. أما في إنتاج البيض العضوي، فيُشترط أن يكون العلف خاليًا من الكائنات المعدلة وراثيًا، وألا تكون الأسمدة الكيميائية قد استُخدمت في التربة لمدة 3 سنوات على الأقل. وانطلاقًا من ذلك، توصي الجهات المستقلة باستهلاك البيض العضوي بدرجة أكبر.') WHERE id = '0d3c6f23-838a-4186-987c-62162e29d087';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين أن طفلكِ يبلل فراشه خلال هذه المرحلة، فهذه الحالة من أكثر الشكاوى شيوعًا في مجال صحة الأطفال وأمراضهم. وبوجه عام، قد تكون هناك 3 أسباب رئيسية للتبول اللاإرادي ليلًا لدى الأطفال: اختلال التوازن بين عضلات المثانة، مثل ضعف العضلة التي تمنع خروج البول، أو صغر حجم المثانة، أو إنتاج الجسم كمية من البول تفوق المعدل الطبيعي. لذلك، حاولي ألا تجعلي طفلكِ يشرب كميات مفرطة من الماء خلال الساعتين السابقتين للنوم. كما ينبغي التأكد من عدم وجود التهاب في المسالك البولية. ومن المهم جدًا حجز موعد مع طبيب الأطفال للتحقق مما إذا كان هناك اضطراب هرموني.') WHERE id = '706d264f-8089-480e-811b-db2ce4f82fa7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إلقاء نفسه على الأرض، أو الركض وضرب رأسه بالحائط، أو الصراخ عند الغضب، أو نوبات البكاء التي تكون عادةً من دون دموع، أو عدم معرفة ما يريده... هل تبدو لكِ هذه السلوكيات مألوفة أيضًا؟ 😊 إذا بدأتِ تلاحظين هذه الحالات مجددًا لدى طفلكِ، فاعلمي أنكِ لستِ وحدكِ. ففي هذه اللحظة، تتعامل آلاف الأسر معكِ مع واحدة من هذه المتلازمات التي تبدو بلا نهاية. وقد تظهر أعراض متلازمة سن 3 سنوات بصورة أكثر حدة خلال هذه المرحلة. وكلما كان تواصلكِ مع طفلكِ أقوى، استطعتِ اجتياز هذه المرحلة بسهولة أكبر. ورغم أن هذه الفترة قد تكون أصعب قليلًا مع الأطفال الذين يجدون صعوبة في التعبير عن أنفسهم، فتذكري أنها مجرد مرحلة عابرة. من المهم جدًا أن تتحلي بالصبر وتدركي أن هذه الحالة مؤقتة.') WHERE id = 'aad09a79-e81c-43b7-ab90-cbeb4244addf';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ خلال هذه المرحلة إدخال العسل بسهولة ضمن وجبة إفطار طفلكِ. وإذا كان يواجه صعوبة في ابتلاعه، فيمكنكِ دهنه على الخبز. يُعد العسل مصدرًا غنيًا بالفوائد للأطفال بفضل ما يحتويه من فيتامينات ومعادن وبروبيوتيك وبريبايوتيك. ومن المعروف أنه يقوّي المناعة ويساعد على الوقاية من الأمراض من خلال زيادة أعداد كريات الدم البيضاء والخلايا اللمفاوية، وهي الخلايا التي تدافع عن الجسم. كما يساهم في زيادة خلايا الدم الحمراء والوقاية من فقر الدم الناجم عن نقص الحديد، ما ينعكس إيجابًا على النمو الجسدي والعصبي، وحتى على مستوى الذكاء. ولكن نظرًا إلى كثرة المنتجات المغشوشة في الأسواق، احرصي على اختيار عسل عضوي من علامة تجارية موثوقة وعالية الجودة. وإذا كان طفلكِ سيتذوق العسل للمرة الأولى، فلا تنسي اتباع قاعدة الأيام الثلاثة تحسبًا لحدوث حساسية.') WHERE id = '56e68160-3db6-4a51-9004-f5ed90328cb8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نعلم أنكِ تولين تغذية طفلكِ أهمية كبيرة، لكن لا تنسي أن النوم الليلي المتواصل لا يقل أهمية عن التغذية لنموه الصحي؛ فالأطفال ينمون بالفعل أثناء النوم. خلال النوم، ولا سيما في الظلام، يُفرز هرمون الميلاتونين. ويساعد هذا الهرمون على تقوية المناعة، كما يحفز الغدة النخامية على إفراز المزيد من هرمون النمو. وخلال النوم، يخزّن رضيعكِ في دماغه المعلومات التي تعلّمها طوال اليوم، ما يعزز الروابط بين خلايا الدماغ. ويستقبل الطفل الذي نام جيدًا وحصل على قسط كافٍ من الراحة يومه الجديد بطاقة أكبر، ويكون أكثر حماسًا للتعلم واستمتاعًا باللعب.') WHERE id = 'd38c5b0c-a2eb-49b2-9b6a-81efef827283';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ خلال هذه المرحلة شراء ألعاب المهن لطفلكِ، مثل أطقم النجارة أو الطب أو الطهي. ويوصي اختصاصيو نمو الطفل بهذا النوع من الألعاب لما له من إسهام كبير في نموه. ويمكنكِ اختيار هذه الألعاب للفتيات والفتيان على حد سواء. ويشير الاختصاصيون إلى أن تعريف الأطفال بجميع أنواع اللعب، من دون التمييز بين الألعاب، يفيد في تطور هويتهم الجنسية بشكل صحي. وبالطبع، قد يفضّل طفلكِ بعض الألعاب بما يتوافق مع ميوله الفطرية، كميل الفتيات إلى الدمى والفتيان إلى السيارات مثلًا. لكن تذكّري أن المهن لا ترتبط بجنس معين، ولا تقيّدي طفلكِ في هذا الجانب.') WHERE id = 'b8d6b288-c63d-469e-a5b5-b302aabd5be2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين خلال هذه المرحلة أن مشاعر رضيعكِ أصبحت أكثر حساسية. فعلى سبيل المثال، عندما يرى شخصًا يبكي، يهتم بمعرفة سبب بكائه، وقد يشاركه حزنه ويتأثر بشدة. ومع تنامي شعوره بالتعاطف، يحاول تهدئة الشخص الباكي، فيربّت على خده ويقوم بتصرفات تواسيه. وبالطبع، يفعل كل ذلك لأنه تعلّمه منكِ. وتذكّري أنكِ، بصفتكِ معلمته الأساسية، قدوته في كل شيء. خلال هذه الأشهر، يبدأ أيضًا في إدراك مشاعركِ؛ فعندما تكونين سعيدة أو متوترة أو حزينة، يحاول البقاء إلى جانبكِ. كما يفهم التصرفات التي تثير لديكِ هذه المشاعر، وعندما يواجه الموقف نفسه مستقبلًا، سيتصرف على الأرجح مثلكِ تمامًا. وفي الوقت نفسه، عليكِ أن تحاولي فهم طفلكِ، لأنكِ الشخص الأساسي الذي يربيه ليصبح فردًا ناضجًا. ولكي يتمكن من التواصل مع الآخرين بطريقة سليمة، علّميه التعاطف وجمال مساعدة من يحتاجون إلى العون. وعلّميه أيضًا التعبير عن الشكر والتصرف بأدب، وأظهري له أن الكلمة الطيبة تفتح كل الأبواب. كذلك شجّعي رضيعكِ للتخفيف من مشاعر الخجل التي قد تظهر في هذا العمر، وادعميه لينمو شخصًا واثقًا بنفسه.') WHERE id = '0ce0c599-580b-4527-aa93-807483cb4649';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تكون لديكِ بعض الأسئلة حول الطريقة المناسبة لتغذية رضيعكِ خلال هذه المرحلة. لذلك نقدم لكِ نموذجًا لقائمة توضح ما يمكن لطفلكِ البالغ من العمر 33 شهرًا تناوله خلال يوم واحد! في وجبة الإفطار: عجة بالزبدة مع الأعشاب والجبن + 2-3 حبات زيتون + شريحة واحدة من خبز القمح الكامل، لتضمني حصول طفلكِ على مختلف المجموعات الغذائية. وفي الوجبة الخفيفة: ثمرة فاكهة صغيرة واحدة + 2-3 حبات تين مجفف + حبة جوز كاملة، لتلبية احتياجاته من الطاقة. وفي وجبة الغداء: سمك سلمون مطهو في الفرن + شريحة واحدة من خبز القمح الكامل؛ وإذا لم يتوفر السمك، يمكنكِ تقديم طبق من البقوليات مع الدجاج أو اللحم بدلًا منه. وفي الوجبة الخفيفة التالية: تكفي قطعتان من بسكويت الشوفان المنزلي الخالي من السكر + نصف كوب من عصير الفاكهة. أما في وجبة العشاء، فيمكنكِ تقديم أرز بالخضراوات + نصف وعاء من الزبادي. ويمكنكِ أيضًا، حسب الرغبة، تقديم كوب واحد من الحليب قبل النوم ليلًا.') WHERE id = '549b2994-2980-4e78-85f4-a5477bf37526';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يميل النمو الذهني لرضيعكِ إلى التسارع خلال هذه المرحلة، لذلك من المهم أن تختاري ألعابًا تحفز نموه وتنشّط دماغه. وبما أن قدرته على الحركة قد تطورت كثيرًا، يمكنكِ شراء دراجة ثلاثية العجلات له. ومن خلال إتاحة ركوب الدراجة له في بيئة آمنة، ستساعدينه على التفاعل الاجتماعي وتفريغ طاقته بطريقة مفيدة. وفي الأيام التي تقضونها في المنزل، يمكنكِ اختيار ألعاب تركيب أو أحاجٍ ذات قطع كبيرة لتعزيز مهاراته اليدوية. وبما أنه يقلدكِ في الأعمال المنزلية، يمكنكِ أيضًا شراء أطقم مطبخ وأدوات منزلية صغيرة مخصصة للعب. ولأن رغبته في الوثب والقفز والطرق تكون كبيرة خلال هذه المرحلة، فستكون ألعاب مثل الطبل أو عصي الإيقاع مفيدة جدًا. وتُعد هذه الألعاب كلها وسائل ممتازة لتنمية المهارات الحركية الدقيقة والكبيرة لدى رضيعكِ.') WHERE id = '369cc37b-2f9a-4abf-a1f2-8c6ddb44235b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ الاستفادة من التوابل لحماية طفلكِ من الأمراض، وتقوية جهازه المناعي، أو ببساطة منحه الطاقة. وإلى جانب قوتها المضادة للأكسدة، تتمتع التوابل بالعديد من الخصائص المضادة للالتهابات. وتساعد مضادات الأكسدة الموجودة فيها، مثل البيتا كاروتين والسيلينيوم وفيتامينات A وC وE، على حماية طفلكِ من مشكلات صحية عديدة، بدءًا من أمراض القلب وصولًا إلى السرطان. فعلى سبيل المثال، تشير الأبحاث إلى أن الكركم يؤثر إيجابيًا في صحة الدماغ والتطور المعرفي المرتبط بالعمر. ووفقًا لدراسة أخرى، تحتوي ملعقة صغيرة من الزنجبيل على كمية من مضادات الأكسدة تعادل تلك الموجودة في كوب من السبانخ. لذلك، يمكنكِ استخدام التوابل الصحية في غذاء طفلكِ باطمئنان، شرط عدم الإفراط في كميتها واستشارة طبيبكِ دائمًا.') WHERE id = 'c72aa2b5-e59d-4e6f-ad3f-c7a037c197ef';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عند الإجابة عن أسئلة طفلكِ، من المهم أن تشجعيه أيضًا على البحث في الموضوع والتفكير فيه. فعلى سبيل المثال، يمكنكِ تحفيزه على التفكير بطرح أسئلة مثل: «لماذا تعتقد أن الأمر قد يكون كذلك؟»، و«ما رأيك؟»، و«هل لديك تخمين؟». فالطفل الذي تجيبين عن أسئلته يستطيع أيضًا الاستفسار بسهولة أكبر في المدرسة عن الموضوعات التي لا يفهمها. وقد لوحظ أن الأطفال الذين يطرحون أسئلة أكثر على معلميهم يحققون نجاحًا دراسيًا أكبر. وعلى العكس من ذلك، يشعر الأطفال الذين تُترك أسئلتهم بلا إجابة أو يتم تجاهلها بأنهم غير مقدَّرين، ويترددون في طرح الأسئلة في المدرسة. وكلما ازداد طفلكِ تفكيرًا وتساؤلًا وبحثًا، زادت فرص نجاحه في المستقبل. لذلك، من المهم جدًا أن تجيبي عن أسئلة طفلكِ بصبر قدر استطاعتكِ.') WHERE id = '5b153890-626c-4f66-9895-e87a3626f96f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هل تختارين الحليب المعبأ الذي يُباع في المتاجر أم الحليب الخام المحلوب من البقرة؟ يُعد هذا السؤال منذ سنوات من أبرز المسائل التي تشغل أذهان الأمهات. فبينما يرى بعضهن أن غلي الحليب الخام في المنزل خيار أكثر صحة، تفضّل أخريات الحليب المبستر أو المعالج بالحرارة الفائقة UHT. إذا لم يكن مصدر الحليب الخام وظروف نقله معروفين تمامًا، فقد ينطوي على مخاطر كبيرة. إذ يمكن أن تسبب البكتيريا الضارة الموجودة فيه تفاعلات مختلفة في جسم طفلكِ. كما قد يشكل إعطاء المضادات الحيوية للبقرة أو تخزين الحليب في ظروف غير صحية خطرًا أيضًا. ومن هذا المنطلق، يُعد اختيار الحليب اليومي المبستر أكثر أمانًا لصحة طفلكِ من شراء الحليب السائب من مصادر لا تثقين بها.') WHERE id = 'e3a23f3e-4fd8-4dbb-ac95-29d46ad09622';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أوشك طفلكِ على بلوغ نهاية مرحلة الطفولة المبكرة، وقد أصبح الآن طفلًا شغوفًا باللعب بكل معنى الكلمة. يمكنه قضاء يومه بأكمله في اللعب من دون أن يشعر بالملل، ويرغب دائمًا في إشراككِ في ألعابه. فاللعب هو الوسيلة الأكثر فاعلية لمساعدة طفلكِ على فهم العالم وتعلّم أشياء جديدة. ويُنصح بأن تختاري له ألعابًا بنّاءة وإبداعية بدلًا من الألعاب التي تروّج للعنف، مثل الأسلحة والمسدسات. وبما أنه يبدأ تدريجيًا دخول مرحلة ما قبل المدرسة، يمكنكِ مساعدته على تعلّم الحروف والأرقام، لكن لا تتعجلي في ذلك. فإذا لاحظتِ أنه يبدي اهتمامًا بالأرقام والحروف، يمكنكِ تعليمه إياها من دون ضغط. وباختصار، إذا كان متحمسًا للتعلّم من تلقاء نفسه، فعليكِ بالطبع دعمه.') WHERE id = 'e878f726-41d1-4bee-844c-9a7d1fa53eaa';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في عصرنا الحالي، أصبح من الممكن العثور على معظم أنواع الفاكهة والخضراوات في جميع الفصول تقريبًا. لكن عندما يتعلق الأمر بتغذية طفلكِ، تكون المنتجات المزروعة في موسمها ألذ وأكثر فائدة للصحة. ولأنها تنمو بصورة طبيعية، فهي غنية بالفيتامينات والمعادن. فعلى سبيل المثال، تبيّن وجود فرق يصل إلى ثلاثة أضعاف في محتوى فيتامين C بين السبانخ المحصودة في الشتاء وتلك المحصودة في الصيف. ومن ناحية أخرى، تكون المنتجات المحلية أكثر طزاجة وفائدة من المنتجات التي تأتي من أماكن بعيدة. وتذكّري أنه مع تغيّر الطبيعة والمناخ في كل فصل، تتغيّر احتياجات جسم طفلكِ، مثلما تتغيّر احتياجات جسمكِ. لذلك، من الأفضل اتباع نظام غذائي ينسجم مع نظام الطبيعة المتوازن.') WHERE id = '00332087-6a8f-4e62-b2f8-03640f4bf4b5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ تفكرين في نقل طفلكِ إلى سرير مستقل، فنود تذكيركِ بأنكما في مرحلة مناسبة جدًا للقيام بذلك. ولتسهيل هذه المرحلة الانتقالية، يمكنكِ مساعدته على النجاح بالثناء عليه وتشجيعه باستمرار. لكن انتبهي إلى أنه بعد أن يعتاد طفلكِ سريره الجديد، قد يصعد إلى سريره الكبير وينزل منه لمجرد أن يثبت قدرته على ذلك. وإذا نهض، فكوني هادئة ولكن حازمة. يمكنكِ إعادته إلى سريره، وإخباره ببساطة أن وقت النوم قد حان، ثم تركه بمفرده. وإذا قاوم، يمكنكِ الاستفادة من توصيات اختصاصيي النوم: ربّتي على ظهره وأخبريه أن كل شيء على ما يرام، لكن وقت النوم قد حان. لا تحمليه ولا تستلقي بجانبه؛ كوني لطيفة ولكن حازمة. انتظري خمس دقائق ثم عودي للاطمئنان عليه. كرري هذه العملية حتى يغفو، مع إطالة مدة الانتظار قليلًا في كل مرة. وإذا التزمتِ بروتين ثابت وحازم عند وقت النوم، فستتلاشى حالات الاستيقاظ ليلًا خلال بضعة أسابيع.') WHERE id = '4078f349-ac2c-48e1-a276-0ec6e642a5ee';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ أمًا عاملة وتشعرين بأنكِ لا تقضين وقتًا كافيًا مع طفلكِ، فلا تحزني أبدًا. يؤكد المختصون أن جودة الوقت الذي تقضينه مع طفلكِ أهم من مدته. فنصف ساعة أو ساعة من الوقت الممتع والمفيد معه بعد عودتكِ من العمل قد تكون أحيانًا أكثر فائدة بكثير من قضاء يوم كامل معًا دون تفاعل حقيقي. كما أن عطلات نهاية الأسبوع ملك لكِ أيضًا! يمكنكِ خلالها الخروج مع أسرتكِ في نزهات طويلة أو ركوب الدراجة أو ممارسة ألعاب الكرة المختلفة. ويُعد الذهاب معًا إلى مراكز ترفيه الأطفال وقضاء وقت ممتع خيارًا رائعًا أيضًا. تذكّري أن مكانتكِ لدى طفلكِ تختلف عن مكانة الجميع مهما كانت الظروف، وستظل كذلك دائمًا. لذلك لا ترهقي نفسكِ، وركّزي على اللحظات الجميلة التي تستطيعان الاستمتاع بها معًا بدلًا مما لم تتمكني من إنجازه.') WHERE id = 'd9001d20-5e18-461f-a3d5-cec998022416';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد أكملتِ شهرًا آخر برفقة طفلكِ. أهلًا بكِ في الشهر الرابع والثلاثين! 😊 لا يختلف نمو طفلكِ البالغ من العمر 34 شهرًا خلال هذه الفترة كثيرًا عن الشهر السابق. وأهم تطور هذا الشهر هو أن طفلكِ أصبح الآن مستعدًا تمامًا للالتحاق بالتعليم ما قبل المدرسي. كما تجدر الإشارة إلى أن مرحلة صعبة بعض الشيء، لكنها ممتعة، تنتظركِ مع دخول طفلكِ ما يُعرف بمتلازمة سن الثالثة. خلال هذه المرحلة، التي تُسمى أيضًا أزمة سن الثالثة، سيبدأ طفلكِ باكتشاف الأنا لديه. وتُعد الأنا أحد أهم مكونات بنية الشخصية. وتتكون الشخصية من ثلاثة مكونات أساسية مترابطة تشمل الدوافع والرغبات والاحتياجات، والأنا، والقيم والمعتقدات والضمير. وتؤدي الأنا دور الموازن بين هذه المكونات. ومن هذا المنظور، يتضح أن للأنا مكانة بالغة الأهمية في صحتنا النفسية. نحن في عائلة Anacan إلى جانبكِ دائمًا!') WHERE id = 'a8ffabb9-3040-4b25-bec5-5f9659629255';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لم تُخضعي طفلكِ لفحص شامل للعينين في سن الثانية، فمن المهم جدًا إجراء هذا الفحص قبل أن يبلغ الثالثة. إذ يجب فحص العينين قبل سن الثالثة للكشف عن الحَوَل وكسل العين ومختلف عيوب الإبصار. يكتمل نمو الجهاز البصري لدى الأطفال خلال السنوات التسع الأولى، ولا تطرأ عليه بعد ذلك تغيرات كبيرة. لذلك، وكما هو الحال مع جميع الأطفال، ينبغي أن يفحص طبيب عيون طفلكِ قبل بلوغه سن الثالثة، حتى إن لم تكن لديه أي مشكلة ظاهرة. وقد يتعذر علاج كسل العين في مراحل عمرية متقدمة إذا نتج عن اضطرابات بصرية لم تُعالج حتى سن 9-10 سنوات. بالإضافة إلى ذلك، تزداد احتمالية مواجهة الأطفال الذين يعانون من عيوب بصرية صعوبات في التعلم في المدرسة. لذا، كلما اكتُشفت المشكلة مبكرًا، زادت فرص نجاح العلاج.') WHERE id = 'e386827d-ad41-4c20-bd38-219ad4b81467';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ ترغبين في أن ينام طفلكِ طوال الليل دون انقطاع، فعليكِ تعويده على الخلود إلى النوم بمفرده. وإلا فستضطرين إلى الاستيقاظ في كل مرة يستيقظ فيها لمساعدته على النوم مجددًا. وربما لم يعد سرير الرضع مناسبًا لحجم طفلكِ، ما قد يؤثر سلبًا في جودة نومه. ويمكنكِ شراء سرير يناسبه لضمان نوم صحي ومريح. وتتمثل أكثر مشكلتين شيوعًا في نوم الأطفال بمختلف الأعمار في صعوبة الخلود إلى النوم والاستيقاظ المتكرر. وإذا كنتِ تريدين أن ينام طوال الليل دون أن يناديكِ، فمن الضروري أن يتعلم تهدئة نفسه والعودة إلى النوم، مثلًا من خلال احتضان لعبة أو غرض يحبه. وليس من الصواب أن يعتاد طفلكِ على الموسيقى أو الضوء أو الطعام كي يخلد إلى النوم، لأن هذه العادة غير السليمة ستجعله يطلب الأشياء نفسها ليتمكن من النوم مجددًا عندما يستيقظ ليلًا.') WHERE id = '4ab036c3-4a94-40eb-b15f-cc5e03491b45';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المهم جدًا خلال هذه الفترة أن يتناول طفلكِ أطعمة غنية بالكالسيوم لدعم نمو عظامه. لذلك ينبغي أن يشرب يوميًا كوبين من الحليب أو يتناول كمية مكافئة من منتجات الألبان. ويمكنكِ إدراج منتجات الألبان ضمن وجبات طفلكِ الرئيسية ووجباته الخفيفة. وأهم ما يجب الانتباه إليه عند اختيار الحليب هو أن يكون طازجًا ومبسترًا. وحاولي أيضًا قدر الإمكان تحضير الزبادي في المنزل بنفسكِ باستخدام حليب مبستر. وإذا كان طفلكِ لا يحب مذاق الحليب ولا يرغب في شربه، فتجنبي تحليته بالسكر أو إضافة مواد أخرى لتغيير نكهته. ويمكنكِ بدلًا من ذلك تقديم منتجات ألبان بديلة له، مثل الزبادي والجبن القريش والجبن.') WHERE id = 'eeb8003d-add3-422d-9fd8-3b5b9e6003eb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بلغ فضول طفلكِ مستوى قد يدفعه إلى طرح أسئلة كثيرة لدرجة قد تُشعركِ بالتعب أحيانًا. ومع تطور مهاراته اللغوية، قد تسمعين منه مرارًا أسئلة مثل: لماذا؟ لماذا ننام ليلًا؟ لماذا ينمو التفاح على الأشجار؟ لماذا يهطل المطر؟ وبالطبع قد ترهقكِ هذه الأسئلة التي لا تنتهي، كما يحدث مع جميع الآباء والأمهات. لكن تذكّري أن طرح الأسئلة دليل على نمو طفلكِ المعرفي وسعيه إلى اكتشاف العالم، فهو يتعلم من خلال الأسئلة. وعندما تشعرين بالتعب، لا ترفضي سؤاله أو تصدّيه، بل تعاملي معه بلطف وقولي مثلًا: هل يمكنني الإجابة عن سؤالك بعد قليل؟ لأن إجاباتكِ وحدها قد تطمئنه عندما يواجه أمرًا يربكه أو يثير قلقه.') WHERE id = '2fa7ea2e-a30f-47c2-aef5-ed3fe5788bde';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ لا يأكل الخضروات وكان هذا الأمر يقلقكِ، فاعلمي أنكِ لستِ وحدكِ في مواجهة هذه المشكلة. غالبًا ما تكون الخضروات من أقل الأطعمة تفضيلًا لدى الأطفال، رغم أنها من أكثرها أهمية لهم. توجد جميع الفيتامينات تقريبًا في أنواع مختلفة من الخضروات والفواكه. لذلك، احرصي على تنويع غذاء طفلكِ قدر الإمكان. وإذا لم يحب الخضروات المطهية، فيمكنكِ إعداد سلطة من الخضروات التي يمكن تناولها نيئة. أما بالنسبة إلى الوجبات الخفيفة، فالفواكه هي الخيار الأفضل. وبهذه الطريقة، ستُبعدين طفلكِ أيضًا عن تناول السكر والشوكولاتة دون حاجة. ليس من الضروري أن يحب طفلكِ كل نوع من الخضروات أو الفواكه؛ فله ذوقه الخاص مثل البالغين. ويكفي أن يتناول 2-3 أنواع من كل مجموعة غذائية. قد يؤدي إجباره على الأكل إلى زيادة نفوره من الطعام.') WHERE id = '93e9401a-1194-4460-ab5a-1ff01deaad41';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'وفقًا للرأي العام للخبراء، يحتاج الأطفال الذين تتراوح أعمارهم بين سنتين وثلاث سنوات إلى 11 ساعة من النوم ليلًا، وإلى قيلولة نهارية مدتها نحو ساعة ونصف أو ساعتين. ينام معظم الأطفال في هذا العمر بين الساعة 19:00 و21:00 مساءً، ويستيقظون بين الساعة 06:30 و08:00 صباحًا. ورغم أن نمط نوم طفلكِ يصبح تدريجيًا أكثر شبهًا بنمط نومكِ، فإنه سيظل حتى سن 4 سنوات يقضي وقتًا أطول منكِ في مرحلة نوم حركة العين السريعة (REM) الخفيف. ونتيجة لذلك، سيستيقظ طفلكِ ليلًا أكثر منكِ بسبب كثرة الانتقال بين مراحل النوم. لهذا السبب تحديدًا، إذا أردتِ أن ينام طوال الليل دون انقطاع ومن دون إيقاظكِ، فمن المهم أن تعلّميه كيفية العودة إلى النوم بمفرده. واحرصي خصوصًا على إبعاده قبل النوم عن الأجهزة التكنولوجية التي تؤثر في العقل الباطن، مثل التلفاز والجهاز اللوحي والهاتف. فقد تتسبب هذه الأجهزة في تقطّع نوم طفلكِ بوتيرة أكثر من المعتاد.') WHERE id = '2c2d7b4a-f9e9-4546-9aa6-71036a012509';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ في هذه المرحلة شراء أقلام تلوين وكتب تلوين وأنشطة تساعد طفلكِ على تطوير مهاراته الحركية الدقيقة. وممارسة الأنشطة معه، ولا سيما باستخدام كتب الأنشطة المناسبة لعمره، تساعدكما على قضاء وقت ممتع وهادف معًا، كما تتيح لطفلكِ التعلّم من خلال اللعب والمرح. إن تخصيص ما لا يقل عن 1-2 ساعة يوميًا للعب الألعاب التعليمية معًا هو من أفضل الاستثمارات التي يمكنكِ تقديمها لمستقبل طفلكِ. فعلى سبيل المثال، يُعد تكوين شكل كامل من قطع صغيرة من أكثر الألعاب تشويقًا في هذه المرحلة. لذلك، قد تكون الأحجيات والألعاب ذات القطع المتداخلة ومجموعات الليغو طوق نجاة حقيقيًا لطفلكِ الذي لا تنفد طاقته. وتزداد هذه الألعاب تعقيدًا مع تقدمه في العمر، إذ تتطلب مهارات حركية أكثر تطورًا. وهذا يتيح لطفلكِ اكتساب قدرات جديدة والشعور بمتعة النجاح.') WHERE id = 'b66a0d11-0af2-4535-8154-1f619d2a0bfa';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تكون لديكِ أسئلة حول نظام طفلكِ الغذائي وحجم حصصه في هذه المرحلة. لقد أعددنا لكِ نموذجًا لقائمة غذائية ليوم واحد! 😊 من الرائع أن تبدئي وجبة الإفطار بشريحة واحدة من خبز القمح الكامل المحمّص، وملعقة شاي واحدة من زبدة الفول السوداني، ونصف كوب من الحليب. وللوجبة الخفيفة، يمكنكِ اختيار نصف كوب من الفراولة، أو نصف كوب من الزبادي، أو رقائق الذرة الصحية (الموسلي). وفي الغداء، يمكنكِ إعداد وجبة غنية تتكون من شريحة واحدة من خبز النخالة، وقليل من السمك، وحبة بطاطس صغيرة مسلوقة، وبرتقالة صغيرة واحدة. أما الوجبة الخفيفة التالية، فيمكنكِ تقديم 5 قطع من مقرمشات الحبوب المحضرة منزليًا، أو 5 حبات من اللوز النيئ، أو شريحة واحدة من خبز القمح الكامل مدهونة بدبس الفاكهة/العسل. وفي العشاء، سيكون نصف جزرة و30 غرامًا من الخضروات، إلى جانب 30 غرامًا من لحم العجل أو الدجاج، ونصف وعاء من برغل البيلاف، خيارًا مشبعًا ومفيدًا.') WHERE id = '443f9eda-baee-4eb9-a55b-b12c4d58ecb1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'رغم أن نمو طفلكِ الجسدي يتباطأ في هذه المرحلة، فإن نموه الذهني يستمر بوتيرة سريعة. أصبح طفلكِ الآن قادرًا على تسمية الصور التي تعبّر عن الحركة والأفعال بسهولة. وإذا كنتِ قد علّمتِه ذلك مسبقًا، فيمكنه مطابقة الأشكال الهندسية مع صورها. كما يمكنه إدخال 5 حلقات في عمود بالترتيب من الأكبر إلى الأصغر أو من الأصغر إلى الأكبر. ويستطيع التمييز بين الأشياء الخفيفة والثقيلة. بل يمكنكِ أيضًا متابعة وزنه بالكيلوغرامات معه، وسيستمتع بذلك كثيرًا. ويمكن لطفلكِ كذلك جمع نصفي صورة لتكوين صورة كاملة. وعندما تسألينه، يستطيع الإشارة إلى الأشياء الطويلة والقصيرة. كما يمكنه العثور على الأشياء المرتبطة ببعضها، مثل معجون الأسنان وفرشاة الأسنان، أو الدمية ورضّاعة الأطفال. إن تعلّمه كل هذه الأمور خلال مدة قصيرة دليل على مدى استعداد دماغ طفلكِ للتعلّم.') WHERE id = '7f5ccfc6-4475-4f0c-8f31-12479dd8da41';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هذه المرحلة وقت مناسب لتغيير سرير طفلكِ، لأنه إذا كان لا يزال يستخدم مهد الرضع، فسيصبح من الصعب عليه أن يتسع فيه مع مرور الوقت. وقد يؤدي انضمام فرد جديد إلى الأسرة إلى تسريع هذا القرار أيضًا؛ فإذا كنتِ حاملًا أو تخططين للحمل، فعليكِ نقل طفلكِ الأكبر إلى سريره الجديد قبل ولادة الرضيع بما لا يقل عن 6-8 أسابيع. فمن الأفضل نفسيًا أن يعتاد طفلكِ الأكبر على سريره الجديد قبل أن يأتي المولود الجديد و«يأخذ» مهده منه. وإذا واجه صعوبة كبيرة في هذا الانتقال، فيمكنكِ تأجيل التغيير حتى يبلغ الرضيع الجديد عمر 3-4 أشهر. فبينما يقضي الرضيع الجديد هذه الأشهر نائمًا في أي مكان مناسب، سيعتاد طفلكِ الأكبر أيضًا على فرد الأسرة الجديد، ما يجعل الانتقال أسهل. ومن الأسباب الأخرى لتغيير السرير تعلّم استخدام المرحاض؛ إذ ينبغي لطفلكِ أن يتعلم الذهاب إلى المرحاض ليلًا دون إيقاظكِ. ومن المهم جدًا أن تشجعيه على ذلك، سواء لاكتساب هذه العادة أو لتحسين جودة نومكِ.') WHERE id = 'b162f1d9-6368-4367-b8db-fde84325b9ed';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا بد أنكِ لاحظتِ مؤخرًا تطورًا كبيرًا في مهارات طفلكِ اللغوية. فمثلًا، قد يتمكن من إجراء حوار مكوّن من جملتين أو ثلاث، وقد يبدأ باستخدام اللواحق في الجمل. كما يستطيع تكوين جمل صحيحة مثل: «هذه لعبة»، واستخدام تصنيفات مثل الألعاب والحيوانات والأطعمة. ويستخدم صيغ الرغبة والمستقبل، كما يمكنه وصف الأشياء بأنها مفتوحة أو مغلقة. ويستعمل أدوات الاستفهام في مواضعها الصحيحة، ويمكنه ذكر اسمه واسم عائلته عند سؤاله، رغم أنه قد لا يرغب دائمًا في ذكر اسمه لأشخاص لا يعرفهم. كذلك يمكنه تنفيذ مهمتين متتاليتين غير مرتبطتين ببعضهما. فمثلًا، إذا قلتِ له: «هل يمكنك التقاط الورقة من الأرض ورميها في سلة المهملات؟»، فسينفذ كلا الفعلين بالترتيب. ومع ذلك، إذا كان كلامه لا يزال غير واضح تمامًا، فقد يكون من المفيد أن تدرّبيه على بعض تمارين النطق.') WHERE id = '78c832c1-4c0d-4309-9e24-09ccab108546';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ يُصاب بالإسهال كثيرًا، فعليكِ أولًا الانتباه إلى الأطعمة التي يتناولها. فمثلًا، تُعد أطباق الخضراوات مفيدة جدًا، لكن الإفراط في التوابل قد يسبب الإسهال لدى الطفل. ومن المعروف أن الفلفل الحار على وجه الخصوص قد يُحدث هذا التأثير. كما قد يكون تناول الأطعمة المقلية بكثرة سببًا آخر؛ لذا ينبغي ألا يتناول طفلكِ الأطعمة المقلية أكثر من مرة واحدة أسبوعيًا. وإذا كان الإسهال قد يسبب الجفاف حتى لدى البالغين خلال فترة قصيرة، فقد يكون تأثيره في الأطفال أشد بكثير. لذلك من المهم ألا تنسي أن كل طعام تقدمينه لطفلكِ يؤثر مباشرةً في صحته.') WHERE id = 'c8770cc7-96b4-4f44-abc5-fe4118707f16';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُنصح في هذه المرحلة بأن تبدئي تدريجيًا في إعداد طفلكِ للتعليم قبل المدرسي. ففي السابق، كان التعليم قبل المدرسي يُنظر إليه غالبًا بوصفه حلًا للأمهات العاملات، لكن الخبراء يتفقون اليوم على ضرورة حصول جميع الأطفال عليه. ومع نمو طفلكِ وبدئه في التعبير عن نفسه، يصبح من الصعب عليكِ بصفتكِ أمًا تلبية جميع اهتماماته واحتياجاته بمفردكِ. فأطفال عصرنا أكثر فضولًا وانفتاحًا على التعلّم. ويُعد التعليم قبل المدرسي بالغ الأهمية لنمو طفلكِ نموًا صحيًا وتكوّنه كشخص مستقل. وتشير الدراسات إلى أن الأطفال يتعلمون في هذه المرحلة بسرعة وفاعلية كبيرتين. كما أن تواصله مع أقرانه في بيئة جسدية واجتماعية مناسبة يضع أساسًا متينًا لنجاحه في المستقبل.') WHERE id = '09cc45a6-5357-478d-806f-e921dc4066af';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هل خطر ببالكِ يومًا أن طفلكِ قد يُصاب في هذا العمر بالاكتئاب مثل البالغين تمامًا؟ رغم أن هذه الفكرة ليست مقبولة على نطاق واسع في المجتمع، يؤكد الخبراء أن الأطفال أيضًا قد يعانون كثيرًا من الحزن والاكتئاب. وقد تظهر علامات الاكتئاب لدى الأطفال بأعراض متنوعة تختلف عن تلك التي تظهر لدى البالغين. وبوجه عام، قد يكون تشتت الانتباه أو فرط النشاط أو صعوبات التعلّم أو الاضطرابات السلوكية أو الاعتراض المستمر مؤشرات على الاكتئاب. ويُعد قدوم أخ أو أخت جديد إلى الأسرة، على وجه الخصوص، أحد أبرز أسباب اكتئاب الطفل. فقد يساوره حينها القلق متسائلًا: «هل سيتوقف والداي عن حبي؟». وقد يتصرف أحيانًا بعدوانية تجاه الرضيع، أو على العكس، يُظهر له حبًا مفرطًا. ووفقًا للملاحظات السريرية، غالبًا ما يعبّر الطفل الذي يعيش هذا الصراع الداخلي عن مشاعره بعبارة: «أشعر بحزن شديد».') WHERE id = 'd5cee6e1-14a0-4774-a124-d29478e56e0b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هل تدركين مدى تطور مهارات طفلكِ الحركية في هذه المرحلة؟ لقد بلغ الآن مستوى يمكّنه من أداء مهامه اليومية، مثل ارتداء ملابسه وتناول الطعام وجمع ألعابه بعد اللعب وتنظيف أسنانه، دون مساعدة تقريبًا. ولا بد أنكِ لاحظتِ أيضًا تغيرًا في طريقة لعبه. فقد بدأ الآن بابتكار ألعابه بنفسه، وربما تلاحظين أنه يوزع الأدوار والمهام عليكِ وعلى أصدقائه أثناء اللعب. وإلى جانب ذلك، أصبح طفلكِ قادرًا على إجراء قصّات عشوائية بالمقص تحت إشرافكِ. وقد يساعده هذا النشاط على استخدام أصابعه بصورة أفضل، ومن ثم تطوير مهاراته الحركية الدقيقة. ومع ذلك، تذكري أن المقص أداة حادة وخطرة، لذا يجب أن تراقبيه بعناية.') WHERE id = '52831199-fbe3-4b62-ad35-73e2e71edbc4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هل تعلمين أنه يمكنكِ تنمية ذكاء طفلكِ من خلال تحفيز فضوله؟ يمكنكِ الإسهام بدرجة كبيرة في تطوره الفكري بابتكار ألعاب وسيناريوهات تناسب شخصيته. فمثلًا، يمكنكِ إخفاء بعض الأشياء والطلب منه العثور عليها وذكر أسمائها. وأتيحي له فرصة تخمين أشياء مختلفة تلفّينها بورق الألومنيوم، مستعينًا بحاسة اللمس وفضوله. ويمكن أن تكون هذه الأشياء أي شيء موجود في المنزل، مثل ملعقة أو لعبته المفضلة أو كوب بلاستيكي أو حتى بعض مستحضرات تجميلكِ. في بيئة غنية بالفضول، ينخرط طفلكِ في عملية تعلّم نشطة. ولا تسهم الرغبة في التعلّم التي يغذيها الفضول في تنمية ذكاء الطفل فحسب، بل تساعده أيضًا على اكتساب معرفة أعمق من أقرانه بالموضوع الذي يثير اهتمامه.') WHERE id = '6725b944-c3f1-499c-a21a-3bbbd23afe4b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ تفكرين في إلحاق طفلكِ بمؤسسة للتعليم قبل المدرسي، فهناك بعض النقاط التي ينبغي لكِ الانتباه إليها. فمرحلة بدء المدرسة للمرة الأولى تكون مثيرة للأطفال والوالدين على حد سواء. وكلما كنتِ أنتِ وأسرتكِ أكثر ارتياحًا، مرّ طفلكِ بهذه المرحلة الانتقالية بصورة أكثر سلاسة وصحة. ومن المهم جدًا في هذه المرحلة أن تتحلي بالهدوء وتثقي بالمؤسسة التعليمية. ستكون الحضانة أو الصف التمهيدي أول مكان يبتعد فيه طفلكِ عن المنزل من دون وجود أحد من أسرته إلى جانبه. وسيساعده نهجكِ الداعم خلال هذه الفترة على التأقلم مع المدرسة بسهولة أكبر. وبعد اكتمال هذه العملية، سيبدأ طفلكِ في تكوين شخصيته المستقلة داخل المجموعة والتفاعل اجتماعيًا. وفي هذه المرحلة التي يكون فيها شديد التلقي، سيكتسب معارف جديدة بسرعة وفاعلية بفضل مختلف المحفزات المحيطة به.') WHERE id = '88e562a2-5445-4b67-bbd0-d77c240f5606';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح عمر طفلكِ الآن 35 شهرًا. بعبارة أخرى، لم يتبقَّ سوى أيام قليلة حتى يبلغ 3 سنوات! نهنئكِ! 😊 أصبح طفلكِ البالغ من العمر 35 شهرًا فردًا قادرًا على اتخاذ قراراته بنفسه. لذلك سيصعب عليكِ من الآن فصاعدًا توجيهه وفق آرائكِ وحدها كما كنتِ تفعلين سابقًا. وقد يطلب منكِ خلال هذه المرحلة أمورًا مختلفة في مواقف مختلفة، مثل: أريد من أبي أن يطهو الطعام، ومن أمي أن تلعب معي. وعلى الرغم من أن طفلكِ بدأ يكتسب الاستقلالية، فقد يظل مترددًا في القيام ببعض الأمور من دونكِ. لذا ينبغي لكِ تشجيعه على اللعب بمفرده لتعزيز استقلاليته وتعلُّم التحكم في ذاته. تذكري أنه لا يزال طفلكِ الصغير الذي يحاول فهم العالم. والطريقة الأكثر فاعلية لحل المشكلات هي التحدث معه والتواصل معه.') WHERE id = '209004b7-d29a-4345-ba5f-85059bbd8a7e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد لا تطرأ خلال هذه المرحلة تغيرات كبيرة على متوسط طول طفلكِ ووزنه. يبلغ متوسط وزن الأولاد في عمر 35 شهرًا نحو 16 kq، بينما يبلغ متوسط وزن البنات نحو 15 kq. وفي هذه المرحلة، يتغير الوزن وفقًا للعادات الغذائية والشهية أكثر من تأثره بالجنس والعوامل الوراثية. أما الطول، فيرتبط بدرجة أكبر بالعوامل الوراثية. وتشير الدراسات إلى أن 80% من العوامل التي تحدد الطول مرتبطة بالشفرة الجينية. وبعبارة أخرى، إذا كان الأب والأم طويلي القامة، فمن المتوقع أن يكون طفلكِ أطول من أقرانه أيضًا. ومع ذلك، من المفيد الاطلاع على مخطط النسب المئوية للنمو. قد يتراوح طول البنات في عمر 35 شهرًا بين 87-102 sm، بينما يتراوح طول الأولاد بين 89-103 sm.') WHERE id = '8106725e-0710-4935-aa3f-544d3a83dba4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يتمكن طفلكِ خلال هذه الأشهر من العد حتى 10، ويتعلم طرح أسئلة مثل: "ماذا، أين، من؟". وكل ذلك يدل على أن تطوره اللغوي قد بلغ مستوى أفضل. فهو يحاول الآن التحدث بطلاقة أكبر، لأن حصيلته اللغوية تزداد، ومع تطور قدراته الذهنية يتعلم استخدام اللغة بصورة أدق. وقد تلاحظين أيضًا أن طفلكِ يمزح معكِ خلال هذه المرحلة، وربما يستمتع أحيانًا بإغاظتكِ بهذه المزحات. وإذا كان من حوله أشخاص مرحون، فسيسعده تقليدهم ومحاولة إضحاككِ. ومن الرائع أن يتمتع طفلكِ بحس الفكاهة في هذا العمر، لكن من المهم أن يكون مضمون المزاح ملائمًا لسنه. وإذا كان يقلد نماذج سلبية من الآخرين في مزاحه، فينبغي لكِ التحدث معه وشرح الأمر له بدلًا من الضحك.') WHERE id = 'b3f8428e-6bca-4e17-b06f-253ecc4381cb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ تواجهين مشكلة تتعلق بضعف شهية طفلكِ، فعليكِ الانتظار حتى يشعر بالجوع بدلًا من إجباره على الأكل. فقد يؤثر إطعامه بالقوة سلبًا في حالته النفسية وصحته الجسدية. وبدلًا من ذلك، يُفضل إعادة تقديم الأطعمة التي لا يحبها على فترات متباعدة. ومن أهم الأمور التي ينبغي لكِ الانتباه إليها في التغذية أسلوبا المكافأة والعقاب. فليس من الصواب معاقبة طفلكِ لعدم تناوله الطعام أو مكافأته على تناوله. تذكري أنه فرد مستقل مثلكِ، وكما تختلف احتياجات الأشخاص، قد تختلف أيضًا كمية الطعام التي يحتاج إليها كل طفل. لذلك من المفيد استشارة مختص. ويمكنكِ معرفة احتياج طفلكِ اليومي من السعرات الحرارية خلال المتابعة مع الطبيب، أو الحصول من اختصاصي تغذية على برنامج غذائي ملائم له.') WHERE id = '64ea6bc8-7775-4535-9a1e-fa17c68ef78b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ البالغ من العمر 35 شهرًا قادرًا على ارتداء حذائه وخلعه بنفسه عند الخروج، لكنه لا يزال يحتاج إلى بعض الوقت ليتعلم ربط حذائه. كما يستطيع ارتداء ملابسه وخلعها بصورة مستقلة، بل ويمكنه أيضًا إغلاق الأزرار ورفع السحّاب. وكل ذلك نتيجة تطور مهاراته الحركية الدقيقة يومًا بعد يوم. وأصبح الآن يؤدي بسهولة الكثير من الأمور التي لم يكن قادرًا عليها سابقًا، إذ يمكنه الاهتمام بنظافته الشخصية، والقفز على قدم واحدة، وبناء أبراج من مكعبات الليغو، وتقليب صفحات الكتب، والإمساك بالكوب بيد واحدة. ولتعزيز هذه المهارات، ينبغي لكِ تهيئة الظروف المناسبة له. فعلى سبيل المثال، حتى إن ظننتِ أنه لا يستطيع ارتداء ملابسه بطريقة صحيحة تمامًا، عليكِ منحه هذه الفرصة وعدم التدخل ما لم يكن ذلك ضروريًا.') WHERE id = '163cc8b7-054e-465f-87c5-aa48d630b9cc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يبدأ طفلكِ تدريجيًا في الاهتمام بالموت وطرح أسئلة عنه، خاصةً إذا سمع أحدًا يتحدث عنه. وقد يسأل: «ماذا يعني الموت؟»، «إلى أين يذهب الموتى؟»، «هل سأموت أنا أيضًا؟». وعلى الرغم من أن هذا الموضوع يثير القلق لدى كثير من الأسر، فمن المهم ألا تتركي مثل هذه الأسئلة بلا إجابة؛ فالأطفال، مثل البالغين، يخافون ويشعرون بالقلق مما يجهلونه لا مما يعرفونه. والمعرفة هي مفتاح الفهم والتخلص من المخاوف. لذلك يمكنكِ التحدث عن الموت بصورة طبيعية ضمن مواقف الحياة اليومية، قبل حدوث وفاة في محيطكِ القريب، ومن دون إثقال طفلكِ عاطفيًا؛ كأن تتحدثي مثلًا عن فراشة ميتة أو عن دورة حياة الحيوانات والنباتات. وإذا تجنبتِ هذا الموضوع رغبةً في حماية طفلكِ وعدم إحزانه، فقد تكون ردة فعله شديدة عندما يواجه هذه الحقيقة في الحياة الواقعية، وقد يجد صعوبة في التحكم في مشاعره.') WHERE id = '89a84db5-00a0-4250-8e17-5337f74b7208';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يكفي طفلكِ أن ينام 11 ساعة ليلًا و1,5-2 ساعة نهارًا. لكن انتظام مواعيد النوم هذه مهم للغاية أيضًا. يسمح بعض الآباء لأطفالهم بالبقاء مستيقظين حتى وقت متأخر كي يتمكنوا من النوم مدة أطول في الصباح، إلا أن هذا نهج خاطئ؛ فلكي يستفيد طفلكِ استفادة كاملة من هرمونات النمو التي يحتاج إليها، يجب أن يكون في سريره في موعد أقصاه الساعة 21:00. كذلك، لا بد من تحويل ذلك إلى روتين ثابت حتى تتكون لديه عادات نوم جيدة. وقد يؤدي عدم إفراز الهرمونات بالمستويات المطلوبة بسبب مواعيد النوم غير المناسبة إلى تأخر النمو على المدى الطويل. بالإضافة إلى ذلك، لن يحصل دماغه على الراحة الكافية لاستيعاب المعلومات الجديدة. لذلك احرصي على أن يبدأ نوم طفلكِ المسائي بين الساعة 19:00 والساعة 21:00.') WHERE id = '9bac81bd-cded-4b25-9404-36ce1f5fe50c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مثل كل طفل، وُلد طفلكِ بخصائص جينية وفسيولوجية تميزه عن غيره. وإلى جانب ذلك، تُعد التجارب خلال مرحلة الطفولة المبكرة بالغة الأهمية لنمو الطفل الاجتماعي والعاطفي السليم. وتُظهر الدراسات أن تقديم الوالدين قدوة حسنة وتواصلهما الإيجابي يؤديان دورًا مهمًا في نمو الطفل. إن تحدثكِ مع طفلكِ عن المشاعر التي تعيشينها في محيط المنزل سيؤثر إيجابيًا في علاقتكما ويعزز قدرته على تمييز المشاعر. على سبيل المثال، يمكنكِ أنتِ وشريك حياتكِ مشاركة مشاعركما بشأن ما حدث خلال يومكما من دون الخوض في تفاصيل كثيرة: «أرهقني الازدحام كثيرًا اليوم»، «أخافتني سيارة توقفت فجأة»، «غضب مديري بسبب تأخر العمل، وشعرتُ بالحزن أيضًا»، «رأيت صديقي في الطريق، وأسعدني ذلك كثيرًا». وستتطور بدرجة كبيرة قدرة الطفل الذي ينشأ وهو يسمع الآخرين يتحدثون عن مشاعرهم على التعبير عن عواطفه وتنظيمها.') WHERE id = 'c1323801-3c49-4703-a7f2-cac086e9addc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ يُظهر سلوكيات لا تتناسب مع عمره، فغالبًا ما يرجع ذلك إلى عدم معرفته بكيفية التعبير عن نفسه. بعبارة أخرى، تصدر عنه هذه الاستجابات لأنه لا يستطيع التعبير بطريقة أخرى عن توتره الداخلي ومشكلاته. ومن أمثلة ذلك أن يضرب رفيقه عندما يغضب، أو يرتمي على الأرض عندما لا يحصل على ما يريد، أو يتصرف بخجل مفرط عندما يطرح عليه أحدهم سؤالًا، أو يظل في حالة قلق مستمرة. في هذه الحالة، ينبغي أن تتمثل استراتيجيتكِ الأكثر فاعلية أولًا في تعليم طفلكِ كيفية التعرف إلى الشعور الذي ينتابه. فالأطفال القادرون على التعبير عن مشاعرهم بالكلمات بصورة صحيحة يعانون مشكلات سلوكية أقل. فإذا تمكن طفلكِ مثلًا من قول «أنا غاضب جدًا» عندما يغضب من شيء ما، فستقل احتمالية حدوث نوبات الغضب والبكاء. إن سؤالكِ طفلكِ باستمرار عما يشعر به سيطور قدرته على التعرف إلى مشاعره والتعبير عنها، وسيساعده على التعامل مع المشاعر السلبية بطريقة أكثر صحة.') WHERE id = 'c41a4ffe-aceb-49cc-a6db-32a8461961ac';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تكون كثرة أسئلة طفلكِ مؤشرًا على ذكائه وفضوله، كما قد تشير إلى شدة قلقه. وأفضل طريقة لمعرفة ذلك هي الانتباه إلى مضمون أسئلته. فإذا كانت الأسئلة تدور حول موضوعات مليئة بالخوف، مثل: "هل سأمرض إذا أكلت هذا الطعام؟"، "قلبي ينبض بسرعة، هل سأموت؟"، "هل سيدخل لص إلى المنزل الليلة؟"، "هل سيحدث شيء إذا أكلت بيدي اليسرى؟"، فقد يكون من المفيد أن تطلبي الدعم من مختص. قد يشعر كل طفل بالقلق من حين إلى آخر ويطرح مثل هذه الأسئلة، لكن إذا تكررت هذه الحالات كثيرًا، فعليكِ مراقبة طفلكِ جيدًا. ومن المهم جدًا لصحته النفسية تحديد المواقف التي تخيفه وتثير قلقه. ولا تترددي في استشارة مختص عندما تواجهين أمورًا لا تستطيعين التعامل معها بمفردكِ. وتذكري أن التدخل المبكر هو الخيار الأكثر سلامة دائمًا.') WHERE id = 'd8d7160d-4daa-41aa-b77a-2dab3b64dfdc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا ينمو فضول طفلكِ بين الكتب والدفاتر وحدها. ولا يظهر نمط التعلم النظري ضمن التطور الطبيعي للإنسان إلا خلال المرحلة العمرية 11-14 عامًا. وقبل هذه المرحلة، يستوعب طفلكِ جزءًا كبيرًا مما يتعلمه من خلال التطبيق أو اللعب أو بفضل فضوله. لذلك ينبغي ألا تكبتي فضوله الذي يظهر غالبًا في صورة أسئلة كثيرة؛ فالطفل الذي يُثبَّط فضوله لن يتمكن من إكمال نموه بصورة سليمة حتى مرحلة المراهقة. ولهذا عليكِ الإجابة عن أسئلة طفلكِ بصبر، بل وتشجيعه على طرحها. أما الأسئلة التي لا تعرفين إجابتها، فيمكنكِ البحث عنها معه وتعلُّم أشياء جديدة أيضًا.') WHERE id = 'c925eb18-ca4f-4e30-b127-cf5a2c698dac';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ لا يرغب في النوم نهارًا خلال هذه المرحلة، فعليكِ تقديم موعد نومه مساءً. وقد تلاحظين أنه يخاف من خروج شخص ما من الخزانة أو من تحت السرير، أو من الظلام. في هذه الحالة، لا ينبغي أن تردّي عليه بعبارات مثل: لا، هذا مجرد وهم! أو: هذا خوف لا معنى له! لأن ذلك لن يبدد خوفه، بل قد يلحق ضررًا كبيرًا بنموه أيضًا. تذكّري أن الشعور بالخوف مرحلة مهمة من مراحل نمو طفلكِ. عندما يشعر بالخوف، يمكنكِ التحدث إليه بطريقة تبعث على الطمأنينة، أو قراءة كتاب له، أو توضيح الفرق بين الواقع والحلم، أو التحدث معه عما يخيفه. وبهذا تساعدينه على فهم شعوره بالخوف فهمًا صحيحًا وتعلّم كيفية التعامل معه.') WHERE id = '70f5b6ed-9e2c-4dc4-adbf-c9b127e85789';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعدّ الكفير من أكثر المشروبات المفيدة التي ينبغي إدراجها في النظام الغذائي لطفلكِ. وعليكِ مساعدته على اكتساب عادات صحية، مثل شرب الكفير بدلًا من الشاي المثلج والمشروبات الغازية والقهوة. كما يمكنكِ تحضير الكفير بسهولة في المنزل بدلًا من شراء المنتجات الجاهزة المتوفرة في المتاجر. يمكنكِ تحضيره بسهولة بإضافة بادئ الكفير، الذي يمكنكِ العثور عليه في الصيدليات أو متاجر التوابل، إلى وعاء من الحليب بدرجة حرارة الغرفة، ثم تحريكه برفق. بعد ذلك غطّي الوعاء لحجبه عن الضوء واتركيه جانبًا. وبعد بقائه في درجة حرارة الغرفة لمدة يوم واحد على الأقل، يمكنكِ فصل حبيبات الكفير عن السائل باستخدام مصفاة بلاستيكية. ومن الأمور الأخرى التي ينبغي الانتباه إليها عند تحضير الكفير عدم استخدام وعاء أو ملعقة معدنية، لأن الأدوات المعدنية قد تُفقد بادئ الكفير فعاليته.') WHERE id = 'b9a410f0-fac4-4211-b529-90bd6f7038fb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين خلال هذه المرحلة أن طفلكِ يقوم ببعض التصرفات غير المرغوبة التي لا تعجبكِ. في مثل هذه الحالات، عليكِ تقبّل مشاعره في تلك اللحظة، ووضع حدود بنّاءة، وتقديم بديل له بالتأكيد. على سبيل المثال، يمكنكِ أن تقولي: نعم، أفهم أنك غاضب الآن، لكن أغراض المنزل ليست للرمي على الأرض، ويمكنك بدلًا من ذلك رمي ألعابك في الصندوق. بهذه الطريقة، سيفهم طفلكِ أن مشاعره مفهومة وأنه مقبول، وأن التصرف الذي قام به وحده هو غير الصحيح. أما إذا انتقدتِ شخصيته أيضًا عند منعه من سلوك ما، فقد يتضرر احترامه لذاته، وقد يعاند ويستمر في ذلك السلوك. لذا بدلًا من مهاجمة ذاته بقولكِ: أنت طفل سيئ، عليكِ الإقرار بمشاعره، وتوضيح الحدود المتعلقة بسلوكه، وتوجيهه إلى نشاط أكثر فائدة. ومن المهم جدًا تطبيق هذه الطريقة بهدوء وثبات؛ لأن السماح له في يوم بما منعتِه عنه في اليوم السابق قد يسبب له الارتباك وعدم اليقين.') WHERE id = '4e533ab4-dd97-4697-9a7a-2763d84d0153';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يشير كثير من المتخصصين إلى أن الأطفال يبدأون في إظهار علامات الاستقلالية بين عمر 18 و24 شهرًا. وعندما يبلغ طفلكِ 3 سنوات، تزداد هذه الرغبة، ويبدأ بالتعبير عن نفسه قائلًا: "أنا شخص مستقل". في هذه المرحلة، يدرك طفلكِ أن لديه آراء خاصة به ويرغب في أن تُحترم. وفي البلدان المتقدمة، يُستخدم تعبير "threenager" لوصف مرحلة عمر 3 سنوات، ويعني "المراهق الصغير". قد تمرّ عليكِ بصفتكِ أمًا لحظات ينفد فيها صبركِ، لكن تذكّري أن متلازمة سن 3 سنوات لن تدوم إلى الأبد! ومن الأمور الأخرى التي تهم الوالدين معرفة المدة التي تستغرقها هذه المرحلة. وكما هو الحال في مراحل النمو الأخرى، لا توجد حدود زمنية دقيقة لمتلازمة سن 3 سنوات. لكن وفقًا للرأي العام، فعلى الرغم من أن هذه المرحلة تكون أكثر حدة من متلازمة سن السنتين، فإنها تستمر مدة أقصر.') WHERE id = 'ad73d53b-9ddf-47dd-846f-bc47a9465bbe';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد لا تتمكنين حتى الآن من فهم نصف ما يقوله طفلكِ والجمل التي يصوغها. وقد يكون بين أقرانه أطفال يتواصلون بصورة أفضل، لكن لا داعي للمقارنة. وفقًا لاختصاصيي النمو، من الطبيعي ألا يكون كلام طفلكِ مفهومًا بالكامل حتى يبلغ في المتوسط سن 4 سنوات. باختصار، هذه عملية طبيعية. لكن إذا كنتِ تعتقدين أن طفلكِ متأخر جدًا مقارنة بأقرانه، فيمكنكِ استشارة مختص. في هذه المرحلة، يستطيع طفلكِ تكوين جمل بسيطة من 3-4 كلمات، وتنفيذ تعليمات من خطوتين مثل: "خذ لعبتي وأحضرها إليّ". وقد تظل الضمائر صعبة عليه، لذا من الطبيعي أن تسمعي منه جملًا قصيرة تخلو من الضمائر مثل: "كُل الطعام" و"جوعان". إن قراءة الكتب له باستمرار أو تأليف القصص معًا سيجعلان هذه العملية ممتعة ويسرّعان تطور مهاراته اللغوية.') WHERE id = 'ec5bfd9e-b028-4a27-9161-19876bcbf319';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين خلال هذه المرحلة أن طفلكِ يعاني من بعض مشكلات الهضم وآلام الغازات. ووفقًا لبعض المتخصصين، تكون مشكلات الغازات أكثر شيوعًا لدى الأطفال الذين يتجولون والطعام في أيديهم، أو يتناولون الطعام أثناء اللعب أو مشاهدة التلفاز. ووفقًا لهذه النظرية، فإن الأطفال الذين يأكلون ويبتلعون بسرعة بسبب حماس اللعب يبتلعون كميات كبيرة من الهواء، ما يسبب لهم اضطرابات هضمية. وللوقاية من مشكلة الغازات لدى طفلكِ، من المهم أن تحرصي على تناوله الطعام ببطء على مائدة الأسرة. وإنهاء وجبته بكمية كافية وخلال مدة معتدلة أكثر صحة من تناولها بسرعة أو تناول كمية تفوق حاجته. لذلك، إذا كان طفلكِ معتادًا على الأكل بسرعة، فعليكِ محاولة تغيير هذه العادة وهو لا يزال في مرحلة ما قبل المدرسة. وبذلك، لن يعاني في المستقبل من مشكلات الهضم نفسها، كما ستقل احتمالية مواجهته مشكلات متعلقة بالوزن.') WHERE id = '2a5e6072-b787-4135-92b2-5c7dcfe3dd8a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعدّ نظام النوم مهمًا جدًا في هذه المرحلة التي يقترب فيها طفلكِ من عمر 3 سنوات، كما هو الحال في كل مرحلة. إذا كنتِ قد غيّرتِ سريره واعتاد عليه، وأصبح ينام طوال الليل من دون أن يستيقظ، فعليكِ الثناء عليه لهذا النجاح. وإذا نهض من سريره وأراد المجيء إليكِ، فأخبريه بهدوء ولطف أن عليه العودة إلى سريره والنوم. وإذا لم يفهم السبب وأصرّ على موقفه، فاشرحيه له باختصار وبأسلوب يمكنه فهمه. ومع ذلك، قد يواصل محاولة تجنّب النوم باختلاق أعذار مختلفة. لكن حاولي ألّا تتنازلي عن القواعد التي وضعتِها في هذا الشأن. يمكنكِ حل هذه المشكلة بالصبر واتباع نهج ثابت ومنتظم. وإذا لم يرغب في النوم فورًا، فقد تساعده قراءة كتاب في غرفته أو قضاء بعض الوقت بهدوء على الاسترخاء والاستعداد للنوم.') WHERE id = 'a45f03f4-7495-4f93-9e19-ea1e8ffa609b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لم يكن طفلكِ قد أكمل التدريب على استخدام المرحاض بعد، فيمكنكِ التفكير في بدء التدريب خلال هذه الأسابيع. وفي حال عدم وجود تأخر في النمو، يُعد عمر 3 سنوات نهاية الفترة المناسبة لبدء التدريب على استخدام المرحاض. إذا بدأ طفلكِ بالتحكم في التبول نهارًا، فعليكِ التوقف عن إعطائه السوائل قبل النوم بساعة واحدة، والتأكد من ذهابه إلى المرحاض قبل النوم، ونزع حفاضه ليلًا. فوضع الحفاض ليلًا لطفل يتحكم في التبول نهارًا قد يرسل إليه رسائل متناقضة ويؤخر نجاح التدريب. قد يكون التحكم الليلي أصعب قليلًا لدى الأطفال الذين ينامون بعمق. لكن تقبّلكِ لاتساخ المكان لفترة من الوقت سيسرّع العملية ويمنع تشوش طفلكِ. ويمكنكِ استخدام أغطية واقية للمرتبة لتسهيل التنظيف.') WHERE id = '10d272f3-fd20-44b4-9b09-1b4398b61ba5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تتغير تفضيلات طفلكِ الغذائية من يوم إلى آخر خلال هذه الفترة؛ فقد يأكل طعامًا بشهية في أحد الأيام ثم يرفضه في يوم آخر. المهم أن تقدّمي له على المائدة مجموعة متنوعة من الأطعمة الصحية، وأن تتركي له اختيار ما يأكله والكمية التي يتناولها. وإلى جانب الأطعمة المألوفة والمحببة لديه، شجّعيه من حين إلى آخر على تذوق قطعة صغيرة من طعام جديد. لكن من المهم جدًا ألّا تجبريه على ذلك. ولا تتوقعي منه أن يتناول حصة كاملة من الطعام الجديد فور تذوقه. وقد تحتاجين إلى تقديم الطعام نفسه 6-7 مرات على الأقل قبل أن تعرفي ما إذا كان يحبه أم لا. ومن المهم لصحته أن تتضمن كل وجبة أطعمة من مجموعات البروتين والحبوب والخضراوات. كما أن تقديم الفاكهة في الوجبات الخفيفة بدلًا من الشوكولاتة والأطعمة الغنية بالسكر سيكون أكثر فائدة.') WHERE id = 'ac9f56dc-94bf-4adb-a7ed-1d15446f273b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ يمر بما يُعرف بمرحلة تحديات عمر 3 سنوات، فيلقي بنفسه على الأرض ويصرخ، فإن أفضل ما يمكنكِ فعله هو الحفاظ على هدوئكِ. بالطبع، قول ذلك أسهل من تطبيقه، لكن الأطفال غالبًا ما يعكسون سلوك والديهم. إذا حافظتِ على هدوئكِ وقت نوبة الغضب، فستعلّمين طفلكِ كيف يتحكم في مشاعره عندما يواجه مشكلة في المستقبل. قد يلجأ طفلكِ الذي بلغ عمر 3 سنوات إلى طرق مختلفة لإثبات استقلاليته. ولتجنب النتائج غير المرغوب فيها، حاولي عدم التدخل ما لم تكن هناك ضرورة حقيقية، حتى لو لم تعجبكِ بعض تصرفاته، واسمحي له بالقيام ببعض الأمور بنفسه. في هذه المرحلة، يشكو بعض الآباء من رغبة أطفالهم في اختيار ملابسهم بأنفسهم. وفي مثل هذه الحالات، ينصح المختصون بأن تعرضي على طفلكِ عدة خيارات وتتركي له اتخاذ القرار من بينها. لا تقلقي، لن تدوم هذه المرحلة طويلًا! 😊') WHERE id = '77d3682e-ed32-46fd-bdc5-b4fcebf4896e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يشهد التطور اللغوي لدى طفلكِ قفزات جديدة في الآونة الأخيرة. ويمكنكِ الآن ملاحظة أن الجمل التي يُكوّنها أثناء الحديث أصبحت أكثر سلامة من الناحية النحوية. كما بدأ يربط بين أفكاره وفق علاقة السبب والنتيجة. ويبلغ متوسط حصيلته اللغوية نحو 300 كلمة مختلفة. وقد يتحدث مطولًا مع نفسه، ومعكِ، ومع ألعابه وأصدقائه. كما ازداد اهتمامه بالكلمات الجديدة، وبدأ يكتشف كيفية استخدام حرف العطف "و" في الجمل. وأصبح يفهم الزمن الحاضر والمستقبل، والضمائر مثل "أنا" و"أنت". كما يستخدم حروف الجر والضمائر البسيطة بصورة أدق من السابق. ويتعلم أسماء الألوان، لكنه قد لا يتمكن بعد من مطابقة كل لون باسمه بدقة تامة. فمثلًا، قد يخلط بين الألوان المتقاربة، مثل الأحمر والوردي، أو الأصفر والبرتقالي.') WHERE id = 'a7f6f0c5-f1b1-4f0e-b9c2-28b4975c766e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعدّ التلوين من أكثر الأنشطة التي يستطيع طفلكِ، الذي أوشك على بلوغ عمر 3 سنوات، ممارستها والاستمتاع بها. فالتلوين لا يعزز التناسق بين اليد والعين لديه فحسب، بل يقوّي أيضًا قدرته على فهم الأشياء ومنحها معنى. ولأن الرسم عملية معقدة وصعبة في الوقت نفسه، اختاري له ألوانًا جذابة ووفّري له مساحة حرة للرسم. يمكنكِ استخدام أقلام الشمع بأمان، ويُنصح باختيار الأقلام السميكة كبيرة الحجم (jumbo). فقد يحب طفلكِ التلوين، لكن اختيار أدوات غير مناسبة قد يجعله يفقد اهتمامه به. وإذا كنتِ ستشترين أقلام تلوين، فاختاري أيضًا الأنواع الكبيرة (jumbo). وتُعدّ قدرة طفلكِ على تحريك أصابعه بحرية وراحة أثناء التلوين من أهم الأمور التي ينبغي مراعاتها.') WHERE id = 'ce9d6e51-8832-4d9d-bbb8-766b28abc2e6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إلى جانب تطور فهم طفلكِ، الذي يمشي منذ بضعة أشهر ويتجول مستكشفًا محيطه، للمسافة والاتجاه، فقد تطورت أيضًا ذاكرته وقدرته على الإدراك. في هذه المرحلة، يبدأ بتعلّم مفاهيم الاتجاهات. وقد يبدأ بمفاهيم بسيطة مثل الأمام والخلف، ثم يتعلم لاحقًا مفاهيم متضادة أخرى مثل الأعلى والأسفل، والداخل والخارج. كما يفهم مفهومي التشابه والاختلاف، ويستطيع مقارنة أحجام الأشياء وأشكالها وألوانها والتمييز بينها. وبفضل التطور السريع لمخيلته، قد تلاحظين أنه أصبح يمارس ألعاب التقليد بطريقة أكثر إبداعًا. لكنه قد لا يكون قادرًا بعد على العد ذهنيًا ما لم يرَ الأشياء التي يعدّها أمامه. ويمكنكِ مساعدته على تطوير هذه المهارة بتعليمه تكديس مكعبات اللعب فوق بعضها مع العد 1، 2، 3. ويُفضّل تجنّب شراء الألعاب والدمى المخصصة لأطفال أكبر منه سنًا، لأن تعريضه باستمرار لمهام تفوق قدراته قد يؤثر سلبًا في حالته النفسية؛ أما مكعبات الليغو والألعاب المناسبة لعمره فستكون أكثر فائدة لنموه.') WHERE id = '41a7e71a-e46c-4110-ac09-a7e8357cae05';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, '[[فشلت الترجمة]] حدث خطأ أثناء معالجة هذا القسم. بداية النص الأصلي: "قدرة طفلكِ اللغوية قليلًا..."') WHERE id = 'aad2bc69-ad6a-413b-90fa-aefe2a168556';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, '[[فشلت الترجمة]] حدث خطأ أثناء معالجة هذا القسم. بداية النص الأصلي: ابتداءً من عمر 3 سنوات، طفلكِ...') WHERE id = '0d5b4196-e611-4d6d-85b3-4906d4cda8aa';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, '[[فشلت الترجمة]] حدث خطأ أثناء معالجة هذا القسم. بداية النص الأصلي: مهما كانت متلازمة عمر السنتين مشهورة...') WHERE id = '6336e340-35e1-4840-970b-7f0baec679fd';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, '[[فشلت الترجمة]] حدث خطأ أثناء معالجة هذا القسم. بداية النص الأصلي: نمو ذكاء طفلكِ و...') WHERE id = 'ab9bda44-8551-4efb-83a1-2cd1c1dbdb5b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, '[[فشلت الترجمة]] حدث خطأ أثناء معالجة هذا القسم. بداية النص الأصلي: متوسط وزن طفلكِ وطوله...') WHERE id = 'd8fbb3b8-bb5c-4edd-9483-cf983895ad96';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نعلم مقدار الجهد الكبير الذي تبذلينه لحماية طفلكِ منذ لحظة ولادته، بل منذ اللحظة التي علمتِ فيها بحملكِ. وحتى مرحلة معينة، يكون هذا الجهد ضروريًا ومهمًا للغاية للحفاظ على صحته. لكن مع تطور بعض مهارات طفلكِ في هذه المرحلة، يبدأ بالرغبة في الاستقلال عنكِ والقيام بأموره بنفسه واستكشاف العالم بحرية. لذا عليكِ أن تسمحي له بذلك وتحترمي استقلاليته وحريته. ومن المهم، عندما يحين الوقت، أن تدعمي استقلال طفلكِ وتحمله للمسؤولية من خلال منحه مسؤوليات تتناسب مع عمره ونموه. فالطفل الذي يُسمح له بالاستقلال والاستكشاف سيصبح مستقبلًا شخصًا قادرًا على الاعتماد على نفسه ويتمتع بثقة عالية بذاته. لذلك، تجنبي استخدام عبارات مثل «احذر، قد يحدث لك شيء!» أو «احذر، قد تؤذي نفسك!» ما لم يكن ذلك ضروريًا فعلًا، ولا تعيقيه عن الاستكشاف.') WHERE id = '26d3c54b-09eb-43e7-b3e6-8e1d6b9efa0a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تسهم الألعاب في هذه المرحلة في نمو طفلكِ، وتتيح له أيضًا قضاء وقت ممتع. ففي هذا العمر، سيُدهشكِ طفلكِ بخياله الواسع الذي يحوّل كل شيء إلى لعبة. لذلك يوصي الخبراء بممارسة ألعاب تنمّي إبداع الأطفال بدلًا من شراء الألعاب الباهظة الثمن. فالألعاب الباهظة التي لا تدعم الإبداع قد تحدّ من خيال طفلكِ وتُضعفه. يمكنكِ توجيه طفلكِ نحو ألعاب أكثر فائدة، مثل صنع منزل أو طائرة أو سيارة أو سفينة أو مركبة فضائية من صندوق كرتوني. حتى الملاءة المشدودة بين كرسيين يمكن أن تتحول في خيال طفلكِ إلى ميناء أو خيمة أو منزل أو أي شيء يستطيع تخيله. كما يمكن لألعاب التظاهر وتمثيل الأدوار واللعب بالبيت أن تسهم بدرجة كبيرة في نمو طفلكِ. وفي هذا الإطار، احرصي قدر الإمكان على إتاحة الفرصة لطفلكِ لقضاء الوقت واللعب مع أقرانه.') WHERE id = 'a2a78f60-b8a2-4f4c-8094-c1ec1d443ca9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عندما يعاني طفلكِ من آلام الغازات، راجعي ما تناوله خلال الساعات القليلة الماضية، إذ يُرجح أن يكون الطعام الذي تناوله هو سبب الغازات. وقد يكون بعض الأطفال أكثر حساسية من غيرهم للأطعمة الغنية بالألياف والدهون. وتذكري أيضًا أن جهازه الهضمي لم يكتمل نموه بعد بالقدر نفسه لدى البالغين. لذلك، قد يكون أحد الأطعمة التي تتناولينها ولا تسبب لكِ أي انزعاج صعبًا جدًا على جهاز طفلكِ الهضمي. في مثل هذه الحالات، قد يكون من المفيد إعداد قائمة بالأطعمة التي يتناولها طفلكِ، والحد من الأطعمة المشتبه بها، ثم مراقبة حالة الغازات. كما قد يؤدي شرب أكثر من كوب واحد من عصير الفاكهة يوميًا إلى الغازات؛ فقد يواجه طفلكِ، مثل بعض الأطفال، صعوبة في هضم الكميات الزائدة من الفركتوز والسكروز الموجودة في عصير الفاكهة. إضافة إلى ذلك، فإن تناوله كميات كبيرة من المشروبات السكرية يضر بأسنانه أيضًا.') WHERE id = 'e0542a27-8733-472b-8360-25ce6853ad56';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لم تنجحي في تدريب طفلكِ على استخدام المرحاض، فقد تحتاجين إلى الانتباه إلى بعض التفاصيل. في مثل هذه الحالات، يتحرى الخبراء موعد اكتساب طفلكِ القدرة على التحكم في التبول ليلًا، وما إذا كانت هناك حالات تبول لا إرادي ليلي في العائلة. كما تُعد الأساليب الخاطئة المتبعة أثناء التدريب من أبرز أسباب عدم النجاح. فعلى سبيل المثال، إن غضبكِ من طفلكِ عند تعرضه لحادث، أو إلقاء اللوم عليه، أو حتى إظهار خيبة أملكِ من خلال تعابير وجهكِ، كلها عوامل تؤخر عملية التدريب. وقد يؤدي هذا النوع من التعامل الخاطئ إلى أن ينشأ طفلكِ خجولًا، ومترددًا في المبادرة، وضعيف الثقة بنفسه. كذلك، قد يفسر طفلكِ هذه التصرفات على أنها تهديد لسلامة جسده، فلا يثق بالآخرين ويظل خائفًا من التعرض للأذى في أي لحظة. ونتيجة لذلك، قد تتشكل لديه شخصية قلقة ومتوترة، وقد تظهر لديه مشكلات سلوكية أخرى. لذلك، من المهم جدًا أن تشعري أنتِ أولًا بأنكِ مستعدة لهذه العملية قبل أن تبدئيها مع طفلكِ.') WHERE id = 'a0e48404-d991-4429-b070-28474430ad64';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أنتِ تدركين ضرورة وضع بعض القواعد لدعم نمو طفلكِ وتوجيه سلوكياته بصورة إيجابية. لكن قد تكون لديكِ تساؤلات حول كيفية تحديد هذه القواعد وتطبيقها. ويشير الخبراء إلى أنه لا توجد صيغة واحدة صحيحة وفعالة للتربية تناسب جميع العائلات. فالتواصل الفعال بين الوالدين والطفل يختلف باختلاف بنية الأسرة وقيمكِ وثقافتكِ وشخصية طفلكِ. ومن المهم جدًا أن تراقبي جيدًا طفلكِ الذي يقترب الآن من عمر 3 سنوات، وأن تكيّفي أسلوبكِ وفقًا لاحتياجاته وسماته. فكونكِ أمًا لطيفة وداعمة يتيح لطفلكِ اكتشاف قدراته وتحقيق إمكاناته. وفي هذه المرحلة، ركزي على ما يستطيع طفلكِ فعله، ولا تقارنيه أبدًا بأقرانه، ولا تثقلي عليه بكثرة القواعد التي لا يستطيع الالتزام بها.') WHERE id = '3da2acf8-a0e8-4a9b-bfd1-5a6c83e8b5da';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لدينا بعض الاقتراحات لكِ بمناسبة عيد ميلاد طفلكِ الثالث! ها هو صغيركِ يتم عامه الثالث، وعلى الأرجح سيكون عيد ميلاده في عمر 3 سنوات أول عيد ميلاد يتذكره بوضوح. يمكنكِ جعل هذا اليوم ذكرى لا تُنسى بالنسبة إليه، من خلال اللعب مع أصدقائه وأقرانه والركض والمرح، بل وتنظيم ورش وأنشطة متنوعة وممتعة. وإذا كان الطقس ملائمًا، فإن الاحتفال بعيد ميلاده في الهواء الطلق سيمنح طفلكِ وضيوفكِ تجربة رائعة! لا تنسي التقاط الكثير من الصور في هذا اليوم المميز، فهي ستكون ذكرى جميلة للمستقبل. والأهم من كل شيء هو ما بذلتِه من جهد وعناء من أجل طفلكِ حتى بلغ هذا العمر... أنتِ تحديدًا من تستحقين أكبر تصفيق! لا تنسي أبدًا أنكِ أم رائعة! <3') WHERE id = '48bcf5cd-dbe3-4417-8aa0-e362136d2694';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يكفي أن يشرب طفلكِ نحو 200 ml، أي كوبًا واحدًا من الكفير يوميًا، للمساعدة في الحفاظ على صحته العامة. والكفير أكثر قيمة غذائية من الزبادي؛ فإلى جانب احتوائه على جميع العناصر المفيدة الموجودة في الحليب، يتمتع بقيمة غذائية أعلى بفضل بكتيريا البروبيوتيك الموجودة في حبيباته. كما أن جسم طفلكِ يهضمه ويمتصه بسهولة أكبر. ويميزه عن غيره من منتجات الألبان غناه بالبروتين والمعادن الأساسية وفيتامينات المجموعة B. ويُعد الكفير غنيًا خصوصًا بفيتامينات B12 وB1 وK. وبينما يساعد الزبادي على تنظيف الجهاز الهضمي وتغذية البكتيريا النافعة، يحتوي الكفير على بكتيريا توازن الفلورا المعوية وتقويها. باختصار، ينبغي أن تُدرجي الكفير في غذاء طفلكِ إلى جانب الزبادي. وإذا كان طفلكِ لا يحب مذاق الكفير السادة، فيمكنكِ تنكيهه بالفواكه المتوفرة في المنزل لإعداد نكهات متنوعة.') WHERE id = 'd5d21407-1821-4172-9e4c-16f1330393d6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تسهم أنشطة التلوين والرسم، التي تساعد على نمو العضلات الدقيقة لدى طفلكِ، في تحسين التناسق بين اليد والعين بدرجة كبيرة. لذلك، يمكنكِ التغاضي عن بعض الفوضى وتخصيص ركن يستطيع طفلكِ أن يرسم فيه بحرية. كما سيعزز التلوين ثقته بنفسه، لأنه يتيح له ابتكار أعماله الخاصة. وتُظهر الأبحاث أن الرسم والتلوين ينميان قدرة طفلكِ على التركيز. ولأن هذه الأنشطة تعكس خياله، فإنها تسهم أيضًا بدرجة كبيرة في تنمية تفكيره الإبداعي. إضافة إلى ذلك، فإن طرح أسئلة بسيطة على طفلكِ بعد الانتهاء من التلوين حول الرسم الذي ابتكره يقوي قدرته على فهم المعاني. ويمكنكِ مساعدته على تطوير مهارة التعبير عن نفسه بسؤاله عمّا يشبهه الرسم، أو عن سبب اختياره لونًا معينًا.') WHERE id = 'd90627d2-0af7-4088-8ea2-59eaa2ccc0b5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا جدال في روعة سن 3 سنوات! آه، لولا تحديات هذه المرحلة… :) ستستمر خلال هذه الفترة خطوات الاستقلال التي بدأت في سن 2. وقد تواجهين سلوكيات مثل رغبة طفلكِ في القيام بالأمور بمفرده، وعدم تقبله لتدخلكِ، والعناد. وقد يبكي طفلكِ في هذه المرحلة، بل قد تنتابه نوبات غضب أحيانًا، لأنه لا يستطيع دائمًا التعبير عن مشاعره وأفكاره بصورة كاملة. وسيساعدكِ إدراك أن هذه السلوكيات هي طريقته للتعبير عن احتياجاته والتأكد من أنكِ تفهمينه على التعامل معه بصورة أكثر فاعلية. ولتقليل نوبات الغضب والبكاء، يمكنكِ بدلًا من الغضب منه تعليمه فهم المشاعر والتمييز بينها من خلال أنشطة متنوعة تتعلق بالعواطف. وبعد أن يتعرف طفلكِ إلى مشاعره، يمكنكِ القيام معه بتمارين تساعده على التعبير عنها بالكلمات.') WHERE id = 'fb8117d2-23da-46f7-96e8-b23a38bf77ec';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تتغير تفضيلات طفلكِ الغذائية من يوم إلى آخر؛ فقد يأكل طعامًا بشهية في يوم، ثم يرفضه في يوم آخر. المهم أن تقدمي له على المائدة أطعمة صحية ومتنوعة، وتتركي له اختيار ما يريد تناوله والكمية التي تناسبه. وإلى جانب الأطعمة المألوفة والمحببة إليه، يمكنكِ من حين إلى آخر تشجيعه، من دون إجباره، على تذوق قطعة صغيرة فقط من طعام جديد. ولا تتوقعي منه أن يتناول حصة كاملة من هذا الطعام فور تذوقه للمرة الأولى. ويمكنكِ تقديم الطعام الذي سيجربه لأول مرة إلى جانب الأطباق الرئيسية. ومن المهم لصحته أن تضم وجباته الرئيسية أطعمة من مجموعات البروتين والحبوب والخضراوات. كما أن إعداد أطباق ملونة ومرحة تجذب اهتمامه، والسماح له بتناول الطعام بنفسه، سيزيدان شهيته.') WHERE id = '762fb583-ab88-4246-85a9-964005a3eff6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لم تكوني قد نقلتِ طفلكِ إلى غرفة منفصلة بعد، فقد تنتظركِ مرحلة صعبة. فالفصل بين سريركما عملية صعبة بحد ذاتها، وكل محاولة غير ناجحة تجعل الخطوة التالية أصعب قليلًا. لذلك، ينبغي اختيار الوقت المناسب لنقل طفلكِ إلى سريره وتخصيص الطاقة اللازمة لهذه العملية. وعلى الرغم من أن الأطفال لا يفكرون بالطريقة نفسها التي نفكر بها، ولا يستطيعون بعد استيعاب أمور كثيرة، ولا سيما المفاهيم المجردة، فإنهم يحتاجون أيضًا إلى شرح ما سيحدث قبل أي تغيير. ولتهيئة طفلكِ، ينبغي أن تُعدّي غرفته وسريره وتساعديه على حبهما. وضعي جميع ألعابه وملابسه في أماكن مناسبة داخل الغرفة بحيث يستطيع الوصول إليها. وفي ديكور الغرفة، اختاري الدرجات الفاتحة من الألوان المهدئة مثل الأزرق والأخضر، بدلًا من درجات الأحمر والأصفر والبني التي قد تجعل النوم أكثر صعوبة. ولا تنسي أن تخبريه قبل كل نوم بمدى حبكِ له، وأنكِ ستكونين إلى جانبه كلما احتاج إليكِ.') WHERE id = '843a47c0-4aff-4ff5-85ba-6031f15fc752';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تشمل مهارات العناية بالذات نظافة الطفل الشخصية واعتناءه بنفسه. ويتضمن ذلك أن يتناول طفلكِ الطعام بمفرده، ويهتم بنظافته، ويرتدي ملابسه، أي أن يتمكن باختصار من الاعتماد على نفسه. ومن السلوكيات المتوقعة من طفلكِ في هذه الأشهر أن يرتدي من دون مساعدة الملابس الخالية من الأربطة أو الأزرار، وأن يميز بين الجهة الأمامية والخلفية للملابس، وأن يذهب إلى المرحاض بمفرده عند الحاجة. ولدعم تطور مهارات العناية بالذات، شجعيه على أداء كل ما يستطيع القيام به. كما ستسهم في ذلك الأنشطة البسيطة التي تمارسانها معًا خلال اليوم. فعلى سبيل المثال، عندما تستيقظان صباحًا، أخبريه أنكما ستذهبان معًا إلى الحمام لغسل اليدين والوجه. اغسلي يديكِ ووجهكِ أولًا، ثم خذي المنشفة وأريه كيف تجففينهما. قولي له: “انظر، لقد غسلت يدي ووجهي الآن، وأنا أجففهما بالمنشفة”، ثم قولي: “حان دورك الآن”، واطلبي منه القيام بالأمر نفسه.') WHERE id = 'f0bf3df0-c2a3-4852-8e59-7d26c9ec2d21';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'على الرغم من أن طفلكِ يتعلم في هذه المرحلة القيام ببعض الأمور بصورة مستقلة، فإنه لا يمتلك بعد القدرة الجسدية التي تمكّنه من فعل كل شيء. وبالمثل، حتى وإن كان يعرف كلمات أكثر ويستطيع تكوين بعض الجمل، فإنه لا يملك بعد القدرة الكاملة على التعبير شفهيًا عن جميع مشاعره وأفكاره. لذلك، قد تنتابه بعض نوبات الغضب عندما لا يتمكن من فعل ما يريده بالطريقة التي يرغب فيها أو عندما يعجز عن التعبير عن نفسه. فعدم قدرته على التعبير عن نفسه بصورة كاملة بسبب محدودية مهاراته الجسدية واللغوية قد يسبب له التوتر. كذلك، ولأنه لا يعرف دائمًا كيف يعبّر بالكلمات عن احتياجاته، مثل الملل أو التعب أو الجوع، فقد يحاول إبلاغكِ بها وجعلكِ تفهمينه من خلال الصراخ أو البكاء أو إلقاء نفسه على الأرض. إن إدراككِ لهذه الأمور ومعرفتكِ أن هذا السلوك طبيعي لدى الأطفال في هذا العمر أمران مهمان للغاية في طريقة تعاملكِ مع طفلكِ. ولتقليل نوبات الغضب والبكاء، يمكنكِ بدلًا من الغضب منه مساعدته على فهم مشاعره والتمييز بينها من خلال أنشطة عاطفية متنوعة، حتى يتعلم التعبير عن مشاعره وأفكاره بطرق أكثر فاعلية.') WHERE id = 'bc00e9df-4632-4728-bd4b-cc292b91d13e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد القواعد والانضباط من الأسس التي لا غنى عنها في التربية الفعالة، كي يكون طفلكِ أكثر نجاحًا في المستقبل. فالبيئة التي تُرسَم فيها الحدود بوضوح وحزم هي البيئة التي تدعم نمو طفلكِ على النحو الأمثل. ولا تحدّ القواعد من حرية طفلكِ، بل تساعده على اكتساب الاستقلالية ضمن بيئة آمنة، والتمييز بين الخير والشر والصواب والخطأ، وتنمية الانضباط الذاتي. لكن من المهم جدًا أن تستند هذه القواعد إلى نظام واضح وأن تكون متسقة. فإذا سمحتِ بشيء في يوم ثم منعتِه في اليوم التالي، فقد يضعف ذلك احترام طفلكِ للقواعد. كما قد تؤدي القيود غير الضرورية إلى عدم فهمه للموقف واعتراضه عليه. أما القواعد الموضوعة لمواقف مفهومة ويمكن توضيح أسبابها، فتكون أكثر واقعية وأسهل تطبيقًا بالنسبة إلى طفلكِ.') WHERE id = 'daec4206-a96e-46c2-8e87-38016160371c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'رغم معرفتكِ بفوائد السمك الكثيرة، قد لا تعرفين كيف تقنعين طفلكِ بتناوله. وكما هو الحال مع جميع الأطعمة، يحتاج طفلكِ إلى رؤية الطعام 10-20 مرة وملاحظة تناوله بانتظام على مائدة الأسرة حتى يعتاد عليه ويحبه. ولأن البالغين أيضًا يتناولون السمك بوتيرة أقل مقارنة بالأطعمة الأخرى، فمن الطبيعي جدًا أن يستغرق طفلكِ وقتًا أطول للاعتياد عليه. وتذكّري أن طفلكِ يمر بمرحلة يكون فيها شديد العناد ومائلًا إلى رفض الكثير من الأطعمة. لذلك، فإن رفضه السمك خلال مرحلة انتقاء الطعام لا يعني بالضرورة أنه لا يحب مذاقه أو أنه لن يحبه أبدًا. وعلى عكس أنواع اللحوم الأخرى، غالبًا ما يُقدَّم السمك كاملًا، وقد ينزعج طفلكِ من رأسه أو ذيله أو عينيه اللتين تبدوان وكأنهما تنظران إليه. وإذا كان هذا ينطبق على طفلكِ، فقد يكون من المفيد تحضير السمك وتقديمه على هيئة شرائح فيليه أو قطع.') WHERE id = '3ce2c11b-ecd0-47c6-af07-b3a6d4a2ed23';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع تطور قدرات طفلكِ اللغوية بدرجة أكبر، قد يبدأ في طرح الكثير من الأسئلة عليكِ خلال هذه المرحلة. ومن المحتمل أن تسمعي منه أسئلة تهدف إلى التعلّم، مثل: «لماذا تتساقط أوراق الأشجار؟»، أو «لماذا الشمس صفراء؟»، أو «لماذا البحر أزرق؟». كما يبدأ طفلكِ في هذه المرحلة بفهم مفهومي «المتشابه» و«المختلف»، وبمقارنة أحجام الأشياء وأشكالها وألوانها والتمييز بينها. ونظرًا إلى التطور الكبير الذي يشهده خياله، قد تلاحظين أنه أصبح يمارس ألعاب التقليد بطريقة أكثر إبداعًا. وفي الوقت نفسه، قد تظهر لديه مخاوف لم تكن موجودة من قبل بسبب نمو خياله؛ كأن يعتقد بوجود وحش مختبئ في المنزل، أو يتخيل أن لديه رفيق لعب وهميًا ينام معه ليلًا. وقد تلاحظين أيضًا أنه يتذكر بعد مرور بعض الوقت أجزاءً من القصص التي رويتِها له، ثم يحكي لكِ المقاطع التي بقيت في ذاكرته.') WHERE id = 'd3b957d4-3ab1-417b-8bbe-00cb8a21a286';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يُلاحظ اضطراب الكلام المعروف بالتأتأة لدى نحو 5% من الأطفال الذين تتراوح أعمارهم بين 2-6 سنوات، وهي الفئة العمرية التي ينتمي إليها طفلكِ. وقد تظهر ضمن هذه الفئة العمرية، وتحديدًا بين عمر 3-4 سنوات، حالة تُعرف بالتأتأة الفسيولوجية. كما تُلاحظ مشكلة التأتأة لدى الأولاد بمعدل يقارب ضعفي معدلها لدى البنات. ويشير المتخصصون إلى أن مشكلات النطق، مثل التأتأة، قد تسبب صعوبات كبيرة داخل الأسرة وخارجها، فضلًا عن مشكلات مختلفة في التكيّف. لذلك، إذا كان هناك أيضًا تاريخ عائلي لاضطرابات النطق، فمن الضروري طلب الدعم من متخصص. وعند استشارة متخصص دون تأخير والتدخل مبكرًا، يمكن أن تتحسن مشكلة التأتأة بنسبة 80% قبل الوصول إلى مرحلة المراهقة. وإذا كان طفلكِ يعاني من هذه المشكلة، فينبغي ألا تلوميه أو تضغطي عليه خلال هذه الفترة.') WHERE id = '42f63232-fd9a-4cbc-b534-0404c45b38f0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد البقوليات المجموعة الغذائية الأعلى محتوىً بالألياف. ولذلك، فهي تساعد على توازن سكر الدم من خلال إبطاء معدل إفراغ المعدة وامتصاص الغلوكوز من الأمعاء الدقيقة. كما تساهم في الحفاظ على كوليسترول الدم وضغط الدم ضمن المستويات المرغوبة. وتنتفخ في المعدة عند امتصاصها الماء، مما يمنح شعورًا بالشبع ويوفر لطفلكِ الطاقة التي يحتاج إليها خلال اليوم. وإلى جانب ذلك، تتميز بعض الخضراوات والأطعمة الجافة، مثل الحمص والفاصولياء المجففة والبروكلي والقرنبيط، بقدرتها على التسبب في الغازات رغم فوائدها الصحية. إن تناول طفلكِ لهذه الأطعمة مفيد جدًا! لكن عليكِ التأكد من أنه لا يتناولها تباعًا أو بكميات كبيرة. ويجب أن تتخلصي من ماء نقع البقوليات التي تستخدمينها في إعداد الوجبات، ثم تغسليها جيدًا. كما أن إضافة ملعقة من الشمر أو جوزة الطيب إلى الطعام قد تساعد على الوقاية من الغازات.') WHERE id = 'ef688bea-192e-4e4e-8e2b-89b299796329';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'على الرغم من أن نمو العضلات المسؤولة عن التحكم في التبول والتبرز يكتمل في الشهر 18، فقد لا يتمكن طفلكِ من التحكم الكامل قبل سن الثالثة. وخلال هذه المرحلة، قد ينجح في استخدام المرحاض نهارًا، لكنه قد يظل بحاجة إلى المساعدة ليلًا. كوني صبورة، ولا تتعجلي أو تبالغي في رد فعلكِ. تجنبي توبيخه أو لومه عندما يبلل ملابسه، واشرحي له أن مثل هذه الحوادث قد تقع من وقت إلى آخر. وفي هذه الحالات، يمكنكِ منحه بعض المسؤوليات البسيطة، مثل خلع سرواله ووضعه في سلة الملابس المتسخة. شجعيه على الذهاب إلى الحمام ليس لقضاء حاجته فحسب، بل أيضًا لاكتساب عادات مثل غسل اليدين وتنظيف الأسنان. وبدلًا من سؤاله باستمرار: «هل تحتاج إلى الذهاب إلى الحمام؟»، راقبي كمية السوائل التي يتناولها ووجهيه بقولكِ: «حان وقت الذهاب إلى الحمام الآن».') WHERE id = '127bfb16-6c2c-4ee2-8f0f-55e5671db200';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ الآن يبتكر الألعاب ويكوّن الصداقات، ويستمتع كثيرًا بقضاء الوقت مع أقرانه. لكنكِ قد تشهدين أحيانًا حدوث بعض الخلافات بينهم. فقد يتصرف وكأنه يعرف كل شيء، أو يحاول فرض سيطرته على أصدقائه، وقد يسيء التصرف ويسبب المشكلات عندما لا تتحقق رغباته. عند مساعدته على حل النزاعات مع أقرانه، امنحيه فرصة للتعبير عن رأيه، وتحدثي معه عن الحلول الممكنة، واطلبي منه أن يحاول حل المشكلة بنفسه. ادعميه ليصبح شخصًا مستقلًا وقادرًا على الاعتماد على نفسه. فتدخلكِ المستمر في تواصله مع أصدقائه قد يؤثر سلبًا في تطور مهاراته الاجتماعية. لذلك، من الأفضل أن تتركيه يلعب بحرية، وأن توفري بيئة آمنة بعد التأكد من أنهم لن يؤذوا بعضهم، ثم تراقبيهم من بعيد. ننصحكِ خلال هذه المرحلة بأن تعاملي طفلكِ قدر الإمكان كشخص ناضج، وأن تدعميه ليحل مشكلاته بنفسه.') WHERE id = 'ef337793-35af-4f64-93e3-376a6a149769';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'احرصي على توزيع جميع أنواع الطعام بصورة متوازنة ضمن النظام الغذائي اليومي لطفلكِ. ويُنصح بأن يتناول 6 حصص يوميًا من مجموعة الحبوب. وتعادل الحصة الواحدة من الحبوب: شريحة واحدة من الكعك، أو شريحة واحدة من الخبز، أو نصف كوب من الأرز أو المعكرونة. ويجب أن يتناول 5 حصص يوميًا من مجموعة الفواكه والخضراوات؛ فعلى سبيل المثال، تُعد حبة متوسطة الحجم من الخوخ أو التفاح، أو نصف كوب من الخضراوات، حصة واحدة. ويحتاج إلى 3-5 حصص يوميًا من مجموعة الدهون؛ وتعادل ملعقة شاي واحدة من الزبدة أو زيت الزيتون حصة واحدة. كما يجب أن يتناول حصتين يوميًا من مجموعة اللحوم؛ وتعادل 1-3 ملاعق طعام من الدجاج أو اللحوم الحمراء أو السمك حصة واحدة. ويمكن أيضًا أن تحل بيضة واحدة أو 4-5 ملاعق طعام من البقوليات محل حصة واحدة من اللحوم. أما منتجات الألبان، فيُنصح بتناول 3 حصص منها يوميًا؛ وتُعد قطعة جبن بحجم علبة كبريت، أو 3/4 كوب من الحليب أو الزبادي، حصة واحدة. وهكذا، يمكنكِ من خلال التغذية المتوازنة الحفاظ على صحة طفلكِ وتقوية جهازه المناعي.') WHERE id = '4bf4b02c-af51-47f9-ba7a-47457d6c50de';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع دخول طفلكِ هذه المرحلة المعروفة باسم «مرحلة اللعب»، أصبح مفعمًا بطاقة كبيرة يصعب عليه تفريغها بمفرده في المنزل. وتُعد الحضانة البيئة الأنسب لتفريغ هذه الطاقة، كما يُعد عمر 3-3,5 سنوات السن المثالية لبدء الالتحاق بها. يجد الأطفال الذين ليس لديهم إخوة في المنزل أصدقاء جددًا في الحضانة، ويتعلمون المشاركة ويكتسبون حس المسؤولية. قد تفكرين قائلة: «طفلي خجول وقد يواجه مشكلات في الحضانة». لكن الخبراء يشيرون إلى أن مشكلة الخجل لدى الأطفال غالبًا ما تبدأ بالتحسن بعد التحاقهم بالحضانة وبدئهم في التفاعل الاجتماعي. وإذا لاحظتِ أن طفلكِ يواجه صعوبات كبيرة في التأقلم مع البيئة الجديدة، فلا تجبريه، وانتظري حتى يصبح مستعدًا.') WHERE id = 'ae372f82-277f-4b8f-b759-2dccdf242ba6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ الآن قادرًا على تكوين جمل بسيطة تتألف من 3-4 كلمات. ويمكنه تنفيذ تعليمات مكونة من خطوتين، مثل: «خذ جهاز التحكم وأحضره إليّ». وقد تظل الضمائر صعبة عليه بعض الشيء، لذلك من الطبيعي أن تسمعي منه جملًا قصيرة خالية من الضمائر، مثل: «كُل الطعام» و«أحضر الماء». وخلال هذه الأشهر، يمكنه العد حتى 10، ويتعلم طرح أسئلة مثل: «ماذا؟ وأين؟ ومن؟». ومع وصول تطوره اللغوي إلى مستوى أفضل، يحاول طفلكِ التحدث بطلاقة أكبر، وتزداد حصيلته اللغوية تدريجيًا. وبفضل تطور قدراته الذهنية، قد يمزح معكِ أيضًا، بل قد يستمتع أحيانًا بإغاظتكِ بهذه المزحات. ومع ذلك كله، قد لا تتمكنين حتى الآن من فهم نصف ما يقوله. وإذا لاحظتِ أنه متأخر كثيرًا عن أقرانه في هذا الجانب، فيمكنكِ استشارة مختص.') WHERE id = '953823ad-cdcb-41ad-830e-fd7b2c088e70';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد تعليم الموسيقى خلال هذه المرحلة وسيلة فعالة للغاية لغرس بعض المفاهيم والقيم لدى الأطفال. كما يؤدي تعليم الموسيقى دورًا إيجابيًا في النمو النفسي للطفل، ويساعد طفلكِ على اكتساب عادات حياتية سعيدة برفقة الأطفال الآخرين. وتؤثر الأنشطة الموسيقية أيضًا في النمو الحركي النفسي؛ فعلى سبيل المثال، يدعم استخدام الطفل للآلات الموسيقية نمو العضلات الكبيرة والدقيقة. وإذا استمع الأطفال إلى موسيقى عالية الجودة منذ سن مبكرة، فسيصبحون في المستقبل أشخاصًا بالغين قادرين على اختيار الموسيقى الجيدة وحبها والاستمتاع بها، حتى إن لم يصبحوا موسيقيين. ويجب ألا ننسى أن الأطفال قد لا يمتلكون جميعًا الدرجة نفسها من الموهبة الموسيقية، لكنهم جميعًا يحبون الموسيقى.') WHERE id = 'fedbb0d2-4a4b-4ba8-9970-6d8a02f5d453';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمر طفلكِ الآن بمرحلة يستطيع فيها اللعب بألعابه لفترات أطول ويستمتع بابتكار ألعابه بنفسه. لذلك، من المفيد شراء ألعاب تناسب عمره وتسهم في تنمية قدراته الذهنية. وبما أنه بدأ يميّز الألوان بوضوح، يمكنكِ اختيار ألعاب مرتبطة بالألوان؛ فهي ستسلّيه وتمنحه شعورًا بالسعادة والإنجاز. ومن الألعاب المناسبة التي يمكنكِ اختيارها: المكعبات الخشبية، والصناديق، وقطارات الألعاب، والدمى، والمجسمات الهندسية المختلفة ثلاثية الأبعاد، وغيرها من الأشياء المشابهة. ويُعد تكوين شكل متكامل من قطع صغيرة من أكثر الألعاب تشويقًا في هذه المرحلة، لذا يمكنكِ شراء الأحاجي وألعاب التركيب ومجموعات الليغو لطفلكِ. وليس من الضروري أن يلعب بألعاب باهظة الثمن، إذ يمكنكِ أيضًا ابتكار ألعاب له باستخدام أشياء مختلفة موجودة في المنزل. وسيستمتع طفلكِ كثيرًا في هذه المرحلة بألعاب التخيّل والتمثيل الرمزي باستخدام شخصيات وأشياء من ابتكار خياله.') WHERE id = 'eeac9ed5-495a-4af1-9154-9727dc9ff6ba';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بما أن طفلكِ أصبح قادرًا على استخدام الملعقة والشوكة بمفرده، فإنه يستطيع تناول طعامه بسهولة أيضًا. ومن المهم أن يجلس معكِ إلى المائدة ويتناول الطعام برفقتكِ، فذلك يساعد على اكتساب عادات غذائية سليمة. وقد تبدو لكِ كمية الطعام التي يتناولها قليلة، لكنها في الواقع طبيعية وكافية تمامًا بالنسبة إلى عمره. أما محاولة إطعامه باستمرار لاعتقادكِ بأنه لم يشبع، فقد تؤدي إلى مشكلات صحية خطيرة في المستقبل. يحتاج الطفل في عمر 3 سنوات إلى نحو 1200 سعرة حرارية يوميًا في المتوسط. وقد يختلف ذلك من طفل إلى آخر، لذا يمكنكِ استشارة مختص لمعرفة احتياج طفلكِ الفردي من السعرات الحرارية. وينبغي أن يتضمن نظامه الغذائي اليومي 3 وجبات رئيسية و2-3 وجبات خفيفة. من المهم متابعة تناول طفلكِ طعامًا منتظمًا ومتوازنًا، والتأكد من عدم تفويت الوجبات الرئيسية أو الخفيفة.') WHERE id = '8f0a3b9b-c1b6-48d1-8194-b380ad4ebe6e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ لا يرغب في النوم، فقد يكون أحد الأسباب المحتملة أنه لا يريد ترك والدته ووالده بمفردهما. فالأطفال في الفئة العمرية من 3 إلى 6 سنوات يمرون بالمرحلة الأوديبية، ولذلك قد لا يحبون رؤية والديهم منفردين معًا، حتى خارج وقت النوم. وقد يتوقع الطفل أن يمنحه الوالد من الجنس الآخر كل حبه وحده، كما قد يشعر بالغيرة من العلاقة بين والديه. لا تقلقي، فهذه مرحلة مؤقتة. ومع ذلك، ليس من الصواب الاستجابة لكل رغبات طفلكِ والنوم بجواره خلال هذه المرحلة. وفي بعض الأحيان قد يكون السبب مختلفًا؛ فبعض الأطفال لا يشعرون بأنهم يحظون باهتمام كافٍ من والديهم، لذلك يحاولون استغلال وقت النوم للتواصل معهما. إلا أن الوقت الذي يقضيه الطفل مع والديه عند النوم لا يكون فعّالًا في تلبية احتياجه إلى التواصل بقدر الوقت النشط والجيد الذي يقضيه معهما. لذلك، حاولي قدر الإمكان استثمار الأوقات خارج ساعات النوم بطريقة جيدة لتعزيز ارتباط طفلكِ بكِ.') WHERE id = '09a880ca-a8b7-4625-9ae1-bbc95ae9f537';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بينما يكتسب طفلكِ خبرات جديدة كل يوم، من المهم جدًا أن تمدحيه بعد كل محاولة ناجحة. ويمكنكِ أيضًا تحويل هذا التشجيع إلى مكافأة ملموسة من خلال إعداد جدول وتعليقه على الحائط. أنشئي في هذا الجدول مخططًا يغطي 7 أيام، وضعي معه، على سبيل المثال، ملصقًا لشخصية يحبها في الخانة المخصصة لكل ليلة نام فيها بانتظام. وفي نهاية الأسبوع، إذا تجاوز عدد الملصقات الحد الذي حددتِه، يمكنكِ شراء هدية صغيرة له أو القيام معًا بنشاط يحبه. ومن المهم أيضًا الإشادة بجهود طفلكِ أمام الضيوف. وإذا كان يذهب إلى الحضانة أو المدرسة، فيمكنكِ إشراك معلمته أو معلمه في هذا النظام. أخبري معلمته أو معلمه في اليوم التالي لكل ليلة ينام فيها جيدًا، حتى يحظى بالثناء في مؤسسته التعليمية أيضًا؛ فهذا سيكون مصدرًا كبيرًا لثقته بنفسه.') WHERE id = 'c2cf3063-80b7-4cce-b4a4-43230a67a805';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بعد أن يتعلم طفلكِ الوقوف، يستمر نموه بوتيرة سريعة. وحين يتقن الحفاظ على توازنه، يبدأ بالاستمتاع بأنشطة مثل القفز من أماكن مختلفة، والتوقف فجأة وتغيير الاتجاه أثناء الركض، ولعب الكرة، والتسلق. ويساعد تخصيص وقت يومي لمثل هذه الأنشطة في الحديقة أو الفناء أو حصص الجمباز على تقوية جسم طفلكِ. كما تساعد ممارسة هذه الأنشطة في الطقس المشمس على تقوية عضلاته وعظامه. ويمكنكِ أيضًا إعداد مسار حواجز داخل المنزل ليستمتع بوقته. ومن الأنشطة الممتعة التي يمكنكما ممارستها معًا في المنزل: الغميضة، والرقص، والشقلبة. هذه الحركات سهلة جدًا، وستمنح طفلكِ المتعة وتؤثر إيجابيًا في نموه البدني.') WHERE id = 'ebe52971-5876-4787-8235-17c23e1fdb6f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمر طفلكِ الآن بمرحلة يبدأ فيها اللعب مع أقرانه. ومن خلال علاقاته بالأطفال الآخرين، سيتعرف إلى مفاهيم مثل الانتظار، وتأجيل الرغبات، والالتزام بالدور، وحل الخلافات. كما تبدأ في هذه المرحلة مهاراته الاجتماعية، مثل التعاون، بالتطور. ومن الطبيعي تمامًا أن يختبئ خلفكِ خجلًا عند دخوله بيئة جديدة أو عندما يسأله أحد عن اسمه. امنحيه الوقت الكافي حتى يعتاد على المكان ويشعر بالأمان. وقد يفضّل طفلكِ اللعب أكثر مع أقرانه من الجنس نفسه. ومن المهم جدًا ألا تتدخلي في علاقاته بأقرانه، وأن تحترمي اختياراته وألعابه.') WHERE id = '8455bcdc-fada-4c0f-a7dd-2a2412059239';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تبدأ علاقة طفلكِ الأولى بالكتاب بين عمر 0-6 سنوات. ومن مسؤوليتكِ بصفتكِ أمًا أن تساعديه على اكتشاف الكتاب وتنمية اهتمامه به. وعند شراء الكتب له، ينبغي مراعاة عمره وخصائص نموه. في هذه المرحلة، اختاري كتبًا تحتوي على صور للمواقف والكائنات والأشياء التي يراها في محيطه. قد ينظر طفلكِ إلى صور الكتب التي تقرئينها له، ويقلّد أصوات الكائنات والأشياء، ويطرح أسئلة حول الصور. وقد يطلب منكِ توضيح العلاقة بين النصوص والصور. خلال هذه الفترة تتسع معرفة الطفل بمحيطه، وتتطور اهتماماته، وتزداد مهاراته اللغوية. يمكنكِ اختيار كتب تدعم إبداعه، وتركز على أسباب الأحداث، وتحكي عن مواقف مرتبطة بالحياة اليومية. ويتطلب تحويل القراءة إلى عادة جهدًا خاصًا من الوالدين والمعلمين. والنقطة الأهم هنا هي أن تكوني قدوة له، بدلًا من الاكتفاء بنصيحته قائلة: «اقرأ كتابًا».') WHERE id = '7afbe40c-9017-45b7-9741-68b1e5e44bb0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدءًا من عمر 2-3 سنوات، يبدأ طفلكِ بالتعرّف إلى هويته الجنسية بالتزامن مع التدريب على استخدام المرحاض. ومن العوامل التي تسرّع هذه العملية وجود أخ أو أخت من الجنس الآخر، أو اختلاطه في الحضانة بأطفال من الجنس الآخر. أما الأطفال الذين لا يذهبون إلى الحضانة، وليس لديهم إخوة أو أخوات، وتكون دائرتهم الاجتماعية محدودة، فقد يميّزون ذلك في وقت لاحق. ومع ذلك، من المهم أن يدرك الطفل جنسه ويعرف الفروق بينه وبين الجنس الآخر بحلول سن 5 سنوات على أقصى تقدير. ويُتوقع توضيح هذه المفاهيم وتعليمها داخل الأسرة، حتى يصبح الطفل قادرًا على التعبير عن هويته كفتاة أو فتى. قد يبدأ طفلكِ خلال هذه المرحلة بطرح أسئلة تتعلق بالجنس، وينتظر الإجابة من أقرب الأشخاص إليه وأكثرهم ثقة، أي والديه. ومن المهم أن يطرح عليكِ أسئلته وأن يستمر فضوله. ينبغي أن يكون الهدف هو تشجيع الطفل على السؤال وتلقّي الإجابات من الأشخاص الذين يثق بهم أكثر من غيرهم، من دون تردد. إذا أخّرتِ الإجابة في مثل هذه المواقف أو أظهرتِ موقفًا يتضمن إصدار الأحكام عليه، فقد يتوقف بعد مدة عن طرح الأسئلة ويبحث عن الإجابات في مصادر أخرى. أجيبي عن أسئلة طفلكِ بأكبر قدر ممكن من الوضوح والإيجاز، بما يُشبع فضوله.') WHERE id = 'df5565ed-acef-4630-91e5-3e94babb0601';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يتوقف بعض الأطفال في هذا العمر عن أخذ القيلولة. وفي هذه الحالة، يمكنكِ تقديم موعد نومه مساءً. لا تنسي أهمية انتظام مواعيد النوم وحصوله على حاجته الكافية منه. إذا رفض النوم، فاشرحي له بهدوء، ومن دون أن تغضبي منه، أنه يحتاج إلى النوم وأن عليه الذهاب إلى سريره. وإذا استمر في الرفض، فيمكنكِ أن تطلبي منه قضاء بعض الوقت في غرفته أو قراءة كتاب. ويمكنكِ أيضًا الاستعانة برفيق النوم الذي اعتاد عليه سابقًا، مثل لعبته المفضلة. وقد يكون من المفيد كذلك إبقاء مصباح ليلي خافت الإضاءة في الغرفة. وقبل كل نوم، طمئنيه بأنكِ ستكونين إلى جانبه فورًا إذا ناداكِ، ولا تنسي منحه بضع قبلات إضافية. 🙂') WHERE id = '4b759359-897f-442e-898f-e91b4d1f488e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا تنسي أن طفلكِ أصبح الآن شخصًا مستقلًا. ومن الطبيعي أن تكون لديه أشياء خاصة يحبها وأخرى لا يحبها. وهذا يعني أنه سيصبح من الصعب توجيهه كما في السابق اعتمادًا على آرائكِ وحدها. وقد تواجهين اعتراضاته كثيرًا. ومن الطبيعي أن يغضب أو يبكي أو يعاند في بعض المواقف. وبدلًا من الرد عليه كما لو كان شخصًا بالغًا، حاولي التحدث إليه، فهذا غالبًا ما يساعد على حل المشكلة. فالطريقة التي تعاملينه بها ستنعكس على طريقة استجابته لكِ. ويقع على عاتقكِ الدور الأكبر في تنمية مهاراته في التواصل. احترمي مساحته الشخصية، ووجّهيه من دون فرض رأيكِ أو التدخل في أفكاره. بهذه الطريقة، لن يتردد في التواصل مع أم تستمع إليه وتحترمه، وسيتعلم مع مرور الوقت التعبير عن نفسه من دون بكاء أو عناد.') WHERE id = '121d280d-108f-470d-8ec1-2acd91b6403d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بعد أن تطور نمو طفلكِ اللغوي بدرجة كبيرة، أصبح قادرًا على استخدام الأسماء والأفعال والضمائر والصفات وصيغ الجمع بسهولة. وقد يشارك في النقاشات عندما تتحدثين مع الآخرين بحضوره. كما أصبح قادرًا على التعبير عن مشاعره بالكلمات، وليس بالحركات الجسدية فقط. وبالتزامن مع بدء تطور حس الفكاهة لديه، قد يتفاعل مع المواقف المضحكة. ويمكنه تنفيذ مهمتين أو ثلاث مهام متتالية، ويفهم الغرض من استخدام الأشياء. كما أصبح كلامه أكثر وضوحًا. وقد يردد من تلقاء نفسه عبارات صعبة النطق وأغاني، ويستطيع التمييز بين المفاهيم المتشابهة والمتضادة.') WHERE id = '38765ac8-4717-455f-8180-86f822819f07';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تتراوح مدة النوم المثالية للطفل في عمر 3 سنوات بين 10-13 ساعة. وقد يؤدي نومه لأكثر من 14 ساعة إلى إبطاء نموه العاطفي والجسدي. خلال هذه المرحلة، قد تفكرين في إيقاف قيلولة طفلكِ. لكن يُنصح بعدم إيقافها إذا كنتِ تريدين أن ينمو طفلكِ بهدوء واتزان أكبر. فالأطفال الذين يحصلون على قسط كافٍ من النوم وقت الظهيرة يتمتعون بنمو ذهني أسرع مقارنة بمن لا ينامون في هذا الوقت. وتُظهر الدراسات أن الأطفال الذين يأخذون قيلولة يكونون أكثر نشاطًا في التفكير والتذكر وحل المشكلات. وما دمتِ تحافظين على نظام نوم مثالي، فستظل القيلولة مفيدة له دائمًا.') WHERE id = '494c995c-0f5f-468c-ac19-77cfd1a4b7f4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نظرًا إلى أن طفلكِ ينتظره مشوار مدرسي طويل، فلا داعي للاستعجال في تعليمه تعليمًا رسميًا. احرصي على أن يقضي سنوات طفولته المبكرة في اللعب والاستمتاع قدر الإمكان. ومع ذلك، يبدأ كثير من الأطفال في هذا العمر بالاهتمام بالحروف والأرقام. فإذا كان طفلكِ متحمسًا ويستمتع بقضاء الوقت في تعلّم الحروف والأرقام، فلا مانع من أن تعلّميه المبادئ الأساسية. وعندما يبدأ بالتمييز بين الحروف، يمكنكِ شراء كتب أبجدية تربط الحروف بالأشياء. ضعي على رفوف الألعاب ملصقات مثل "الدمى" و"الكتب" و"السيارات"، وأضيفي بجانب كل كلمة صورة توضيحية لها. وبذلك سيتمكن من الربط بسهولة بين الكلمة والشيء.') WHERE id = '620dd0a6-5b3b-4996-884c-101ad6b8614b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يبدأ نمو الدماغ لدى الأطفال في رحم الأم ويستمر حتى سن البلوغ. لكن وفقًا للخبراء، يكتمل نمو الدماغ إلى حد كبير بحلول سن 5 سنوات. وخلال هذه الفترة، تُعد التغذية الصحية والمتوازنة لطفلكِ بالغة الأهمية لنموه الجسدي والعقلي. ويأتي البيض بالطبع في مقدمة الأطعمة التي تدعم نمو الذكاء. فهو عنصر أساسي في وجبة الإفطار، ويساعد بفضل محتواه العالي من البروتين على تعزيز التركيز لدى الأطفال. كما أنه غني بالفيتامينات الضرورية للذاكرة، ويحتوي على التيروزين اللازم لتمكين الدماغ من استقبال الإشارات وإرسالها، ويوفر الطاقة التي يحتاج إليها الجسم ليظل نشيطًا.') WHERE id = '346378cf-c32a-4e3a-aa35-d7f1c6bfb93c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد تطورت القدرات الحركية لطفلكِ الآن بشكل ملحوظ. فهو يركض بسهولة في خط مستقيم، كما أصبحت مهارته في القفز أكثر تطورًا. ومع إحرازه تقدمًا كبيرًا في النمو الجسدي، اتسع أيضًا نطاق ألعابه. إذ يبتكر ألعابًا بنفسه، بل بدأ بتوزيع المهام على أصدقائه الذين يلعب معهم. ويمكنه بسهولة أداء حركات مثل الشقلبة والقفز وصعود الدرج. وأصبح ركل الكرة المتدحرجة والتقاط الكرة الملقاة أمرين في غاية السهولة بالنسبة إليه. وقد تكون هذه المرحلة فرصة رائعة لتوجيه اهتمامه بالرياضة توجيهًا صحيحًا وتحقيق نتائج ناجحة.') WHERE id = 'fac45c7d-fc32-4650-9898-0271871259d3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا تكون احتياجات الأطفال في سن 3 سنوات إلى الطاقة والعناصر الغذائية مرتفعة بقدر ما كانت عليه خلال مرحلة الرضاعة. لكن بما أن نمو الجسم يستمر في هذه المرحلة العمرية، تظل التغذية السليمة بالغة الأهمية بالطبع. ويُنصح بأن تأتي 45-50% من الطاقة اليومية خلال هذه الفترة من الكربوهيدرات، و15-20% من البروتينات، و35% من الدهون. ينبغي لكِ التحدث مع طفلكِ عن أطعمة مثل الشوكولاتة والحلوى والمشروبات الغازية ورقائق البطاطس وإقناعه بالحد منها. واشرحي له أن هذه الأطعمة قد تؤثر سلبًا في صحته ونموه. وعند القيام بذلك، لا تغفلي عن الطريقة التي تعرّف بها إلى هذه الأطعمة أول مرة. فكلما تأخر تعرّفه إلى هذه الأطعمة، التي سيصادفها حتمًا في مرحلة ما من حياته، كان ذلك أفضل.') WHERE id = 'e0c4db2c-e5e7-44b0-acd7-3cd699b5d73e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ الآن فردًا قادرًا على اتخاذ قراراته بصورة مستقلة. ولذلك، سيصعب عليكِ توجيهه بالكامل وفق أفكاركِ كما كنتِ تفعلين من قبل. وقد يطلب أشياء مختلفة من أمه وأبيه في مواقف متعددة، كأن يقول: ‐أريد من أمي أن تقرأ لي كتابًا، ومن أبي أن يلعب معي‐. عليكِ الاستماع إلى رغباته وتفهّمها، وقبول ما هو مناسب منها، وشرح سبب عدم ملاءمة بعضها الآخر بأسلوب لطيف. وقد تُشعركِ أسئلته المتواصلة بالإرهاق بسبب فضوله الشديد في هذا العمر، لكن تحلّي بالصبر. فمساعدته على فهم أسباب القواعد تسهّل عليه الالتزام بها. كل ما عليكِ فعله هو أن تكوني ثابتة وواضحة. وستكون التذكيرات المهذبة والموجزة مثالية.') WHERE id = '5c814408-34ed-41f0-a49f-4e136c48eff6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذا العمر، يستطيع طفلكِ رسم خربشات بسيطة ضمن حدود معينة. ومع اكتشافه أشياء جديدة متعلقة بالرسم، يمكنه تطوير قدرته تدريجيًا نحو رسم أشكال بسيطة. وغالبًا ما يفضّل في رسوماته الخطوط الرأسية والأفقية والمائلة والمنحنية. كما يمكنه إنشاء مخططات أو أنماط معقدة انطلاقًا من أشكال رسمها سابقًا. ويبدأ برسم الرأس وملامح الوجه، ويمكنه رسم شكل إنسان يتكون في المتوسط من ثلاثة أجزاء. ورغم أن تفاصيل الجسم لا تظهر كثيرًا في رسوماته، فإنه يستطيع إكمال الأجزاء الناقصة من الجسم المرسوم. ويمكنكِ مساعدته على قضاء وقت ممتع والتعلّم بسهولة أكبر من خلال ممارسة تمارين رسم الخطوط خلال اليوم.') WHERE id = 'c493c5fe-d48d-4e7c-91e0-fe08465a7aee';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هذه مرحلة قد يُظهر فيها طفلكِ قدرًا كبيرًا من المبادرة. لكن منعه من المحاولة أو معاقبته عليها قد يؤثر فيه سلبًا. ولمساعدته على تجاوز التردد في المبادرة بصورة إيجابية، ينبغي تشجيعه بطريقة صحيحة ومتسقة. وهكذا سيتمكن من تحقيق توازن بين ما ينبغي له فعله وما ينبغي له تجنبه، وسيكتسب مهارة ضبط النفس. أما إذا مُنع باستمرار عن طريق العقاب، فقد يشعر بالذنب ولا تتطور لديه روح المبادرة بما يكفي. لذلك، فإن بناء تواصل صحي ومتسق مع طفلكِ ودعمه أمر بالغ الأهمية لتنمية مهارات التواصل التي سترافقه طوال حياته. ومساعدته على تطوير روح المبادرة ستسهم في أن يصبح فردًا فاعلًا في المجتمع مدى الحياة.') WHERE id = 'da3bc0fb-d618-4650-bd81-5423d3bc0091';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'طفلكِ واحد من أدق المراقبين الذين قد ترينهم. فهو يتعلم باتخاذ من حوله قدوةً له وتقليد سلوكياتهم. وعندما يراقب الشخص الذي يقتدي به، ينبغي أن يفهم السلوك بصورة صحيحة. فإذا رأى أن السلوك الذي يراقبه يُكافأ، ازدادت رغبته في تكراره. أما إذا عوقب ذلك السلوك، فسيتجنبه طفلكِ ويحاول ألا يفعله. ومن المهم جدًا، خلال اكتساب طفلكِ عادات جديدة، أن يُظهر الشخص الذي يقتدي به سلوكيات صحيحة. لذلك، وجّهي انتباه طفلكِ نحو القدوات الصالحة، واحرصي أنتِ أيضًا، بصفتكِ أمًا، على أن تكوني دائمًا مثالًا يُحتذى به.') WHERE id = '609dcb46-d1bd-4f1c-90ea-799e3c5e4531';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد التغذية السليمة والمتوازنة ضرورية للنمو الجسدي والذهني لطفلكِ. فالنمو الملحوظ، مثل زيادة الطول والوزن، لا يتحقق بصورة صحية إلا بالتغذية الجيدة. وتشير الزيادة المنتظمة في طول طفلكِ ووزنه إلى حصوله على غذاء كافٍ. ولضمان نمو صحي، ينبغي أن يتناول أطعمة من جميع المجموعات الغذائية. احرصي على أن يشمل نظامه الغذائي مختلف الخضراوات والفواكه، إلى جانب اللحوم ومنتجات الألبان والبيض والبقوليات. وتذكّري أن تناول طفلكِ كميات كبيرة من الطعام لا يعني بالضرورة أنه يتغذى جيدًا. فقد يبدو وزن الطفل الذي يتناول يوميًا أطعمة منخفضة القيمة الغذائية، مثل المقليات أو المعكرونة، طبيعيًا، لكنه قد يتأخر في النمو لعدم حصوله على العناصر الغذائية المفيدة.') WHERE id = '056726bd-6460-4e68-8506-371ea64792ec';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تظهر بعض المشكلات إذا لم تسمحي لطفلكِ بأداء المهام التي يستطيع إنجازها بنفسه. فإذا لبّى الآخرون كل طلباته، فقد تضعف بعض مهاراته. وعندئذٍ سينتظر من غيره القيام بكل شيء بدلًا من أن يفعله بنفسه، وسيتجنب تحمّل المسؤولية. ومن الطبيعي أن يرغب الوالدان في حماية طفلهما، لكن الإفراط في الحماية قد يؤثر سلبًا في نموه الفردي ويجعله معتمدًا على أسرته. فعلى سبيل المثال، منعه من الاختلاط بالآخرين خوفًا من أن يمرض يقلل ثقته بنفسه. وبدلًا من الإفراط في حمايته، أوكلي إليه مسؤوليات صغيرة تناسب قدراته. فهذه المسؤوليات ستساعده على أن ينشأ فردًا مستقلًا.') WHERE id = '35c295ce-6938-40be-bd01-33d29397e9d3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدءًا من عمر 3 سنوات، يبدأ طفلكِ أولًا بإبداء الفضول تجاه أعضائه التناسلية، ثم تجاه الموضوعات الجنسية المحيطة به. وهذا جزء طبيعي من عملية النمو النفسي والاجتماعي. وقد يطرح الأطفال في هذه المرحلة أسئلة مختلفة على والديهم. حاولي أن تشرحي لطفلكِ الموضوع أو السلوك الذي يثير فضوله بطريقة تناسب عمره. لكن لا تلجئي أبدًا إلى الكذب أو الشرح المعقد؛ بل قدّمي له توضيحات بسيطة ومفهومة. فقد تؤدي المعلومات الناقصة إلى تكوّن أفكار خاطئة ومخاوف لدى الطفل، وإلى مشكلات في نموه الجنسي مستقبلًا. وتختلف أوقات ظهور هذه الأسئلة والمراحل من طفل إلى آخر تبعًا للعوامل البيئية. والاستجابة لفضوله بصورة طبيعية جزء من عملية النمو هذه.') WHERE id = '727f21dd-8b8d-4256-8326-d8a14decc7b4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي التخطيط لأنشطة مناسبة تساعد الأطفال في عمر 3 سنوات على تطوير المهارات الحركية الدقيقة، التي تحظى بأهمية كبيرة في تعليم مونتيسوري. فتطور المهارات الحركية الدقيقة يدعم مهارات الكتابة، كما أن البراعة اليدوية مؤشر على التطور العقلي. لذلك، تُعد الأنشطة التي تُشغّل أصابع طفلكِ الصغيرة مفيدة جدًا. وإليكِ بعض الاقتراحات: يُعد التقاط الأشياء ونقلها باستخدام ملقط نشاطًا ممتعًا وتعليميًا في آنٍ واحد. كما تساعد مهام الحياة اليومية، مثل إغلاق الأزرار وربط أربطة الحذاء، على تنمية هذه المهارات. وإذا لم يتمكن طفلكِ من إنجازها من المحاولة الأولى، فيمكنكِ تعزيز ثقته بنفسه بعبارات مشجعة مثل: «لا بأس، هل نحاول مرة أخرى؟».') WHERE id = 'b1b27ccb-a59d-4f78-b850-b6b85156fdf3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ يأكل أثناء مشاهدة التلفاز، فهو أولًا لا ينتبه إلى أنه يتناول الطعام. فبالنسبة إليه، الأمر مجرد مشاهدة ممتعة للتلفاز. ولأن الأطفال يتعلمون من خلال التجربة، فإن تناول الطعام أمام التلفاز يمنعهم من اكتساب عادات غذائية سليمة. وقد يعاني الطفل الذي لا يتعلم هذا السلوك بالقدر الكافي في مراحل عمرية لاحقة من سوء التغذية، أو عدم الرغبة في الجلوس إلى المائدة، أو الانتقائية في الطعام، أو عدم القدرة على تناول الطعام بمفرده. وعند تناول الطعام أمام التلفاز أو الحاسوب، قد يواصل الأطفال الأكل طوال مدة اللعبة أو الفيلم من دون الشعور بالشبع. وهذا سيؤثر سلبًا في شعور طفلكِ بالجوع في الوجبة التالية وفي توازنه الغذائي اليومي. وهكذا قد تمنعينه من اكتساب القدرة على إدراك شعوره بالشبع والتوقف عن الأكل.') WHERE id = 'a4f1d0bd-58eb-4370-bb57-6949cd1e1527';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بعد سن 3 سنوات، إذا كان طفلكِ قادرًا على بصق معجون الأسنان، فيمكنه تنظيف أسنانه باستخدام معجون أسنان مخصص للأطفال. وللأسف، قد يحدث تسوس الأسنان حتى لدى الأطفال الذين لا يتناولون الشوكولاتة أو الحلويات أو الأطعمة المشابهة. فعلى عكس الاعتقاد الشائع، كل ما يلتصق بسطح الأسنان قد يسبب التسوس. ويمكن للكربوهيدرات، مثل الخبز والمعكرونة، والحليب بما يحتويه من لاكتوز، والمشروبات المشابهة أن تسبب جميعها تسوس الأسنان. ومع ازدياد استهلاك الأطعمة المصنّعة، ارتفعت أيضًا نسبة السكر في الأغذية على مر السنين، مما جعل حماية أسنان الأطفال أكثر صعوبة. والهدف الأساسي هو تقليل بقاء بقايا الطعام على سطح الأسنان إلى أدنى حد. ويمكنكِ اتخاذ خطوات مهمة للوقاية من التسوس من خلال تنظيف أسنان طفلكِ مرتين يوميًا، لمدة دقيقتين في كل مرة، والتأكد من مضمضة فمه بالماء بعد الوجبات الخفيفة. وبعد سن 3 سنوات، تساعد أيضًا إجراءات سد الشقوق وتطبيق الفلورايد التي يجريها أطباء الأسنان على الوقاية من التسوس.') WHERE id = '74588fea-3393-4777-9d52-b001b79cdfc6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من أبرز العوامل التي تؤثر في نمط نوم طفلكِ البالغ من العمر 3 سنوات قضاء ساعات طويلة أمام التلفاز وألعاب الحاسوب، خاصة إذا كانت تتضمن محتوى قد يسبب الكوابيس. يتمتع الأطفال في هذه السن بقدرة عالية على الاستيعاب، ولأنهم يفهمون ما يحدث من حولهم، فقد يتأثرون به بسهولة. وقد يؤدي ذلك إلى ظهور مشكلات في النوم. كما قد تنشأ لديهم بعض المخاوف بسبب القصص التي تُقرأ لهم أو يشاهدونها. لذا يجب عليكِ بالتأكيد وضع حدود لاستخدام طفلكِ للشاشات؛ بحيث لا تتجاوز المدة 30 دقيقة يوميًا، وألا يشاهد إلا المحتوى الذي تختارينه أنتِ. ومن المفيد أن ترافقينه أثناء المشاهدة وتراقبيه للتعرف إلى مخاوفه.') WHERE id = '89c3ef7f-a4e3-4d2d-9a7f-42e0b75a36a6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكن القول إن الأسئلة الأولى المرتبطة بالتربية الجنسية الواعية تبدأ تقريبًا في سن 3 سنوات. وقد تشعرين بالقلق أو الخوف عندما يطرح طفلكِ سؤاله الأول حول الجنس. وقد تتعلق هذه الأسئلة بوظائف الأعضاء التناسلية، وأدوار النساء والرجال، وكيف يأتي البشر إلى العالم. ومن مسؤوليتكِ تزويد طفلكِ بالمعلومات الأولى، وتعريفه بالموضوع بطريقة صحيحة، ومتابعة ما يتعلمه من مصادر أخرى. لذلك ينبغي أن تكوني على دراية بموضوع التربية الجنسية وأن تختاري أسلوب التعامل المناسب. تجنّبي استخدام نبرة دفاعية أو معتذرة، وتحدثي بنبرة صوتكِ وسرعتكِ الطبيعيتين في الحياة اليومية. فإذا كنتِ تتحدثين بسرعة عادةً، فإن التحدث ببطء شديد في هذا الموضوع سيلفت انتباهه وقد يجعله يعتقد أنه مختلف عن الموضوعات الأخرى أو أنه غريب. كما ينبغي ألا تظهر على وجهكِ علامات الصدمة أو الانزعاج عند سماع أسئلته، لأن هذه التعبيرات قد تجعله يعتقد أنه لا يجوز التحدث عن هذا الموضوع.') WHERE id = 'df1bc0c0-a742-4c28-9bf6-e95185ce12cb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي تأخير تعريف الأطفال بالوجبات الخفيفة غير الصحية قدر الإمكان. وعندما لا يتناول طفلكِ وجبته، لا تدعيه يظن أن هذه الأطعمة يمكن أن تكون بديلًا عن الطعام الأساسي. لا تقدمي له شيئًا صغيرًا يرغب فيه كلما طلبه، بل يمكنكِ تقديمه فقط بعد أن يتناول وجبته الأساسية وفاكهته، ويشبع بطريقة صحية، وعندما يتبقى 1,5-2 ساعة على الوجبة التالية. وهكذا ستضمنين أنه سيتناول كمية أقل منه. وإذا طلب المثلجات، فيمكنكِ أن تعرضي عليه مثلجات صحية أعددتِها في المنزل. وإذا لم تنجح هذه الطريقة، فاقترحي شراء مثلجات تحتوي على الفاكهة والحليب من مكان موثوق بدلًا من المثلجات المعبأة. وكلما طلب وجبة خفيفة غير صحية، حاولي تأجيل الأمر بدعوته إلى نشاط يحبه ويجذب انتباهه. ولا تجعلي هذه الأطعمة أبدًا موضوعًا للمساومة، لأن طفلكِ سيبدأ سريعًا باستخدام هذه الطريقة ضدكِ.') WHERE id = '50b63152-534e-4f39-95a9-aeba706b5baa';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك بعض النقاط المهمة التي ينبغي مراعاتها لتعزيز شعور إيجابي بالثقة بالنفس لدى طفلكِ. أولًا، عليكِ احترام أفكار طفلكِ وتطلعاته، وأن تكوني صادقة معه دائمًا. وبدلًا من رفضه تمامًا، حاولي أن توضحي له بلغة يفهمها ما تتوقعينه منه وما السلوكيات المقبولة. أنصتي إلى طفلكِ باهتمام وأشعريه بمدى أهمية محاولاته للتواصل. وبدلًا من توقع سلوك مثالي منه، اجعلي توقعاتكِ واقعية وضعي حدودًا واضحة. وأتيحي له فرصة الاختيار. على سبيل المثال: "حان وقت النوم الآن. هل تريد أن تنام مع دبدوبك أم مع كلبك اللعبة؟" أو "هل تريد تناول دوائك الآن أم بعد 10 دقائق؟". استخدمي عبارات تبدأ بـ"أنا" عند التواصل معه، ووضحي له كيف يؤثر فيكِ السلوك غير المرغوب فيه. على سبيل المثال: "أشعر بالقلق من أن يُصاب أحد عندما ترمي المكعبات." اسمحي لطفلكِ بارتكاب الأخطاء حتى يتمكن من التعلم منها. فالأطفال يحتاجون إلى الوقت لإيجاد حلولهم الخاصة، وبهذه الطريقة سيتعلمون أيضًا كيفية تصحيح أخطائهم.') WHERE id = 'af61b7a0-7776-4b9d-8393-d1e3bf0de875';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدءًا من عمر 3 سنوات، يفهم الأطفال دور الطعام في حياتنا، ويبدأون بالتأثر بالإعلانات والألعاب. وتُسهم المؤثرات في هذه المرحلة في تحديد اختياراتهم المستقبلية. فقد تتحول أطعمة الوجبات السريعة مثل الهامبرغر والبيتزا والبطاطس المقلية، التي يراها طفلكِ على التلفاز أو يلعب بمجسماتها، مع مرور الوقت إلى أطعمة مفضلة لديه. ورغم أن هذه الأطعمة غنية بالدهون المشبعة، فإنها فقيرة بالفيتامينات والمعادن. كما تحتوي على الملونات والمواد الحافظة وكميات مفرطة من الملح. أما المشروبات الغازية فتحتوي على كميات كبيرة من شراب الذرة. وتزيد الوجبات السريعة والمشروبات الغازية خطر الإصابة بالسمنة بسبب السعرات الحرارية الزائدة، ما قد يؤدي مستقبلًا إلى الإصابة بالسكري من النوع 2 والربو وأمراض القلب والأوعية الدموية. لضمان تغذية صحية لطفلكِ، لا تستخدمي الوجبات السريعة والحلويات أبدًا وسيلةً للمكافأة. وحاولي إبعاده عن الإعلانات والرسوم المتحركة التي تشجعه على تناول هذه الأطعمة.') WHERE id = 'c9d496f4-cfe4-45b1-abe1-dd54922bd115';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يتعرض طفلكِ لهجمات الفيروسات والبكتيريا في البيئات التي يوجد فيها. وعندما يعمل جهازه المناعي جيدًا، تزداد مقاومته للجراثيم وينخفض خطر إصابته بالأمراض. وقد تؤدي التغذية غير الكافية وغير المتوازنة إلى ضعف المناعة، لا سيما خلال فترات تبدل الفصول. ويشيع انخفاض المناعة لدى الأطفال في عمر 3 سنوات تقريبًا، وإذا اكتُشفت هذه الحالة، يمكن تحسينها بتقديم الدعم المناسب. وسيساعد النظام الغذائي الغني بالعناصر الغذائية المتنوعة الذي تُعِدّينه لطفلكِ على تعزيز مناعته ونموه الصحي معًا. ويُفضّل أن يتناول في وجبة الإفطار تحديدًا بيضة واحدة على الأقل ويشرب كوبًا واحدًا من الحليب. وينبغي أن تشمل الوجبات الأخرى الفلفل الأحمر والأخضر والخضراوات الورقية الخضراء، والأهم من ذلك البصل والثوم. وعند الحاجة، لا ينبغي إعطاء مكملات الفيتامينات إلا تحت إشراف الطبيب.') WHERE id = '1f040fd3-210e-465e-94b9-9cad5e55958d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لكل مرحلة من مراحل النمو سلوكياتها الخاصة، لذلك ينبغي أن تكوني على دراية جيدة بخصائص المرحلة العمرية لطفلكِ. وتوجد بعض المعايير التي تحدد ما إذا كان سلوك ما يُعد اضطرابًا. فعلى سبيل المثال، يرغب الطفل في عمر 3 سنوات في أن يكون محط الاهتمام. وبفضل خياله الواسع جدًا، قد يروي قصصًا يصعب تصديقها. فالأطفال في هذا العمر لا يستطيعون بعد التمييز بين الكذب والحقيقة. لذلك لا يُعد ما يقولونه في هذا العمر كذبًا، لكن السلوك نفسه لدى طفل يتراوح عمره بين 11 و14 عامًا قد يُعد اضطرابًا سلوكيًا. ومن المعايير الأخرى شدة السلوك؛ فالغضب والعناد طبيعيان لدى الطفل في عمر 3 سنوات، لكن إذا تحولا إلى إلحاق أذى جسدي بالآخرين، فإنهما يدخلان ضمن فئة الاضطرابات السلوكية. كما يُعد إصرار الطفل على سلوك معين واستمراره فيه مدة طويلة مؤشرًا مهمًا أيضًا.') WHERE id = 'e2e3a081-c2d4-43fa-9fb7-5fa0204ba1dc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدءًا من هذا العمر، تتغير البيئة الاجتماعية للطفل ويزداد تواصله مع أقرانه. ومن خلال ذلك، يتعلم الصغار الصبر واكتساب المعرفة بمراقبة الكبار، بينما يتعلم الكبار معاملة الصغار بمحبة. وتتطور حواس البصر والسمع والتذوق واللمس بسرعة لدى الأطفال في عمر 3 سنوات. لذا ينبغي أن تركزي على الأنشطة التي تنمّي حواس طفلكِ، وأن تدعمي تطور ذكائه من خلالها. وبدءًا من عمر 3 سنوات، يمكن للأطفال أيضًا الالتحاق بالمؤسسات التعليمية التي تتبع منهج مونتيسوري. وتحتل زجاجات الروائح والمذاقات مكانة مهمة بين مواد مونتيسوري. ويمكنكِ تحضير هذا النشاط بسهولة في المنزل أيضًا. يمكنكِ إعداد زجاجات للتذوق بإضافة عصير الليمون أو دبس السكر أو مصل اللبن الرائب إلى الماء في زجاجات مختلفة. ويُنصح أيضًا بإعداد أسطح متنوعة الملمس، ليتمكن طفلكِ من تحسسها بيديه وقدميه وتنمية حاسة اللمس لديه.') WHERE id = '2f2859f2-2f74-4d9b-8af7-2a5b021a62ab';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تظهر مخاوف التعرض للأذى والفناء، التي تبدأ في عمر 3 سنوات، في صورة أشباح أو أماكن مهجورة أو وحوش. ومن خلال اللعب، يمنح طفلكِ هذه المخاوف أشكالًا محددة في عالمه الخاص. وعندما تتصارع الشخصيات البطولية والشريرة داخل اللعبة، فإن كلتيهما في الواقع انعكاس لعالم الطفل الداخلي. قد يثير هذا الوضع قلقكِ قليلًا، لكن من الضروري التعامل معه بهدوء. فقولكِ: «لا وجود للوحوش!» قد يجعل الطفل يشعر بأنكِ لا تفهمينه. ينبغي أولًا أن تفهمي عالم طفلكِ، والطريقة الأكثر فاعلية لتحقيق ذلك هي مشاركته في ألعابه. وعندما تلاحظين تصرفًا غير معتاد أثناء اللعب، يمكنكِ فهمه بصورة أفضل بطرح الأسئلة، ومساعدته على تبديد مخاوفه من خلال الأدوار الإيجابية.') WHERE id = '9e9d2250-5512-46d4-b8e9-3d1a806c30dc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يكون هدف طفلكِ من اللعب مجرد الاستمتاع، لكن اللعب يمثل للوالدين فرصة رائعة لقضاء الوقت مع الطفل والتعرف إليه بصورة أفضل. وليس من الضروري أن تكون عملية التعلم والنمو مملة. يمكنكِ دعم نمو دماغ طفلكِ من خلال الألعاب الممتعة والتعليمية. ضعي أمام طفلكِ مجموعات من المكعبات بأشكال وألوان مختلفة، واتركي الباقي لخياله. ستساعده هذه اللعبة على تنمية قدراته الذهنية في مجالات عديدة، بدءًا من التعرف إلى الأشكال والألوان، كما ستعزز إبداعه. أما تعريفه بآلات موسيقية متنوعة، فيؤثر إيجابيًا في نموه العاطفي والاجتماعي والذهني. وتُعد ممارسة الموسيقى من أكثر الأنشطة إفادةً ومتعةً في الوقت نفسه.') WHERE id = '20a29436-fc37-4a8d-9225-4d47565f2992';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بالنظر إلى الخصائص الجسدية للأطفال، تُعدّ الجمباز، التي تُعتبر أساس جميع الرياضات، أول رياضة يمكنهم ممارستها. وهي نشاط يستمتع به الأطفال منذ سن مبكرة وثبتت فوائده. وقد لوحظ أن الأطفال الذين يمارسون الجمباز يتطورون بسرعة أكبر من الناحية الحركية النفسية والمعرفية والعاطفية. يمكنكِ تعريف طفلكِ بهذه الرياضة بدءًا من عمر 3 سنوات من خلال تمارين الجمباز التي تأخذ شكل ألعاب. تعزز الجمباز المهارات الحركية لدى الأطفال، مثل التوازن والسرعة والقوة وخفة الحركة والتنسيق والمرونة. كما تبيّن أن الأطفال الذين يبدأون تدريبات الجمباز في سن مبكرة تتطور لديهم إلى أقصى حد مهارات مثل الجري والقفز والتسلق. ومن خلال هذه الرياضة، سيتمكن طفلكِ من تصريف طاقته بطريقة سليمة، وستعود عليه بفوائد صحية كبيرة.') WHERE id = '3a71e453-dc05-444b-a5d5-f7d179a2c1b2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إن البدء بتعلم لغة ثانية في عمر 3 سنوات فعّال للغاية في تنمية الإدراك اللغوي لدى الطفل. ويمكن للطفل الذي ينشأ في بيئة تُستخدم فيها لغة أخرى إلى جانب لغته الأم أن يكتسب كلتا اللغتين بسهولة. ولتحقيق ذلك، من المفيد أن يتواجد طفلكِ في بيئة ناطقة باللغة الإنجليزية. ويُعدّ عرض الرسوم المتحركة وتشغيل التهويدات باللغة الإنجليزية له باستمرار وسيلة ممتعة وسهلة في آن واحد. وعندما يرغب طفلكِ في مشاهدة أي برنامج، احرصي أيضًا على اختيار أفلام الأطفال باللغة الإنجليزية. وهكذا ستصبح الكلمات مألوفة لديه بمرور الوقت. ويمكنكِ كذلك أن تخبريه بالمقابل الإنجليزي للكلمات التي بدأ ينطق بها. فمثلًا، عندما يقول «قطة»، يمكنكِ أن تقولي له «Cat» لتعلّميه كلمة جديدة. وعند محاولتكِ تسريع تطور النطق لديه، يجب ألا تجعليه يشعر بالضغط، بل اجعلي التعلم ممتعًا. فعلى سبيل المثال، يمكنكِ أثناء لعب لعبته المفضلة أن تصفي الحركات التي تجري في اللعبة باللغة الإنجليزية.') WHERE id = '94749156-ac73-4e79-8936-22626911b701';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد تطورت في هذه المرحلة قدرة طفلكِ على التخيل بدرجة كبيرة. والتخيل المتأصل في طبيعة الأطفال هو في الواقع نموذج رمزي للحياة الواقعية. فإذا راقبتِ الألعاب التي يلعبها مع أصدقائه، ستلاحظين بسهولة كيف يجسدون الحياة الواقعية بصورة رمزية. ومن خلال دعم عالم طفلكِ الخيالي، تساعدينه على الاستعداد للمستقبل بصورة أفضل. فالطفل الذي يحظى خياله بالدعم ينشأ شخصًا منفتحًا على الإبداع، أما الطفل الذي يواجه قيودًا باستمرار فقد يفقد رغبته في الاستكشاف. ولإثراء عالم طفلكِ الداخلي، يمكنكِ الاهتمام بأنشطة مثل قراءة الكتب وتركيب الأحجيات والرسم والذهاب إلى السينما وقضاء الوقت مع الأصدقاء وممارسة الموسيقى. وتذكري أن الطفل الذي يتمتع بخيال متطور قد يُحدث فوضى من حوله أثناء اللعب؛ لذا لا تتعاملي معه بقسوة، بل تفهّمي هذه الفوضى واقضي معه وقتًا ممتعًا وهادفًا.') WHERE id = '0d882b08-7404-48d9-97ab-a63d45290aad';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تذكري أن عدم تفويت مواعيد الوجبات يأتي في مقدمة قواعد التغذية لدى الأطفال. واحرصي خصوصًا على أن يتناول طفلكِ وجبة الإفطار، فهي أهم وجبة في اليوم. ويمكنكِ اختيار الفواكه المجففة والتمر والمكسرات كوجبات خفيفة صحية. واحرصي على أن يشمل نظامه الغذائي اليومي المكسرات المفيدة، مثل الجوز والبندق واللوز، إلى جانب منتجات الحبوب الكاملة. وحاولي اختيار الفواكه والخضراوات الطازجة والموسمية. ويجب غسلها جيدًا جدًا للتخلص من بقايا المبيدات الزراعية. ومن الأفضل تقديم الفاكهة كاملة بأليافها بدلًا من تقديمها في صورة عصير فقط. وتُظهر الدراسات أن الأسماك تؤثر إيجابيًا بدرجة كبيرة في جهاز المناعة لدى الأطفال، وتزيد مقاومة الجسم للأمراض. لذلك اجعلي تناول السمك مرة واحدة في الأسبوع عادة منتظمة.') WHERE id = 'e2ff4d89-6e44-49f2-8f66-9efbff6dfaad';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'الحوادث المنزلية من الوقائع المؤسفة التي تحدث كثيرًا. وتشمل أكثرها شيوعًا السقوط والاصطدام والجروح والاختناق أو انسداد مجرى التنفس بالأجسام الغريبة والغرق والتسمم والحروق والصعق الكهربائي. وتقع على عاتقكِ مسؤولية توفير بيئة آمنة لطفلكِ واتخاذ التدابير الوقائية اللازمة. ولمنع هذه الإصابات، إليكِ بعض النصائح سهلة التطبيق: استخدمي أقفال الأمان حتى لا يتسبب باب الشرفة أو النافذة المتروكان مفتوحين في وقوع حادث. وثبّتي الأجهزة الكبيرة، مثل التلفاز، في مكانها وتأكدي من عدم انقلابها. ويمكنكِ تركيب واقيات خاصة على الزوايا الحادة والمدببة للوقاية من الإصابات الناتجة عن الاصطدام بها. واستخدمي أقفال الأدراج في خزائن المطبخ لمنع طفلكِ من الوصول إلى الأدوات الحادة والمدببة، مثل السكاكين والشوك. كما تساعد هذه الأدوات على الوقاية من خطر انحشار الأصابع واليدين. وتؤدي واقيات مقابض الأبواب والأصابع الوظيفة نفسها. واحفظي الأدوية ومواد التنظيف والمواد السامة بعيدًا عن متناول الأطفال، ويفضل وضعها في خزائن مرتفعة أو محكمة الإغلاق.') WHERE id = 'da19983e-64ca-4ef1-be1d-d6b1b52c415f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يضعكِ تصرف طفلكِ كشخص بالغ صغير أمام تحديات كثيرة. ويمكنكِ معالجة المشكلات التي تواجهينها من خلال وضع قواعد جديدة. وبالطبع، ليس وضع القواعد أمرًا سهلًا؛ فالتشدد المفرط قد يكون ضارًا بقدر التساهل المفرط. اختاري أسلوب التعامل الملائم لطفلكِ، ولا تغيّريه من يوم إلى آخر، بل كوني ثابتة ومتسقة. وتذكري أن وضع القواعد جزء من تربية الطفل؛ فمن خلاله تحمينه وتساعدينه على النمو في الوقت نفسه. ومع مرور الوقت، سيدرك طفلكِ أن القواعد الموضوعة بصورة صحيحة تصب في مصلحته، وسيشعر بأنها جزء من محبتكِ له. كما أن وضع القواعد وسيلة فعالة لتجعليه يشعر بثقتكِ به.') WHERE id = '8821b078-f268-490e-aff6-43d6dec5162e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تحتل التربية على الخصوصية مكانة مهمة في نمو الأطفال. فمعرفة الطفل بجسده ومساحته الشخصية تساعده على فهم حدوده وحدود الآخرين، كما أنها ضرورية جدًا لحماية نفسه جسديًا ونفسيًا. وعند تقديم هذه التربية، من الأفضل استخدام مفاهيم مثل «شخصي» أو «خاص» بدلًا من كلمات مثل «عيب» أو «حرام». ينبغي تعليم الخصوصية بصورة طبيعية، بوصفها جزءًا من الحياة اليومية، من دون إثارة الخوف. عرّفي طفلكِ على المناطق الخاصة في جسده، واشرحي له أنه لا يجوز لأشخاص مقرّبين، مثل الأم أو الجدة أو مقدمة الرعاية، لمسها إلا عند الضرورة. ويمكنكِ مساعدته على حماية خصوصيته من خلال تعليمه في سن مبكرة مهارات العناية الذاتية، مثل الاغتسال وارتداء الملابس. تجنّبي المزاح بشأن مناطق طفلكِ الخاصة، وعلّميه أنه إذا انتهك أحد هذه الحدود، فعليه الاعتراض أو الهرب أو طلب المساعدة.') WHERE id = '553d9c23-e7d4-493a-b17a-3b250bd976ed';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المهم في هذه المرحلة أن تحرصي على استخدام جمل كاملة وصحيحة عند التحدث مع طفلكِ. وبما أنه يمر بـ«مرحلة كثرة الأسئلة»، فعليكِ الإجابة عن جميع أسئلته بصبر. فطريقة مخاطبتكِ له وأسلوبكِ في التواصل يمثلان قدوة له. يستمتع طفلكِ بالأشياء المضحكة، وقد تجذب انتباهه أحيانًا الكلمات البذيئة أو التعبيرات العامية لأنها تبدو مثيرة للاهتمام بالنسبة إليه. ومن المرجح أن يتعلم هذه الكلمات من أطفال آخرين. إذا كنتِ لا تريدين أن يستخدم طفلكِ مثل هذه التعبيرات، فعليكِ أولًا الانتباه إلى كلامكِ أمامه. وإذا تعلمها من شخص آخر، فلا تضحكي ولا تتجاهلي الأمر، بل اشرحي له بهدوء ومن دون غضب أن هذه الكلمات خاطئة وبذيئة. وسيفهمكِ بالتأكيد.') WHERE id = 'c0ccda10-853b-4577-bb20-e9b11dd89481';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لاحظتِ انخفاضًا في شهية طفلكِ مقارنة بالسابق، فقد يكون السبب مرضًا أصيب به، أو تغيرًا في روتينه اليومي، أو أسلوب تعامل الوالدين معه. ومن أبرز أسباب فقدان الشهية الإفراط في الاهتمام بالطفل أو، على العكس، إهماله، والتشدد الشديد في قواعد تناول الطعام، وتهديده، أو مكافأته مقابل الأكل. ومن الأخطاء الكبيرة إجباره على الأكل حتى يتقيأ، أو إرغامه على تناول أطعمة لا يحبها، أو تخويفه بعبارات مثل «إذا لم تأكل طعامك فسيأكلك الوحش» أو «سيطاردك كلب». يستطيع الأطفال الذين يعانون من ضعف الشهية عادةً تناول وجبة واحدة جيدًا. كما يمكنهم الحصول على العناصر الغذائية اللازمة عبر ثلاث وجبات صغيرة يتناولونها على فترات. لكن ينبغي ألا تسمحي لطفلكِ بالاتجاه إلى الأطعمة الغنية بالسكر والسعرات الحرارية، مثل البسكويت والمقرمشات والمشروبات الغازية والشوكولاتة. وبذلك تمنعين عزوفه عن الأطعمة الصحية، واستهلاكه للسعرات الحرارية الفارغة، وزيادة وزنه، وتسوس أسنانه. كما أن تحضير الطعام مع طفلكِ يساعده على تناوله بشهية أكبر. وحتى إن عانى الطفل الذي لا يتعرض لضغط نفسي ويتبع نظامًا غذائيًا متوازنًا من هذه المشكلة على فترات، فسيتمكن من تجاوزها بسهولة بدعمكِ.') WHERE id = 'b3ccd641-2a40-4051-bdae-4ea45fc3c82d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أتيحِي لطفلكِ فرصة اللعب بالرمل والماء والتراب. فالتواصل مع الطبيعة علاج رائع لنموه الذهني! واجعليه يلتقي بأطفال آخرين، ويقضي وقتًا في بيئات متنوعة، ويكوّن صداقات جديدة. فالطفل الذي يبقى وحيدًا دائمًا قد يشعر بالتعاسة. واسمحي لطفلكِ بمساعدتكِ في الأعمال المنزلية؛ فالمهام البسيطة، مثل أن يناولكِ مشابك الغسيل أثناء نشر الملابس أو أن يرتب الملاعق على المائدة، تحمل معنى كبيرًا بالنسبة إليه. وكلما أوكلتِ إليه مهام وأنجزها، شعر بسعادة أكبر. وأسندي إليه مسؤوليات بسيطة يستطيع القيام بها، مثل تنظيف أسنانه. وبهذه الطريقة، ستشركين طفلكِ في الحياة، وتساعدينه على الاستمتاع وإدراك أنه فرد مستقل.') WHERE id = 'd9cbf0fb-de40-4e79-8907-e51a5d91c55d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ البالغ من العمر 3 سنوات لا يزال يستخدم الحفاض ليلًا ونهارًا، فلا تلوميه ولا تشعريه بالخجل. يختلف العمر المناسب للتوقف عن استخدام الحفاض من طفل إلى آخر. ويجب أن يرغب طفلكِ بنفسه في اكتساب عادة استخدام المرحاض وأن يتأقلم معها. ولتسهيل هذه العملية، يمكنكِ تحديد أوقات معينة. فمثلًا، عوّديه على الذهاب إلى المرحاض قبل الخروج من المنزل أو قبل قيلولة الظهر. وبعد مدة، سيكتسب طفلكِ هذه العادة من دون الحاجة إلى تذكيركِ. واحرصي أيضًا على أن يكون المكان الذي يقضي فيه حاجته هادئًا. ينبغي ألا يشعر طفلكِ بأي ضغط خلال هذه العملية، بل يجب أن يكون مرتاحًا تمامًا.') WHERE id = '4cd58449-48a3-4ba7-8d3b-5c017a035884';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إن حصول الطفل على تغذية كافية ومتوازنة يعني أنه مستعد للتعلم. كما يتمتع الأطفال الأصحاء والنشيطون بقدرة أكبر على التعلم والتحمل والثقة بالنفس. وإلى جانب النشاط البدني المنتظم، تساعد التغذية السليمة الأطفال على الحفاظ على صحتهم. ويؤثر تفويت الوجبات باستمرار سلبًا في إنجازات الطفل. وعلى الرغم من أن وجبة الإفطار من أكثر الوجبات التي يجري إهمالها، فإن تفويتها يشبه بدء اليوم متأخرًا بنتيجة 1-0. فالإفطار الجيد يعزز نجاح طفلكِ في التعلم ويحافظ على طاقته. لا تنسي أبدًا أن الأطفال يحتاجون قبل كل شيء إلى الطاقة كي يتعلموا أشياء جديدة.') WHERE id = '852b4ba3-0212-4567-91c1-bd38e389f59b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكن من خلال التعليم في مرحلة ما قبل المدرسة تحديد اهتمامات طفلكِ ومواهبه البارزة. وعند مراعاة السمات الفردية لكل طفل، يصبح دعم نموه الجسدي والعقلي أسهل. يكتمل 50% من النمو العقلي خلال السنوات 4 الأولى، و30% منه حتى سن 8 سنوات. لذلك، عندما نتحدث عن التعليم في مرحلة ما قبل المدرسة، فإننا نتحدث عن أهم فترة يمكن لطفلكِ فيها اكتشاف إمكاناته الفكرية. خلال هذه الفترة، تتم متابعة الطفل عن كثب من خلال اختبارات متنوعة، ويُسجَّل تطوره بانتظام. كما تُكتشف مهارات طفلكِ من خلال الألعاب والأنشطة الفنية داخل الروضة. وبفضل ذلك، يمكن ملاحظة نقاط قوته والجوانب التي تحتاج إلى تطوير في وقت مبكر.') WHERE id = 'fcdecd06-9935-451b-a2fa-d85e42defeda';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد القدرة على الكلام مرحلة بالغة الأهمية في نمو الأطفال. إذا بلغ الطفل سن 3 سنوات ولم يبدأ الكلام بعد، وكانت قدرته على الفهم ضعيفة أيضًا، فمن الضروري الحصول على رأي مختص. وقد تؤدي مواقف مثل "والده أيضًا تأخر في الكلام" إلى مواجهة الطفل مستقبلًا مشكلات يصعب تداركها. يمكن أن يكون لتأخر النطق أسباب عديدة، مثل فقدان السمع، ونقص التحفيز، والإعاقة الذهنية، والتوحد، ويتطلب كل سبب منها نهجًا مختلفًا. وقد يؤدي الانتظار بحجة أن "الأمر سيتحسن مع الوقت" إلى عواقب لا يمكن تداركها. لا يمكن تشخيص الحالة من خلال القراءة على الإنترنت أو في الكتب؛ بل لا بد من إجراء تقييم سريري على يد مختص متمرس.') WHERE id = '820eb790-8d69-449a-8be1-43f47a9dd95b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تشير الأبحاث، للأسف، إلى أن أطفالنا لا يحصلون على قسط كافٍ من النوم أو ينامون في وقت متأخر جدًا. بالنسبة إلى طفل يبلغ 3 سنوات، يُعد النوم بعد الساعة 22:00 متأخرًا. في هذه المرحلة، قد يتطلب تنويم طفلكِ مزيدًا من الوقت والصبر، لأنه يكون قد انتقل إلى سرير بلا حواجز وأصبح قادرًا على التعبير عن نفسه بالكلام. أهم ما في الأمر هو أن تتحلي بالصبر والحزم. يعرف الطفل جيدًا أي طلباته ستُلبّى، فيركز عليها. أريد كوبًا آخر من الماء، احكي لي قصة أخرى، اذهبي يا أمي وليأتِ أبي، غطيني، يجب أن أذهب إلى الحمام، دلّكي ظهري، غني لي تهويدة أخرى... هل تبدو لكِ هذه الأعذار مألوفة؟ قد تستمر طوال الليل وتحرمكِ من النوم. يمكنكِ التغلب على هذه المشكلة بالثبات والحزم.') WHERE id = 'e9f80de9-ae84-478b-943d-e1b333c1b0f7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إن تعلُّم طفلكِ كيفية تهدئة نفسه جزء من عملية نموه، تمامًا مثل الحبو أو المشي أو إمساك القلم. وإذا قدمتِ له الدعم المناسب، فسيكتسب مهارة التنظيم الذاتي (self-regulation)، أي القدرة على تهدئة نفسه. عندما تُسند هذه المهمة إلى الهاتف المحمول، يتعرض الطفل للتحفيز بواسطة عامل خارجي آخر بدلًا من أن يتعلم كيف يهدئ نفسه. وعودته إلى البكاء عند أخذ الهاتف منه دليل على ذلك. من الطبيعي أن يبكي عندما تضعين حدودًا لرغباته؛ فهنا تبدأ التربية الحقيقية. أخبريه بأنكِ تتفهمين مشاعره مع الحفاظ على حدودكِ، لكن انتظري بهدوء من دون جدال أو محاولة إقناعه. إن حفاظكِ على هدوئكِ من دون محاولة إسكاته على عجل سيساعده بمرور الوقت على تهدئة نفسه بسهولة أكبر.') WHERE id = '9c23d639-ad9f-4e04-a46c-08501b1d3ab9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تكمن عوامل نفسية وراء مشكلة حبس البراز التي تظهر في سن 3 سنوات. فالأطفال الذين لا يعانون من مشكلات صحية جسدية قد ينظرون أحيانًا إلى البراز على أنه جزء من أجسامهم ولا يرغبون في فقدانه. ووفقًا لعلماء النفس، يحاول الأطفال بهذه الطريقة إثبات وجودهم. وقد تشمل الأسباب الأخرى تعرض الطفل لضغط نفسي شديد، أو وجود خلافات داخل الأسرة، أو بدء تدريبه على استخدام المرحاض مبكرًا جدًا أو بطريقة غير صحيحة. كما يعبّر بعض الأطفال بهذه الطريقة عن حاجتهم إلى التحكم. كذلك قد يكون الخوف من كرسي المرحاض أو من صوت تدفق الماء بعد سحبه من عوامل القلق التي تدفع الطفل إلى حبس برازه.') WHERE id = '11f77601-04b8-47b0-af21-9926fe8313e7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لتنمية إبداع طفلكِ، ينبغي أن يكون خيالكِ أنتِ أيضًا بلا حدود. يمكنكِ تنمية حاسة اللمس والخيال لديه باستخدام الصلصال، والأحاجي، ومكعبات الليغو، والمواد القابلة لإعادة الاستخدام. تعزز ألعاب الصلصال مهارات الطفل الحركية إلى جانب إبداعه. وتنمي الأحاجي مهارة حل المشكلات. أما مكعبات الليغو، فهي وسيلة ممتازة لتنمية المهارات الحركية الدقيقة وتعليم مفاهيم مثل الكبير والصغير، والطويل والقصير، وكذلك الألوان. ومن خلال ابتكار أشياء معًا بهذه الأنشطة، ستكتشفين مدى المتعة التي يمنحها ذلك لكِ ولطفلكِ.') WHERE id = 'bf87ac9e-0c8c-4b92-971a-12c295af60cc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا بدأ طفلكِ باللعب بالطعام، فهذه علامة على أنه قد شبع. في هذه الحالة، يمكنكِ إبعاده عن المائدة أو رفع طبقه من أمامه. لا تضغطي عليه لإنهاء كل ما في الطبق، فقد يؤدي ذلك إلى نفوره من هذا الطعام مستقبلًا. من شأن ممارسة بعض النشاط البدني أو اللعب قبل الوجبة أن يفتح شهية طفلكِ ويساعده على تناول الطعام بمزاج مرح. أتيحي له فرصة المشاركة في التخطيط للوجبات وإعدادها. ولجعل وقت الطعام ممتعًا، قدّمي الأطعمة بطريقة ملوّنة وجذابة تناسب ذوقه. إن استمتاعه بالطعام، وعدم شعوره بالتوتر بسبب ضرورة إنهاء طبقه، وعدم إجباره على تناول أطعمة لا يحبها، أمور تساعده على أن يكون طفلًا سعيدًا وبصحة جيدة.') WHERE id = 'c795e196-6a00-43c9-b36a-4c06f33e9796';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، قد يتحول جرح صغير إلى حدث كبير بالنسبة إلى الطفل، لأن إحساس طفلكِ بسلامة جسده مهم جدًا له. وقد يشعر الطفل الذي يبدو متماسكًا عند وقوع حوادث كبيرة بذعر شديد أمام نزف بسيط. عبارات مثل: “ألهذا تبكي؟ إنه مجرد جرح صغير! لا تبالغ!” لن تهدئ طفلكِ، بل قد تزيد انزعاجه وخوفه. في مثل هذه المواقف، من الأفضل أن تحافظي على هدوئكِ وتطمئنيه بلمساتكِ. يمكنكِ توجيه انتباهه نحو الحل بقولكِ: “تعال لنختار لك أظرف ضمادة لاصقة”. وإذا لم يوافق على وضع الضمادة، فيمكنكِ تحويل الموقف إلى لعبة بقولكِ: “هل تريد أن تضعها على يدي أولًا؟”.') WHERE id = '1875f0d9-a30a-4320-bde4-1bf3b044e4f4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'سن 3 سنوات مرحلة يزداد فيها النشاط الاجتماعي للأطفال، وقد تؤثر الأنشطة التي يمارسونها خلالها في نمط نومهم. وقد تؤدي عوامل مثل الانضمام إلى مجموعة لعب جديدة، ونوع الأنشطة، والتواصل مع الأطفال الآخرين فيها إلى توتر الطفل وإصابته بالأرق، حتى إن لم تكن لديه مشكلات في النوم من قبل. كما أن قضاء وقت طويل أمام التلفاز وألعاب الكمبيوتر قد يحفّز هذه المشكلة. وبصفتكِ أمًا، تُعد ملاحظتكِ مهمة جدًا لتحديد السبب. يمكنكِ معرفة ما يؤثر في طفلكِ من خلال متابعة ما يفعله خلال اليوم والبرامج التي يشاهدها. وبعد تحديد السبب، سيصبح إيجاد الحل أسهل بكثير. وإذا كنتِ أمًا عاملة، فمن المفيد أن تتعاوني مع الشخص الذي يعتني بطفلكِ بشأن هذا الموضوع.') WHERE id = '2c94cf91-454d-4e52-814d-caf33e7a8c00';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحتاج الأطفال إلى الحركة. فعلى خلاف البالغين، يُعد الحفاظ على نشاط الأطفال أمرًا بالغ الأهمية لنموهم. ويمكن لطفلكِ في سن 3 سنوات أن يبدأ الآن دروس السباحة، فهي ستعلّمه التغلب على الخوف من الماء وتساعده على الاسترخاء. كما تُعد قيادة الدراجة ثلاثية العجلات والمشي والجري والقفز خيارات رائعة للأطفال في هذا العمر. ومنذ سن عامين، يُعد رمي الكرة أو ركلها نشاطًا يجذب اهتمام الأطفال كثيرًا، كما يساعدهم على استهلاك قدر كافٍ من الطاقة لأن أجسامهم تظل في حركة مستمرة. أما الجمباز الإيقاعي، فيحرّك الجسم بأكمله وينمّي الإحساس بالإيقاع والمرونة. ويمكن زيادة مستوى صعوبة هذه الأنشطة تدريجيًا مع نمو طفلكِ واكتسابه مهارات جديدة.') WHERE id = 'b10de036-169f-413e-a171-34dd349200ac';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد التحدث كالأطفال الرضّع أحد أكثر السلوكيات النكوصية شيوعًا لدى الأطفال. حاولي فهم السبب الكامن وراء هذا السلوك. إذا كان طفلكِ يريد أن تعامليه كرضيع صغير، فلبّي هذه الحاجة لديه. قد يحتاج إلى مزيد من العناق والتواصل الجسدي وإظهار الحب. وخلال هذه الفترة، ينبغي أن تتجنبي إجباره على تناول الطعام أو فرض قواعد صارمة عليه. قد تقلقكِ عودته إلى الاعتماد عليكِ، لكن مقاومة ذلك ستزيد الوضع سوءًا. أظهري له أقصى قدر من التفهم، وحاولي تحديد عامل التوتر الذي تسبب في هذا السلوك. لا تقلقي، فبعد تجاوز هذه المرحلة الصعبة سيكون لديكِ متسع من الوقت لإعادة ترسيخ العادات الصحيحة.') WHERE id = 'f90d33ac-0447-4870-8d96-71bc500d58eb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يؤدي تناول الأطعمة غير الصحية بانتظام، مثل الوجبات السريعة والأطعمة عديمة القيمة الغذائية، إلى السمنة والمشكلات العاطفية وانخفاض الثقة بالنفس والإصابة بأمراض مزمنة مستقبلًا. وقد تضيف وجبة سريعة واحدة فقط ما بين 160-310 سعرات حرارية زائدة إلى الاحتياج اليومي من السعرات الحرارية لدى الأطفال الصغار. ويزداد الوضع تعقيدًا بسبب احتواء كثير من منتجات الوجبات السريعة على أصباغ غذائية خطرة ودهون متحولة ضارة، فضلًا عن المخاوف المتعلقة بسلامة إعداد الطعام. ويزيد تناول الوجبات السريعة أكثر من ثلاث مرات أسبوعيًا احتمال إصابة الأطفال باضطرابات تأتبية مثل الربو أو الإكزيما أو التهاب الأنف. بل تتجاوز نسبة تفاقم الربو لدى الأطفال الصغار 25%. وتؤدي الكميات المفرطة من السعرات الحرارية والدهون والسكريات في هذه الأطعمة إلى تغيير تفضيلات الطفل للمذاقات؛ ونتيجة لذلك، قد يرفض طفلكِ تناول الأطعمة الغنية بالألياف والفواكه والحليب والخضراوات، ما يعني زيادة احتمال إصابته بالإمساك. كما أن اعتياد تناول كميات كبيرة من الوجبات السريعة في الطفولة يجعل الانتقال إلى نظام غذائي صحي مستقبلًا أكثر صعوبة، حتى بعد ظهور مشكلات طبية. وبسبب مذاق الوجبات السريعة الذي قد يسبب التعلق بها، قد لا يستسيغ الطفل مستقبلًا الأطعمة الطبيعية العادية والأقل احتواءً على التوابل.') WHERE id = '10b4e0f2-9940-49f3-b88c-796456c2e129';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ في سن 3 سنوات أكثر وعيًا بما يدور حوله وأكثر استعدادًا للتعلّم. وفي الوقت نفسه، قد يملّ من قضاء الوقت في المنزل خلال هذه المرحلة. وبصفتكِ أمًا، ينبغي لكِ في هذه الأوقات الاهتمام بطفلكِ عن قرب وبأسلوب ودي وتعليمي. ويمكنكِ، خصوصًا من خلال الألعاب التعليمية، زيادة معرفته وضمان استمتاعه في الوقت نفسه. على سبيل المثال، ضعي ألعابًا متنوعة في وعاء واطلبي منه أن يختار واحدة منها. وساعديه على التعلّم بسؤاله عما إذا كانت اللعبة التي اختارها صلبة أم ناعمة. اجمعا معًا بعض الحجارة في الخارج، ثم نظّفاها في المنزل ولوّناها معًا. ودعيه يختار الألوان التي يريدها. كما ستساعد لعبة الترتيب من الأطول إلى الأقصر على تنمية قدرته على الفهم والإدراك. رتّبي ألعابه أمامه وساعديه على ترتيبها من الأطول إلى الأقصر. ابتكري ألعابًا متنوعة كهذه، واستمتعا بقضاء الوقت والتعلّم معًا! :)') WHERE id = 'ac05520b-73f7-4218-90fc-85e1f1a6e0bd';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يثير السفر مع طفلكِ بعض القلق، لكن يمكنكما الاستمتاع بعطلة صحية وممتعة باتخاذ بعض التدابير البسيطة. وما دمتِ تلبّين احتياجات طفلكِ على نحو مناسب خلال العطلة، فلن تواجهكما أي مشكلة. وبما أنه بلغ مرحلة اللعب، فقد أصبح أكثر قدرة على التكيّف مع الإقامة خارج المنزل. إذا كنتِ تخططين لعطلة صيفية، فاختاري عند تجهيز الحقيبة ملابس قطنية فاتحة اللون. وإلى جانب الملابس ذات الأكمام القصيرة، احرصي على أخذ عدة قطع ذات أكمام طويلة أيضًا. ومن المهم أخذ الصنادل إلى جانب الأحذية اليومية. ولا تنسي إضافة قبعات عريضة الحواف ونظارات شمسية لحمايته من الشمس والرياح. ويجب أخذ عدة ملابس سباحة لتبديلها بعد الخروج من البحر. أما في العطلة الشتوية، فمن الضروري أخذ ملابس مقاومة للبرد، وأكياس نوم تحتفظ بالحرارة جيدًا، وأوشحة وقبعات احتياطية، وأحذية للثلج. ولا تنسي أيضًا مستلزمات العناية الخاصة، مثل الشامبو والصابون والزيوت المرطبة. ويمكنكِ عند الحاجة أخذ جهاز مراقبة الطفل وألعابه وكتبه المفضلة. كذلك احرصي، من باب الاحتياط، على وضع ميزان حرارة وشاش وضمادات لاصقة وأدوية تُستخدم وفقًا لتوصية الطبيب وكريمات الحساسية في حقيبتكِ.') WHERE id = '3bb13115-fde0-4b85-b773-03ceef37c99a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لاحظتِ أن طفلكِ يتلعثم في أثناء الكلام، فقد يُعد ذلك طبيعيًا في هذا العمر. ورغم أن 90% من حالات التلعثم تكون مؤقتة، فقد تستمر 10% منها. عند التلعثم يضطرب تدفق كلام الطفل، وقد يطيل الأصوات والمقاطع أو يكررها، كما قد يتوقف في أثناء نطق الكلمات. وأحيانًا يحاول استبدال الكلمة التي يصعب عليه نطقها بكلمة أخرى حتى يتجنب قولها. إذا لم يختفِ التلعثم خلال فترة معينة، فعليكِ مراجعة طبيب نفسي للأطفال دون تأخير. وبعد بلوغ سن معينة، تُستخدم تمارين خاصة للنطق والتنفس والإيقاع للمساعدة على علاج التلعثم. وإلى جانب هذه التمارين، قد يصف الطبيب علاجًا دوائيًا بهدف تخفيف قلق الطفل.') WHERE id = '214f43d5-3cc9-418c-b873-438c22b36c11';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك العديد من المهارات التي ترغبين في إكسابها لطفلكِ، وللأنشطة التي تُمارَس خلال اليوم دور كبير في ذلك. وعند التخطيط لهذه الأنشطة، ينبغي لكِ توفير بيئة تتيح لطفلكِ الاستمتاع والتعلّم في الوقت نفسه. دعي طفلكِ يختار بنفسه من بين المواد التي ستُستخدم في النشاط. وأتيحي له فرصة استخدام ما اختاره بالطريقة التي يريدها واللعب به. امدحي ما ينجزه وشجعيه بإخباره أنكِ ستعرضين عمله اليدوي في المنزل أو ستُرينه لأفراد الأسرة الآخرين. واختتمي كل نشاط بتلخيص موجز لما فعلتماه. ثم أعيدا المواد المستخدمة إلى مكانها معًا. وفي النهاية، تحدثي معه عما ستفعلانه في المرة المقبلة.') WHERE id = '045697f1-a06f-45b3-9655-5de4669bda47';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'الأفضل لطفلكِ هو الالتزام بنظام غذائي منتظم. فعندما لا تكون مواعيد الوجبات منتظمة، يتناول الأطفال مزيدًا من الأطعمة غير الصحية والوجبات الخفيفة خلال اليوم، ثم لا يشعرون بالشهية عند حلول موعد الوجبة الرئيسية. لذلك، سيكون من المفيد تعويد طفلكِ على تناول الطعام في مواعيد محددة. امنحيه فرصة تحديد ما يريد تناوله وكميته. فقد يتناول الطفل في سن 3 سنوات ما يعادل ربع الكمية التي تتناولينها. ويمكنكِ أيضًا وضع كمية قليلة من الطعام في طبقه أولًا، ثم إتاحة الفرصة له لطلب المزيد بعد الانتهاء منها. وإذا كان يشبع سريعًا أو يملّ عند تناول الحساء أو كرات اللحم أو المعكرونة، فيمكنكِ بدلًا من ذلك إعداد حساء يحتوي على اللحم المفروم والشعيرية، لمساعدته على الحصول على الفيتامينات اللازمة والشعور بالشبع في الوقت نفسه.') WHERE id = '33f0a878-2cad-4ad7-bd00-d76437c96e97';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يشمل المجال النفسي الحركي نمو العضلات الكبيرة والدقيقة لدى الطفل، بما في ذلك عضلات الذراعين والساقين واليدين والأصابع. ومن خصائص نمو طفلكِ في سن 3 سنوات في هذا المجال ما يلي: يستطيع الدوران حول مسار دائري، وركل كرة متدحرجة، والإمساك بكرة تُرمى إليه، والتقاط كرة ترتد عن الأرض. كما يستطيع إيقاف كرة كبيرة متحركة بقدمه، والمشي على أطراف أصابعه، والرقص وفقًا للإيقاع. ويمكنه القفز إلى الأمام بكلتا قدميه من وضع الثبات، وقطع مسافة قصيرة على عارضة التوازن، والوقوف على قدم واحدة لمدة 4-5 ثوانٍ. كما يستطيع رسم دائرة، وقص أشكال بسيطة بالمقص، وصنع أشكال مختلفة من مواد طرية مثل عجينة اللعب، وتنفيذ أعمال الطباعة باستخدام أدوات متنوعة. من المهم أن يتمكن طفلكِ من إظهار هذه المهارات النمائية المناسبة لعمره. ولدعم نموه النفسي الحركي، شجعيه على ممارسة أنشطة متنوعة وأكثري من مدحه على مهاراته.') WHERE id = '5aeea5d3-7c67-4223-93cf-b8c2cc86a497';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحتل التلفاز، ولا سيما الرسوم المتحركة، مكانة مهمة جدًا خلال مرحلة نمو طفلكِ. وربما لاحظتِ من حين إلى آخر أن طفلكِ يتقمص شخصيات الرسوم المتحركة بعد مشاهدتها. فالمحتوى الذي يشاهده يؤثر فيه ويوجّه سلوكه. وقد تدفع الرسوم المتحركة ذات المحتوى العنيف طفلكِ إلى السلوك العدواني، فيرى مستقبلًا أن الجدال أو الشجار هو الحل للمشكلات التي يواجهها. وقد يعجز أيضًا عن التمييز بين الأحداث الواقعية وغير الواقعية، فيتصرف بطريقة قد تؤذيه أو تضر بمن حوله. وعلى عكس ما قد يُعتقد، فإن هذه المسألة خطيرة وقد تترتب عليها عواقب سلبية للغاية. ويمكنكِ الوقاية من المشكلات قبل حدوثها من خلال الرقابة الأبوية وتحديد وقت استخدام الشاشات.') WHERE id = '78cf5c4d-d695-4dab-b490-d1b5c5cb5ec5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يرتبط الجانب الاجتماعي والعاطفي بقدرة الطفل على التكيف مع البيئة المحيطة، ويشمل تكيفه الاجتماعي وتواصله مع الآخرين وخصائصه العاطفية. وفي هذه المرحلة، تتضمن مظاهر نمو طفلكِ ما يلي: يجيب إجابات مناسبة عن الأسئلة المتعلقة به. يستخدم عبارات مهذبة مثل «من فضلك» و«شكرًا». يعبّر عن مشاعره. يدرك الحالة العاطفية للآخرين. يشارك في الألعاب الجماعية. يقف في الطابور وينتظر دوره. يشارك أغراضه الخاصة مع الآخرين. يلتزم بالقواعد تحت إشراف البالغين. ينفذ المهام البسيطة. يطلب الإذن عند الحاجة. قد يخاف من شخصيات خيالية متأثرًا بالقصص أو بما يشاهده. وقد يُظهر أحيانًا سلوكيات عدوانية، لكنها غالبًا ما تكون سلوكيات مكتسبة؛ أي إن الطفل يحاول بهذه الطريقة تحقيق ما يريده. ولدعم نموه الاجتماعي، احرصي دائمًا على أن تكوني قدوة حسنة له، ووفّري له فرصًا للوجود في بيئات تساعده على تكوين صداقات، وتجنّبي الإفراط في حمايته.') WHERE id = 'e64ca6c8-25c3-41b9-bc18-acfeeb611857';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لدينا اقتراح لنشاط ممتع يدعم النمو المعرفي لطفلكِ! من خلال لعبة «هكذا وليس كذلك»، يمكنكِ مساعدته على تركيز انتباهه على شيء أو موقف محدد، وفهم معنى ما يسمعه، والتحرك وفقًا للتعليمات الشفهية. وقاعدة اللعبة هي: بعد أن تقومي بحركة ما، يجب على طفلكِ تكرارها عندما تقولين «هكذا»، أما عندما تقولين «ليس كذلك» فعليه أن يبقى ساكنًا. على سبيل المثال، مدّي يديكِ إلى الأمام واجلسي القرفصاء. عندما تقولين «هكذا»، عليه أن يفعل الشيء نفسه، وعندما تقولين «ليس كذلك»، فعليه أن يتجمد في مكانه. وإذا أخطأ طفلكِ، يُطلب منه البقاء ساكنًا في مكانه حتى انتهاء اللعبة. وتستمر اللعبة باستخدام تعليمات مختلفة. وبعد أن يعتاد طفلكِ عليها، يمكنكِ جعلها أكثر تشويقًا بتغيير القاعدة إلى: «إذا قلتُ الصواب فنفّذ، وإذا قلتُ شيئًا غير صحيح فلا تنفّذ».') WHERE id = 'f0c5c0f6-066a-474d-8871-8aeef2575735';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحتاج طفلكِ إلى عدد كافٍ من خلايا الدم البيضاء (الكريات البيضاء) لمكافحة العدوى، ويمكن لجسمه إنتاجها بالاعتماد على البروتينات عالية الجودة. ويساعد تناول كمية كافية من البروتين على حماية الجسم من الأمراض. لكن عليكِ الانتباه إلى نقطة مهمة: يجب تناول اللحوم والدجاج والأسماك باعتدال لاحتوائها على الدهون المشبعة. كما ينبغي تناول البقوليات مرتين على الأقل أسبوعيًا. أما البروبيوتيك فهي بكتيريا نافعة تعزز جهاز المناعة من خلال دعم الفلورا المعوية. وتؤدي دورًا مهمًا في الوقاية من الإسهال والحساسية الغذائية، وتسهّل عملية الهضم، وتساعد على تصنيع الفيتامينات في الأمعاء. ويُعد الزبادي أهم غذاء غني بالبروبيوتيك.') WHERE id = '42c18429-e564-40bf-aa33-d415df0ffb9f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا تزال مدة انتباه طفلكِ البالغ من العمر 3 سنوات قصيرة جدًا، كما أن الانتباه الانتقائي لديه لم يتطور بعد بصورة تُذكر. ومثل سائر القدرات المعرفية، تتطور مهارات الانتباه مع التقدم في العمر وتزداد مدتها. ولتعزيز انتباه طفلكِ في المنزل، يمكنكِ لعب لعبة «ما الذي ينقص؟». أخرجيه من الغرفة لبعض الوقت وأخفي 3 أشياء موجودة فيها، ثم اطلبي منه عند عودته معرفة الأشياء الناقصة. وبطريقة مشابهة، تصفّحا معًا صفحة من كتاب أطفال مصوّر، ثم أغلقي الصفحة واطرحي عليه أسئلة عن التفاصيل الموجودة في الصورة. ناقشا معًا ما بقي في ذاكرته والتفاصيل التي يتذكرها. وتذكّري أن التلفاز من أكثر العوامل التي تضر بانتباه الطفل، إذ إن الإفراط في مشاهدته يضعف قدرته على التركيز. ولأن التلفاز وسيلة أحادية الجانب وغزيرة المثيرات، فإنه يؤثر سلبًا في انتباه الطفل ونموه الاجتماعي على حد سواء.') WHERE id = '37259b49-81ff-42b3-92f9-9c9297b14a64';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تؤدي عوامل مثل برودة الطقس، وفقدان الجسم للطاقة وشعوره بالتعب، والأماكن المغلقة والمزدحمة، وبيئة الحضانة إلى إصابة الأطفال بالأمراض بوتيرة أكبر. ويمكنكِ اتخاذ بعض التدابير لحماية طفلكِ خلال هذه الفترة. احرصي أولًا على أن يتناول غذاءً متوازنًا ويحصل على الفيتامينات اللازمة. فالأطفال الذين يعانون نقص الحديد أو فيتامين D أكثر عرضة للإصابة بالأمراض. ويُعد التطعيم الوسيلة الأكثر فاعلية للوقاية من الأمراض المعدية؛ لذا يمكنكِ إعطاء طفلكِ البالغ من العمر 3 سنوات لقاح الإنفلونزا، وهو موصى به خصوصًا للأطفال المصابين بالحساسية أو الربو. وفضّلي قضاء الوقت في الهواء الطلق بدلًا من الأماكن المغلقة مثل مراكز التسوق. واحرصي على تهوية منزلكِ وغرفة طفلكِ بانتظام. وتذكّري أن قلة النوم تضعف المناعة، لذا تأكدي من نوم طفلكِ مدة 8-10 ساعات يوميًا. كما ينبغي أن تعلّميه تغطية فمه بمنديل عند العطس أو السعال، ثم التخلص من المنديل بعد ذلك.') WHERE id = '7f8e3411-817d-4aa5-8fbc-2434b38bd6c6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد ألعاب الذكاء مفيدة جدًا لنمو الأطفال. فهي تنمّي لدى طفلكِ مهارات حل المشكلات واتخاذ القرارات والتفكير المنطقي. كما تساعد على تعزيز انتباهه وقدرته على التركيز، وتتيح لكِ في الوقت نفسه فرصة التعرّف إليه عن قرب. ويسهم اللعب بمجموعات ألعاب المنزل التخيّلية في تنمية إبداع طفلكِ. ومن خلال المهام التي تعطينها له، يمكنكِ تعليمه تصنيف الأشياء وعدّها. ويمكنكِ شراء بطاقات المطابقة من المتجر أو إعدادها بنفسكِ في المنزل. اطلبي منه مطابقة البطاقات المتشابهة لتقوية قدرته على الاستنتاج وذاكرته. نحن، أسرة Anacan، نتمنى لكِ ولطفلكِ أوقاتًا ممتعة مليئة باللعب!') WHERE id = '2692cebe-e1fb-4bfb-bb39-9959267a1b09';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يساعد الفضول والمشاعر الجنسية التي تبدأ بالظهور منذ سن 3 سنوات الأطفال على اكتشاف أنفسهم والجنس الآخر. وينبغي أن تكون مهمتكِ الأولى في هذا الموضوع إدارة هذه المرحلة بطريقة صحيحة. وفي هذه الفترة التي تزداد فيها الأسئلة المتعلقة بالجنس، عليكِ تقديم إجابات تناسب عمر طفلكِ وتلبّي فضوله، مع تذكّر أن اهتمامه بهذا الموضوع جزء طبيعي من مرحلة نموه. وهكذا، لا تعود موضوعات النمو الجنسي والأسئلة المرتبطة به من المحظورات، بل تكتسب طابعًا تثقيفيًا. إن تقديم تربية جنسية سليمة لطفلكِ منذ سن مبكرة يحميه مستقبلًا من الكثير من المعلومات الخاطئة والمزعجة، بل وحتى المخيفة، التي قد يواجهها. ولضمان تربية جنسية صحية، ينبغي أن تكوني مستعدة دائمًا للأسئلة المحتملة، وأن تتحلي بالصبر والتفهّم، وأن تتعاملي بنضج مع التصرفات غير المتوقعة وتسعي إلى معالجتها. تذكّري أن النمو الجنسي، شأنه شأن جميع مراحل النمو الأخرى، هو عملية متواصلة. فتجاهل هذه العملية لن يغيّر شيئًا، بل على العكس، قد يمهّد لظهور مشكلات مختلفة.') WHERE id = '1c19987a-0a44-4a51-b2a1-e6df3f6047f6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ثبت أن قلة الحركة في مرحلة الطفولة قد تسبب العديد من المشكلات في مرحلة البلوغ. وهناك أعداد كبيرة من الأطفال الذين يعانون من داء السكري والسمنة بسبب التغذية غير الصحية ونقص النشاط البدني. وقد يعاني الأطفال الذين لا تتاح لهم حرية كافية للحركة من نقص فيتامين D، وضعف جهاز المناعة، وإدمان الإنترنت، وضعف الثقة بالنفس، والعديد من المشكلات النفسية. كما لوحظ أن الأطفال قليلي الحركة أقل ثقة بأنفسهم، وأضعف في مهاراتهم الاجتماعية، وأدنى في تحصيلهم الدراسي. يميل الأطفال بطبيعتهم إلى النشاط البدني، وتُعد هذه السنوات بالغة الأهمية لهم. وبصفتكِ أمًا، عليكِ دعم رغبة طفلكِ في اكتشاف العالم من خلال ممارسة الأنشطة معه، وإتاحة الفرصة له للعب مع الأطفال الآخرين والتواصل مع الطبيعة. وإذا أردنا أن يحافظ أطفالنا على نشاطهم البدني في مرحلة البلوغ أيضًا، فعلينا أن نضع لهم روتينًا ممتعًا ومحفزًا.') WHERE id = 'b78f7a80-0899-4889-b99e-1008a78169dd';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يكتسب طفلكِ مهارات جديدة معينة كلما انتقل إلى مرحلة جديدة من مراحل النمو. وكل مهارة جديدة يكتسبها تحمل معها بعض المسائل التي تحتاج إلى معالجة. والصعوبات التي تظهر خلال مراحل النمو طبيعية ومؤقتة. لكن إذا تعرّض طفلكِ في هذه الفترات لمواقف خاطئة من البالغين المحيطين به، أو واجه عوائق أثناء محاولته حل مشكلاته، فقد يتأخر حل هذه المشكلات الطبيعية إلى مراحل النمو التالية والسنوات اللاحقة. وقد تظهر لديه اضطرابات انفعالية كرد فعل على ذلك، فتتفاقم المشكلات الصغيرة. وتُسمّى هذه الاستجابات السلبية اضطرابات التكيّف والسلوك. فعلى سبيل المثال، إذا لم يتلقَّ طفلكِ في سن 3 سنوات التدريب على استخدام المرحاض، أو لم يكتسب عادة تناول الطعام بنفسه، فستنتقل هذه المسائل إلى المراحل اللاحقة، وقد تتفاقم أكثر مع انضمام مشكلات جديدة إليها. لذلك، عليكِ تحديد المشكلات في الوقت المناسب، وألا تترددي في تقديم المساعدة والدعم اللازمين.') WHERE id = 'aee53b00-dbde-425d-9ce9-7c25f6732049';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع اقتراب سن 3 سنوات، قد يتخلى بعض الأطفال، وإن كان ذلك نادرًا، عن القيلولة ويضيفون الساعات التي كان يُفترض أن يناموا فيها نهارًا إلى نومهم الليلي. وبذلك يستكملون خلال الليل إجمالي ساعات النوم اليومية اللازمة لحياة صحية. ومع ازدياد مدة النوم الليلي، قد تظهر حالات مثل تقطّع النوم أو الاستيقاظ مع البكاء من دون سبب واضح. وقد يبدأ طفلكِ، الذي كان ينام براحة في غرفته حتى ذلك الوقت، فجأة بمنعكِ من الابتعاد عنه. في هذه الحالة، لا تدخلي معه في صراع أو عناد. فقد يكون قلق الانفصال سببًا آخر لما يمر به. وفي سن 3 سنوات تقريبًا، تتطور قدرة الطفل على إدراك الانفصال ويبدأ بفهم أنه مؤقت. حافظي على هدوئكِ واجعلي طفلكِ يشعر بالأمان. وما دام توازن نومه محفوظًا، فسيكون التعامل مع الحالات الأخرى التي قد تظهر أسهل بكثير.') WHERE id = '57867f35-0f30-4312-beb5-92170f7cfc26';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع دخول طفلكِ مرحلة نمو منتظمة، سيبدأ التحسن نفسه في شهيته أيضًا. وستكون لديه أطعمة معينة يحبها وأخرى لا يحبها، بل قد يطوّر تفضيلات غذائية خاصة، مثل رغبته في ألا تلامس الأطعمة بعضها بعضًا في الطبق. وسيساعد تعاملكِ مع هذا الوضع بتفهّم على تغيّر هذه السلوكيات خلال فترة قصيرة. كما أن احترامكِ للأطعمة التي يحبها وتلك التي لا يحبها سيجعله أكثر استعدادًا لتجربة نكهات جديدة. ومع مرور الوقت، ستلاحظين أنه يبدأ تدريجيًا في الاهتمام بمذاقات جديدة. لكن كثيرًا من الأطفال يرفضون الأطعمة غير المألوفة ويتجنبون الخضراوات. وقد يفضّلون الأطعمة البسيطة غير المختلطة، والمقدّمة بدرجة حرارة الغرفة، فلا تكون شديدة السخونة أو البرودة. وقد يرفضون أيضًا الأطعمة ذات النكهات القوية جدًا، أو يمتنعون عن الأكل عند رؤية حصص كبيرة. نظّمي مواعيد الوجبات، وتأكدي من أن طفلكِ يشعر بالجوع عندما يجلس إلى المائدة. وبذلك لن يكون أكثر استعدادًا لتناول الطعام فحسب، بل للاستمتاع به أيضًا.') WHERE id = 'e60990ac-04a0-447a-b8dd-3e9b930f53e6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الصعب جدًا العثور على طفل لا يشعر بأي خوف خلال هذه المرحلة. ومع نمو الأطفال، نلاحظ أن مضمون مخاوفهم وقلقهم يتغير تبعًا لتطور إدراكهم للواقع. وإذا تأملتِ مخاوف طفلكِ، فقد تلاحظين أنه يخشى غالبًا الأمور التي يراها خيالية أو خارجة عن السيطرة أو شديدة القوة. تذكّري أن مخاوفكِ قد تتحول أيضًا إلى مخاوف لدى طفلكِ. ففي العائلات التي تحاول حماية الطفل من العالم عبر مخاوف الوالدين، إذا كان الطفل لا يستطيع النوم بمفرده ويسمع عند كل خطوة يخطوها عبارة «انتبه، كن حذرًا!»، فإن ذلك يزرع بذور الخوف في قلبه. والرسالة الوحيدة التي يفهمها الطفل في هذه الحالة هي أن العالم مكان خطير وأنه سيتعرض للأذى من دون أمه. ونتيجة لذلك، ينشأ الطفل الذي تُقيَّد حريته غاضبًا وقلقًا في آن واحد. كما يفقد فرصة تعلّم ما إذا كان الخطر حقيقيًا أم لا، وتطوير مهارات التعامل مع المخاطر.') WHERE id = 'a689ae5f-76a6-4879-8a7d-913385389f00';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'سيساعدكِ التفاهم مع طفلكِ بشأن النوم وتحديد طريقة ترضي كليكما على تسهيل انتقاله إلى النوم. ويمكنكِ توجيهه نحو أنشطة هادئة من خلال قضاء وقت ممتع معه قبل النوم. فمثلًا، يمكنكما تركيب أحجية يحبها، أو تلوين كتاب تلوين جديد بحماس، أو اللعب ببطاقات الذاكرة العائلية. أما المرحلة الثانية فهي إنشاء روتين للنوم. وإذا لم يكن لديكما روتين حتى الآن، فاحرصي على وضع واحد، مثل تنظيف الأسنان وارتداء ملابس النوم والانتقال إلى الغرفة. كما أن التحدث عما فعلتماه خلال اليوم قبل الدخول إلى السرير مباشرة سيجعل الانتقال إلى النوم أكثر سلاسة. ومع النهج الصحيح، لا توجد مشكلة نوم لا يمكنكِ التغلب عليها.') WHERE id = 'c48bfda0-f484-4ffc-9e93-eb4d1874ec5c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يشمل المجال المعرفي النمو الذهني للطفل. ومن سمات النمو التي يُظهرها طفلكِ في هذه المرحلة: التمييز بين مفاهيم مثل «كبير-صغير، قليل-كثير، مفتوح-مغلق، طويل-قصير». ويعدّ من 1 إلى 10، ويستطيع إظهار أي عدد من الأشياء ضمن هذا النطاق. ويُكمل رسمًا غير مكتمل لشخص بإضافة الذراعين والساقين. ويتعرّف إلى الألوان ويطابق بينها. كما يسمّي الشيء الذي يرى صورته، ويشير إلى أجزاء جسمه، ويذكر جنسه. ويُكمل أحجية مكوّنة من 4 قطع، ويبني جسرًا من ثلاثة مكعبات، ويواصل بعض الأنماط المتسلسلة بالنظر إلى النماذج. ولمساعدة طفلكِ على النمو المعرفي، يمكنكما غناء أغانٍ طويلة معًا، وتكرار الحروف الأبجدية، وتعلّم العد، وابتكار ألعاب حول المفاهيم المتضادة التي تعلّمها. كما أن الإكثار من الرسم مفيد جدًا لهذا الجانب من النمو.') WHERE id = 'b045120f-87b5-4805-8c7a-a4f492679361';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تشمل الأنشطة المناسبة للأطفال في عمر 3 سنوات الأنشطة الفنية. وهي مفيدة خصوصًا لتنمية المهارات الحركية الدقيقة لدى طفلكِ، وتعلّم الألوان واستخدامها، وتعزيز قدرته على اتخاذ القرار وروح الابتكار لديه. الطباعة بالبطاطس: نشاط ممتع للغاية، يتيح لكِ ابتكار نشاط باستخدام مواد متوفرة في المنزل، ويساعد طفلكِ أيضًا على التعرّف إلى الألوان. تلوين المعكرونة: يمكنكِ كذلك دعم تعلّم طفلكِ للألوان باستخدام مواد متوفرة في المنزل. الأشغال اليدوية بالرمل الحركي والطين: تسهم في تنمية المهارات الحركية وحاسة اللمس لدى طفلكِ، إلى جانب تعزيز إبداعه. أعمال الكولاج: يمكنكِ لصق الأشكال التي تقصّينها من المجلات والصحف داخل شكل حيوان أو صورة يحبها طفلكِ. وسيساعد هذا النشاط على تطوير إدراكه للأشكال وحسّه الجمالي وقدرته على تنسيق الألوان. كما ستؤثر أنشطة القص واللصق باستخدام الورق المقوّى المتوفر في المنزل إيجابيًا في نمو طفلكِ. وسيتعلّم أيضًا استخدام المقص والغراء، وتنمو عضلاته الحركية الدقيقة. ومن أكثر الأنشطة التي يستمتع بها الأطفال في عمر 3 سنوات أيضًا طباعة اليدين (طلاء اليدين). فالأطفال يحبون الأشياء التي يلمسونها، ويستمتعون «بالاتساخ» بالألوان.') WHERE id = 'e5bdc7b7-a97a-44c2-b099-bfe105f73253';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الضروري أن تجعلي طفلكِ يشعر بأنكِ تفهمينه. فمجرد معرفته بأنه مفهوم، ورؤيته أمًا تتعامل بهدوء مع خوفه، قد يكونان كافيين لطمأنته. أما قولكِ له: «لقد كبرت، والأطفال الكبار لا يخافون»، فيمنعه من التعبير عن خوفه، وهذا يجعل تعامله مع مخاوفه بمفرده أكثر صعوبة. والطريقة الأفضل هي مساعدته على الاعتياد على الموقف الذي يخشاه، ولكن بخطوات صغيرة. ويمكنكِ أن تطلبي منه رسم الشيء الذي يخيفه أو مساعدته على التعبير عنه من خلال اللعب. تجنّبي المبالغة في حمايته. والأهم هو أن تمنحيه الشعور بالأمان وتُشعريه بأنكِ إلى جانبه. كما أن التركيز مباشرة على إيجاد حل لكل مشكلة تواجهينها سيكون مفيدًا لنمو طفلكِ أيضًا.') WHERE id = '736cfd0f-4d07-4b51-ab44-1153bfbeddcc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد الحفاظ على التوازن بين طفلين من أكثر الأمور التي تشكّل تحديًا للوالدين. ففكرة إدخال منافس إلى علاقة الحب التي بُنيت مع الطفل الأول تثير الشعور بالذنب لدى كثير من الوالدين. وغالبًا ما تؤدي هذه المشاعر المتوترة التي يمر بها الوالدان إلى تأجيج التنافس بين الإخوة. عندما يُرزق طفلكِ بأخت أو أخ، فإنه يوجّه غضبه إليكِ في المقام الأول. ثم عندما يكبر الرضيع ويبدأ بمشاركته ألعابه، قد يحاول الطفل الأكبر استمالة والديه إلى جانبه بدفع الصغير أو إيذائه. وللحد من مشاعر التنافس، عليكِ أن تكوني عادلة. وتذكّري أنكِ قدوة طفلكِ في هذا الأمر أيضًا. وإذا وزّعتِ التفهّم بالتساوي مثلما توزعين الحب، فسيتمكن طفلكِ من التكيّف مع هذه المرحلة بسرعة أكبر.') WHERE id = 'd1f93b96-fae1-4e14-8f57-01339aca54be';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعدّ المشكلات المرتبطة بالخوف شائعة لدى الأطفال. وعادةً ما يكفي أن تلاحظي قلق طفلكِ وتتفهميه، مع طمأنته إلى عدم وجود خطر حقيقي. أما الأطفال الذين لا يتعلمون تهدئة أنفسهم عند الخوف من النوم بمفردهم، فقد يواجهون في المستقبل صعوبة في التعامل مع أنواع أخرى من القلق. كما تشيع لدى الأطفال في هذا العمر مخاوف تُصنَّف ضمن أنواع الرهاب البسيط. وقد تشمل الخوف من حيوانات مختلفة، مثل الكلاب والعناكب والثعابين، إلى جانب الخوف من المهرجين والدمى والعرائس. وعادةً ما تستجيب هذه الحالات جيدًا لأساليب التعوّد التدريجي. وقد تظهر صعوبات مماثلة أيضًا عند بدء الدراسة. ينبغي ملاحظة مدى تأثير هذه السلوكيات في طفلكِ، ثم الاستعانة باختصاصي لتقييم ما إذا كانت تسبب اضطرابًا، وبناءً على ذلك تحديد الخطوات المناسبة.') WHERE id = 'a067638e-a997-4f38-b9e7-190a03622232';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تساعد الأنشطة البدنية طفلكِ على تصريف طاقته الجسدية بطريقة سليمة. فالأطفال في هذا العمر كثيرو الحركة ويحتاجون إلى تفريغ طاقتهم. ومن خلال الأنشطة، يمكنكِ مساعدته على توجيه طاقته توجيهًا صحيحًا والتعلم من خلال التجربة. يمكنكِ أن تلعبي معه لعبة تخيّل قطف التفاح والكمثرى من شجرة وهمية. سيساعده ذلك على توجيه حركاته بصورة صحيحة وتصريف طاقته. كما يمكنكِ إعداد مسارات بسيطة مليئة بالعوائق داخل المنزل باستخدام الوسائد أو الزجاجات البلاستيكية، لدعم تطور قدرته على التوازن. كذلك ستسهم التمارين الرياضية التي تمارسانها معًا في نمو عضلاته وفي استهلاك طاقته بطريقة سليمة.') WHERE id = 'b8723400-ce1a-4748-adc7-c971c125b448';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يشعر الأطفال الذين يشاهدون أفلامًا كرتونية تتضمن مخلوقات مختلفة وغريبة بالارتباك الداخلي. فطفلكِ، الذي بدأ حديثًا في التعرّف إلى محيطه والحيوانات، قد يحتار لأنه لا يستطيع تشبيه هذه المخلوقات بأي كائن حي من حوله، وقد يعتقد أن مثلها موجود في الحياة الواقعية. ولأن الأطفال لا يدركون حقيقة الموت إدراكًا كاملًا، فقد يرون أن شخصيات الرسوم المتحركة لا يصيبها شيء رغم تعرضها لأحداث سيئة، أو أنها تعود إلى الحياة مجددًا، فيظنون أن الأمر كذلك في الواقع أيضًا. وعندما تواجهين مواقف كهذه، فهذا يعني أن الوقت قد حان لاتخاذ الاحتياطات اللازمة. من الضروري أن تكوني على دراية بمحتوى أفلام الرسوم المتحركة التي يشاهدها طفلكِ، وأن تشاهديها بنفسكِ مسبقًا. وإذا شاهد من دون علمكِ فيلمًا كرتونيًا لا ينبغي له مشاهدته، فعليكِ إشراكه في أنشطة توضّح له الحقائق المتعلقة بالمفاهيم التي تعلّمها بصورة خاطئة، وألا تسمحي باستمرار سوء فهمه. وبالطبع، فإن المبالغة في رد الفعل قد تجعله غير مبالٍ بالأخطاء التي قد يرتكبها مستقبلًا. لذا من المفيد التصرف بحذر.') WHERE id = '82c4e544-a3c2-47a5-b6a9-f7d5ed183ba6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين أن طفلكِ لا يعرف مصدر بعض الأصوات أو ماهيتها. لذلك من المهم أن تشرحي له، مثلًا، أن الطيور تزقزق وأن الماء ينساب بخرير، حتى يتمكن من التعرّف إلى هذه الأصوات واستيعابها. ويُعدّ فهم العلاقة بين الأصوات والأشياء جزءًا مهمًا من التطور المعرفي. قد يساعد ترديد الحروف الأبجدية أو قراءة كتب تتناولها مع طفلكِ على معرفة المزيد، ليس فقط عن أشكال الحروف، بل أيضًا عن أصواتها. ويمكنكِ شراء حروف أبجدية مغناطيسية وتثبيتها على الثلاجة لتظل أمام ناظريه باستمرار. ومهما كنتما تفعلان وأينما كنتما، احرصي على إيجاد فرص لعدّ الأشياء معًا. فعدّ الألعاب الموجودة على الأرض أو الأراجيح في ساحة اللعب سيعزز مهارة العد لدى طفلكِ ويفيده على المدى الطويل.') WHERE id = '49a8ae6c-9766-4df6-8909-4e796ec60417';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إن أسلوب تواصلكِ مع طفلكِ في أثناء تنشئته مهم جدًا، فهو يشكّل أساس العلاقة التي ستجمعكما طوال الحياة. أولًا، عليكِ أن تتعلمي الإصغاء إليه جيدًا. فإذا تظاهرتِ بالاستماع إليه، فسيدرك ذلك فورًا. وإذا كنتِ منشغلة، فأخبريه بأن ينتظر قليلًا وأنكِ ستستمعين إليه بعد لحظات. احرصي على التواصل البصري معه في أثناء الحديث، لأن ذلك سيجعله يشعر بأهميته. وقبل بدء الحديث، يمكنكِ احتضانه أو الجلوس بحيث يكون وجهكِ في مستوى وجهه. فقد يوحي الحديث إليه من الأعلى بأنكِ تمثلين سلطة تفرض نفسها عليه. ويمكنكِ استخدام إيماءات تدل على أنكِ تفهمين ما يقوله. وبهذه الطريقة، ستحافظين على الركائز الأساسية للتواصل الصحي. فالتواصل السعيد يعني علاقة سعيدة بين الأم وطفلها. :)') WHERE id = '347c6615-9410-46a6-991e-5f1e3c8203fe';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'كلما زاد اندماج طفلكِ اجتماعيًا وتواصله مع عدد أكبر من الأشخاص، قد يبدأ بالإصابة بالأمراض بوتيرة أكثر تكرارًا. وقد يحتاج في هذه الفترة إلى قدر أكبر قليلًا من الدعم. وتتمثل وسيلة الوقاية من الأمراض التي تزداد مع تغير الفصول وتنتقل بسهولة، وفي مقدمتها الإنفلونزا، في دعم الجهاز المناعي الذي يعمل كدرع في مواجهة الجراثيم. يحتاج طفلكِ يوميًا إلى فيتامين C وغيره من مضادات الأكسدة، ومن المهم إيلاء عناية خاصة لتلبية هذه الحاجة عندما يكون مريضًا. وتُعدّ الفواكه والخضراوات الطازجة مصادر ممتازة لفيتامين C. كما تتمتع مضادات الأكسدة والعناصر الغذائية، مثل فيتامينات A وC وE والبيتا كاروتين والزنك والسيلينيوم، بأهمية كبيرة في دعم المناعة. يتقوى الجهاز المناعي لطفلكِ تدريجيًا طوال حياته، ويتعلم محاربة الكائنات الحية الدقيقة ويحتفظ في ذاكرته بما تعلمه. ويمكن العثور في الصيدليات على مكملات عشبية وفيتامينات مختلفة يُدّعى أنها تقوي المناعة. لكن الدراسات تشير إلى أن كثيرًا من هذه المكملات لا يؤثر تأثيرًا ملموسًا في معدل الإصابة بالأمراض أو شدتها. والأفضل أن تحاولي توفير هذا الدعم لطفلكِ من خلال الأطعمة الطبيعية.') WHERE id = '669440a9-0ed7-4808-b35f-e8eb8a2f9d28';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في الوقت الحاضر، يكاد يكون من المستحيل إبعاد الأطفال عن الشاشات لفترات طويلة. وإذا كنتِ قد نجحتِ في ذلك حتى الآن، فنهنئكِ. وبسبب كثرة الخيارات وعدم شعور الأطفال المعتادين على الشاشات بالاكتفاء، قد يطلب منكِ طفلكِ باستمرار مشاهدة رسوم متحركة مختلفة. ولأن بعض الرسوم المتحركة لا تتوافق مع الواقع، فقد تؤثر سلبًا في نفسية الأطفال. ففي هذه المرحلة التي تتشكل فيها أسس شخصية طفلكِ، قد تحول مشاهدة هذا النوع من البرامج دون تعلّمه كيفية مواجهة المشكلات، وقد تجعله يشعر بعدم الكفاءة ويؤمن بوجود قوى خفية. كما قد تتسبب هذه البرامج في إضعاف موهبة الخيال لدى طفلكِ، وهي موهبة ربما كانت ستمكّنه من تحقيق نجاحات كبيرة في المستقبل. لذلك، قد يساعدكِ حذف القنوات التي تعرض رسومًا متحركة ضارة أو تقييد الوصول إلى الإنترنت على الاقتراب أكثر من الحل.') WHERE id = 'cb829028-fb2e-42e5-8dbf-8ffd5eeadfe6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المتوقع أن يقلّ التعلّق، الذي يُعد طبيعيًا حتى سن 3 سنوات، ابتداءً من هذه السن. وإذا استمر بعد ذلك، فعلى الوالدين أولًا أن يتقبلا أن طفلهما لم يعد رضيعًا يحتاج إلى الرعاية باستمرار، بل أصبح فردًا ينمو ويتطور. ومن الضروري دعمه في المهام التي يستطيع إنجازها باستقلالية، وإرشاده وتعزيز ثقته بنفسه. يمكن للأطفال منذ مرحلة الرضاعة الابتعاد عن أمهاتهم لفترات قصيرة، أما في سن 3 سنوات فيمكنهم البقاء من دون أمهاتهم طوال اليوم، بل لعدة أسابيع عند الضرورة. لكن الأطفال شديدي التعلّق يجدون صعوبة حتى في البقاء في غرفة منفصلة عن الأم داخل المنزل أو في اللعب بمفردهم. إذا كنتِ لا تريدين أن ينشأ طفلكِ شديد الاعتماد عليكِ، فلا تنجزي كل شيء بدلًا منه، ولا تسارعي إلى تلبية احتياجاته قبل أن يطلبها، ولا تعامليه كما لو كان لا يزال رضيعًا. وتجنّبي عبارات مثل "لن تنجح" و"لا يمكنك فعل ذلك"، ولا تحمليه بين ذراعيكِ ما دام قادرًا على المشي، ولا تخيفيه بتحذيرات متكررة مثل "توقف، ستسقط".') WHERE id = '4738fb4c-c793-443f-b75e-37a8d6ed29fc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'غالبًا ما تبدأ عادة قضم الأظافر بالظهور بعد سن 3 سنوات. وقد تشير هذه العادة إلى وجود بعض الضغوط أو التوترات الداخلية لدى الطفل. وكما هي الحال مع مصّ الإصبع، تكون الأسباب الكامنة وراء هذا السلوك نفسية في الغالب. لكن قد يبدأ الطفل أحيانًا بقضم أظافره دون سبب محدد، وإنما لمجرد تقليد شخص آخر. فقد ينسخ هذا السلوك إذا رأى شخصًا في أسرته أو محيطه القريب يقضم أظافره. وكما هي الحال مع سائر المشكلات، ينبغي تحديد الأسباب المؤدية إلى هذا السلوك وإيجاد الحل المناسب بناءً عليها. والهدف الأساسي هو تغيير العادة الخاطئة واستبدالها بسلوك صحي. ويمكن حل هذه المشكلة بدعم من مختص وباتباع نهج حازم ومنتبه وإيجابي. والأهم هو معالجتها قبل أن تستمر إلى مراحل عمرية متقدمة.') WHERE id = 'e5f665da-3a53-44ad-a3a1-38110cb4e5cb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ دعم نمو طفلكِ وقضاء وقت ممتع معه من خلال أنشطة بسيطة باستخدام أشياء موجودة في المنزل. اكتبي الأرقام من 1 إلى 10 على ورقة، ثم قصّيها لتحصلي على بطاقات أرقام. بعد ذلك، غطّي عيني طفلكِ وأخفي إحدى البطاقات، ثم اطلبي منه بعد فتح عينيه معرفة الرقم المفقود. وإذا واجه صعوبة، فساعديه بتلميحات بسيطة. وسيصبح اللعب أكثر تشويقًا إذا بدّلتما الأدوار وأغمضتِ أنتِ عينيكِ. يمكنكما ابتكار ألعاب كثيرة باستخدام هذه البطاقات، مثل مطابقة الرقم بعدد الأشياء. اطلبي من طفلكِ ترتيب الأرقام بالتسلسل بدءًا من 1، ثم اطلبي منه وضع عدد مماثل من الأشياء، مثل قطع الليغو، أسفل كل رقم. ويمكنكِ جعل هذه اللعبة ممتعة وتعليمية من خلال إعطائه تعليمات مثل: ضع قطعتين من الليغو أسفل الرقم 2، وضع 5 قطع من الليغو أسفل الرقم 5.') WHERE id = '9e993abd-9c34-4730-9c72-8d2c670361fe';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بعد سن 3 سنوات، يصبح طفلكِ فردًا له رأيه ويحتاج إلى أن تسأليه عنه. وسيؤدي تعاونكما بشأن النوم إلى نتائج إيجابية لكليكما. يمكنكِ وضع طقمي نوم مختلفين على سريره وسؤاله أيهما يرغب في ارتدائه اليوم. كما يمكنكِ قراءة كتاب القصص الذي يختاره طفلكِ والاستماع معه، أثناء الاستعداد للنوم، إلى موسيقى هادئة تساعده على الاسترخاء والتهيؤ للنوم. ولكن ينبغي أن تنتهي القصة والموسيقى بعد دخوله إلى السرير. يمكنكِ البقاء إلى جانبه حتى ينام، أو إخباره بأنكِ ستعودين للاطمئنان عليه من حين إلى آخر، ثم طمأنته والخروج من غرفته. وإذا رفض النوم وغادر غرفته وجاء إليكِ، فتجنّبي السماح له بالنوم في سريركِ أو بقضاء الوقت في غرفة المعيشة. فقد حان وقت النوم، وعلينا تعليمه أنه يجب أن ينام. وإذا بقي طفلكِ في سريره واتّبعتِ الأسلوب الصحيح، فسيتعلم مع الوقت أن ينام بمفرده ويحافظ على هذه العادة.') WHERE id = '733374d5-7605-4401-b96a-efdb4c6641db';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يظهر صرير الأسنان غالبًا لدى الأطفال في سن 3 سنوات فما فوق. إذا لاحظتِ أن طفلكِ يصرّ على أسنانه، فلا تقلقي. صرير الأسنان، أو ما يُعرف طبيًا بالبروكسية، هو عادةً شدّ الفك واحتكاك الأسنان بعضها ببعض أثناء النوم. وعندما تُعالَج العوامل المهيئة لصرير الأسنان لدى الأطفال، تتراجع هذه المشكلة بدرجة كبيرة. وتشمل العوامل المسببة لصرير الأسنان حالات مرتبطة بصحة الطفل العامة وحالته النفسية. وقد تحفّزه خصوصًا اضطرابات الجهاز الهضمي، مثل الارتجاع والطفيليات المعوية، ومشكلات الجهاز التنفسي، مثل التهاب الجيوب الأنفية والتهاب الشعب الهوائية التحسّسي والربو. كما قد تسببه عوامل تولّد ضغطًا نفسيًا، مثل ولادة أخ أو أخت جديدين، والخلافات بين الوالدين، والمشكلات في الحياة المدرسية. ومن المهم تحديد السبب الحقيقي لصرير الأسنان من أجل علاجه.') WHERE id = '3cf9f3d5-8020-4400-b287-32fc685bb51a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لدينا نشاط ممتع يساعد على دعم التطور اللغوي لطفلكِ! من خلال لعب لعبة «ما هذا الصوت؟»، يمكنكِ مساعدة طفلكِ على التمييز بين الأصوات، وفهم خصائصها، ووصف اتجاه الصوت ومصدره، والتحكم في سرعة صوته ونبرته. الأدوات المطلوبة: صندوق من الورق المقوّى وأغراض مختلفة تُصدر أصواتًا (مثل ميدالية مفاتيح وجرس وناي وغيرها). يُفتح الجزء الخلفي من صندوق كبير من الورق المقوّى، ويوضع أمام الطفل على هيئة مسرح. ثم توضع خلف الصندوق أغراض مختلفة تُصدر أصواتًا، مثل ميدالية مفاتيح وشوكة وكوب وجرس وقطعة من الورق المقوّى وكمان وهاتف وغيرها. أصدري صوت كل غرض على حدة، واطلبي من طفلكِ تخمين الغرض الذي أصدره. وبعد أن يخمّن، أريه الأغراض واحدًا تلو الآخر. ثم اطلبي منه تقليد أصواتها. وحوّلي النشاط إلى لعبة بأن تطلبي منه إصدار صوت أرفع أو أغلظ من صوت كل غرض. في النهاية، لخّصي ما فعلتماه واختتما النشاط. نتمنى لكما وقتًا ممتعًا!') WHERE id = '43a70d56-435a-4bbb-9015-96343adf0716';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لمساعدة طفلكِ على تعلّم الكلمات والأسماء وكل ما ينبغي له معرفته، تحدّثي معه كثيرًا عن كل شيء! فكما يحتاج طفلكِ إلى الهواء والحب والغذاء والنوم، يحتاج أيضًا إلى أن تتحدّثي معه. لا تظني أنه لا يزال صغيرًا جدًا على الكلام؛ فحتى إن لم يفهم كل كلمة، يمكنه أن يتعلّم كل شيء من خلال الاستماع إليكِ، فأنتِ معلّمته الأهم. توجد كلمات لشرح كل شيء، حتى الأشياء التي لا يمكنكما رؤيتها. كما أن من أهم طرق تعلّم الأطفال للكلمات الروابط التي يبنونها مع الأشخاص الآخرين الذين يتواصلون معهم. تذكّري أن التحدّث مع طفلكِ وتشجيعه على الكلام من أهم الأمور التي يمكنكِ القيام بها من أجله.') WHERE id = '02e9718b-0c4d-4aac-9885-67ffb7f4465a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد انتظام مواعيد الوجبات من أهم العادات التي يمكنكِ إكسابها لطفلكِ، ويكون تناول الطعام بانتظام أكثر فائدة عندما يكون متوازنًا. ينبغي أن يتناول طفلكِ كميات متوازنة من مختلف أنواع الأطعمة. تشمل الأطعمة الغنية بالبروتين عالي الجودة: البيض والحليب والزبادي وكرات اللحم والبقوليات. وينبغي لطفلكِ تناول 2-3 حصص منها يوميًا. يجب ألا تتجاوز كمية الحليب أو الزبادي 500 ml يوميًا، لأن الإفراط في هذه الأطعمة قد يسبب الإمساك ويعيق امتصاص الحديد، مما قد يؤدي إلى فقر الدم (الأنيميا). يمكن إضافة منتجات الحبوب إلى الحساء أو تقديمها مع الحليب أو الزبادي. كما يمكن تقديم خبز القمح الكامل أو كمية قليلة من الأرز أو المعكرونة إلى جانب الوجبات. وينبغي تناول 4-6 حصص منها يوميًا. تجنّبي الأطعمة الحارة وكثيرة التوابل، ولا تقدّمي الطعام شديد السخونة أو البرودة. قدّمي الطعام في حصص صغيرة، ولا تضعي أمام طفلكِ كمية تفوق قدرته على إنهائها. وإذا كان طفلكِ يعاني ضعفًا شديدًا في الشهية، فاتركي له حرية تحديد الكمية التي يرغب في تناولها. واحرصي دائمًا على استخدام طرق طهي صحية.') WHERE id = 'ba98f01b-59c2-46b5-ad80-6243e50c4c2c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تؤدي روضة الأطفال دورًا مهمًا في حياة الطفل. وابتداءً من عمر 3 سنوات، يُعد طفلكِ ناضجًا بما يكفي للالتحاق بها. عند إعداده للروضة، اشرحي له طبيعة المكان والأنشطة التي سيقوم بها بعبارات مثل: «سيكون لديك أصدقاء ومعلمون جدد، وستتعلّم ألعابًا وأغاني جديدة». وإذا كنتِ قد قررتِ الروضة التي سيلتحق بها، فمن المفيد أن تصطحبيه لرؤيتها مسبقًا. قد تدور في ذهنه أسئلة كثيرة عن الروضة، وعليكِ الإجابة عنها بصدق وبأسلوب يناسب عمره. وينبغي لجميع أفراد الأسرة دعم التحاق الطفل بالروضة. فالطفل الذي يذهب إلى الروضة يُظهر اهتمامًا بالتعلّم، ويكتشف مواهبه، ويتواصل مع أقرانه، ويكتسب مهارات التعاون. كما تتاح له فرصة التصرّف باستقلالية، وتنمو ثقته بنفسه. ويتسارع تطوره اللغوي وتزداد حصيلته من المفردات. كذلك تتحسن قدرته على التواصل، ويتعلّم القواعد الاجتماعية، ويصل إلى مستوى الاستعداد اللازم للمرحلة التعليمية التالية.') WHERE id = 'a0631e7f-5da5-491b-8885-201721d33c3c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من أهم الأمور التي نرغب في تعليمها لأطفالنا في هذه الحياة كيفية التعامل مع مشاعر الغضب. وبالتأكيد، لا يمكننا تعليمهم ذلك من خلال ضربهم. فالشيء الوحيد الذي نعلّمه لطفلنا بهذا السلوك هو أن الضرب أمر مقبول. يرى الأطفال أن كل ما يفعله الكبار صواب، وخصوصًا والديهم الذين يعدّونهم رمزًا للصواب؛ فهم ينشؤون وهم يقلّدون والديهم. ومن الناحية النفسية، لا يوجد عقاب بدني خفيف وآخر شديد. فإذا استمر أسلوب «الضرب الخفيف»، ولم يعد من الممكن توجيه الطفل بالكلام، فقد يزداد هذا السلوك شدةً مع الوقت. لا يستحق أي طفل أن يُضرب مهما كان تصرفه. ولا بد أن توجد دائمًا طريقة لتعليم الصواب دون اللجوء إلى الضرب؛ إذ لا يمكن أبدًا تعليم الصواب باستخدام الخطأ. إذا كنتِ من الأمهات اللاتي يضربن أطفالهن، فعليكِ إعادة النظر في أساليبكِ التربوية.') WHERE id = '92bb35c0-fd2f-4c38-b4fe-df9cb24e9a7e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'اللعب هو أهم عمل يقوم به الطفل، وهو أيضًا من أهم وسائل نموه. ففي بيئة اللعب، يعبّر الأطفال عن أنفسهم بحرية، ويعكسون تجاربهم، ويستعدون للعالم الخارجي دون أن يشعروا بذلك. ومن خلال اللعب، يتعرّفون إلى العالم من حولهم ويتعلّمون كيفية التغلب على الصعوبات. ويُعد اللعب، ولا سيما في مرحلة ما قبل المدرسة، البيئة الأنسب للتعبير عن المشاعر والأفكار. يمكنكِ الدخول إلى عالم طفلكِ الداخلي من خلال «العلاج باللعب»، ومساعدته على التعبير عن مشاعره دون عوائق. أثناء العلاج باللعب، يُظهر الأطفال من خلال اللعب مشاعرهم السلبية ومشاعر التوتر المرتبطة بعلاقتهم بأنفسهم وبمن حولهم. وبمساعدة اختصاصي محترف في العلاج باللعب، يعيد الأطفال تمثيل هذه التجارب أثناء اللعب ويجدون حلولًا أكثر صحة لمشكلاتهم. وهكذا، يتعلّم الأطفال في نهاية عملية العلاج باللعب كيفية التواصل مع الآخرين، والتعبير عن مشاعرهم، وتعديل سلوكهم، وتنمية مهارات حل المشكلات.') WHERE id = '58290ecf-f278-4d4a-9163-4f46b8047707';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ يعاني من تساقط الشعر، فقد تكون هناك عدة أسباب مختلفة لذلك. قد يؤدي النظام الغذائي غير المتوازن، والأطعمة الجاهزة، أو ضعف امتصاص الجسم لبعض الفيتامينات مثل B12 إلى هذه الحالة. وينبغي تحديد نقص العناصر المهمة مثل الزنك والحديد وفيتامين D من خلال التحاليل المخبرية، ثم وضع خطة مناسبة للتغذية والعلاج. كما قد يكون اختلال التوازن الهرموني أو أمراض الغدة الدرقية من الأسباب أيضًا. وقد يكون تساقط الشعر أحيانًا مؤشرًا على أمراض عديدة، لذلك لا بد من متابعته بعناية وعلاجه. وقد يُلاحظ تساقط الشعر أيضًا أثناء الأمراض المصحوبة بارتفاع درجة الحرارة أو بعدها، وعادةً ما تزول هذه المشكلة بعد التعافي من المرض. كذلك قد تؤدي العدوى الفطرية التي تظهر في مرحلة الطفولة، والمعروفة شائعًا باسم سعفة الرأس، إلى تكسّر الشعر وتساقطه. في مثل هذه الحالات، عليكِ استشارة طبيب الأمراض الجلدية دون تأخير، لأن التأخر في العلاج قد يؤدي إلى تلف دائم في الجلد وفقدان الشعر.') WHERE id = 'a768aeb4-9aff-4b79-a04e-4dac320ad5cb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'طفلكِ البالغ من العمر 3 سنوات ليس مستعدًا عاطفيًا بعد للألعاب الجماعية القائمة على المنافسة، وقد لا يتقبل الخسارة. لذلك، من الأنسب أن تفضّلي الألعاب الفردية المنطقية المصممة لعمر 3 سنوات بدلًا من الألعاب الجماعية. كما أن الألعاب المعقدة التي تركز على حل المشكلات لا تزال مبكرة على هذه الفئة العمرية. يستمتع الأطفال في سن 3 سنوات بالألعاب التي تعتمد على تقليد ما يرونه، وبناء شكل مماثل، وإدراك الأشكال والاتجاهات، وتعلّم الألوان، وتنمية المهارات الحركية الدقيقة. وستدعم نموه بصورة كبيرة، خصوصًا ألعاب الذكاء التي تتطلب منه تكوين شكل مطابق للصورة الموجودة على البطاقة. من المهم جدًا أن يكون مستوى اللعبة مناسبًا لعمر طفلكِ، لأن مواجهته ألعابًا تفوق عمره أو مهام تتجاوز قدراته باستمرار قد تؤثر سلبًا في حالته النفسية.') WHERE id = 'f3e811c2-a7fa-456e-97e8-93170cf88e9e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يؤثر ضغط الوالدين في موضوع الطعام، ووضع قواعد تعتمد على المكافأة أو العقاب، سلبًا في عادات طفلكِ الغذائية. فقد يأكل قليلًا في بعض الأيام وكثيرًا في أيام أخرى، لذلك لا ينبغي أن تجبريه على تناول كمية محددة من الطعام، بل عليكِ احترام شهيته. ومن المهم تقديم الطعام في أوقات محددة وإبعاده عن الأطعمة الضارة. كما أن الإفراط في تناول الفاكهة قد يفقده شهيته أيضًا. إذا قدّمتِ له كل شيء بانتظام واعتدال، فلن تواجهي مشكلات خطيرة. وإذا أصرّ طفلكِ على طلب الفاكهة، يمكنكِ توجيهه بطريقة مناسبة بقولكِ: «يمكننا بعد الطعام أن نُعدّ معًا طبقًا جميلًا من الفاكهة».') WHERE id = 'aff152bf-fa50-40eb-a007-43da0c3b4a2b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تستمر في عمر الثالثة معظم مشكلات النوم التي ظهرت في عمر السنتين. أولًا، حافظي على هدوئكِ، فمن الطبيعي أن تمر هذه المرحلة على هذا النحو. إذا ترسخت لدى طفلكِ عادة سلوكية معينة ولم تقدّمي له رد الفعل الذي يتوقعه منكِ، فقد يتصرف بعصبية شديدة إلى حد هز سريره. وقد تجعله لحظات العناد والغضب التي يمر بها خلال النهار يعتقد أنه يستطيع أيضًا دفعكِ إلى المجيء إليه ليلًا من خلال بعض التصرفات. عليكِ الالتزام بنظام النوم الحالي بإصرار، لأن تنازلًا بسيطًا قد يؤدي إلى مشكلات طويلة الأمد. تذكّري أن هذه المرحلة ستمر، ولن يتبقى بعدها سوى العادات التي تكوّنت بسبب الحلول المؤقتة.') WHERE id = 'fe1c6163-4318-4862-9f0a-f62b00223bae';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نعلم أن الأمومة والأبوة، رغم كونهما من أجمل المشاعر في العالم، فهما أيضًا من أصعب المسؤوليات. وقد تجدين صعوبة في تخصيص وقت لنفسكِ وسط هذا الجدول المزدحم الذي يتمحور حول طفلكِ. لكن عليكِ خلال هذه الفترة أن تخفّضي توقعاتكِ قليلًا. لا شك في أن نظافة المنزل وترتيبه ومواعيد الطعام أمور مهمة، لكن توقّع أن يكون كل شيء مثاليًا قد يرهقكِ. ولكي تتمكني من بناء تواصل صحي مع طفلكِ، من المهم أيضًا أن تحافظي على صحتكِ النفسية وأن تحصلي على الراحة. خصصي لنفسكِ وحدكِ ما لا يقل عن 15-20 دقيقة يوميًا: اشربي فنجانًا من القهوة، أو اقرئي كتابًا، أو شاهدي مسلسلكِ المفضل. واهتمي بنظام نومكِ وتغذيتكِ كي تحافظي على نشاطكِ. وبين كل هذه المسؤوليات، لا تنسي قضاء بعض الوقت على انفراد مع زوجكِ؛ فوجود طفل لا يمنع الرومانسية. :) إذا نظّمتِ وقتكِ جيدًا، فستتمكنين من إنجاز مهامكِ وقضاء وقت ممتع ومفيد مع طفلكِ. بل إن الاستيقاظ قبل طفلكِ بقليل لممارسة التمارين الصباحية سيمنحكِ الطاقة طوال اليوم.') WHERE id = 'a3ea6a55-367b-4c42-b618-204464ef44c8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ الذي بلغ 3 سنوات لا يزال يستخدم اللهاية، فالسبب في ذلك هو التعلق العاطفي أكثر من كونه حاجة فسيولوجية. وإذا لم تكوني قد قيّدتِ استخدامها من قبل، فقد يكون البدء بذلك الآن مفيدًا لنمو طفلكِ. تحدثي معه عن أن الأشياء قد تتلف أو تنكسر، وعندما تكونين مستعدة، ودّعا اللهاية. يمكنكِ أن تريه إياها وتقولي: «انظر، لقد تلفت»، ثم تتخلصا منها معًا. وإذا كنتِ متأكدة من رغبتكِ في فطامه عن اللهاية، فمن المهم أن تكوني حازمة وثابتة في تصرفكِ، لأن شراء لهاية جديدة وسليمة سيُذهب كل جهودكِ سدى.') WHERE id = '1383cfac-f84c-4a93-9c73-fb954fdd82ec';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يساعد الرسم على تنمية المهارات الحركية الدقيقة لطفلكِ وتطوره الذهني، كما يعزز ذكاءه ويكشف عن سماته الشخصية. ولأهمية الرسم الكبيرة، يتمثل دوركِ في توفير المواد اللازمة وتشجيعه عليه. ارسمي معه أحيانًا، لكن لا توجّهيه بشأن حجم الرسم أو ألوانه؛ بل دعيه يختار الألوان والأشكال كما يشاء. ويمكنكِ التعرّف على بعض الجوانب المتعلقة بطفلكِ من خلال تأمل رسوماته. فالرسم وسيلة بسيطة وفعالة للغاية للتعبير عن مشاعره وأفكاره تجاه الأحداث. لكن يجب أن نتوخى الحذر عند تفسير الرسومات؛ إذ قد يقودنا استنتاج رأي اعتمادًا على رسم واحد فقط إلى نتائج خاطئة. لذا ينبغي أيضًا الاطلاع على رسوماته الأخرى وإجراء تقييم شامل.') WHERE id = '6817d7d9-546c-4b8b-b293-3dd551564824';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يصبح طفلكِ في هذه المرحلة أكثر فضولًا. فكلما كبر، ازداد انتباهه لما يدور حوله وتوسعت قدراته الذهنية. ومن الطبيعي أن يصاحب ذلك ظهور مشكلات جديدة في النوم. وبالنسبة إلى الطفل، يصبح أي شخص موجود بجانبه رفيقًا للعب. وقد يستيقظ كثيرًا ليلًا راغبًا في اللعب. في هذه المواقف، عليكِ التزام الهدوء قدر الإمكان ومساعدته على العودة إلى النوم. ويمكنكِ لفت انتباهه بكلمات مهدئة مثل: ''''لنشرب قليلًا من الماء، ثم يحين وقت النوم مجددًا!''''. قد يصر على اللعب، لكن يُنصح بأن تظلي حازمة وألّا تبالغي في رد فعلكِ. وعلى الرغم من أنهم يخطون خطوات نحو الاستقلال، فإنهم لا يزالون بحاجة إلى دفء الوالدين. ويمكنكِ البقاء إلى جانبه حتى يستغرق في نوم عميق.') WHERE id = 'becdf37d-0cd9-4b46-9598-0594b4ab6139';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمر طفلكِ بمرحلة مهمة لتنمية مشاعر إيجابية تجاه الطعام واكتساب عادات مفيدة. وفي الواقع، تختلف تفضيلات الأطفال من طعام إلى آخر. فإذا كان طفلكِ يرفض الحليب، يمكنكِ تقديم الجبن أو الزبادي له. لا يمكنكِ سوى إرشاده وتقديم القدوة له، لكن لا يمكنكِ إجباره على الأكل، ولا ينبغي لكِ فعل ذلك مطلقًا. ومن الأفضل أن تقدمي له حصة معتدلة وتنتظري حتى يطلب المزيد بنفسه، بدلًا من إعطائه كمية أكبر. وإذا بدأ باللعب بالطعام، فأوقفي الوجبة فورًا ولا تجبريه على تناول المزيد. ينبغي أن تعادل الحصص 1/3 حصة الشخص البالغ. ويُنصح أحيانًا باحتساب ملعقة طعام واحدة عن كل سنة من عمر الطفل. أي إن 3 ملاعق طعام من طبق الخضراوات تكفي لتكون حصة واحدة لطفل يبلغ 3 سنوات. لا تروي لطفلكِ قصصًا مثل: ''''إذا لم تُنهِ طعامك، فسيبكي وراءك''''. فقد يؤدي هذا السلوك مستقبلًا إلى نفوره من الطعام أو إصابته باضطرابات مختلفة في الأكل. ومن الطبيعي في هذا العمر أن تتغير الشهية من يوم إلى آخر. فقد يتناول في أحد الأيام طبقًا معينًا بشهية، ثم يبعد الطبق نفسه في يوم آخر. وقد يثير ذلك قلقكِ، لكنه أمر طبيعي جدًا بالنسبة إليه.') WHERE id = 'd46412db-4e12-4822-9e8b-098a3584e748';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إن قدرتكِ بصفتكِ أمًا على قول «لا» عند الضرورة تتيح لطفلكِ أن ينشأ شخصًا قوي الشخصية ومسؤولًا ومستقلًا وكفؤًا. فوضع حدود لرغباته تجربة مهمة في نموه النفسي والعاطفي، إذ عليه أن يتعلم التخلي عن السعادة اللحظية الناتجة عن تحقيق كل رغباته. وخلافًا لما قد تظنين، لا يعني وضع القيود إهانته. فالحدود المقبولة تمنح الطفل شعورًا بالأمان أكثر مما تجرح مشاعره. يشعر الأطفال الصغار بالراحة في بيئة تحكمها قواعد محددة؛ إذ يعرفون ما يمكنهم فعله وما لا يمكنهم فعله. وعلى عكس الاعتقاد الشائع، فإن قول «لا» للطفل يساعده على الشعور بالهدوء. إن تفهّم احتياجاته لا يعني السماح له بكل شيء. فتلبية احتياجاته ووضع حدود لرغباته الزائدة سيجعلانه يشعر بالأمان ويساعدانه على إدراك أن زمام الأمور بيدكِ.') WHERE id = '183350b0-b8e0-41a3-a744-161d68cbdfab';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'جمعنا لكِ، بصفتنا عائلة Anacan، طرقًا تساعدكِ على تقوية رابطة الحب اللامحدودة بينكِ وبين طفلكِ! أشعريه كثيرًا بحبكِ وتقديركِ له. وقدّمي له من حين إلى آخر هدايا خاصة به، حتى لو كانت بسيطة. حاولي دائمًا تخصيص وقت له. وكوني إلى جانبه حتمًا عندما يحتاج إلى صديق. اخرجي معه كثيرًا للتنزه وتبادلا الحديث. ونظّمي أنشطة اجتماعية تقومان بها معًا، مثل تناول الطعام أو الذهاب إلى السينما. حاولي اكتشاف صفاته الجميلة. واستمعي إلى حزنه وهمومه واجعليه يثق بكِ تمامًا. ضعَا معًا خططًا للمستقبل. وشاركيه أحلامكِ وأفكاركِ. وعندما تغضبين منه، حاولي التحدث إليه على الفور. وفضّلي التواصل معه بدلًا من وضع افتراضات بشأن أفعاله. حاولي فهم مخاوفه. ولا تنسي أن بينكما العديد من القواسم المشتركة، وذكّري نفسكِ كثيرًا بصفاته الجميلة. وأضيفي شيئًا جديدًا إلى ما تفعلينه من أجله. وعندما يبدو أن كل شيء قد انتهى، امنحيه فرصة أخرى. ولا تنسي أن هذا الإنسان الصغير هو أعظم حظوظكِ وأكثر من يستحق الفرص. :)') WHERE id = 'ffcfd182-0a40-4ea9-b119-05b96294411a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُسمى الحركات والأصوات المتكررة واللاإرادية وغير الهادفة، التي يمكن كبحها، مثل الرمش وسحب المخاط إلى داخل الأنف وتنحنح الحلق، بالعُرّات. وتظهر العُرّات لدى نحو 12-14% من الأطفال بعد سن 3 سنوات. وإذا استمرت هذه السلوكيات لدى طفلكِ لأكثر من عام، فإنها تُسمى «اضطراب العُرّات المزمن». وعلى الرغم من أن معظم العُرّات التي تظهر لدى الأطفال تختفي قبل بلوغ سن الرشد، فقد تستمر لدى بعض الأشخاص. وقد تظهر العُرّات الصوتية على شكل تنحنح أو تكرار كلمات لا علاقة لها بالموضوع أو التلفظ بألفاظ نابية أو تكرار آخر كلمة سمعها الطفل. ويمكن أن يكون العلاج الداعم والعلاج الدوائي مفيدين في معالجة العُرّات. وإذا كان الطفل لا يقوم بهذه الحركات خارج المنزل ولا يُظهرها إلا في مواقف محددة، فينبغي البحث عن أسباب ذلك. وعند تحديد اللحظات التي يزداد فيها التوتر أو يُمنح الطفل اهتمامًا مفرطًا، يمكن أن يساعد خفض التوتر وتوجيه الانتباه نحو الجوانب الإيجابية لدى الطفل على زوال العُرّات. وإذا كانت العُرّات تتكرر كثيرًا وتزعج الطفل وتؤثر سلبًا في حياته الاجتماعية وثقته بنفسه، فيُنصح حتمًا باستشارة اختصاصي في علم نفس الأطفال.') WHERE id = '7bdd3648-4898-435d-a965-c2cd8be626eb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ليس من السهل إطلاقًا اختيار كتاب يجذب اهتمام طفلكِ وسط هذا العدد الكبير من الألعاب والدمى والأجهزة التكنولوجية المختلفة. احرصي على الذهاب معه إلى متجر الكتب ومراعاة رغباته عند الاختيار. ومن المهم أن تمنحيه فرصة لتصفّح الكتب وأن تتحلّي بالصبر. كما أن الاطلاع على الأعمال السابقة لمؤلف الكتاب ورسّامه قد يسهّل عملية الاختيار. ويُعد اختيار كتب صادرة عن دار نشر معروفة وموثوقة مؤشرًا على الجودة أيضًا. ففي بعض الأحيان، قد تخدعنا الكتب ذات التصميم الجميل والمحتوى الضعيف، لذا احرصي على قراءة الكتاب الذي ستشترينه لطفلكِ بنفسكِ. واختاري، إن أمكن، قصصًا تنمّي خياله وتشجعه على التفكير خارج القوالب المألوفة، فهذا سيوسّع نظرته إلى الحياة.') WHERE id = '3e7d3756-d758-4054-a8c8-f70c190c258f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'الطفل الذي تُلبّى رغباته فورًا من قِبل والديه خلال أول 3 سنوات من حياته يتوقع استمرار المعاملة نفسها بعد بلوغه سن 3 سنوات. وإضافة إلى ذلك، تزداد مطالبه في هذه المرحلة مع تنامي رغبته في الاستكشاف. وقد يؤدي ذلك أحيانًا إلى الإلحاح أو العناد، ما يضع الوالدين في موقف صعب. وقد تشعرين بالعجز في مواقف مثل إصراره على الخروج أو طلب لعبة أو رفض العودة إلى المنزل من الحديقة. في هذه اللحظات، يساعد حفاظكِ على هدوئكِ وتمسّككِ بقراركِ وثباتكِ في تطبيق القواعد التي وضعتِها على وضع حد لإصراره. تذكّري أن هناك حدودًا محددة في الحضانة أو المدرسة، وأن غرس هذا الانضباط في طفلكِ منذ سن مبكرة سيساعده مستقبلًا على التكيّف بسهولة أكبر مع البيئة الاجتماعية.') WHERE id = '1b1ff393-2fdb-41cd-a991-599397850f2d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبحتِ الآن على دراية وثيقة بمفهوم انتكاسات النوم. وتحدث إحدى هذه الانتكاسات تحديدًا في سن 3 سنوات، وعادةً ما تؤثر في القيلولة النهارية. خلال هذه المرحلة، قد يقاوم طفلكِ النوم نهارًا. وإذا لم تعرفي سبب ذلك وسمحتِ له بالتوقف عن القيلولة ظنًا منكِ أنه كبر ولم يعد بحاجة إليها، فقد يستيقظ ليلًا مجددًا أو ينهض في وقت مبكر جدًا صباحًا. وقد يكون ذلك مرهقًا لكليكما. الأفضل هو مواصلة القيلولة النهارية من دون الدخول في صراع معه. هيّئيه للنوم باتباع روتين النوم المعتاد، واستخدمي نبرة صوتكِ الهادئة التي تمنحه الشعور بالراحة والأمان.') WHERE id = 'eb19294a-5739-489b-8455-a0a66e7a9841';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ سيُرزق قريبًا بأخ أو أخت، فقد يحتاج إلى بعض الوقت للاعتياد على العضو الجديد في الأسرة. وخلال هذه الفترة، يحظى دعمكِ وأسلوب تعاملكِ بأهمية كبيرة. حاولي تخصيص وقت منفرد لكل واحد من طفليكِ على حدة. وإذا كنتِ أمًا عاملة، فيمكنكِ التخطيط لهذا الوقت الخاص خلال عطلة نهاية الأسبوع. وتحدّثي إلى طفلكِ طوال الأسبوع عما ستفعلانه معًا في عطلة نهاية الأسبوع. واحرصي على أن يكون هذا الوقت ممتعًا وشيقًا بالنسبة إليه. وإذا حاولتِ ألّا تغيّري نظام حياتكم المعتاد كثيرًا، فستجدين أن هذه العملية ليست مخيفة. تذكّري أن الأطفال يتكيّفون بسهولة مع كل وضع جديد ما دام روتينهم المعتاد لم يضطرب!') WHERE id = '858e7ca4-064a-4b59-9756-36e46e0dc68c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحتاج طفلكِ في كل مرحلة عمرية إلى قواعد وحدود واضحة. فوجود القواعد يساهم في بناء شخصيته ويجعله أكثر استعدادًا للتعامل مع العالم الخارجي، لأن هناك قواعد ينبغي الالتزام بها في الحضانة والمدرسة والمجتمع. وإذا غرس الوالدان هذا النظام والانضباط في طفلهما منذ سن مبكرة، فسيشعر مستقبلًا براحة أكبر في البيئات الاجتماعية التي سينضم إليها. ورغم أن طفلكِ يمضي في طريقه ليصبح فردًا مستقلًا، فإنه لم يبلغ بعد درجة النضج التي تمكّنه من وضع هذه الحدود بنفسه. لذلك يحتاج، حتى يُكمل المرحلة الأولى من تطور شخصيته، إلى والدين يضعان قواعد تجعل حياته آمنة. وعند وضع القواعد، اشرحي له ما ينبغي فعله بدلًا مما لا ينبغي فعله. فاستخدام لغة إيجابية يزيد رغبة الطفل في الالتزام بالقواعد ويعزز دافعيته لذلك.') WHERE id = 'ef1e4f9c-d6b8-4c31-9d2d-07f2d52f6112';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تواجهين مخاوف لدى طفلكِ أثناء تدريبه على استخدام المرحاض. وقد يكون سببها الإمساك أو وجود شق شرجي. إذ قد تظهر لدى الطفل المصاب بالإمساك تمزقات صغيرة عند فتحة الشرج، ما يجعل عملية التبرز مؤلمة. وفي هذه الحالة، قد يخاف من المرحاض ويفضّل الجلوس في إحدى زوايا المنزل. ويدفعه الألم إلى تجنّب المرحاض، ما قد يضعكِ في موقف صعب. في البداية، ينبغي أن يفحصه جرّاح أطفال وأن يُعالج الشق الشرجي. وأحيانًا قد يرفض الطفل حتى وضع الكريم بسبب الألم. كما أن الكريمات لا تكون فعالة تمامًا ما دام الإمساك مستمرًا. لذلك ينبغي تعديل نظامه الغذائي وإعطاء الأولوية للأطعمة الغنية بالألياف. وفي بعض الحالات، يمكن استخدام أدوية بناءً على توصية الطبيب لتليين البراز المتصلب. وبهذه الطريقة، يصبح التبرز أسهل ويتمكن طفلكِ من قضاء حاجته من دون ألم.') WHERE id = '23629747-d0b5-4bad-bc11-d6aac9adb32d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عليكِ الابتعاد عن سوء التفاهم والخلافات التي قد تنشأ بين أطفالكِ. فإذا تدخلتِ في شجار بين أخوين أو أختين، فقد تدخلين في حلقة مفرغة تتيح للأطفال التلاعب بكِ. وما دمتِ تتدخلين، فلن يتمكنوا من تعلّم حل مشكلاتهم بأنفسهم. عندما يحاولون إقحامكِ في الخلاف، قولي: «لا أعرف من المحق ومن المخطئ. عليكما حل الأمر بنفسيكما»، ثم غادري الغرفة. وعندما يزول احتمال انحيازكِ إلى أحد الطرفين، ستلاحظين أن أطفالكِ يتشاجرون بدرجة أقل. على سبيل المثال، إذا كان الأطفال يلوم بعضهم بعضًا بسبب إزعاجهم لبعضهم على الأريكة، يمكنكِ أن تقولي لهم: «إذا لم تتوصلوا إلى اتفاق فيما بينكم، فسأطلب منكم الجلوس على الأرض». والأهم هنا هو أن تنفّذي ما قلتِه حتمًا إذا استمر الخلاف. وبهذه الطريقة، يمكنكِ الاطمئنان إلى أن مثل هذه المشكلات ستتكرر بدرجة أقل.') WHERE id = '0d352037-233f-42ba-92ba-3db41252a829';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا يُتوقع منكِ بصفتكِ أمًا أن تتصرفي دائمًا بصورة مثالية. فقد تكافئين أحيانًا، من دون أن تنتبهي، بعض تصرفات طفلكِ غير المرغوب فيها. إذا حصل طفلكِ على ما يريده من خلال سلوك سلبي، مثل البكاء، فسوف يستخدم الأسلوب نفسه لتحقيق رغباته الأخرى. ونتيجة لذلك، يتحول السلوك السلبي لديه إلى وسيلة لحل المشكلات. إذا قلتِ «لا!» لأحد طلبات طفلكِ، فيجب أن تظل الإجابة «لا». فإذا تحولت «لا» إلى «نعم» بعد تصرف سلبي، فسيصبح ترسيخ الانضباط أمرًا بالغ الصعوبة. هناك مفهومان أساسيان في أسلوب التربية الذي يضع الحدود ويوفر الدعم في الوقت نفسه، وهما: «الثبات» و«الحزم». وإذا حافظتِ على ثباتكِ الشخصي وحرصتِ على اتفاق الوالدين، فستزول من ذهن طفلكِ الحيرة المتعلقة بالقواعد، وسيدرك أن محاولة خرقها لن تجدي نفعًا.') WHERE id = 'bf70b99a-29f1-488c-9612-ac08830fbf92';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'للأسف، قد يكون استخدام الكلمات البذيئة إحدى وسائل الطفل للتعبير عن نفسه في عمر 3-4 سنوات. وربما يكون قد سمع هذه الكلمات من أحد أصدقائه في الروضة أو من شخص بالغ. وفي هذه المرحلة، تُعد طريقة تفاعلكِ أنتِ والبالغين المحيطين به مع هذه الكلمات بالغة الأهمية. ففي بعض الأحيان، تتم مكافأة الطفل الصغير على استخدام الشتائم من دون قصد. ولعلكِ رأيتِ بالغين يتعمدون إغضاب الطفل حتى يشتم، ثم يضحكون على ذلك. إن اعتبار هذا السلوك مضحكًا لدى الأطفال الذين بدؤوا بالكلام يؤدي إلى ترسيخه لديهم. وهنا يتلقى الطفل رسالتين متناقضتين: فالوالدان يقولان إن ذلك خطأ، بينما يضحك الآخرون ويمنحونه الاهتمام. ولمساعدة طفلكِ على التخلص من هذه العادة، عليكِ أن توضحي له أن التحدث بهذه الطريقة غير مقبول وأن له عواقب سلبية. وإذا سمعكِ تنطقين بإحدى هذه الكلمات، فلا تتصرفي وكأن شيئًا لم يحدث؛ بل أخبريه أنكِ أخطأتِ وأنكِ ستكونين أكثر انتباهًا في المرة المقبلة. والأهم من ذلك، كوني أفضل قدوة له باستخدامكِ لغة مهذبة وسليمة.') WHERE id = '0d10243e-f09e-41ec-b5d1-7ff0c1cfee87';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بعد حليب الأم، يُعد حليب البقر أهم مشروب ينبغي أن يكون ضمن غذاء طفلكِ. فالحليب يدعم النمو والتطور، ويؤدي دورًا مهمًا في تكوين الخلايا والأنسجة. كما أنه مفيد لنمو الدماغ ووظائفه، ويسهم في تقوية جهاز المناعة ليعمل درعًا واقيًا من العدوى. إذا لم يحب طفلكِ مذاق الحليب، فيمكنكِ إضافة القليل من العسل أو دبس الفاكهة إليه. لكن عند إضافة السكر أو المربى أو العسل، عليكِ إيلاء صحة أسنانه اهتمامًا خاصًا. وبالطبع، كما هو الحال مع كل شيء، فإن كمية الحليب مهمة أيضًا. فقد يؤدي شرب أكثر من نصف لتر من الحليب يوميًا إلى فقر الدم الناتج عن نقص الحديد وتسوس الأسنان. وتذكّري أن الطفل الذي يحصل على سعراته الحرارية من الحليب وحده سيواجه صعوبة في تناول الطعام، ما قد يؤدي إلى نمط غذائي غير منتظم.') WHERE id = '3925d3e4-1fd4-4eeb-b94d-9ed380f4e11a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المهم مكافأة نجاحات طفلكِ وتصرفاته الإيجابية من أجل مساعدته على اكتساب السلوكيات المرغوبة. فكما أن تطبيق أسلوب التقويم بطريقة صحيحة مهم لمنع الأخطاء، فإن المكافأة لا تقل أهمية عنه. يمكنكِ استخدام المكافأة لتعليم مهارة جديدة أو تشجيع تكرار سلوك إيجابي. وأحيانًا قد لا تكفي كلمة «أحسنت». فإلى جانب الثناء اللفظي، قد تكون هدية صغيرة أو لعبة حافزًا جيدًا. على سبيل المثال، إذا اعتاد طفلكِ إلقاء ملابسه على الأرض كل يوم، لكنه علّقها هذه المرة في الخزانة، فإن الإشادة به ستساعد على ترسيخ هذا السلوك. لكن انتبهي: إذا أصبح يتوقع حتمًا هدية مادية مقابل كل تصرف إيجابي بسيط، فهذا يدل على استخدام هذه الطريقة بصورة خاطئة. حاولي ألّا تبالغي في تقديم المكافآت.') WHERE id = 'fb6387ae-879e-47b4-a25b-35adc6b4b2b4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مثلما يتعلم طفلكِ السلوكيات الإيجابية، فقد يكتسب أحيانًا، بتوجيه منكِ، سلوكيات سلبية أيضًا. فإذا كنتِ تواجهين مشكلة مع طفلكِ، فهذا يعني أنكِ جزء من هذه المشكلة. وإذا كنتِ جزءًا من المشكلة، فعليكِ أن تكوني أيضًا جزءًا من الحل. لا تنسي أن الوصول إلى الحل يتطلب منكِ تغيير بعض سلوكياتكِ أيضًا. فإذا كنتِ تتحملين جميع مسؤوليات طفلكِ، وتستسلمين لنوبات بكائه وتشعرين بالذنب أمامها، فهذا يعني أنه هو من يتحكم بكِ. وفي هذه الحالة، يصبح حل المشكلة قائمًا فقط على الخضوع للطفل، وهذا خطأ. فهو حينها لا يكون خاضعًا لتوجيهكِ، بل يكون هو من يوجّه تصرفاتكِ. لذلك عليكِ التخلي عن الأساليب الخاطئة واستعادة سلطتكِ التربوية. وتذكّري أن الطفل يشبه السائل؛ إذ يتخذ شكل الوعاء الذي يوضع فيه. وبحسب التربية التي تقدمونها له بوصفكم أسرة Anacan، ستتكون شخصيته.') WHERE id = '9e8a4ff2-cd35-4ca1-9f39-9f919100e6ad';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نأمل ألا يمرض طفلكِ أبدًا، لكن عندما يضطر إلى تناول الدواء، قد تصبح هذه العملية صعبة أحيانًا. إذا كان طفلكِ يقاوم تناول الدواء، فتأكدي من أن يكون واقفًا أو جالسًا بزاوية 45 درجة لتجنب خطر الاختناق. وإذا كان الدواء على شكل شراب، فمن الأفضل إعطاؤه من جانب الفم لا من منتصفه مباشرةً؛ فهذا يساعد على منع منعكس القيء. وإذا كان مذاقه غير مستساغ، فيمكنكِ، بعد الحصول على موافقة الطبيب، مزجه بأطعمة مثل الزبادي أو هريس التفاح. والأهم: لا تقدّمي الدواء أبدًا على أنه "حلوى". وإلا فقد يتعامل معه طفلكِ كالحلوى، ويعرّض نفسه للخطر مستقبلًا بتناول أي دواء يجده. لا تساومي طفلكِ على تناول الدواء ولا تعديه بالهدايا. كوني هادئة وحازمة في الوقت نفسه. وبعد أن يتناول طفلكِ الدواء، لا تنسي أن توضحي له أنه ضروري لشفائه وأن تعانقيه.') WHERE id = '55d3bb75-920b-4c3a-8d5b-7ddf833df53a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يكتسب غرس القيم أهمية كبيرة في نمو الطفل. فقد يشعر الشخص الذي ينشأ في بيئة لا تراعي المشاعر والقيم بالاغتراب عن نفسه وعن محيطه. وبينما ندعم أطفالنا بوصفهم أفرادًا مستقلين، من المهم أيضًا أن نربيهم ليكونوا أفرادًا نافعين في المجتمع. وينبغي غرس مفاهيم مثل حب الأسرة والوطن والطبيعة في هذه الأعمار. كما يزداد نقل ثقافتنا إلى الأجيال الجديدة أهميةً في عالم يتجه نحو العولمة. علينا ألا نربي أطفالنا على السعي لتحقيق رغباتهم الشخصية فحسب، بل على التحلي بروح التضحية من أجل الآخرين ووطنهم أيضًا. وبهذا نُنشئ أفرادًا أسوياء ومسؤولين ومخلصين لأسرهم ووطنهم.') WHERE id = 'b8eaeb42-36d7-426e-80e3-9cd2fa5cbf1f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'جمعنا لكِ بعض الأنشطة المفيدة لتنمية المهارات الحركية الكبرى. إن رفع طفلكِ أشياء لا تكون ثقيلة عليه وقلبها رأسًا على عقب يساعد على تنمية مهاراته الحركية الدقيقة والكبرى معًا. ويمكنكِ استخدام سلة أو حقيبة فارغة في المنزل لهذا الغرض. ويُعد القفز والوثب في مكان آمن نشاطًا بسيطًا وفعالًا لتقوية مجموعات العضلات الكبيرة. كما تُعد محاولة الإمساك بالكرة المقذوفة في الهواء أو بعد ارتدادها على الأرض من الألعاب المفضلة لدى الأطفال. وتمارين الجمباز التي تهدف إلى تقوية الجسم مفيدة جدًا أيضًا. بالإضافة إلى ذلك، يسهم الرقص والحركة على أنغام الموسيقى إسهامًا كبيرًا في التطور الحركي، لأنهما يشغّلان العديد من العضلات في الوقت نفسه.') WHERE id = '30775c18-64d4-4693-b2c7-9c9cdadc0f91';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُلاحظ اضطرابات النطق لدى نحو 15 طفلًا من كل 100 طفل تتراوح أعمارهم بين 2-7 سنوات حول العالم. وتشمل هذه الاضطرابات تأخر الكلام، وصعوبة فهم اللغة والتعبير بها، وعدم القدرة على نطق الكلمات نطقًا صحيحًا، والتأتأة. إذا كان طفلكِ لا يُظهر المهارات المناسبة لفئته العمرية، أو بدأ يفقد بعض المهارات التي كان يتقنها سابقًا، فمن الضروري أن يخضع لتقييم اختصاصي ويتلقى العلاج المناسب. وينبغي أولًا عرضه على طبيب الأطفال، الذي سيحيله بعد ذلك إلى اختصاصي علاج اللغة والنطق. ولوقاية طفلكِ من تأخر الكلام، لا تضغطي عليه بإفراط، بل أتيحي له فرصًا للتحدث. وإذا نطق كلمة بصورة خاطئة، فلا تجبريه على نطقها بشكل صحيح؛ بل قوليها أنتِ بصورة صحيحة وكرريها أمامه. كلّفيه بمهام صغيرة في المنزل واطلبي منه أن يصف ما يفعله. واشرحي له أيضًا ما تقومين به من أعمال بصبر ومن دون ملل. اطرحي عليه أسئلة خلال اليوم، وقدّمي له توجيهات وراقبي كيفية تنفيذها.') WHERE id = '86814d97-2ff8-4803-bcd1-c851b5d32eea';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'جودة الرسومات لا تقل أهمية عن أسلوب كتابة الكتب. فالأطفال يتعلمون قراءة الصور قبل الكلمات. وقد لا يجذب الكتاب ذو النص الجيد اهتمام الطفل إذا لم تكن رسوماته وألوانه منسقة بذوق. والهدف الأساسي من الرسومات هو تجسيد المشاعر الواردة في النص بصريًا. لذلك قد تكون الصور أحيانًا زاهية ومتعددة الألوان، وأحيانًا تبرز فيها بضعة ألوان فقط، وقد تكون بالأبيض والأسود أحيانًا أخرى. وكلما كانت الرسومات غير مألوفة وغير متوقعة ومدهشة، زاد إسهامها في تنمية إبداع طفلكِ. كما تساعد الصور الغنية بالتفاصيل الطفل على قضاء وقت أطول مع الكتاب والاستمتاع به. فالكتاب أيضًا وسيلة للترفيه وقضاء وقت ممتع. وليس من الضروري أن يقدم درسًا أو يعلّم معلومات جديدة؛ إذ يمكنكِ ببساطة اختيار كتاب طريف وممتع.') WHERE id = 'a6226cc9-ed65-4d8e-a662-57c801fa7ba0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يشعر بعض الأطفال بسعادة كبيرة عندما يبدؤون النوم في أسرّتهم الخاصة. أما بعضهم الآخر، فلأنهم لم يتعلموا بعد قواعد النوم في سرير كبير، يهرعون فورًا إلى والديهم عندما يستيقظون ليلًا. في هذه المرحلة، عليكِ التحلي بالصبر والهدوء، وإعادة طفلكِ إلى غرفته في كل مرة يأتي فيها إليكِ. ويصبح ذلك ضروريًا، لا سيما إذا لم تكوني قد علّمته بعد أن ينام بمفرده. لم يفت الأوان أبدًا لتعليم الطفل النوم باستقلالية. فتكوين عادات جديدة سهل، أما التخلص من العادات القديمة فصعب. وخلال هذه العملية، يحتاج طفلكِ إلى الشعور بحبكِ وصبركِ. تذكري أن تعلم طفلكِ النوم بمفرده يُعد من أكبر الخطوات نحو اكتساب الاستقلالية.') WHERE id = '262dd2ae-9a65-4c86-9b3a-bbc65dc434ec';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عادةً ما يتعلم الأطفال الصغار بسرعة كيفية جذب انتباه الآخرين. عندما تكون أخته أو أخوه محور اهتمام الآخرين، قد تلاحظين أن طفلكِ الأكبر يعبس وينسحب بعيدًا. ومن علامات الغيرة الشائعة رغبته في الجلوس في حضنكِ، أو مص إصبعه، أو مراقبة الرضيع الذي يلعب مع الضيوف من بعيد. أحيانًا يبذل الوالدان جهدًا مفرطًا حتى لا يشعر الطفل الأكبر بالغيرة، مع أن تعلم العيش مع الإخوة من أهم الخبرات التي يمكن أن يكتسبها الطفل. ومن الأفضل خلال هذه العملية أن تمنحي طفلكِ بعض المسؤوليات البسيطة المتعلقة بالرضيع. يمكنكِ تكليفه بمهام تناسب عمره حتى يشعر بأنه فرد مهم في الأسرة، مثل إحضار حفاض الرضيع، أو محاولة تهدئته عندما يبكي، أو اختيار ملابسه.') WHERE id = '80a7c1dd-4961-4b33-84ca-c64f4c73a250';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ البدء في التخطيط للتعليم ما قبل المدرسي اعتبارًا من الشهر 36. في الواقع، يبدأ هذا التعليم معكِ، أي مع الوالدين، ويستمر بطرائق مختلفة حتى بدء مرحلة المدرسة. وله أهمية كبيرة في نمو الطفل العاطفي والجسدي والعقلي واللغوي والاجتماعي. يكتشف الأطفال الذين يتلقون تعليمًا قبل المدرسة مواهبهم في وقت أبكر، ويستثمرون إمكاناتهم الفكرية بفاعلية. كما يتمتعون بثقة أكبر بالنفس، وتتطور لديهم مهارات التواصل وحل المشكلات. ويتعلم هؤلاء الأطفال القراءة والكتابة بسهولة أكبر، وتكون مهاراتهم اليدوية وقدراتهم على التفكير الرياضي أقوى. كذلك يتعلمون تحمّل المسؤولية وقواعد السلوك داخل المجتمع. ويتكيف الأطفال المشاركون في هذا البرنامج بسرعة أكبر مع البيئة المدرسية، ويكتسبون مهارات أكثر مقارنة بأقرانهم.') WHERE id = '54c0ecba-c25f-45f2-a3fc-b7cb74d37bd3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُلاحظ مشكلة حبس البراز لدى الأطفال عادةً خلال مرحلة اكتساب عادات استخدام المرحاض. وبوجه عام، قد يتجنب الأطفال التبرز بعد خوض تجربة سلبية مرتبطة بالمرحاض. وبعد هذه التجربة، يظن الطفل أنه سيتألم عند التبرز، فيبدأ بحبس برازه. ولأن البراز المحتبس يصبح صلبًا، يشعر الطفل فعلًا بالألم عند التبرز. وهكذا يتحقق اعتقاده بأنه سيتألم، وتتحول الحالة إلى حلقة مفرغة. إذا كان طفلكِ يحبس برازه، فعليكِ أولًا استشارة الطبيب لمعرفة ما إذا كانت المشكلة ناتجة عن سبب طبي. وإذا كان السبب مرتبطًا بمشكلة صحية عضوية، فيجب الالتزام بالعلاج الذي يصفه الطبيب. أما إذا لم يُكتشف سبب طبي، فقد تكون المشكلة نفسية. وفي هذه الحالة، ينبغي استشارة اختصاصي تربوي. وبعد تقييم الاختصاصي، سيتضح السبب الذي يدفع الطفل إلى هذا السلوك.') WHERE id = '8159262e-ffbf-45aa-b3d8-6b1cf6b66ec6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من أفضل الأنشطة التي يمكنكِ ممارستها في المنزل مع طفلكِ لتنمية إبداعه صنع مجسمات من المواد المستهلكة. ومن خلال كل نشاط، يمكنكِ دعم جانب مختلف من جوانب نموه. وبما أن طفلكِ يبلغ من العمر 3 سنوات، فقد يصعب عليه قليلًا تنفيذ أعمال كثيرة التفاصيل. لكن صنع منظار من لفافات ورق المرحاض الفارغة مفيد جدًا لتنمية الإبداع وتعليمه إعادة استخدام الأشياء الموجودة في المنزل. ويمكنكِ رسم أشكال مختلفة على أغطية الزجاجات ولعب لعبة مطابقة هذه الأشكال مع الأشكال المماثلة المرسومة على قطعة من الورق المقوى. ومن الأفكار الجميلة أيضًا قص العبوات البلاستيكية المستعملة وصنع أصيص زرع من أجزائها السفلية. عندما يفرّغ طفلكِ طاقته بطرائق مناسبة، سيكون أكثر هدوءًا، والطفل الهادئ سيتعبكِ بدرجة أقل.') WHERE id = '00df44e2-a34f-41b7-a04c-dd03d72172ba';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تعود بعض السلوكيات التي نظن أن الأطفال قد تجاوزوها، ولا سيما في أوقات التوتر والصعوبات. وتُعد هذه الحالة آلية دفاع يستخدمها الطفل لمواجهة ما يمر به من صعوبات واستعادة توازنه، وتُعرف بالنكوص السلوكي. ومن أمثلتها مص الإصبع، أو البدء مجددًا في قضم طرف البطانية، أو التبول في الملابس بعد أن كان قد توقف عنه، أو الإصرار على شيء سبق أن رفضتِه، أو طلب المزيد من العناق وعدم الرغبة في الابتعاد عن الأم، أو البكاء عند مغادرة أحد الوالدين المنزل لفترة قصيرة. عندما تلاحظين لدى طفلكِ مثل هذه السلوكيات الطفولية التي توقف عنها منذ مدة طويلة، حاولي اكتشاف ما تغيّر في حياته خلال تلك الفترة وما الصعوبة التي يواجهها. وفي الفترات المليئة بالتوتر، ينبغي أن تتجنبي الضغط عليه لتطوير مهاراته الاجتماعية أو الذهنية. ولا تجبري طفلكِ خلال هذه المرحلة على تغيير سلوكه.') WHERE id = 'aa61a2f7-ee9b-4a44-967d-63c67ddbd907';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تظهر التأتأة نتيجة عوامل مختلفة مسببة للتوتر، أو الشعور بالقلق، أو سلوك الوالدين المفرط في التحكم، أو صعوبة التكيف مع مراحل حياتية جديدة، مثل ولادة أخ أو أخت أو بدء الذهاب إلى الروضة. عندما يبدأ طفلكِ بالتأتأة، من المهم أن تتعاملي معه كما لو كان يتحدث بصورة طبيعية. فإذا لفتِّ الانتباه إلى ذلك أو حذرتِه منه، سيزداد توتره، ما قد يؤدي إلى تفاقم اضطراب الكلام. وقد تسبب التأتأة تراجع ثقة الطفل بنفسه، وعدم رغبته في المشاركة في الأوساط الاجتماعية، والرهاب الاجتماعي، واضطراب علاقاته مع أقرانه. وقد تزيد أيضًا مخاطر الانطواء وصعوبة التعبير عن النفس والاكتئاب المزمن. لذلك ينبغي اللجوء إلى العلاج النفسي للتعامل مع المشكلات النفسية المصاحبة، وإلى العلاج الدوائي عند الحاجة وتحت إشراف الطبيب. وفي حالات التأتأة المستمرة، ينبغي استشارة اختصاصي دون تأخير التدخل.') WHERE id = 'a1d31857-19e2-46b7-89a5-32c5b29007f8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مجموعة الأنشطة الرياضية التي يمكن لطفل في عمر 3 سنوات ممارستها لا حصر لها. ومن المهم جدًا تشجيع طفلكِ على الحركة منذ اللحظة التي يتعلم فيها المشي. لا ينبغي لأي شيء أن يحرمه من التجارب الغنية والإيجابية، مثل ركوب الدراجة والتأرجح على الأرجوحة والرقص والجري والقفز وغيرها من الأنشطة. في البداية، يمكن لطفلكِ أن يبدأ بمهام سهلة، ثم ينتقل إلى أنشطة أخرى تزداد تعقيدًا بما يناسب عمره. ومن خلال التوجيه الصحيح، عليكِ إثارة اهتمامه بالرياضة وتهنئته وتشجيعه على كل خطوة ينجح في إنجازها. لا فرق بين الجنسين في الرياضة؛ إذ يمكن للفتيان والفتيات ممارسة أي نوع من الرياضة يحبونه. يكفي أن تكوني، كما في كل الأمور، أكبر داعمة له وأقرب رفيقة رياضية إليه! :)') WHERE id = '324a0d0f-be16-4a29-b137-05c9b12b0bd4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يكون الأطفال في هذه المرحلة قليلي الصبر للغاية تجاه بعض المواقف. ومع ذلك، من المهم أن تضعي الأسس التي تعلّمه ضرورة احترام حرية الآخرين ومساحتهم الشخصية. على سبيل المثال، إذا كان طفلكِ يقاطعكِ في أثناء حديثكِ عبر الهاتف، فاسأليه: «هل يمكنني التحدث عبر الهاتف والتحدث معك في الوقت نفسه؟». واطلبي منه أن يفكر في نشاط آخر يمكنه القيام به ريثما تنتهين. سيكون اختياره نشاطًا بنفسه أكثر فاعلية من توجيهكِ له. ولأنه ابتكر الفكرة بنفسه، سينشغل بأمر آخر من دون تذمر، وسيشعر بالفخر لأنه نجح في ذلك. وبعد انتهاء مكالمتكِ الهاتفية، قد تساعده مناقشة الموقف معه على فهم العلاقة بين السبب والنتيجة.') WHERE id = '09869f69-7272-4d96-aa75-31392acb999e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يكون النمو الجسدي ومؤشرا الطول والوزن لدى الأطفال الذين يأخذون قيلولة نهارية أكثر توازنًا مقارنةً بمن لا ينامون نهارًا. فالراحة التي يمنحها النوم تدعم النمو الجسدي مباشرةً. ويُفرَز هرمون النمو، الذي يؤثر في النمو الجسدي، بأعلى مستوياته في أثناء النوم. كما يؤدي هذا الهرمون دورًا مهمًا في تقوية جهاز المناعة، ويدعم النمو العام أيضًا. إضافة إلى ذلك، تؤثر القيلولة النهارية إيجابيًا في صحة بشرة طفلكِ وشعره. ويكون الأطفال الذين يأخذون هذه القيلولة أكثر استقرارًا من الناحية العاطفية. أما الأطفال الذين لا يحصلون على قسط كافٍ من النوم، فقد يتصرفون بعدوانية ونفاد صبر وتوتر أكبر لأنهم يضطرون إلى قضاء يومهم كله اعتمادًا فقط على ما تبقى لديهم من طاقة بعد نوم الليل. إذا لاحظتِ مثل هذه السلوكيات لدى طفلكِ، فقد يكون من المفيد أن تكوني أكثر إصرارًا قليلًا على أخذه قيلولة نهارية.') WHERE id = '85403f52-12f9-4926-af7b-017401144d0c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ، من حيث النمو، قادرًا على أداء مهارات مثل ارتداء ملابسه وتناول طعامه بنفسه. إذا منعتِه باستمرار من إظهار هذه المهارات، فسيتباطأ اكتشافه لذاته وسيصعب عليه التعامل مع المشكلات التي سيواجهها مستقبلًا. كما أن تولّيكِ المهام التي يستطيع إنجازها بنفسه قد يضر بثقته بذاته. ولكي ينشأ طفلكِ واثقًا بنفسه ويتمتع بشخصية سليمة، عليكِ أن تكوني له قدوة تمنحه الثقة وتتسم بالتفهم والمحبة والدعم. شجعيه عندما يحاول القيام بشيء مستقلًا كي لا يفقد حماسه. وإذا لم تنجح محاولته، فلا تكتفي بالإشارة إلى الخطأ، بل اشرحي له السلوك الصحيح بجمل بسيطة وواضحة. ثم كوني قدوة له من خلال تصرفاتكِ.') WHERE id = '37e94cc3-ecd4-4506-8ef5-c80545c83e3c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الطبيعي في هذه الأعمار أن تظهر المواقف المسببة للتوتر على هيئة «خوف». ويتجلى أوضح مثال على ذلك في ردود أفعال الأطفال الذين يتعلمون النوم بمفردهم. فهذه الحالة التي تُسمى «الخوف من النوم بمفرده» هي في الواقع استجابة للقلق تجاه الغموض والبقاء وحيدًا والانفراد بأفكاره. إذا كانت هذه المخاوف تؤثر بشدة في نظام نومه، وتزيد اعتماده عليكِ، وتجعله غير قادر إطلاقًا على النوم بمفرده، فهذا يعني أن الأمر قد تجاوز نطاق النمو الطبيعي. وفي مثل هذه الحالات، قد لا يستطيع الطفل دخول الغرف المظلمة أو الذهاب إلى المرحاض بمفرده داخل المنزل، وقد يصر على وجودكِ بجانبه عند النوم ليلًا. إذا هدّأتِ هذا الخوف باتباع نهج صحيح، فستزول هذه الحالة المؤقتة. تذكري أن المتخصصين يعدّون المخاوف الليلية إحدى سمات مرحلة النمو في عمر 3-4 سنوات. لذلك، فإن تحلّيكِ بالصبر والانتباه في التعامل مع هذه المسألة مهم جدًا لشعور طفلكِ بالراحة مستقبلًا.') WHERE id = '88513928-5145-4980-b11d-073c88b324b2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يستمتع كل طفل كثيرًا بلعب الغميضة في المنزل. تساعد لعبة الغميضة طفلكِ على إدراك البيئة المحيطة، التي يتعرف إليها في البداية بصريًا، من خلال الأصوات لاحقًا. ويؤدي تنشيط حاستي البصر والسمع في الوقت نفسه إلى دعم نموه الذهني. كما يعزز هذا الدعم قدرته على حل المشكلات. ولجعل اللعبة أكثر تشويقًا، يمكنكِ تعليمه العد من خلال التدرب على العد من 1 إلى 10. إضافة إلى ذلك، يتعلم طفلكِ التفكير الاستراتيجي عندما يحاول اختيار أفضل مكان للاختباء أو للعثور على الآخرين. كما أن محاولته العثور على أصغر مكان يمكنه الدخول إليه تساعده على تكوين مفهوم الحجم. وعندما يلعب مع الآخرين، تتطور مهاراته الاجتماعية ويتعلم حل الخلافات التي تنشأ داخل المجموعة والعمل الجماعي. وعلى الرغم من أن شوارعنا لم تعد ملائمة جدًا لمثل هذه الألعاب، فاحرصي على تخصيص وقت للعب الغميضة مع طفلكِ في المنزل أو في أماكن آمنة. فهذه فرصة رائعة لقضاء وقت ممتع وتنمية ذكائه في آن واحد.') WHERE id = 'cc099b73-26fe-4c21-b4cd-01d64a7234d8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'سن الثالثة هي المرحلة التي يكون فيها طفلكِ أكثر استعدادًا لاكتساب النظام، والتعامل مع الأشياء الصغيرة، وتعلّم الموسيقى وقواعد السلوك المهذب، والنمو العاطفي، والكتابة. في هذه المرحلة، من المهم جدًا أن توفّري لطفلكِ بيئة منظّمة، وتضعي له روتينًا ثابتًا وتحافظي عليه. فقد تجعل البيئة غير المنظّمة طفلكِ عدوانيًا وقلقًا، كما قد تؤدي إلى صعوبة في تعليمه الانضباط مستقبلًا. يراقب الأطفال محيطهم باهتمام، ولا سيما فيما يتعلق بالنظام، ويقتدون بوالديهم. فعلى سبيل المثال، عندما ترتّبين سريركِ بعد الاستيقاظ صباحًا وتكرّرين ذلك كل يوم، فإنكِ تساعدين طفلكِ على اكتساب هذه العادة وترسيخها في شخصيته. تذكّري أن الوالدين يؤديان دور المرآة في هذا الأمر. فطفلكِ، الذي يقلّدكِ عن قرب منذ ولادته، يراقبكِ باستمرار ويواصل اتخاذكِ قدوة له.') WHERE id = '50aa2c4b-e671-4b4f-aad4-4dd92b130a76';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عندما يُظهر طفلكِ اهتمامًا بالأعضاء التناسلية للآخرين، عليكِ أن توضحي له أن هذه المناطق خاصة، وأن مثل هذه التصرفات قد تزعج الشخص الآخر. وبالمثل، يجب أن توضحي له أنه من الخطأ أن يلمس الآخرون مناطقه الخاصة، وأنه ينبغي احترام الحدود الشخصية لكل إنسان. إن تزويد الطفل بمعلومات تفوق حاجته في بعض الموضوعات، أو تعرّضه لمشاهد لا تناسب عمره، قد يؤدي إلى استثارة جنسية مبكرة جدًا، وهذا يضر بنموه الجنسي السليم. ومن ناحية أخرى، إذا لم يتلقَّ التوجيه المناسب، فقد يشعر بالاضطراب بسبب المعلومات الخاطئة وغير الضرورية التي يسمعها من محيطه. إذا تحوّل فضول الطفل خلال نموه إلى سلوكيات لا تناسب عمره أو كانت مفرطة أو غير معتادة، فقد يكون ذلك مؤشرًا إلى وجود بعض المشكلات. في مثل هذه الحالات، ينبغي أن تنتبهي وتستشيري طبيبًا نفسيًا للأطفال.') WHERE id = '0c747f57-cfe1-4910-b650-61db053cff4c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يعيش الأطفال عادةً في اللحظة الراهنة ويريدون كل شيء فورًا، ولذلك يصعب عليهم استيعاب مفهوم الزمن. فقد يعدّون الدقائق والساعات حتى موعد الغداء، أو يشعرون أن انتظار اليوم الذي سيذهبون فيه إلى منزل جدهم يستغرق سنوات. ولأن مفاهيم مثل الساعة والتقويم لم تترسخ لديهم بعد، فقد يشعرون بالارتباك أحيانًا. كما تظل مفاهيم الأمس واليوم والغد، وما قبل وما بعد، غير واضحة لهم. في سن الثالثة، يمكنكِ البدء بتعليم طفلكِ مفهوم الزمن من خلال أسئلة بسيطة. على سبيل المثال: هل نستيقظ من النوم صباحًا أم مساءً؟ هل نتناول العشاء نهارًا أم مساءً؟ ماذا نفعل بعد الاستيقاظ من النوم (تنظيف الأسنان، وتمشيط الشعر، وما إلى ذلك)؟ سيساعد البرنامج اليومي المتّبع في الحضانة والمنزل طفلكِ على تعلّم أحداث اليوم وتسلسلها، وهذه هي الخطوة الأولى لفهم الزمن.') WHERE id = 'c4b8636a-f4ef-44d3-bff7-6c32928c991a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تتحكم المهارات الحركية الدقيقة في عمل العضلات الصغيرة في أيدينا وأصابعنا وفي حركاتنا. وعندما تكون هذه المهارات متطورة جيدًا، يصبح التواصل بين الدماغ وعضلات الأصابع سريعًا ومتناسقًا ودقيقًا. في هذه المرحلة، يستخدم الأطفال أيديهم وأصابعهم بتناسق أكبر بفضل نمو العضلات الصغيرة. ويساعد هذا التطور أيضًا على اكتساب مهارات العناية بالنفس. ولتنمية مهارات اليدين، يمكنكِ ممارسة الأنشطة الآتية مع طفلكِ: اقتطاع قطع بحجم حبة العدس من عجينة متماسكة وتشكيلها بحركات دائرية باستخدام أصابعه، وعجن العجين، وخلط مزيج الكعك، وتدليك أطراف الأصابع وراحة اليد، والتدرّب على رسم الخطوط. كما تُعد أعمال مثل مسح الطاولة أو النافذة، ونفض الوسائد، ونشر الملابس، وإغلاق الأزرار، وفتح السحّاب وإغلاقه مفيدة جدًا.') WHERE id = '335aa3a6-8982-4b3b-8657-cff57634d64f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ قراءة كتاب قصصي مع طفلكِ، ثم تطلبين منه أن يروي القصة أو يمثّل أحداثها. سيساعد هذا النشاط على تقوية ذاكرته، كما سيعينه على التعبير عن نفسه بلغة الجسد. ويمكنكِ دعم نموه الذهني من خلال تقليد أصحاب المهن المختلفة والحيوانات. وبهذه الطريقة، سيتعرّف طفلكِ إلى المهن المختلفة وتنمو قدراته الإبداعية. حاولي ألّا تقرئي القصة بسرعة كبيرة، وتحدّثا عن الصور الموجودة في كل صفحة؛ فهذا سيسهّل عليه تصوّر الأحداث في ذهنه. وقبل الانتقال إلى الصفحة التالية، اطرحي عليه سؤال: ما الذي تعتقد أنه سيحدث الآن؟ فهذا ينمّي خياله ومهاراته في حل المشكلات. كما أن طرح أسئلة عن القصة بعد قراءتها يؤثر إيجابيًا في تطوره اللغوي. وعند الإجابة عن هذه الأسئلة، يمكنه تلخيص الأحداث بحسب تسلسلها. تذكّري أن هذه العملية يجب ألّا تبدو كاختبار، بل كمحادثة لطيفة ولعبة ممتعة.') WHERE id = '13286d03-198d-41c2-868f-bb2189853f6c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لدعم النمو الجنسي لطفلكِ بصورة سليمة، عليكِ الحفاظ على حدود جسدية مناسبة في تعاملكِ معه. فالتوضيحات المتعلقة بخصوصية الجسد، إلى جانب التصرفات المتوافقة معها، تؤدي دورًا كبيرًا في نمو الطفل. وينبغي أيضًا تعزيز مفهوم الخصوصية من خلال السلوكيات المتّبعة في المنزل، حتى تتكوّن لدى الطفل أسس صحية وسليمة. تذكّري أن اقتراب الوالدين من الطفل بالقوة ومن دون موافقته، بحجة احتضانه أو تقبيله أو تحميمه، قد يضر بردود فعله الفطرية لحماية نفسه. وعليكِ أن تكوني قدوة له من خلال الحفاظ على خصوصيتكِ أيضًا. ومن المهم جدًا أن تشجّعي طفلكِ دائمًا على إخباركِ أو إخبار شخص بالغ يثق به عن أي موقف يسبب له الانزعاج.') WHERE id = 'b9ae5f1d-2e17-426f-a059-b6bf710090cb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ استثمار الوقت الذي تقضينه مع طفلكِ بفاعلية لدعم نموه المعرفي. فعندما تغنيان معًا في المنزل أو السيارة، فإنكِ تنمّين ذاكرته وثروته اللغوية من دون أن تدركي ذلك. وعلى الرغم من أن الاستماع إلى الأغنية نفسها مرارًا وتكرارًا قد يشعركِ بالملل كشخص بالغ، فإن تذكُّر مدى فائدة هذا النشاط لطفلكِ سيجعله ممتعًا لكِ أيضًا. يطرح الأطفال الأسئلة كثيرًا، لكن من المهم جدًا أن تطرحي عليه أنتِ أيضًا بعض الأسئلة. فعلى سبيل المثال، يمكنكِ تنمية مهاراته في حل المشكلات من خلال طرح أسئلة مثل: “لماذا ينبغي أن نتشارك ألعابنا؟” أو “متى ينبغي أن نغسل أيدينا؟”. ويساعده ذلك أيضًا على بناء ارتباط أقوى بالبيئة المحيطة به. ممارسة الألعاب نفسها طوال الوقت ليست كافية للنمو؛ فالتنويع في الألعاب يساعد طفلكِ على اكتساب مهارات جديدة. وإذا كان يحب اللعب بمكعبات الليغو والمكعبات الأخرى، فحاولي تعريفه تدريجيًا بالشطرنج أو الداما أو أنواع الرياضة المختلفة.') WHERE id = '5b22f9e5-ec4f-401b-afdd-84ef1eae30bc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'استمعي دائمًا إلى أفكار طفلكِ باحترام. فحتى عندما يكون مخطئًا، يظل من حقه أن يُستمع إليه. ينبغي للطفل أن يتعرف إلى مشاعره وأفكاره وأن يشعر بأنه يستطيع التعبير عنها في بيئة تمنحه الحرية. فالطفل القادر على التعبير عن نفسه براحة يتمتع بثقة أكبر بنفسه. دعيه يبذل جهده لحل مشكلاته بنفسه؛ وعندما يواجه صعوبة، لا تقدمي له الحل الجاهز فورًا، بل اكتفي بإرشاده حتى يتمكن من إيجاد الحل بنفسه. وحتى عندما يصدر منه سلوك خاطئ، ابدئي حديثكِ معه بذكر جوانبه الإيجابية. وأشعريه بأن حبكِ له لن ينقص أبدًا بسبب هذا التصرف. وبعد الحديث عن جوانبه الإيجابية، اشرحي أسباب خطأ هذا السلوك واتخذا معًا قرارًا بشأن كيفية معالجته. ويجب تطبيق كل قاعدة توضع وكل قرار يُتخذ بثبات وحزم. فهذا الاستمرار من جانبكِ يساعد طفلكِ على اكتساب عادات سلوكية سليمة.') WHERE id = '1928ee94-c579-4855-a4af-294726cb979c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'خلافًا للاعتقاد الشائع، لا يقتصر قلق الانفصال على أطفال الأمهات العاملات. فعندما يُشرح الأمر للأطفال بطريقة مناسبة، يفهمون ويتقبلون أن أمهاتهم مضطرات إلى الذهاب إلى العمل وأنهن سيعدن مساءً. يشعر كل طفل عند انفصاله عن أمه بقدر من القلق والتوجس بشأن ما إذا كانت ستعود أم لا. لكن هذا القلق يكون أشد لدى الأطفال شديدي التعلق بأمهاتهم. كما يواجه هؤلاء الأطفال صعوبة في الذهاب إلى الروضة والتكيف معها. تذكّري أن الروضة ليست مجرد مكان لرعاية الطفل أو اللعب؛ بل هي بيئة مهمة يتعلم فيها الطفل التنشئة الاجتماعية، واتباع القواعد، والتواصل مع أقرانه، والمشاركة. ويساعد الذهاب إلى الروضة، خصوصًا الأطفال الذين يعتمدون اعتمادًا كبيرًا على أمهاتهم، على تخفيف هذا التعلق وتعزيز استقلاليتهم.') WHERE id = 'fabedbe0-aa31-4f39-8c1a-cb32f87df3dd';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي ألا تتجاوز قيلولة طفلكِ ساعتين، وأن تكون في منتصف النهار. فعلى سبيل المثال، لا يُعد نومه الساعة 16:00 واستيقاظه الساعة 18:00 قيلولة. بل إن ذلك يخل بروتينه اليومي ويؤثر سلبًا في نومه ليلًا. وإذا كان طفلكِ يرفض أخذ قيلولة، فعليكِ مراجعة نظام نومه العام. فمن الطبيعي ألا يرغب الطفل الذي يستيقظ نحو الساعة 10:00-11:00 صباحًا في النوم ظهرًا، ولن يشعر بالتعب إلا في وقت متأخر من بعد الظهر. وإذا حددتِ موعد استيقاظه صباحًا عند الساعة 08:00 كحد أقصى، فسيكون من الأسهل عليكِ تنظيم مواعيد قيلولته.') WHERE id = '0e62f6f1-8f3e-4c79-a883-84f4ae40a292';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لن يفيد أن تقولي لطفلكِ إنه يجب أن يتعلم الصبر؛ فقد يكون قليل الصبر لدرجة تمنعه من الإصغاء إلى هذا الشرح. وعندما نخبره بأنه سيحصل لاحقًا على شيء يريده أو سيتمكن من القيام بأمر ما بعد قليل، فقد يبدو له الانتظار بلا نهاية، لأنه لا يستطيع التفكير فيما سيفعله خلاله. في مثل هذه الحالات، يمكنكِ أن تلعبي مع طفلكِ لعبة «ماذا يمكنك أن تفعل أثناء الانتظار؟». ويمكنكما إعداد «قائمة بالأشياء التي يمكن فعلها أثناء الانتظار» معًا. وهكذا تتيحين له فرصة التفكير في الأنشطة التي يمكنه القيام بها خلال وقت الفراغ هذا.') WHERE id = 'fef40a30-3535-4ac3-985e-fd9d1e77c9d0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي الانتباه إلى احتمال ارتباط عادة قضم الأظافر لدى الطفل بالشعور بعدم الثقة بالنفس. ويُلاحظ هذا السلوك كثيرًا لدى الأطفال الذين ينشؤون تحت ضغط مفرط ويعانون ضعف الثقة بالنفس. كذلك قد يعبّر الطفل الذي يتعرض للانتقاد باستمرار أو ينشأ في بيئة تفتقر إلى الاهتمام والمحبة عن توتره بقضم أظافره. وأفضل ما يمكنكِ فعله تجاه هذه العادة هو تجاهل السلوك. ففي بعض الأحيان، لا يدرك الأطفال حتى أنهم يقضمون أظافرهم، وغالبًا ما يفعلون ذلك بصورة لا إرادية. عندها يمكنكِ تنبيه طفلكِ بلطف عن طريق لمس ذراعه. ولمساعدته على التخلص من هذه العادة، يمكنكِ توفير نشاط جديد يشغل يديه. فمثلًا، يمكنكِ إعطاؤه كرة أو غرضًا آخر ينشغل به. عادةً ما يكون قضم الأظافر لدى الأطفال عادة غير ضارة، ومن غير المرجح أن يكون علامة على مشكلة خطيرة. وفي معظم الأحيان، يتوقف الأطفال عن قضم أظافرهم مع تقدمهم في العمر.') WHERE id = '06e56282-be2c-4e69-8498-3f1907cf8587';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك العديد من الأنشطة التي يمكنكِ القيام بها في المنزل لدعم النمو الذهني لطفلكِ. يمكنكِ ابتكار ألعاب تسلسل خاصة بكِ باستخدام الأدوات المنزلية. اصنعي تسلسلًا بسيطًا باستخدام المعكرونة وماصّات الشراب. مرّري في خيط قطعة معكرونة على شكل خرزة أولًا، ثم قطعة صغيرة قصصتِها من الماصّة. واطلبي من طفلكِ ترتيب القطع وفق التسلسل نفسه. ارسمي عدة وجوه بشرية على ورقة، واتركي في كل رسمة جزءًا واحدًا أو أكثر من الوجه، مثل الأذن أو الأنف أو العين أو الحاجب، من دون رسم. اطلبي من طفلكِ أولًا تحديد الجزء الناقص، ثم إكماله بالرسم. ويمكنكِ تنفيذ هذا النشاط باستخدام أشياء أخرى غير الوجوه البشرية. كما يمكنكِ استخدام الجوارب في نشاط المطابقة، واطلبي منه العثور على الجورب المطابق لكل جورب. ويمكنكما استكشاف الجوارب وفق ألوانها وأحجامها وملمسها. ولتنمية مهارات اليد أيضًا، يمكنكِ أن تطلبي منه تعليق هذه الجوارب بمشابك الغسيل على حبل أعددتِه.') WHERE id = '6332b5c8-aa0a-4fe6-a24b-a78fc7ce3a48';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لتشجيع طفلكِ على الكلام، يمكنكِ طرح أسئلة عليه عن الأشياء المحيطة به. تحدّثي معه عن ماهية الأشياء وأسمائها، واطرحي عليه أيضًا أسئلة عن اختلافاتها أو خصائصها. ناقشي معه ما يشعر به عند لمس الأشياء، والأصوات التي تصدرها، والروائح التي تفوح منها. وتحدّثي معه بطريقة تساعده على تعلّم شكل الأشياء، وما تشبهه، وكيف تتحرك (بسرعة أو ببطء)، ومكانها (قريبة، بعيدة، في الأعلى، في الأسفل، في الأمام أو في الخلف)، وتوقيت الأحداث (أمس، اليوم، قبل، بعد، الآن، بعد قليل، غدًا). يمكنكِ ممارسة ألعاب الأسماء مع طفلكِ في أي مكان. ابدئي بالإشارة إلى أي غرض في المنزل، واسأليه: «هل هذه ثلاجة أم فرن؟». ثم لاحظي عدد الأشياء التي يستطيع طفلكِ الإشارة إليها وتسميتها من تلقاء نفسه.') WHERE id = '0d10d8ac-5d5b-45d2-b64b-483a0f66e680';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الأمور التي ينبغي مراعاتها عند اختيار روضة الأطفال: أن يعمل فيها متخصصون وأشخاص مؤهلون، وأن تكون البيئة المادية ملائمة لتلبية احتياجات الطفل، وأن توفر بيئة تعليمية إبداعية وداعمة. وينبغي أيضًا الانتباه إلى توافر أنشطة اجتماعية كافية، مثل الفنون والرياضة، وملاءمة عدد الأطفال في الصف وفئتهم العمرية. قبل إرسال طفلكِ إلى الروضة التي اخترتِها، اصطحبيه إليها وعرّفيه بالمكان واستمعي إلى رأيه. حاولي ألّا يوصله إلى الروضة الوالد الذي يُبدي طفلكِ رد فعل أشد عند الانفصال عنه. اشرحي له أهمية الذهاب إلى الروضة من دون ممارسة الضغط عليه. وإذا رفض الذهاب إليها، فينبغي البحث عن السبب. وعندما يعرض عليكِ مهارة تعلّمها في الروضة، مثل رسمة رسمها أو أغنية تعلّمها، شجّعيه وعبّري عن تقديركِ له.') WHERE id = '0c6b2ddb-615f-4d3a-9351-189e0dbb2930';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يبدأ الأطفال بتعلّم سلوك الضرب عن طريق التقليد. ويستخدمونه في البداية أثناء اللعب، ثم ينقلونه إلى الحياة الواقعية ويبدؤون بممارسته مع أصدقائهم أو إخوتهم، ولا سيما الأصغر سنًا والأضعف منهم. وقد يؤدي ذلك إلى ظهور مشكلات سلوكية؛ فقد لا ينسجم الطفل مع إخوته، وإذا كان يذهب إلى المدرسة فقد يُوصم بأنه مثير للمشكلات أو غير منضبط. كما أن وصف الآخرين له باستمرار بأنه عدواني قد يؤدي إلى زيادة هذه التصرفات وإيذاء مشاعره. تعاملي مع طفلكِ بهدوء في هذا الشأن، لأن إهانته أو الحطّ من شأنه قد يدفعانه إلى العناد معكِ والتصرف بعدوانية أكبر. نبّهيه بلطف عندما يضرب، وتحدّثي معه بصفتكِ والدته. اشرحي له أن ما يفعله غير صحيح، وأن الضرب سلوك خاطئ.') WHERE id = 'f92ad59e-71af-4c04-aa9e-3f7e501b8900';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُسمّى النوع المتخصص من العلاج الذي يهدف إلى مساعدة الأطفال على التعبير عن أنفسهم واحتياجاتهم من خلال اللعب والألعاب بـ«العلاج باللعب». يهدف العلاج باللعب إلى تمكين الأطفال من إظهار مهاراتهم المعرفية والاجتماعية ومشاعرهم وأفكارهم من خلال اللعب. ويدخل المعالج باللعب، برفقة الطفل، إلى عالم اللعب الذي أنشأه ويتحدث بلغته الخاصة في اللعب. وفي نهاية العملية العلاجية، يكون الهدف مساعدة الأطفال على تجاوز الضيق النفسي الذي يعانون منه وتحقيق نمو صحي. وللعلاج باللعب أهمية علاجية لأنه يمنح الطفل فرصة لإعادة تمثيل تجاربه ومشاعره. وخلال هذه العملية، يكون مسار العلاج أهم من النتيجة. يتحرر الطفل أثناء العلاج من القيود، ويتمكن من استئناف نموه من النقطة التي توقف عندها. ولا تساعده هذه العملية على التعامل مع المشاعر الصعبة وحل المشكلات فحسب، بل تعلّمه أيضًا احترام ذاته، وتحمل المسؤولية، والإبداع، والتعاطف مع الآخرين.') WHERE id = '1de275d3-8cd8-4618-9f11-fcae232765bb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد الرسم أسهل وسيلة تعبير لطفلكِ الذي لا يستطيع التعبير عن نفسه بسبب محدودية حصيلته اللغوية. فهو يكشف عن عالمه الداخلي من خلال رسوماته. ولكل من ترتيب رسم الأشياء والأشخاص وأشكالها، والألوان المستخدمة، والخربشات دلالة خاصة. فعلى سبيل المثال، يرسم الأطفال الذين يعانون من ضعف الثقة بالنفس الأشخاص بحجم صغير جدًا مقارنة بحجم الورقة، ويستخدمون ألوانًا قليلة. وقد يشير عدم رسم اليدين والقدمين في الأشكال البشرية إلى انعدام الثقة بالنفس، وصعوبة التكيف مع البيئة المحيطة، وضعف التواصل. أما الأطفال مفرطو النشاط، فيميلون إلى رسم صور أكثر عشوائية ومتعددة الألوان. ونظرًا إلى شعورهم بالتوتر، فإنهم يفضلون عادةً الخربشة، وغالبًا ما يتركون رسوماتهم غير مكتملة، كما تكون الأشكال التي يرسمونها كبيرة جدًا. تذكّري أنه ينبغي لكِ إجراء هذا التقييم بناءً على الصورة العامة لجميع رسومات طفلكِ، لا استنادًا إلى رسمة واحدة فقط.') WHERE id = 'b9f23d9c-fb50-40c7-963a-c98217635134';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إن التمسك بالقرارات المتخذة مسبقًا في أوقات الأزمات وعدم الاستسلام للغضب هو أفضل رسالة يمكنكِ تقديمها لطفلكِ. وعلى العكس، فإن الطفل الذي يشعر بأنه حقق هدفه بالصراخ يصبح أكثر عجزًا وقلقًا عند غياب الحدود. أولًا، يجب التمييز بوضوح بين المحظورات المطلقة (النوم مع الوالدين، وإيذاء الآخرين، وما إلى ذلك) والقواعد الخاصة بالأسرة (وقت مشاهدة التلفاز، ومواعيد الطعام). يجب ألا تتساهلي أبدًا في المحظورات العامة. ذكّري طفلكِ بهذه القواعد من حين إلى آخر، وليس فقط في أوقات الأزمات. وعند وضع قواعد الأسرة، اختاري قواعد تناسب عمر طفلكِ وشخصيته ويمكنكِ تطبيقها على المدى الطويل. إذا كانت لديكِ أي شكوك، فلا تترددي في استشارة مختص. فرغم أنكِ بصفتكِ أحد الوالدين صاحبة القرار، يمكن للمتخصصين تقديم آراء مختلفة وأكثر فاعلية بشأن احتياجات الطفل.') WHERE id = 'c6e50720-5633-44e1-ba45-31174c851d52';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'اعتبارًا من هذا الأسبوع، بلغ طفلكِ سن 3,5 سنوات. نأمل أن تقضيا معًا أوقاتًا ممتعة وشيقة في هذه المرحلة التي تُسمّى مرحلة اللعب. وعلى الرغم من أنكِ قد تواجهين من حين إلى آخر نوبات من العناد والغضب، فإن استكشاف العالم معًا وتعلّم ألعاب جديدة ومشاهدة طفلكِ وهو يكبر مشاعر لا تُقدّر بثمن. وبفضل تطور قدرته على التعاطف، سيصبح تواصلكما الآن أسهل قليلًا. تذكّري! أنتما، والديه، أكثر من يراقبهما عن قرب ويتخذهما قدوة له. طفلكِ هو مرآتكِ وصديقكِ الأقرب. وبصفتنا عائلة Anacan، نود أن نؤكد أن نشأته في أسرة سعيدة هي أعظم حظ له. :)') WHERE id = '335b0feb-7b33-40af-8e79-2b8268bc60c0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يبلغ متوسط وزن طفلكِ لهذا الشهر 15.500 غرام. ويبلغ هذا المتوسط نحو 15.100 غرام لدى البنات و15.900 غرام لدى الأولاد. أما متوسط طول الأطفال في عمر 42 شهرًا فيبلغ 100 سم (99.0 سم للبنات و100.5 سم للأولاد). تذكّري أن هذه الأرقام ليست سوى متوسطات إحصائية. وحتى إن اختلف طول طفلكِ ووزنه عن هذه الأرقام، فلا داعي للقلق ما داما ضمن النطاق الآمن الذي يحدده طبيبكِ. وفقًا لمخطط المئينات، يتراوح الوزن الطبيعي للأطفال في عمر 42 شهرًا بين 11.900 غرام و19.300 غرام للبنات، وبين 12.600 غرام و20.600 غرام للأولاد. أما الطول الطبيعي فيتراوح بين 91.1 سم و107.0 سم للبنات، وبين 92.8 سم و108.2 سم للأولاد.') WHERE id = 'e06b5f35-b325-4c43-83ca-c31b4ee75bab';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'رغم أن حليب الأبقار لا يضاهي حليب الأم ولا يمكن أن يحل محله، فإنه يتمتع بفوائد عديدة. تُظهر الدراسات أن تناول 3 حصص من الحليب ومنتجات الألبان يوميًا يساعد على تنظيم ارتفاع ضغط الدم لدى الأطفال. وتُعد هذه الأطعمة مصدرًا للكالسيوم والفوسفور والمغنيسيوم والبروتين، وهي عناصر ضرورية لنمو العظام بصورة صحية. إن الحصول على كمية كافية من الحليب في مرحلة الطفولة يقوّي العظام ويحمي من أمراض مثل هشاشة العظام في المستقبل. كما أن الكالسيوم والفوسفور الموجودين في الحليب مفيدان لنمو الأسنان بصورة صحية. ويغلف بروتين الكازين الموجود فيه مينا الأسنان المعرضة للأطعمة الحمضية بطبقة واقية، ما يمنع فقدان المعادن. ولكن كما هي الحال مع كل شيء، قد تكون زيادة الحليب ضارة أيضًا؛ والكمية اليومية الموصى بها لطفلكِ هي كوبان.') WHERE id = 'd3289862-36fe-45db-83f1-f05747c7d26c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في عمر 3,5 سنوات، ينبغي تعليم الأطفال مفهوم الزمن. فقياس الأشياء التي نراها ونشعر بها أسهل من قياس الزمن. يمكنكما القيام معًا بأنشطة ممتعة وتعليمية في آن واحد. على سبيل المثال، يمكنكِ قياس طول طفلكِ كل ستة أشهر ووضع علامة على الحائط، ثم التحدث معه عن مقدار نموه. أعطيه كيسَي تسوق مختلفين واسأليه أيهما أثقل. وتساعده كلمات مثل كبير وأكثر وثقيل على فهم وحدات القياس. وهذا يسهّل عليه إدراك الزمن، ويساعده أيضًا على تكوين أساس للتفكير الرياضي.') WHERE id = '15dd2f5c-24a1-4844-bb61-aee9bf14e9f7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أفضل مكافأة ليست مادية، بل عاطفية. يعتقد كثير من الآباء أن شراء الهدايا الباهظة للطفل هو أفضل أسلوب. لكن الطفل الذي يعتاد باستمرار على الأشياء المادية قد لا يرضى مستقبلًا حتى بأغلى هدية. إن مداعبتكِ له واحتضانكِ إياه وخروجكما معًا في نزهة وقولكِ كلمات لطيفة له هي أكثر أشكال المكافأة صحة. وإذا وعدتِ طفلكِ بشيء مادي، فاحرصي حتمًا على الوفاء بوعدكِ. لكن إذا أصبح طفلكِ يسألكِ بعد كل مهمة: «إذا فعلت هذا، فماذا ستشترين لي؟»، فهذه إشارة إلى أن المكافآت المادية تُقدَّم بوتيرة متكررة جدًا. ولتجنب مثل هذه المواقف، أعطي الأولوية للدعم العاطفي والتقدير.') WHERE id = '8fbaf939-e6e7-4b88-b1bc-9a2068498830';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ لا يزال يستخدم اللهاية، فيمكنكِ تجربة طريقة الأيام الـ3. في اليوم الأول، أخبريه بأنه سيتوقف عن استخدامها قريبًا. وفي اليوم الثاني، كرري الفكرة نفسها بإيجاز ووضوح، وأكدي له أن ذلك سيحدث غدًا. أما في اليوم الثالث، فاجمعا معًا جميع اللهايات الموجودة في المنزل، وقررا سويًا إلى أين ستذهب. وإذا كان التخلص منها نهائيًا أمرًا صعبًا، فيمكنكِ اختيار طرق مبتكرة، مثل تقديمها إلى جنية الهدايا أو خياطتها داخل دمية دب في المنزل. وأيًا كانت الطريقة التي تختارينها، فكوني حازمة. لا تتراجعي حتى لو بكى طفلكِ أو أصرّ على موقفه. تذكري أن هذه مجرد مرحلة انتقالية مؤقتة، وسرعان ما ستعود الأمور إلى طبيعتها.') WHERE id = '8d23e99d-ad33-4ab2-adc6-df69c3a74752';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يكتسب الطفل القيم بسهولة أكبر عندما يرى من حوله بالغين يتصرفون وفقًا لها. ففي الحياة اليومية، تؤدي علاقات طفلكِ بالأشخاص المحيطين به، وردود الفعل التي يتلقاها خلال هذه العلاقات، وملاحظته لسلوك البالغين دورًا مهمًا في تكوين قيمه. ومن الضروري أن يكتسب السمات المهمة لنموه الشخصي، مثل التحفيز وروح المبادرة والتفكير السليم والمثابرة والتعاطف والاجتهاد وحل المشكلات. كما لا تقل أهمية القيم اللازمة لحياة اجتماعية جيدة، مثل التعاون والمشاركة والتعاطف واحترام الاختلافات. ولغرس هذه المفاهيم في سن مبكرة من خلال أمثلة وتجارب ملموسة، ينبغي توفير بيئات تتيح لطفلكِ التعلم والاستمتاع. وتساعد زيارة كبار العائلة، ولا سيما في الأعياد، والمشاركة في تحضيرات العيد، وارتداء الملابس الجديدة، وحضور الفعاليات المرتبطة بالمناسبات الوطنية المهمة، الطفل على فهم معنى هذه الأيام مستقبلًا. ويسهم وجود مثل هذه التجارب في ذكريات الطفولة في بناء أساس متين لفهم القيم المعنوية في مراحل العمر اللاحقة.') WHERE id = '0956bcb5-c78d-49ee-bc25-8dc67ef8b2d5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي لطفلكِ البالغ من العمر 3,5 سنوات أن يكون قادرًا على الإجابة عن الأسئلة بالكلام أو بتعبيرات الوجه. كما ينبغي أن يتمكن من تكوين 1-2 جملة صحيحة، تتألف كل منها من كلمتين على الأقل، وفق ترتيب المبتدأ والخبر. ويجب أن يكون قادرًا على تنفيذ التعليمات المتتابعة، وأن يمتلك حصيلة لغوية تبلغ في المتوسط نحو 200 كلمة. ويُتوقع منه عند الإجابة عن الأسئلة ألا يكرر الكلمات نفسها. كما ينبغي أن يتمكن الأشخاص من خارج الأسرة من فهم كلامه. ويمكنه التحدث بسهولة والتعبير عما يزعجه، ومشاركة ما فعله في المنزل أو روضة الأطفال في بيئات مختلفة. كذلك يستطيع تكوين جمل من 3-4 كلمات، بل وحتى 5 كلمات، وطلب الأشياء التي يريدها بذكر أسمائها.') WHERE id = 'c4f2aeb3-8fc8-4e06-8bd0-e81a062fc9f1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'على الرغم من أن أسباب ظهور العرّات في مرحلة الطفولة غير معروفة تمامًا، يُعتقد أن العوامل الوراثية والبيئية تؤدي دورًا في ذلك. وعادةً ما تزداد أعراض العرّات بعد حدث يسبب التوتر. وقد تؤدي تنبيهات أفراد الأسرة والمحيطين بالطفل أو معاقبته إلى تفاقم العرّات. فعندما يشعر الطفل بقلق والديه، يحاول التحكم في سلوكياته، ما يزيد التوتر الداخلي لديه ويجعل العرّات أكثر وضوحًا. لذلك، يُعد دعم الأسرة وتعاونها أمرًا بالغ الأهمية للتغلب على العرّات. ولكي تُعد حركة ما عرّة، يجب أن تتكرر بانتظام. وإذا لم تكوني متأكدة مما إذا كان سلوك طفلكِ عرّة أم لا، فاستشيري مختصًا بالتأكيد. إذ قد يؤدي التعامل الخاطئ إلى إصابة الطفل باضطرابات نفسية أخرى.') WHERE id = '71e03cb4-9929-45ab-90e6-32d6fcbcb10e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نلاحظ أحيانًا أن الوالدين ينحازان إلى أحد الأبناء، أو يتجاهلان احتياجات الطفل الأكبر لأنهما ينسيان أنه لا يزال طفلًا أيضًا. وهذا لا يؤدي إلا إلى تأجيج الغيرة. فقد يتعرض الطفل الأكبر لصدمة عاطفية لاعتقاده أن أخاه أو أخته يحظى بحب أكبر. لذلك، ينبغي أن تتجنبي عبارات مثل: «أنت الأكبر وهو الأصغر، لذا دعيه يركب الأرجوحة أولًا». والأصح أن تقولي بدلًا من ذلك: «يمكنكما ركوب الأرجوحة بالتناوب. قررا معًا من سيركب أولًا». تؤدي مقارنة الأطفال بعضهم ببعض إلى نشوء مشاعر سلبية لدى الطفل تجاه الشخص الذي يُقارَن به. وإذا أردتِ تقديم نموذج لطفلكِ، فركزي على السلوك لا على الشخص. فبدلًا من مدح أخيه بقولكِ: «أخوك ذكي جدًا»، قولي: «كان هذا التصرف من أخيك ذكيًا جدًا»، كي يركز طفلكِ على السلوك الإيجابي نفسه لا على أخيه أو أخته.') WHERE id = '9cdb8679-29d3-41d6-8a56-4e13edf50ca7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ معرفة ما إذا كان طفلكِ مستعدًا للالتحاق بروضة الأطفال من خلال مراقبة سلوكه مع أقرانه. فإذا كان سعيدًا جدًا برفقة أصدقائه أو يتواصل بسهولة مع الأطفال الآخرين في الحديقة، فمن المرجح أن يتأقلم بسهولة مع الروضة أيضًا. ومن الطبيعي تمامًا أن تشعري بالتردد عند بدء التحاقه بالروضة؛ فقد ترين أنه لا يزال صغيرًا جدًا. تذكري أنه كلما كنتِ أكثر ارتياحًا وإيجابية تجاه هذا الأمر، شعر طفلكِ بسعادة أكبر في الروضة. ولكن إذا لاحظتِ تغيرات حادة في طباعه بعد التحاقه بها، فعليكِ إعادة النظر في هذا القرار. وإذا لاحظتِ مشكلات في عادات استخدام المرحاض، أو نفورًا من الروضة، أو اضطرابات في النوم والتغذية، أو سلوكًا عدوانيًا، أو تجنبًا للتواصل، فقد يكون من المفيد البحث عن بدائل للروضة.') WHERE id = '50845cb9-b6c0-473b-8a09-2a2127edc70b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تؤدي الأنشطة البدنية دورًا حيويًا في نمو الأطفال وتطورهم. ويُعد اكتساب عادة النشاط البدني عاملًا مهمًا للوقاية من السمنة الناتجة عن اختلال التوازن بين كمية الطاقة المتناولة والطاقة المستهلكة. كما أن تعريف الأطفال بالرياضة في سن مبكرة مفيد جدًا لتعزيز صحتهم الجسدية والاجتماعية والنفسية. وكما هي الحال مع كثير من العادات الجيدة، من المهم اكتساب عادة النشاط البدني في سن مبكرة للحفاظ على الصحة. وقد يزداد اهتمام طفلكِ بالرياضة إذا مارستِ أنتِ أيضًا أي نوع منها لتكوني قدوة له. حتى التنزه لفترة قصيرة مع طفلكِ في المساء سيكون مفيدًا. كما تساعده التمارين البسيطة التي تمارسانها في المنزل والأنشطة التي تتطلب حركة بدنية، مثل ألعاب سباق الحواجز، على تفريغ طاقته بطريقة سليمة.') WHERE id = '5e2458f1-3eab-45fb-b380-b8a0da43731a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد الاضطرابات السلوكية التي تظهر لدى الأطفال من أكثر الموضوعات التي يركز عليها اختصاصيو علم نفس الطفل. وللوقاية من الاضطرابات السلوكية لدى طفلكِ، عليكِ احترامه. ينبغي التعامل مع كل طفل بوصفه فردًا مستقلًا، وسؤاله عن آرائه وتقديرها. ولكي يثق طفلكِ بنفسه، عليكِ أولًا أن تثقي به. كما ينبغي أن تمدحي جهوده وتشجعيه. فالتشجيع مهم جدًا ليشعر الطفل بقيمته، ويعني ذلك تقبّله كما هو وتقديره لذاته. ولكي يشعر طفلكِ بالأمان، يجب قبل كل شيء أن يعرف أنه محبوب وأن يحب نفسه.') WHERE id = 'ac7650b2-a45a-497e-a58c-e5826e7ff20d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المهم جدًا في هذا العمر تحفيز دماغ طفلكِ من خلال الألعاب التي تنمّي الذكاء. فهذه الألعاب تطوّر جميع قدراته وتهيئه للمستقبل على نحو جيد. ومن أفضل ألعاب الذكاء لطفل يبلغ من العمر 3.5 سنوات الأحاجي وألعاب تركيب الصور المقطّعة (البازل). ويمكنكِ العثور على هذا النوع من الألعاب، الذي ينمّي العديد من مهارات الطفل، في مختلف متاجر كتب الأطفال. تساعد هذه الألعاب طفلكِ على تطوير مهارات حل المشكلات والمهارات الحركية. كما تعزّز ألعاب البازل التناسق بين اليد والعين وتنمّي التفكير المنطقي، وتغرس لديه أيضًا الشعور بالمسؤولية. وسيزيد إتمامه لمهمة بدأها من ثقته بنفسه.') WHERE id = '0956afc0-b1d3-4280-8218-1c13e9a87a81';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك علاقة وثيقة جدًا بين اللغة والتعلّم. يصل الطفل إلى الأشياء من خلال الحركة ويستكشفها، ثم يري ما في يده لمن حوله ويسأل: ما هذا؟ يستمع إلى وصفهم ويواصل التعلّم بمحاولة تكرار ما سمعه. ومن المهم جدًا أن تكون لدى الطفل رغبة في طرح الأسئلة وأن يحاول التكرار. وكلما تطورت لغته، ازدادت معارفه. وتُعد السنوات 3 الأولى أهم مرحلة لنمو الدماغ. لذلك، إذا لاحظتِ أي تأخر في تطور اللغة أو المهارات الاجتماعية أو الحركية، أو سلوكًا حركيًا لا يتناسب مع عمر طفلكِ، فمن الضروري استشارة مختص لإبداء رأيه وإجراء التدخل اللازم.') WHERE id = '79557be8-9f94-4d68-99d5-2e7df0b8035b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا تتعزز الرابطة العاطفية التي ينبغي بناؤها مع الوالدين بالمشاعر الإيجابية وحدها، بل إن طريقة تعاملكِ مع المشاعر السلبية وما تفعلينه لمساعدة طفلكِ على الشعور بالتحسن والهدوء مهمان أيضًا لتقوية هذه الرابطة. في الواقع، نحتاج إلى قدر معين من المشاعر السلبية من أجل البقاء. فعلى سبيل المثال، يمنع شعور الطفل بالخوف من خطر أن تصدمه سيارة من الركض إلى الطريق، وهذا أمر بالغ الأهمية لحياته. لذلك، من المهم جدًا أن يتعلم طفلكِ كيفية التعامل مع هذه المشاعر. وعندما يشعر بالخوف، بدلًا من التقليل من شأنه أو إخباره بأنه لا ينبغي أن يخاف، عليكِ تفهّم شعوره وتعليمه كيفية التعامل معه. وينطبق النهج نفسه على المشاعر السلبية الأخرى، مثل الغضب والضغينة والسخط.') WHERE id = '20cb9f1e-2f42-4ba7-8325-b99221decb3a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مثلما قد يؤدي نقص الفيتامينات إلى إصابة الأطفال بأمراض مختلفة، قد يظهر أيضًا نتيجةً لبعض الأمراض. ومن المهم تناول الفيتامينات بطريقة صحيحة وبجرعات مناسبة للحفاظ على الصحة الجسدية والنفسية. ويظهر نقص الفيتامينات، التي تؤثر في جميع أعضاء الجسم وأجهزته، من خلال أعراض مختلفة. فقد يشير التعب المستمر والتشوش الذهني واضطراب التناسق الحركي إلى نقص فيتامين B1. أما سهولة ظهور الكدمات على الجسم أو ظهور بقع حمراء مائلة إلى الزرقة على الجلد، فقد تدلان على نقص فيتامين C. وتشير مشكلات الشعر والأظافر إلى نقص فيتامين H (البيوتين أو B7). وقد ترتبط بعض الأمراض الجلدية واضطرابات الجهاز العصبي، ولا سيما تشقق الشفتين واللسان وحالات مثل الإكزيما، بنقص فيتامين B6.') WHERE id = '3bf0c30a-d169-4d8a-9012-062df97c971c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكن تحقيق نجاحات كبيرة في تنمية مهارات الأطفال الاجتماعية من خلال التربية الموسيقية التي تساعدهم على إدراك الخير والصواب والجمال. فعندما يشارك كل طفل في أنشطة موسيقية متنوعة وتمارين جماعية، فإنه يتقدم نحو هذا الهدف، وبذلك يصبح تكيّف طفلكِ مع المجتمع أسهل. كما أن استجابة طفلكِ للموسيقى بحركات جسده، ومحاولته ابتكار حركات راقصة تتناغم مع الإيقاع، ومرافقته الموسيقى بصوته ليتعرّف إلى صوته، كلها أمور تؤثر إيجابيًا في نموه المعرفي والحركي النفسي. ولعلكِ لاحظتِ أيضًا اهتمام طفلكِ بالموسيقى واستمتاعه وهدوءه عند الاستماع إليها. وإذا اكتشفتِ اهتمامه بآلة موسيقية معينة، فمن المفيد أن تدعميه في هذا المجال. لكن إجباره على ذلك إن لم يكن مهتمًا قد ينفّره من الموسيقى. ونظرًا إلى أهمية الموسيقى في النمو، فإن إبعاد الطفل عنها قد يؤدي إلى نتائج غير محمودة.') WHERE id = 'dcc3837e-160c-4928-9bc0-9ee1684dcb4e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، يحتاج طفلكِ إلى ثقتكِ به بينما يسعى إلى تجربة أمور كثيرة لإثبات ذاته وإظهار قدراته. وإذا واجه عوائق مستمرة من أحد الوالدين، فقد ينشأ لديه العناد. أما الأطفال الذين يُجبرون باستمرار على الطاعة، فقد تتشكل لديهم شخصية تتسم بالخجل والاعتماد على الآخرين والحاجة إلى الرقابة الخارجية. وإذا تعرّض الطفل أولًا لما يدفعه إلى الخجل، ثم وُضع تحت الضغط للتخلي عن هذا السلوك أيضًا، فقد تتضرر ثقته بنفسه. عليكِ أن تتفهمي كل سلوك وشعور يُظهره طفلكِ، وألا تدخلي معه في صراع عناد. اسمحي له بفعل ما يرغب فيه، وقدّمي له الدعم عندما يحتاج إلى المساعدة. وامدحيه على المهام التي ينجزها بنجاح، وعندما يخطئ، جدّدي ثقته بنفسه بإخباره أنكِ واثقة من أنه سيتمكن من أدائها بصورة أفضل في المرة المقبلة.') WHERE id = '342a5175-5532-4a44-96cd-06410ba982b9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد تطورت مهارات طفلكِ في الرسم كثيرًا. فلم تعد الجدران أو قطع الأثاث لوحاتٍ للرسم بالنسبة إليه، بل أصبح يستمتع برسم الخطوط على الورق. ومع تطور خياله، بات يستخدم ألوانًا ورموزًا متنوعة بكثرة في رسوماته. ولدعم هذه المهارة، يمكنكِ شراء أقلام تلوين مناسبة لعمره. كما ستزيد أنشطة مثل الرسم بالأصابع أو الألوان المائية أو التلوين بالخيوط من اهتمامه بالرسم. وستجعل الأوراق المقوّاة الملونة وأوراق الأشغال اليدوية والملصقات التي يلصقها على رسوماته هذه العملية أكثر متعة. وتجدر الإشارة إلى أن الخبراء لا ينصحون كثيرًا بكتب التلوين التي تحتوي على حدود محددة ورسومات جاهزة، لأنها قد تحدّ من عالم طفلكِ الخيالي.') WHERE id = '7bde6d12-0c46-4f21-b597-0ed9e192db06';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ، الذي يكبر يومًا بعد يوم، قادرًا على المشي وتناول الطعام وارتداء ملابسه وخلعها بصورة مستقلة. ومن الضروري أن تسمحي له بالقيام بهذه الأمور بنفسه. وإلا فقد يصبح معتمدًا على أمه، بل وقد يعجز عن أداء مهام يستطيع في الواقع القيام بها. فالتعلّق شعور صحي ينبع من المحبة بين الطفل وأمه، أما الاعتمادية فتنشأ عندما لا يسمح الوالدان للطفل بأداء مهامه رغم قدرته على ذلك. وإذا لبّى الآخرون كل احتياجات الطفل، فقد تؤثر هذه الاعتمادية سلبًا في حياته المستقبلية. وبالطبع، يجب حماية الطفل، لكن الإفراط في حمايته قد يزعزع ثقته بنفسه. لذلك من الضروري منح الأطفال قدرًا مناسبًا من الحرية كي يتعلموا إنجاز مهامهم بأنفسهم.') WHERE id = 'cae119a1-a7e9-4d3d-9076-641fdea9dd64';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لكي يكتسب طفلكِ عادات غذائية صحية، يجب أن يدرك أن موعد تناول الطعام قد حان وأنه يتناول وجبته. لا تفوّتي مواعيد الوجبات، واجلسي إلى المائدة مع طفلكِ، وكوني قدوة له بعدم الانتقائية في الطعام. أتيحي له فرصة تناول الطعام بنفسه، والالتزام بآداب المائدة، والمشاركة معكِ في إعدادها. واحرصي على خلو المكان من العوامل التي قد تشتت انتباهه أثناء تناول الطعام. وحتى لو كان يتناول أكثر الأطعمة صحية في العالم، فمن المهم أن يكون طفلكِ خلال الوجبات الخفيفة أيضًا في بيئة تمكّنه من التركيز على ما يأكله. تذكّري أن النشاط البدني يؤدي دورًا مهمًا في التغذية الصحية أيضًا؛ فالطفل الذي يفرّغ طاقته خلال اليوم تكون شهيته أفضل. وينطبق الأمر نفسه على الأطفال الذين يحصلون على قسط كافٍ من النوم.') WHERE id = '281b9ff9-cb00-4dc1-92db-2e3ae08fcf60';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عندما لا يتلقى الطفل تربية جنسية مناسبة، فقد يحاول اكتشاف الحقائق بنفسه، أو يحصل على المعلومات من أشخاص غير مناسبين، أو يلجأ إلى المشاهدة سرًا. وفي جميع هذه الحالات، يكون احتمال توصله إلى استنتاجات خاطئة مرتفعًا جدًا. لذلك لا ينبغي لكِ ترك هذا الموضوع للصدفة، بل عليكِ مناقشته ومنحه الاهتمام اللازم، أولًا داخل الأسرة ثم في المؤسسات التعليمية. وللتحدث عن هذه الموضوعات مع طفلكِ، عليكِ أولًا اختيار بيئة مناسبة. ففي الأماكن المزدحمة والصاخبة قد يتشتت انتباهه بسهولة، أو لا يسمعكِ، أو يتردد في طرح بعض الأسئلة لشعوره بالحرج ممن حوله. لا تُظهري دهشتكِ من أسئلته، بل أجيبي عنها بهدوء وبأسلوبكِ المعتاد في الحديث. وينبغي ألا تتخذ أحاديثكما طابع الوعظ أو التوبيخ، بل أن تكون حوارًا يوميًا صادقًا ووديًا.') WHERE id = '6aa6b9b6-16ae-485f-b93d-fa31a1491634';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ يميل إلى العنف، فقد تكون لذلك أسباب عدة. أولًا، يتعلم الأطفال معظم السلوكيات من خلال الملاحظة والاقتداء بالآخرين. فالطفل الذي يرى بالغين يمارسون العنف باستمرار من دون أن يتعرضوا للعقاب، أو يتعرض هو نفسه للعنف، قد يتصرف بعدوانية تجاه أقرانه الأضعف منه، بل وحتى تجاه الحيوانات. وعلى الوالدين اللذين لا يريدان أن يمارس طفلهما العنف أن يكونا قدوة حسنة له في المقام الأول. فإذا حللتِ مشكلاتكِ بالحوار بدلًا من الصراخ والعنف، فسيتعلم طفلكِ أن العنف ليس الحل الوحيد. وكما يقلّد الأطفال والديهم، قد يقلّدون أقرانهم أيضًا، لذلك يؤدي اختيار الأصدقاء دورًا مهمًا. ويمكنكِ المساعدة على منع طفلكِ من اكتساب السلوك العدواني من خلال الحرص على ألا يكون بين المحيطين به أطفال يمارسون التنمر.') WHERE id = '24d429b5-e417-4b33-8078-028bcefe6f7f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عادةً ما ينتظر الأطفال الهدايا بحماس في أعياد ميلادهم والمناسبات أو عندما يحققون نجاحًا. وفي هذه المواقف، احرصي على ألا تكون القيمة المادية للهدايا مرتفعة جدًا، وإلا فقد يعتقد طفلكِ أن من يقدم له هدية أغلى يحبه أكثر. ولتجنب تكوّن هذه الفكرة لديه، يمكنكم تبادل هدايا يدوية لا تُشترى بالمال، لكنها تعبّر عن محبتكم، مثل رسمة أو قصيدة أو رسالة. وهكذا سيدرك طفلكِ بنفسه أن أجمل هدية ليست الأشياء التي تُشترى بالمال، بل المشاعر الصادقة النابعة من القلب. وسيرى أن المشاعر أيضًا يمكن أن تمنح الإنسان السعادة بدلًا من تقدير الأشياء المادية وحدها.') WHERE id = 'd3735694-7159-4c33-aa4d-430790be64d4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، يكون التطور المعرفي لطفلكِ قد تقدم بدرجة كبيرة. فهو يفهم جيدًا مفاهيم مثل طويل وقصير، وكبير وصغير، وخفيف وثقيل، وكذلك الكلمات الدالة على المكان مثل تحت وفوق وبجانب وخلف. ويتعرف على الأشكال الأساسية مثل المثلث والمربع والدائرة، ويمكنه تسمية 3 ألوان على الأقل. كما يستطيع تكرار رقمين بالترتيب نفسه بعد أن تقوليها له. ويدرك الفرق بين الليل والنهار، ويفهم مفاهيم الزمن مثل الأمس واليوم. ويعرف عمره ويستطيع إظهاره بأصابعه. كما يمكنه تصنيف الأشياء وذكر أوجه التشابه أو الاختلاف بينها.') WHERE id = '4768c45c-43c6-4236-9f86-623c2f9ec40d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عليكِ تعليم طفلكِ هذه القواعد البسيطة، لكنها بالغة الأهمية: جسده ملك له وحده. وإذا لمسه أي شخص بطريقة غير مألوفة أو مزعجة تثير خوفه، فعليه أن يقول بحزم: «لا». كما يجب أن يعرف أن عليه إخبار شخص بالغ بمثل هذا الموقف من دون تردد. ولا يحق لأحد أن يطلب منه إبقاء قبلة أو عناق أو لمسة سرًا بينهما. وعليه التحدث إلى شخص بالغ يثق به عن أي تصرف يجعله يشعر بعدم الارتياح. وإذا حاول أحد إيذاءه، فعليه أن يصرخ ويهرب ويطلب المساعدة.') WHERE id = '38ccb98e-f7f0-42f1-9fc8-8d02a460e0ee';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المهم تشجيع الأطفال في هذا العمر على ممارسة الألعاب الحركية والرياضة. فالتنزه مع أفراد الأسرة واللعب بالكرة في الهواء الطلق يسهمان بدرجة كبيرة في نمو طفلكِ الجسدي والنفسي. ومن المهم أن يمارس الحركة لمدة ثلاث ساعات على الأقل يوميًا. ويساعد النشاط البدني المنتظم على تقوية العظام والقلب، كما تؤدي الحركة دورًا مهمًا في نمو الدماغ. ويتكيف الأطفال النشطون بسهولة أكبر مع البيئات الاجتماعية، وتتطور مهاراتهم الاجتماعية بسرعة أكبر.') WHERE id = '9c00d257-a15f-4f9f-917f-c9d3da786356';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يواجه الأطفال الذين ينشؤون في أسر تسمح لهم بكل شيء بإفراط بعض الصعوبات مستقبلًا. ففي مثل هذه البيئة، لا تكون الحدود بين الطفل وأسرته واضحة، ويتمكن الطفل من دفع الجميع إلى تنفيذ كل ما يريده. وأحيانًا يتعامل الوالدان بتساهل مفرط حتى مع أخطاء الطفل، ولا يشرحان له ما هو صواب وما هو خطأ. ويتوقع الأطفال الذين ينشؤون بهذه الطريقة تلبية كل رغباتهم فورًا. ولأنهم لا يعرفون أي قواعد، فقد يشعرون بخيبة أمل شديدة عند بدء الدراسة. كما أنهم يواجهون صعوبة في التعاون مع الآخرين ولا ينجحون في العلاقات الاجتماعية، لأنهم لم يتعلموا معنى كلمة «لا» أو احترام الحدود في الحياة.') WHERE id = 'c829e69e-d9a0-43ec-931d-da6d9fab436d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أهم ما يميز هذه المرحلة العمرية هو حب الاستطلاع. فلا تنتهي أسئلة «ماذا؟ ولماذا؟ وكيف؟». وإلى جانب ذلك، يُقيَّم نمو طفلكِ في خمسة مجالات أساسية: النمو الجسدي، والمعرفي (الذهني)، والاجتماعي والعاطفي، واللغوي، ومهارات العناية بالنفس. تذكّري أن نمو كل طفل له خصائصه الفردية؛ فقد يتقدم الأطفال في بعض المجالات ويتأخرون في مجالات أخرى. والأهم هو أن تتعرّفي إلى طفلكِ عن قرب وتقدّمي له الدعم اللازم في المجالات التي يحتاج إليها.') WHERE id = '069e0e2c-55b0-4247-966d-9ce442ff2cb6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تثير قلقكِ بعض السلوكيات التي يستطيع طفلكِ القيام بها أو التي لم يتقنها بعد. ولكن قبل أن تقلقي، عليكِ معرفة ما يُتوقع أن يتمكن طفلكِ من فعله وفقًا لمرحلته النمائية؛ فمن غير العادل أن تتوقعي منه سلوكًا يفوق مستوى نموه. يُستحسن استشارة مختص إذا كان طفلكِ لا يستطيع القفز، أو ركوب دراجة ثلاثية العجلات، أو إمساك قلم التلوين بأصابعه، أو يجد صعوبة في الخربشة، أو لا يستطيع رسم دائرة، أو تكديس أربعة مكعبات بعضها فوق بعض، أو لا يستجيب لأشخاص من خارج العائلة، أو لا يهتم باللعب التخيلي، أو يقاوم ارتداء الملابس أو النوم أو استخدام المرحاض، أو يفقد السيطرة على نفسه عند الغضب ويعتدي على من حوله، أو لا يستطيع تكوين جملة تتجاوز ثلاث كلمات، أو لا يستخدم ضميري «أنا» و«أنت» في موضعهما الصحيح. وبإرشاد المختص، يمكنكِ تجاوز القلق واتباع الأساليب المناسبة.') WHERE id = 'ec1f5a53-bfd2-4c57-b329-9cb8e54c1459';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'حقق طفلكِ في هذه المرحلة نموًا جسديًا ملحوظًا. إذ يمكنه المشي على خط مستقيم، وصعود الدرج بالتبديل بين قدميه، وتغيير اتجاهه فجأة، والوقوف على قدم واحدة لمدة ٣-٥ ثوانٍ والقفز. بل يمكنه أيضًا أداء حركات أكثر صعوبة، مثل الشقلبة، وضرب الكرة بالأرض ثم التقاطها، وتسلق الأشجار، والقفز من ارتفاع ٢٠ سم. كما يجيد رسم خط مستقيم بالقلم، وتتبع حواف القوالب لرسم الأشكال، وإجراء قصّات عشوائية بالمقص. ومن السهل جدًا عليه الرقص على الإيقاع والمشاركة في الألعاب الراقصة. كذلك يؤدي بحماس كبير أنشطة تتطلب مهارات حركية دقيقة، مثل نظم الخرز في خيط. ولدعم نموه الجسدي، يمكنكِ زيادة هذه الأنشطة والاستمرار في كونكِ أقرب رفيقة لعب له!') WHERE id = 'e5d5b53c-0757-47ac-bd1a-38d2522ecc95';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين أن طفلكِ بدأ يميل إلى الاهتمام بالمقتنيات المادية. فقد يتأثر بما يراه حوله وبالأشياء التي يملكها أصدقاؤه، فيرغب في امتلاك بعضها. لا يمكننا الحصول على كل ما نريده في أي وقت طوال حياتنا؛ لذلك فإن إحدى أهم مسؤولياتكِ بصفتكِ أمًا هي تعريف طفلكِ بهذه الحقيقة منذ سن مبكرة. إن شراء كل ما يراه طفلكِ ويرغب فيه أثناء التجول في مراكز التسوق يضره أكثر مما ينفعه. لا تقلقي من أنه لن يحبكِ إذا لم تشتري له اللعبة التي يريدها، أو أنه سيظن أنكِ لا تحبينه. تذكّري أن الحب ليس شعورًا يمكن قياسه بالمال. وإذا كانت ظروفكِ المادية لا تسمح، أو كنتِ ترين أن ما يطلبه طفلكِ غير ضروري، فمن المفيد أن تضيفي كلمة «لا» إلى قاموسكِ.') WHERE id = '2f8ddfe6-7178-4fde-930f-e80f6581caa4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'العناق المفعم بالحب مهم جدًا للأطفال. لكنهم يحتاجون إلى معرفة الفرق بين اللمسات المقبولة واللمسات غير المقبولة. وفيما يلي نقاط ينبغي الانتباه إليها في هذا الشأن: يجب أن يفهم الأطفال، حتى أثناء اللعب، أن كلمة «توقّف» تعني التوقف فعلًا. ويجب أن يعرفوا أن من حقهم قول «لا» إذا لم يرتاحوا للتلامس الجسدي. فمثل البالغين، قد تمر بهم أوقات لا يرغبون فيها في أن يقبّلهم أحد أو يعانقهم، وينبغي احترام ذلك. وكلما كبر الطفل، يجب تهيئة الظروف وإتاحة الفرصة له لأداء مهارات العناية بنفسه، بما في ذلك تنظيف نفسه بعد استخدام المرحاض. كما يجب تعليمه الأسماء الصحيحة للأعضاء التناسلية وتوعيته بأن هذه الأجزاء من جسمه خاصة.') WHERE id = '5c24967a-5741-4f41-a656-2c01ee3f742a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بصفتكِ أمًا، تجنّبي الإفراط في حمايته، واسمحي لطفلكِ بأن يخطئ ويشعر بخيبة الأمل، ثم تحدثي معه عن التجربة التي مر بها. وبدلًا من التركيز دائمًا على النتيجة وحدها، أكّدي له أهمية أن يبذل قصارى جهده. وشدّدي على أهمية التحلي بالعزيمة ومواصلة المحاولة وعدم الاستسلام عند الإخفاق. كوني قدوة له منذ صغره، واغرسي فيه الأهداف التي ينبغي أن يسعى إليها والقيم التي تمنح الحياة معنى. شجّعيه على اتباع نمط حياة صحي لتسهيل التعامل مع التوتر، واهتمي بنظامه الغذائي ومواعيد نومه، ووجّهيه إلى ممارسة رياضة يحبها. عزّزي مهاراته في حل المشكلات، وساعديه على اكتساب القدرة على تقبّل المواقف التي لا يستطيع تغيير نتائجها وتركها تمضي كما هي.') WHERE id = '13491f07-e2fc-4e62-9b03-f0e14bc044db';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إن تفاعل طفلكِ مع الحيوانات، سواء في المنزل أو أثناء التنزه، يؤثر إيجابيًا في صحته العاطفية والجسدية. فالحيوانات تحب الأطفال من دون أحكام أو تحيز، وهذا يعزز مهارات طفلكِ الاجتماعية. عندما تقررين تربية حيوان أليف لطفلكِ، عليكِ التأكد من استعداد جميع أفراد المنزل لذلك. وإذا كان لديكم أي تردد، فمن الأفضل الانتظار حتى تصبحوا مستعدين تمامًا؛ لأن إخراج الحيوان من المنزل لاحقًا قد يؤثر سلبًا في طفلكِ.') WHERE id = 'ebdde511-5991-44a2-b151-22c1dd2b496b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يولد بعض الأطفال بطباع "صعبة". فقد يكون تناولهم الطعام ونومهم وارتداؤهم الملابس وخلعها والذهاب إلى الأماكن، بل وكل لحظة من حياتهم اليومية وكل تجربة جديدة، بمثابة تحدٍّ. الطفل صعب الطباع مختلف، لكن اطمئني إلى أنه لن يبقى هكذا دائمًا، فهو أيضًا سيكبر. وعلى الرغم من اختلاف التكوين والطباع، فإن كثيرًا من السمات السلوكية لدى الأطفال تستقر في مسارها الطبيعي مع نموهم. لا تصغي إلى ما يقوله المقربون منكِ أو المحيطون بكِ. فالأطفال صعبو الطباع ليسوا كذلك بسبب خطأ ارتكبتِه؛ وهذا ليس ذنبكِ ولا ذنبهم. أن تكوني أمًا لطفل صعب الطباع أمر شاق حقًا، لكنكِ على الأرجح أدركتِ ذلك منذ وقت طويل. ومع مرور الوقت، ستتعلمين حتمًا كيفية التعامل معه. أنتِ أم رائعة، لذا اعتني بنفسكِ أولًا وحافظي على سلامتكِ. فهؤلاء الأطفال الذين يوصفون بأنهم "صعبون" يحتاجون إليكِ لكي ينموا بصحة وعافية.') WHERE id = 'f3c98e3d-a387-4475-99d8-7416db4b20d3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'للتلفاز ووسائل الإعلام تأثير كبير في ميل الأطفال إلى السلوك العدواني. فقد يتخذ طفلكِ ما يراه ويسمعه على الشاشة نموذجًا له، ويُظهر سلوكيات عنيفة تجاه الآخرين ويستمتع بها. ولتقليل هذا التأثير السلبي للتلفاز، عليكِ متابعة البرامج التي يشاهدها طفلكِ والحد من الوقت الذي يقضيه أمام الشاشة. ونظرًا إلى أن الرقابة المفرطة قد تؤدي إلى نتيجة عكسية، فمن المهم جدًا أن تشرحي لطفلكِ أسباب هذه القيود بطريقة منطقية. ولمساعدة الطفل الذي يتصرف بخشونة مع صديقه على تعلّم التعاطف، عليكِ أن توضحي له أثر تصرفه. وقد تفيدكِ أسئلة مثل: ماذا شعر صديقك عندما ضربته؟ أو كيف كنت ستشعر لو فعل بك شخص آخر ذلك؟ وفي الوقت نفسه، لا تترددي في التعبير مرارًا عن رفضكِ للعنف.') WHERE id = '2ec21ce0-5777-416a-828f-fcbf4be267d8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بمجرد أن تشعري بأن طفلكِ منزعج، اسأليه بالتأكيد عما يزعجه. قد يكون طفلكِ مدركًا للمشكلة، لكنه قد لا يرغب في التحدث عنها خجلًا إذا كان هناك أشخاص آخرون بالقرب منكما. وقد لا يكون طرح السؤال فورًا ممكنًا في مثل هذه الحالة، لذا تحدثي معه في أقرب وقت بعد الموقف، وفي مكان مريح يتيح لكما الحوار بحرية. لا تحصري إجابته بطرح أسئلة لا تحتمل سوى نعم أو لا؛ بل اطرحي أسئلة تتطلب شرحًا أوسع، مثل: ما الذي يزعجك؟ ينبغي أن تُشعره طريقة طرحكِ للأسئلة بأنكِ مهتمة بمشكلته وترغبين في دعمه. لا تستهيني أبدًا بمخاوف طفلكِ؛ فإذا شعر بأن قلقه لا يحظى بالاهتمام، فسيتردد في الإجابة عن الأسئلة، وسيصعّب ذلك مهمتكِ.') WHERE id = 'b97543dc-ce79-4fbc-93de-cbef3249c71a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد حقق طفلكِ تقدمًا ملحوظًا في نموه الاجتماعي والعاطفي. وبما أنه أصبح أكثر استقلالية، فإنه يحب التصرف من تلقاء نفسه. كما أصبح يستمتع أكثر باللعب مع طفل آخر، وإن كانت ألعابهما عادة قصيرة المدة. وهو يحاكي الحياة الواقعية من خلال ألعاب تمثيل الأدوار، مثل اللعب بالبيت أو بالطبيب. ويستطيع الالتزام بقواعد اللعبة، كما يمكنه تغييرها بما يناسبه. ويتواصل بسهولة مع أقرانه أو البالغين، ويمكنه تحية البالغين الذين يعرفهم من دون تذكير. وقد تراوده مخاوف من الظلام أو من وحوش خيالية. كما يستطيع الرقص والغناء على أنغام الموسيقى والتعبير عن مشاعره، ويستمتع بالرد على الهاتف والتحدث إلى الأشخاص الذين يعرفهم.') WHERE id = '4a246325-9284-4833-910a-5c234bb8b853';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'على الرغم من مزايا توجيه كل الاهتمام والطاقة والإمكانات إلى طفل واحد، فإن تربية طفل وحيد تنطوي أيضًا على تحديات خاصة. ويمكنكِ اتخاذ بعض الخطوات لتقليل هذه التحديات إلى أدنى حد. اصطحبي طفلكِ منذ سن مبكرة إلى مجموعات اللعب، واقضي معه وقتًا طويلًا في حدائق الأطفال. ادعي أصدقاءه المقربين إلى المنزل، وحاولي قدر الإمكان ألا ترفضي عندما يتلقى دعوة للذهاب إلى مكان ما. وإذا كنتِ أمًا في أسرة ذات والد واحد، فاقضي العطلات مع أصدقائكِ الذين لديهم أطفال. ولا تسمحي له بالفوز دائمًا في الألعاب التي تلعبانها. فإغراقه بالهدايا لمجرد أنه طفل وحيد قد يرسخ لديه فكرة أنه سيحصل فورًا على كل ما يريده. لا تسمحي بتحقيق كل رغباته في الحال، بل علّميه الانتظار والتحلي بالصبر.') WHERE id = '901c80ba-6c0e-46b1-9617-63b92aa875d7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لأن مرحلة الطفولة هي الفترة التي ينمو فيها الدماغ بأسرع وتيرة، فإن لنمط التغذية تأثيرًا كبيرًا في الانتباه والوظائف الإدراكية. وقد تؤثر أنواع الأغذية الـ5 التي سنذكرها إيجابيًا في نشاط دماغ طفلكِ، سواء في حياته اليومية أو مستقبلًا. يساعد الزبادي الغني بالبروتين على نمو أغشية خلايا الدماغ؛ ويمكنكِ تقديمه مع الفاكهة كوجبة خفيفة أو بجانب الوجبات. أما البروكلي، الذي يحتوي على نسبة قليلة من السكر وكثير من الألياف، فهو غني بحمض الفوليك وفيتامين B6، ولذلك يعزز الحالة النفسية والذاكرة. وتُعد المكسرات الغنية بالبروتين والأحماض الدهنية الأساسية والفيتامينات والمعادن من الأطعمة التي «تُسعد» الجهاز العصبي. ومن المعروف أن الشوفان، وهو مصدر للبروتين والألياف، يحمي الأوعية الدموية في القلب والدماغ ويحسن الذاكرة؛ ويمكنكِ إضافة التفاح أو الكمثرى أو القرفة إليه لإكسابه نكهة لذيذة. كما ثبت أن الأشخاص الذين يتناولون كميات وفيرة من الخضراوات الورقية الكبيرة، مثل السبانخ، يكون خطر إصابتهم بالخرف مستقبلًا أقل.') WHERE id = '18904566-7a89-4f66-b086-d296bdbb9068';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي أن يكون نظام نوم طفلكِ من أولوياتكِ. فعدم استمرار أنشطته الحركية إلى ساعات متأخرة جدًا، وخلو غرفته من الأجهزة الإلكترونية مثل التلفاز والحاسوب المحمول، سيؤثران إيجابيًا في جودة نومه. وقد تؤدي قلة النوم إلى زيادة الشهية ودفع الطفل إلى تناول الأطعمة مرتفعة السعرات الحرارية، مما قد يسبب السمنة. كما قد تسوء حالته النفسية، وقد يصاب بالقلق أو الاكتئاب. وقد يتراجع أداؤه المدرسي بسبب ضعف الذاكرة والانتباه، ويصبح أكثر عرضة للحوادث المختلفة، بما فيها الإصابات الرياضية. كذلك تضعف قلة النوم قدرة الطفل على اتخاذ القرارات، وقد تدفعه إلى اتخاذ خطوات خاطئة.') WHERE id = '57b0220c-72e8-44f7-8b63-aa64a167b83f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد تطورت مهارات طفلكِ اللغوية كثيرًا خلال هذه المرحلة. وأصبح الآن قادرًا على ذكر اسمه واسم عائلته عندما يُطلب منه ذلك. ويستمتع بالكلام وإلقاء النكات. كما يستطيع إلقاء القصائد وغناء الأغاني وترديد العبارات صعبة النطق عن ظهر قلب. ويطرح أسئلة باستخدام أداة الاستفهام «كيف؟»، ويجيب عن الأسئلة الموجهة إليه. كما يستطيع ربط جملتين باستخدام أدوات الربط. ويحافظ على التواصل البصري عند الاستماع أو التحدث، ويشارك بفاعلية في الحوار.') WHERE id = '8b9223c1-8cb2-41b5-98b2-84189ec82cbb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين أن طفلكِ لا يزال يتحدث كرضيع رغم بلوغه سن 3,5 سنوات. وقد يثير ذلك ردود فعل سلبية من أقرانه، ويسبب له صعوبات في حياته الاجتماعية ويضر بثقته بنفسه. وفي هذه الحالة، يمكن إحراز تقدم أسرع باتباع الوالدين نهجًا سليمًا. أولًا، ينبغي ألا تتحدثي معه بالطريقة نفسها مستخدمةً لغة الأطفال، حتى لا تعززي نطقه الخاطئ. وفي المقابل، يجب عدم السخرية مطلقًا من طريقة كلامه. وتجنبي تصحيح الكلمات التي لا يستطيع نطقها بصورة سليمة بأسلوب يبدو انتقاديًا. بل ينبغي أن يسمع منكِ النطق الصحيح للكلمة بطريقة طبيعية فور نطقها بشكل خاطئ. فعلى سبيل المثال، إذا قال الطفل: «أغلتُ الباب»، فقولي له: «أحسنت يا صغيري، لقد أغلقتَ الباب»، لتقدمي له نموذجًا صحيحًا.') WHERE id = 'c4b115b3-ef2f-472a-953f-e45e211c4cd3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي أن نتصرف نحن أيضًا وفق الصفات التي نرغب في تنشئة أطفالنا عليها. فإذا أردنا تربية طفل كريم، فعلينا أن نكون كرماء أيضًا. وإذا أردنا طفلًا محبًا للخير، فعلينا أن نكون مبادرين إلى مساعدة الآخرين. فلا يمكننا أن نتوقع ممن لم يرَ معنى مساعدة الآخرين أن يصبح شخصًا متعاونًا. ولتربية طفل يحب الطبيعة، علينا أن نحب الحيوانات ونحافظ على نظافة محيطنا. ولن يكون من الصادق أن نلقي القمامة من حولنا ثم نتوقع من طفلنا أن يحب الطبيعة. ويجب دائمًا أن تنسجم أقوالنا مع أفعالنا.') WHERE id = '5f784ef7-81b7-45ed-8f69-52151968d6e6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك طرق عديدة لتحبيب طفلكِ في الكتب. ولكي يشعر بأن الكتب جزء من الحياة، كان من الأفضل أن تشتري له الكتب منذ مرحلة الرضاعة. وكوني قدوة له بقراءتكِ الكتب بانتظام. واذهبا معًا من حين إلى آخر لشراء الكتب. واشتري له كتبًا مناسبة لعمره، تجذب اهتمامه، وتتناول موضوعات متنوعة، وتجمع بين الفائدة والمتعة. ويمكنكِ أيضًا تخصيص حصالة وتسميتها «صندوق الكتب»، ثم شراء الكتب التي يرغب فيها معًا بالنقود المدخرة فيها. وخصصي وقتًا يوميًا للقراءة معًا. وعندما تقرئين له كتابًا، أضفي الحماس على القصة وجسدي أحداثها بتغيير نبرة صوتكِ واستخدام تعابير وجهكِ. كما أن وضع كتبه في مكان ظاهر داخل غرفته يسهل عليه الوصول إليه سيوصل له رسالة مفادها: «يمكنك قراءة كتاب متى شئت».') WHERE id = 'f1964371-90a4-463e-96ce-62c966f65628';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يرجع شيوع المخاوف في هذه الأعمار إلى محدودية معلومات الأطفال وتجاربهم، وإلى أن مهارات التفكير لديهم لم تكتمل بعد. لذلك، يجدون صعوبة في فهم ما يرونه وتفسيره. وفي الظروف الطبيعية، تقل هذه المخاوف مع التقدم في العمر، لكن التجارب الصادمة والأساليب الوالدية الخاطئة قد تجعلها مزمنة. بالإضافة إلى ذلك، قد تنتقل إلى طفلنا أيضًا المخاوف التي نظهرها نحن البالغين دون ضبط أو وعي. ورغم أن المخاوف جزء مهم من عملية النمو، فإن كثيرًا من الآباء والأمهات يتعاملون معها بقلق. ويعود السبب الأساسي في ذلك إلى عدم امتلاكهم معلومات كافية حول كيفية التعامل مع الخوف. حافظي على هدوئكِ، وتفهّمي خوف طفلكِ، وابحثي عن سبل مناسبة لمساعدته على التغلب عليه.') WHERE id = 'd2b56eb9-64b3-4d2a-9bea-2c89289a5a9f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يساعد الانضباط الطفل على اكتساب سلوكيات جديدة. فمن خلاله، يتعلم طفلكِ السلوكيات الاجتماعية، والالتزام بالقواعد، وضبط النفس، والثقة بالنفس. ولا يعني فرض الانضباط على الطفل إطلاقًا الصراخ عليه أو توبيخه أو ضربه. ولا مكان لفكرة «لن يضرّه صفْعٌ خفيف» في مفهوم الانضباط الإيجابي. فضرب شخص أضعف منكِ ولا يستطيع الدفاع عن نفسه هو في الحقيقة دليل على فقدانكِ السيطرة على نفسكِ. لكن الأخطر من ذلك أن طفلكِ سيتخذكِ قدوة له. وإذا رأيتِه يصفع أخاه أو أخته الأصغر منه مرة أو مرتين، فلن تجدي ما تقولينه له. لذلك، احرصي عند وضع قواعد الانضباط على ألا يكون للعنف أي مكان فيها.') WHERE id = '1771eb2a-f537-43ee-b06f-ae57310d6566';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يشكو كثير من الآباء والأمهات والمعلمين من فوضوية الطفل، وقد تكون وراء هذه الفوضى أسباب مختلفة. ففي حين تحتاج الأم إلى النظام والانضباط، قد لا يكون ما يحتاج إليه الطفل سوى «أمه». وربما يحاول طفلكِ من خلال الفوضى جذب انتباهكِ إليه. ففوضوية الطفل تحمل دلالة معينة، تمامًا كما يحمل ترتيبه ونظامه دلالة أيضًا. إذا كان طفلكِ فوضويًا، فينبغي تحليل احتياجاته بطريقة صحيحة لفهم السبب الكامن وراء ذلك، ومراجعة مدى أمان وقوة الرابط بينكما. إن إدراك احتياجه الحقيقي وتلبيته، مثل حاجته إلى أن يُستمع إليه أو إلى اللعب أو التواصل الجسدي، سيساعده على ترتيب غرفته وعالمه الداخلي معًا. وهكذا، ستستعيد علاقته بوالديه توازنها بصورة طبيعية.') WHERE id = '0c1e3fdc-522c-4ec0-b788-6079b836c01d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ تعتقدين أن طفلكِ لا يستمع إليكِ بانتباه، فيمكنكِ مساعدته على تطوير مهارة التركيز. كوني له قدوة في حسن الاستماع. وعندما يتحدث إليكِ، لا تتظاهري بالاستماع، بل أنصتي إليه فعلًا مع التواصل البصري. لا تقاطعيه أثناء حديثه، ودعيه يكمل جمله بنفسه. وعندما يحاول مقاطعتكِ، وجّهيه إلى الانتظار. تحدثي معه كثيرًا عن الموضوعات التي تثير اهتمامه؛ فهذا سيسهم في تعزيز علاقتكما وتطوير قدرته على التعبير عن نفسه والاستماع. رتّبي ألعابه أمامه وصفي له إحداها، ثم اطلبي منه العثور عليها باتباع توجيهاتكِ. واجعليه يرسم وفقًا لتعليماتكِ: «ارسم دائرة كبيرة في منتصف الورقة. والآن ارسم على يمينها مثلثًا بحجم نصف الدائرة». حضّرا الطعام معًا؛ اذكري له المكونات ودعيه يخلطها بالترتيب.') WHERE id = 'd5751336-7039-4c31-8668-3f750e2f3116';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يتعامل الآباء والأمهات مع أطفالهم بأساليب مختلفة من وقت إلى آخر. فمن الممكن ألا تتمكني من تخصيص وقت كافٍ لطفلكِ بعد يوم متعب، أو أن تبالغي في رد فعلكِ تجاه شيء قاله. والأهم هو ألا تتحول هذه السلوكيات السلبية إلى نمط مستمر. ويُعد اتباع الوالدين أسلوب التربية نفسه عاملًا بالغ الأهمية في تكوين شخصية سليمة لدى الطفل. فاتخاذ الأم والأب مواقف مختلفة في كل موضوع يخلق لدى الطفل شعورًا بالحيرة وعدم الأمان. كما يزداد القلق لدى الطفل حين لا يعرف رد الفعل الذي سيتلقاه من والديه تجاه تصرفاته. وقد تؤدي هذه الحالة على المدى الطويل إلى اضطرابات عاطفية وسلوكية لديه.') WHERE id = 'a5bd86bc-c069-466f-af85-e16d00cba4e2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ تسمعين كثيرًا خلال اليوم أسئلة مثل «كم بقي؟» أو «هل وصلنا؟»، فاعلمي أن هذا أمر طبيعي. ولأن النمو المعرفي لدى الأطفال لم يكتمل بعد، فإنهم يدركون مفهوم الزمن بطريقة مختلفة عن البالغين. ولهذا السبب يكررون السؤال نفسه مرارًا. فعبارات مثل «بقيت 30 دقيقة» أو «أمامنا ساعتان من الطريق» لا تحمل معنى واضحًا للطفل. لذلك، من الضروري التحدث معه باستخدام أمثلة واضحة وملموسة قدر الإمكان. فتفسيرات مثل «بقي من الطريق ما يعادل مدة أربعة أفلام كرتونية» أو «بقي من الوقت مقدار ما ننتظره عادة حتى نتناول العشاء» ستطمئنه بسرعة أكبر، وتساعده على فهم الوضع بوضوح.') WHERE id = '62a96225-850d-4700-bdbf-477dae8e326b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ الاستفادة من التوابل لحماية طفلكِ من الأمراض، وتقوية مناعته، أو منحه الطاقة. فإلى جانب قوتها المضادة للأكسدة، تتمتع التوابل بالعديد من الفوائد المضادة للالتهابات. وتحمي مضادات الأكسدة الموجودة فيها، مثل البيتا كاروتين والسيلينيوم وفيتامينات A وC وE، طفلكِ من أمراض خطيرة عديدة، بما فيها أمراض القلب. كما تعزز المناعة وتزيد مقاومة الجسم للأمراض بفضل خصائصها المضادة للالتهابات. وتشير الدراسات إلى أن الكركم مفيد جدًا لصحة الدماغ والتطور المعرفي. وقد تبيّن أن ملعقة صغيرة من الزنجبيل تحتوي على كمية من مضادات الأكسدة تعادل ما يحتويه كوب من السبانخ. لذلك يمكنكِ إدخال التوابل الصحية إلى غذاء طفلكِ بأمان، مع ضبط الكمية جيدًا واستشارة طبيبكِ.') WHERE id = '85dd773a-500a-4181-ba61-330cd6ca6903';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لدينا اقتراح لنشاط ممتع يمكنكِ القيام به مع طفلكِ! يمكنكما البحث معًا عن أوراق النباتات في أماكن مختلفة، ثم فحص ما جمعتماه باستخدام عدسة مكبرة ومقارنته بعضه ببعض. ومن الأشياء التي يمكنكما جمعها: مخاريط الصنوبر، وأوراق بألوان وأحجام مختلفة، وقطع من الأغصان، وزهور، وبذور. ويمكنكما استخدام خيالكما للصق هذه المواد على ورقة بيضاء، وتكوين أشكال مختلفة وإضافة رسومات بالأقلام الملونة. ثم يمكنكِ تعليق هذا العمل الفني الذي صنعتماه في ركن جميل من غرفة طفلكِ. فالأوراق الكبيرة ممتعة جدًا لتستكشفها الأيدي الصغيرة، كما أن الجمع بين المواد الملتقطة من الطبيعة نشاط مشوق للغاية.') WHERE id = 'a3d322c1-283c-451c-8c14-a41a173f99ea';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'التنمر بين الأقران هو سلوك عدواني جسدي أو لفظي أو اجتماعي يتعرض له الطفل بصورة متكررة من أشخاص في فئته العمرية. عندما تلاحظين علامات هذا النوع من التنمر في كلام طفلكِ أو تصرفاته، فلا ينبغي لكِ تجاهلها. ومن المهم جدًا أن يكون تواصلكِ معه عند ملاحظة هذه العلامات بعيدًا تمامًا عن إصدار الأحكام أو إلقاء اللوم، وأن يهدف إلى فهم ما حدث وفهم مشاعر الطفل. فقد يعتقد الأطفال الذين يتعرضون للتنمر أنهم يستحقون ذلك أو أنهم غير مؤهلين بما يكفي. لذلك قد يكون لأسلوب اللوم والاستجواب، مثل: ألم تردّ عليه؟، تأثير سلبي. يُعد التنمر بين الأقران مشكلة خطيرة، كما أن الأطفال الذين يمارسونه يحتاجون إلى الدعم بقدر الأطفال الذين يتعرضون له. وإذا لم تُتخذ التدابير اللازمة، فقد تؤدي هذه الحالة إلى مشكلات عديدة لكلا الطرفين على المديين القصير والطويل.') WHERE id = '9a287db2-0736-4590-9beb-67cb23fbacb8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يكفي أن يشرب طفلكِ نحو 200 ml من الكفير يوميًا، أي ما يعادل 1 كوب، للمساعدة في الحفاظ على صحته العامة. فالكفير أعلى قيمة غذائية من الزبادي، إذ يحتفظ بجميع العناصر الغذائية الموجودة في الحليب، كما يتمتع بقيمة غذائية مرتفعة جدًا بفضل ما يحتويه من بكتيريا نافعة. كذلك يمتص جسم طفلكِ الكفير بسهولة أكبر. ويجعله غناه بالبروتين والمعادن الأساسية وفيتامينات B12 وB1 وK أكثر قيمة من غيره من منتجات الألبان. وبينما يساعد الزبادي على دعم صحة الجهاز الهضمي وتغذية البكتيريا النافعة، يحتوي الكفير على بكتيريا تسهم في موازنة الفلورا المعوية وتقويتها. باختصار، احرصي على إدراج الكفير في قائمة طعام طفلكِ إلى جانب الزبادي. وإذا لم يحب طفلكِ مذاق الكفير السادة، فيمكنكِ مزجه بالفواكه المتوفرة في المنزل لإعداد نكهات متنوعة.') WHERE id = '75f841e9-b23b-4e4f-8c19-19710a966f43';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تكون الأمومة أصعب مهمة في العالم. فمنذ اليوم الذي علمتِ فيه أنكِ سترزقين بطفل، وأنتِ تحملين مسؤولية كبيرة على عاتقكِ. ولكي تكوني أمًا جيدة، تذكري أولًا أنكِ إنسانة أيضًا، وامنحي نفسكِ فرصة لارتكاب الأخطاء. فعندما تخففين هذا الضغط عن نفسكِ، تصبحين أكثر فاعلية في دوركِ كأم. ومن الضروري أيضًا أن تكون هناك قواعد يلتزم بها طفلكِ أثناء نموه. وإذا كنتِ تعتقدين أنه سيعيش وفق القواعد طوال حياته، ولذلك ينبغي تركه حرًا الآن، فقد يؤدي ذلك إما إلى إبطاء نموه وتطوره أو إلى بقائه معتمدًا كالأطفال. تذكري أنكِ إذا حاولتِ إنجاز هذه المهمة الصعبة من خلال الضغط على نفسكِ وحدكِ، فستشعرين بإرهاق شديد. ويمكنكِ تخفيف العبء عن نفسكِ، ولو قليلًا، بوضع قواعد محددة ومساعدة طفلكِ على الالتزام بها.') WHERE id = '23ccddfb-c2e9-4bc4-bc64-31a8fb82ad5b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ساعدي طفلكِ على مواجهة مصادر قلقه ومخاوفه بصورة تدريجية، وضعي معه خطة لذلك. فعلى سبيل المثال، قد تكون الخطوة الأولى لطفل يخاف من العناكب هي النظر إلى صورها. وفي المراحل التالية، يمكنه إمساك عنكبوت لعبة، ثم البقاء في الغرفة نفسها مع عنكبوت حقيقي، والاقتراب منه مترًا إضافيًا في كل مرة. حددي هذه المراحل بالتعاون مع طفلكِ، وأشيدي بجهده في كل خطوة. وشجعيه على التفكير في أكبر عدد ممكن من الحلول للمشكلة التي تقلقه، واطرحي عليه أسئلة تساعده على معرفة الحل الذي قد يحقق نتيجة أفضل. واحرصي على تهنئة طفلكِ بهذه الخطوة الكبيرة التي اتخذها نحو حل مشكلاته بنفسه وباستقلالية.') WHERE id = '773a65e5-9a54-4e9c-97a7-6988ed4a909d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يطوّر طفلكِ في هذه المرحلة مواهبه، ويكتسب المهارات الأساسية، ويخوض تجارب متنوعة تساعده على الاندماج الاجتماعي وتعزيز قدراته الذهنية. إن توفير بيئة غنية بالمحفزات الخارجية، وإتاحة تجارب تدعم نموه، ومنحه الدعم الأبوي السليم في هذه المرحلة، كل ذلك سيُعِدّه للحياة بأفضل صورة ممكنة. ولدعم نمو طفلكِ من جميع الجوانب، يمكنكِ القيام بما يلي: تحدثي معه كثيرًا لتنمية لغته، واقرئي له الكتب، وناقشي معه ما قرأتماه، وأجيبي عن أسئلته بصبر. ولدعم نموه البدني، أتيحي له يوميًا فرصًا للركض واللعب والتسلق والقفز في الهواء الطلق. ووفّري له فرص قضاء الوقت مع أقرانه ليتعلم الاندماج الاجتماعي. وأثناء قيامكِ بكل ذلك، لا تنسي أن العامل الأهم هو معاملتكِ لطفلكِ بصدق وحنان. :)') WHERE id = '4c3211b1-1b69-4c52-9840-6ed951a97c72';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عليكِ إرشاد طفلكِ إلى السلوكيات الصحيحة والخاطئة. فالأطفال يتعرفون إلى العالم من خلال نظرة والديهم إليه. ومن المهم أن تدعيه يواجه النتائج الطبيعية لتصرفاته الخاطئة. فعلى سبيل المثال، عندما يدفع الطفل من مصروفه ثمن الضرر الذي ألحقه بلعبة صديقه، يدرك أن لكل تصرف نتيجة وأن عليه تحمّل المسؤولية. احرصي دائمًا على ملاحظة محاولاته الإيجابية وتشجيعه. فعند تعليمه عادة جديدة، من المهم جدًا لنموه أن تلاحظي حتى النجاح الصغير وتمدحيه عليه. واستفيدي من الكتب والأفلام التثقيفية؛ فالشخصيات التي تجسد الحب والصداقة والتعاون تصبح قدوة مهمة للأطفال.') WHERE id = '49814a58-2096-4190-95ca-b5eac5936f10';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا يمكن تجنّب سقوط طفلكِ أو ارتطامه بشيء ما أثناء اللعب. وغالبًا ما تكون هذه إصابات بسيطة لا تتطلب تدخلًا طبيًا. ومع ذلك، ينبغي العناية بهذه الجروح البسيطة للحفاظ على صحة الجلد. للحد من التورم والكدمات، اصطحبي طفلكِ أولًا إلى مكان هادئ. وضعي فورًا على المنطقة المصابة ثلجًا ملفوفًا بمنشفة للحد من تدفق الدم وتقليل التورم. ويمكنكِ الضغط برفق على تلك المنطقة وتدليكها بكريم مهدئ ومساعد على التعافي. وبالطبع، لا تنسي أن تحتضني صغيركِ وتقبّلي موضع ألمه! 🥰') WHERE id = 'c11ef2e0-c21f-40eb-8a0a-01c49251e495';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تتميز بشرة الأطفال بحساسية خاصة، ولذلك تحتاج إلى عناية واهتمام خاصين للحفاظ على صحتها ومساعدتها على التكيف مع البيئة المحيطة. وبوجه عام، ينبغي عدم استخدام منتجات التنظيف والعناية المخصصة للبالغين على بشرة الرضع والأطفال. فبشرة الطفل التي تضعف بفعل عوامل خارجية مثل الرياح والطقس البارد والمياه العسرة أو درجات الحرارة المرتفعة، تكون أكثر عرضة للجفاف وفرط التفاعل. عند تحميم طفلكِ، يمكنكِ استخدام منتجات تنظيف لطيفة وخالية من العطور، لا تزيد جفاف البشرة، وتحد من تكاثر الكائنات الحية الدقيقة، وتهدئ الحكة وترطب البشرة. جففي بشرة طفلكِ بعناية ولطف شديدين، ولا سيما ثنيات الجلد. ومن الأفضل أن يرتدي طفلكِ ملابس قطنية، لأن الأقمشة الأخرى، وخصوصًا الصوف والمواد الصناعية، قد تهيّج بشرته. واحرصي على ألا تكون درجة حرارة الغرفة مرتفعة جدًا، وإلا فسيجف الهواء ويضر ببشرته.') WHERE id = '10ca6da4-e8de-47e5-922b-c5d97b0658c7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يعتقد بعض الآباء أن وضع حدود للطفل يجعله سلبيًا ويضر بثقته بنفسه. لكن الحدود في الحقيقة إشارات مهمة تُشعر الطفل بالأمان وتوضح له متى يجب أن يتوقف. فكما يمنحنا وجود إشارة المرور شعورًا بالاطمئنان عند عبور الطريق سيرًا على الأقدام، فإن وجود إشارات تذكّر الأطفال بالمواضع التي ينبغي لهم التوقف عندها يجعلهم يشعرون بالأمان. ولا يعني وضع الحدود أن تقولي "لا" لكل ما يريده طفلكِ أو أن تضعيه تحت الضغط، بل يعني أن تكوني، بصفتكِ راشدة، قادرة على قول "تَوَقَّف" لسلوكياته غير الملائمة، وأن تلتزمي برد الفعل نفسه في كل مرة يتكرر فيها السلوك ذاته. يعرف الأطفال الذين ينشؤون ضمن حدود واضحة أين تنتهي حدودهم، ولذلك لا يتعدون على مساحة حرية الآخرين. ولنتذكر أن "الحياة المريحة" التي نوفرها لأطفالنا بتلبية جميع رغباتهم بهدف إسعادهم قد تجعلهم، على المدى الطويل، أشخاصًا لا يشعرون بالرضا وتعساء.') WHERE id = 'ad4cfebf-ee99-4e96-8f98-238ee9140d88';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عند إعداد برنامج التغذية في هذه المرحلة، يجب بالتأكيد مراعاة اختيارات طفلكِ الفردية. وينبغي أن تتكون قائمة طعام الطفل البالغ من العمر 3,5 سنوات من الأطعمة الصحية التي يحبها. ويُنصح بتقسيم القائمة إلى 3 وجبات رئيسية و3 وجبات خفيفة. ويجب أن تتضمن الوجبات الرئيسية أطعمة غنية بالبروتين، مثل البيض واللحوم والأسماك والدجاج والحليب والزبادي. وإلى جانب ذلك، تساعد الأطعمة الغنية بالكربوهيدرات مثل البطاطس والمعكرونة والأرز على توفير تغذية متوازنة. وإذا كان طفلكِ يواجه صعوبة في تناول الطعام، فيمكنكِ تقديم بدائل له. وستجعل الأقراص اللذيذة المصنوعة من الخضراوات، أو شرائح السمك الخالية من العظام المقدمة مع البطاطس، أو المعكرونة الملونة بصلصة الطماطم، قائمة الطعام أكثر جاذبية.') WHERE id = '9bae275a-b824-4916-834a-a3a6367872a8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'كم يطرح طفلكِ من الأسئلة، أليس كذلك؟ بعضها منطقي، وبعضها غير منطقي، بعضها في محلّه، وبعضها الآخر في غير محلّه تمامًا. إذا أجبتِ عن سؤال طفلكِ على عجل، مستخدمةً كلمات معقدة لا يفهمها أو تفاصيل تزيد فضوله، فلا مفر من أن تتبع ذلك سلسلة جديدة من الأسئلة. إن توقُّع السؤال الذي قد يطرحه بعد شرحكِ سيوفّر وقتكِ ويساعدكِ أيضًا على صياغة إجابتكِ الأولى بصورة أفضل. وإذا لم يكن لديكِ وقت أو طاقة للإجابة عن أسئلة إضافية، فاختاري إجابات بسيطة وواضحة. يظن طفلكِ أنكِ تعرفين كل شيء، مع أن هناك أشياء كثيرة قد لا تعرفينها أيضًا. إذا كنتِ لا تعرفين الإجابة، فقولي له بصدق: لا أعرف. ومع ذلك، سيكون من المفيد جدًا أن ترشديه إلى كيفية العثور على الإجابة ومكان البحث عنها.') WHERE id = 'e49ce7b4-2a04-4ecf-a4d4-0a18be73ddf0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكن للطفل الذي تُتاح له فرصة التعبير عن نفسه داخل الأسرة أن يكون قويًا أيضًا في البيئات الأخرى. فالطفل الذي ينشأ في بيئة أسرية يشعر فيها بالحب والقبول غير المشروط، ويخصّص أفرادها وقتًا بعضهم لبعض، يدرك أن وجوده ذو قيمة وأن آراءه تحظى بالاهتمام. وهذا أساس لا غنى عنه لبناء الثقة بالنفس. وبما أن الثقة بالنفس تعني إيمان الإنسان بقدراته وتكوين صورة إيجابية عن ذاته، فإن كل مسؤولية يؤديها منذ سن مبكرة تمنحه فرصة مهمة لاكتساب الخبرة. لنتذكر أننا نشبه المرآة لأطفالنا خلال فترة نموهم؛ فهم يتشكلون وفقًا لما يرونه ويسمعونه منا وما نجعلهم يشعرون به. ومن المرجح أن ينجح الوالدان الواثقان بنفسيهما في تنشئة طفل واثق بنفسه.') WHERE id = 'e0c1d026-5704-4d25-b4c7-eb54776fe87a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هدفنا هو تنشئة الطفل ليصبح شخصًا يساعد نفسه أولًا ثم يساعد الآخرين. ومن المهم أن يتخذ موقفًا متوازنًا بين الاهتمام بنفسه وحدها والاهتمام بالآخرين وحدهم. على سبيل المثال، لنفترض أنكِ اشتريتِ لطفلكِ كتابًا للتلوين والملصقات من 40 صفحة، يحتوي على أنشطة متنوعة وملونة. يمكنكِ تشجيعه على نزع صفحة من الكتاب وإعطائها لرفيق لعبه. كما يمكنكِ مساعدتهما على الاستمتاع بالتلوين ولصق الملصقات معًا. وعندما يشاركه صديقه إحدى ألعابه، يمكنكِ الإشادة بهذا السلوك الإيجابي على نحو خاص. المهم هنا أن يوافق الطفل على المشاركة، وأن تحترمي اختياره للشيء الذي يرغب في تقديمه.') WHERE id = '2b7fec61-281a-4d68-bfc0-d7dc7a15e8b1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي إعداد برنامج طفلكِ الغذائي بحيث يضمن تناول كميات كافية من جميع المجموعات الغذائية. فقد يتأثر نمو الأطفال وتطورهم الذهني سلبًا إذا لم يحصلوا على تغذية كافية ومتوازنة. وبصفتنا عائلة Anacan، أعددنا لكِ نموذجًا لقائمة طعام يومية كما يلي: الإفطار: نصف كوب من الحليب، نصف كوب من رقائق الشوفان (مخلوطة بالحليب)، 1 كوب من عصير الحمضيات أو عصير الطماطم، والشمام أو الفراولة. وجبة خفيفة: نصف كوب من الحليب، نصف موزة، 1 شريحة من خبز القمح الكامل، 1 ملعقة صغيرة من الزبدة. الغداء: شريحتان من خبز القمح الكامل، 1 ملعقة صغيرة من الزبدة، 30 غرامًا من اللحم أو الجبن، وربع كوب من الخضراوات (60 غرامًا). العشاء: 60 غرامًا من اللحم أو السمك أو الدجاج، نصف كوب من المعكرونة أو الأرز أو البطاطس، نصف كوب من الخضراوات، و1 ملعقة صغيرة من الزبدة.') WHERE id = 'a045a8a2-d4d7-4760-83e1-896e87106a0a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ ممارسة أنشطة قصصية لقضاء وقت ممتع مع طفلكِ. اقرئي قصة قصيرة واطرحي عليه أسئلة حول ما قرأتِه، مثل: من كان بطل القصة؟ أين وقعت الأحداث؟ ماذا حدث في النهاية؟ وما شابه ذلك... وإذا كان الكتاب الذي تقرئينه مألوفًا له، فتوقفي من حين لآخر واسأليه: ماذا سيحدث الآن؟ ماذا سيقول؟ اقرئي جزءًا من قصة اشتريتِها حديثًا واطلبي منه تخمين نهايتها وإكمالها. وأثناء قراءتكِ للقصة، اجعليه يغمض عينيه، ثم يفتحهما أو يصفق كلما ذُكر اسم بطل القصة. وبينما تقرئين، دعيه يجسّد أحداث القصة بنفسه أو يمثّلها باستخدام ألعابه، كما يفضّل. والعبوا معًا كأسرة لعبة تأليف القصص: يبدأ أحدكم القصة، ثم يضيف كل شخص جملة بالتناوب حتى تكتمل.') WHERE id = '15c8d0bb-8482-4ae4-8209-e9a1eaef5f89';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لاحظتِ حالة غير معتادة في سلوك طفلكِ، أو راودكِ مجرد شعور بأن شيئًا ما ليس على ما يرام، فلا ينبغي لكِ تجاهل ذلك. فنحن لا نستطيع معرفة ما إذا كان الأطفال يواجهون صعوبات نفسية إلا من خلال التغيرات التي تطرأ على سلوكهم. فالأطفال لا يجلسون أمامنا ويتحدثون مثل البالغين قائلين: "لديّ مشكلة"، بل غالبًا ما تظهر عليهم أعراض معينة. فقد يصبحون أحيانًا مفرطي الحركة، وقد يُلاحظ أحيانًا أخرى تراجع في سلوكهم؛ كأن يطلب الطفل الذي توقف عن استخدام زجاجة الرضاعة العودة إليها، أو يبدأ الطفل الذي أكمل التدريب على استخدام المرحاض بتبليل ملابسه مجددًا. وقد تظهر أحيانًا حالات مثل تشتت الانتباه. إذا لاحظتِ لدى طفلكِ علامات قد تشير إلى مشكلة محتملة في الصحة النفسية، فإن اكتشافها مبكرًا يسهّل علاجها.') WHERE id = '11263985-19b8-4671-b976-ed9543821ed8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'غالبًا ما يعتقد الأطفال أنهم وحدهم من يشعرون بالقلق تجاه موضوع معين، ويتجنبون الحديث عنه لأنهم يظنون أن الشعور بالقلق أمر غريب. أشعري طفلكِ بأن القلق بشأن أي أمر شعور طبيعي، وبذلك يمكنكِ أن تسهّلي عليه التحدث عن مخاوفه. ساعديه على النظر إلى المواقف من زوايا مختلفة بطرح أسئلة مثل: «ماذا كان سيفكر شخص آخر لو كان مكانك؟». ستساعده إجاباته على إيجاد الطريق المناسب. اطرحي عليه أسئلة مثل: «ما الذي يجعلك تعتقد أن مخاوفك ستتحقق؟» أو «هل سبق أن حدث لك هذا من قبل؟»، لتساعديه على فهم أسباب قلقه، ولتحاولي أنتِ أيضًا فهمه. وبدلًا من الاكتفاء بطمأنته بشأن ما يقلقه، احرصي على دعمه ومساندته.') WHERE id = 'd21c7f93-85a4-4a78-bc50-c6c2857a7a2b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يجب أن يعرف طفلكِ: «عندما أقوم بعمل جيد، أتلقى التقدير، وعندما أخطئ، أحصل على التوجيه». لكن ينبغي تجنب المبالغة في مدحه. فعلى سبيل المثال، بدلًا من قول: «هذه أجمل رسمة رأيتها في حياتي!»، من الأفضل أن تقولي: «أعجبتني كثيرًا طريقتك في استخدام الألوان!». كذلك يجب أن تركّز ردود أفعالكِ تجاه السلوك الخاطئ على السلوك نفسه، لا على شخصية طفلكِ. فعلى سبيل المثال، بدلًا من قول: «افعل شيئًا واحدًا بشكل صحيح على الأقل!»، قولي: «أتوقع منك أن تكون أكثر انتباهًا في هذا الأمر في المرة القادمة». وعندما تركّزين على الجهد الذي بذله ومثابرته وعدم استسلامه بسهولة، بدلًا من التركيز على قدراته، فسوف يتعامل مع كل إخفاق على أنه «لم أنجح بعد». وهكذا سيواصل المحاولة من جديد من دون أن يفقد حماسه.') WHERE id = 'ccee8292-0912-47dd-964c-7d03974ce207';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك العديد من الأنشطة التي يمكنكِ القيام بها لقضاء وقت ممتع مع طفلكِ. يمكنكما لعب ألعاب الكلمات التي تجمع بين المرح ودعم نموه وتقوية انتباهه وذاكرته. على سبيل المثال، قولي: «ذهبت إلى السوق واشتريت تفاحًا». وعندما يحين دوره، يضيف كلمة إلى الجملة التي قلتِها: «ذهبت إلى السوق واشتريت تفاحًا وموزًا». وفي كل مرة يحين فيها دور أحدكما، أضيفا كلمة إلى الجملة، واستمرا في اللعب حتى تختلط عليكما الكلمات. وإليكِ لعبة أخرى للذاكرة: قولي ثلاث كلمات مع ترك فاصل مدته ثانية واحدة بينها، ثم اطلبي من طفلكِ تكرارها بالترتيب نفسه. وعندما يتمكن من ذلك بسهولة، ارفعي عدد الكلمات إلى أربع، ثم خمس، ثم ست كلمات.') WHERE id = '11e9cc29-3146-4adb-a397-8a8bd440816e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'كثيرًا ما نسمع في الآونة الأخيرة عن ألعاب المنطق والذكاء في حياتنا اليومية. فما هذه الألعاب، وهل هي ضرورية حقًا، وما فوائدها لأطفالنا؟ ألعاب الذكاء هي ألعاب تُمارس من خلال التفكير والاستدلال وفق قواعد محددة، من دون أن تتطلب أي معرفة أو مهارات خاصة. وتؤدي دورًا مهمًا في تنمية قدرة الأطفال على فهم المشكلات وتقييمها. ومن أبرز أهدافها تمكين الطفل من النظر إلى الأحداث من زوايا مختلفة واتخاذ قرارات سريعة وصائبة عند مواجهة المشكلات. وتُظهر الدراسات العلمية أن ممارسة ألعاب الذكاء بانتظام تعزز المهارات المعرفية لدى الأطفال وتنمّي إمكاناتهم. تتوفر في الأسواق ألعاب ذكاء متنوعة تناسب أعمار الأطفال وشخصياتهم. ويمكنكِ البحث عن اللعبة الأنسب لطفلكِ واختيارها، لتسهمي في تنمية ذكائه بطريقة ممتعة.') WHERE id = 'f713d2d1-d132-46a0-988c-91151d41322e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد الشعور بالذنب وعدم الكفاءة من أكثر المشاعر شيوعًا لدى الأمهات العاملات. وتعتقد كثير من الأمهات اللاتي تتحكم فيهن هذه المشاعر أنهن لا يقضين وقتًا كافيًا مع أطفالهن، لذلك يحاولن اصطحابهم إلى كل مكان يذهبن إليه. لكن الوقت الذي تقضينه مع طفلكِ في مثل هذه الفعاليات لن يكون أكثر قيمة من الوقت الذي تقضينه في اللعب معه في المنزل. والأهم عند قضاء الوقت معًا هو أن تتحدثي إليه، وتتواصلي معه بصريًا، وتلمسيه، أي أن توجّهي إليه كامل انتباهكِ واهتمامكِ. وبهذه الطريقة نوصّل إلى الطفل رسالة «أنت شخص ذو قيمة» بصورة أكثر صحية. اشرحي لطفلكِ بوضوح أنكِ مضطرة إلى العودة إلى عملكِ، وتحدثي معه عن الطرق التي يمكنكما بها قضاء الوقت معًا. قد تواجهان بعض الصعوبة عند لحظات الانفصال في البداية، لكن التجارب الإيجابية التي ستأتي لاحقًا ستجعل هذه المرحلة أكثر سهولة.') WHERE id = '6bad7fb7-a9c2-4e5d-aa23-e31daa627dd6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إن تقديم شرح مناسب لعمر طفلكِ عن الموت والإجابة عن أسئلته قبل أن يواجه وفاة شخص ما، سيساعدانه على تقبّل الموت بوصفه جزءًا من الحياة. تحدثي عن موضوع الموت بهدوء وارتياح. وعندما يطرح طفلكِ سؤالًا، يمكنكِ إخباره بأنكِ لا تعرفين إجابات جميع الأسئلة، لكن حاولي التحدث عن الموت بصورة طبيعية، تمامًا كما تتحدثين عن الولادة. وعلى الرغم من أن الفهم الكامل للموت يتطلب بلوغ سن معينة، فإنه عملية تحدث تدريجيًا. ويمكنكِ منذ سنواته المبكرة أن تحدثيه عن دورة حياة الأزهار والحشرات والحيوانات. كما يمكنكِ أن تعهدي إليه بمسؤولية الاعتناء بنبتة أو حيوان، ليتمكن من ملاحظة مراحل الولادة والنمو والموت. وهكذا سيكون من الأسهل عليه إدراك أن موت جميع الكائنات الحية، بما فيها البشر، أمر طبيعي.') WHERE id = '126484cc-7b4e-4c94-b9de-bb4e567b23d9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ تتساءلين: «طفلي لا يأكل، فماذا أفعل لعلاج فقدان شهيته؟»، فلدينا لكِ بعض النصائح. أولًا، من الضروري تقييم حالته من خلال فحص الطبيب وإجراء التحاليل اللازمة، لأن انخفاض بعض مؤشرات الدم قد يسبب أحيانًا فقدان الشهية. إذا لم تكن المشكلة مرتبطة بصحته الجسدية، فمن المرجح أن تكون العوامل النفسية أو العادات الغذائية غير السليمة هي السبب. في هذه الحالة، ساعدي طفلكِ على الاقتناع بأن التغذية مهمة حقًا. لا تسمحي له في الأيام التي لا يتناول فيها الطعام بأن يملأ معدته بحلوى الجيلي أو الأطعمة غير الصحية؛ واشرحي له أن اللعب يصبح أصعب عندما يكون جائعًا وأن طاقته تنخفض. أتيحي له فرصة اختيار ما يأكله. قدّمي له 3 خيارات من الأطعمة الصحية ودعيه يتخذ القرار النهائي. كما أن مساعدته لكِ في إعداد الطعام قد تزيد شهيته. ينبغي لطفلكِ أن يأكل حتى يشعر بالشبع، لا حتى يحين الوقت الذي تحددينه أنتِ للتوقف. وإذا أخبركِ بأنه شبع ولم تلحّي عليه، فلن تجعليه ينفر من الطعام.') WHERE id = '57426f07-6e04-4acb-a14f-3d19459d109e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحمل تعليم الفنون المنظم بشكل سليم في هذه المرحلة إمكانات كبيرة لتنمية إبداع طفلكِ. فالتربية الفنية الصحية والفعالة تساعده على أن يكبر شخصًا مبدعًا يتذوق الجمال من حوله ويبتكر أعمالًا جميلة. ولا توجد قاعدة تنص على أن تعليم الفنون يجب أن يبدأ في المدرسة. فكما تُكتسب المهارات الأساسية الأولى داخل الأسرة، يمكن للطفل أيضًا أن يتعرف إلى الفنون قبل بدء حياته المدرسية إذا كان راغبًا في ذلك ويحظى بدعم أسرته. خصصي لطفلكِ في المنزل طاولة وصناديق للأدوات يسهل عليه الوصول إليها. ومن المهم جدًا لتنمية معارفه وذكائه أن تبحثي معه في حياة أحد الفنانين وتتحدثي معه عن اللوحات. وعند تقييم أعماله، استخدمي عبارات مشجعة وداعمة. وتجنبي الانتقادات مثل: "لا تكون العين فوق الرأس" أو "السماء ليست بهذا اللون". فقد يصنع طفلكِ من المواد المهملة أعمالًا لا تخطر لكِ على بال، ما دمتِ تمنحينه الفرصة والوقت. وإذا أُتيحت له هذه الفرصة في سن مبكرة، فسيبدأ المدرسة وهو أكثر إيجابية واجتماعية وقدرة على التعبير عن نفسه.') WHERE id = 'b288601e-6a7e-4dfe-be66-b4dd1770340c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بعد بلوغ طفلكِ سنًا معينة، يصبح نومه معكِ مشكلة تؤثر في نموه وفي صحة العلاقة بين الوالدين. فالطفل الذي ينام مع والديه سيجد صعوبة في فهم أن لهما مساحة شخصية خاصة بهما. إضافة إلى ذلك، ستتراجع قدرته على النوم بمفرده وتهدئة نفسه. وبعبارة أخرى، سيواجه الطفل الذي ينام دائمًا مع والديه صعوبة في الخلود إلى النوم بمفرده مستقبلًا، لأنه سيشعر بالعجز عندما لا يكون الشخص الذي يهدئه ويهيئه للنوم، أي أحد الوالدين، بجانبه. كما أن النوم في السرير نفسه قد يشكل خطرًا على سلامة الطفل ويؤثر في جودة نوم الوالدين. وعندما ينام الوالدان مع طفلهما، لا يتمكنان من تخصيص وقت أحدهما للآخر، ما يؤثر سلبًا في الجانبين العاطفي والحميمي من علاقتهما. لذلك، إذا كنتِ لا تزالين تنامين مع طفلكِ، فقد حان منذ وقت طويل أن تضعي حدًا لذلك. فكلما تحسنت جودة نومكِ، أصبحت الأوقات التي تقضينها مستيقظة أكثر متعة.') WHERE id = 'c391391b-fd17-4aff-b9b8-249146e9ae1d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحتاج الطفل المنطوي إلى دعم والديه ليتعلم كيفية التواصل بطريقة سليمة. عليكِ مساعدته على الخروج من عالمه وبناء جسر بينه وبين العالم الحقيقي. وعندما يتعذر عليكِ التواصل معه بالكلام، حاولي إنشاء تواصل من خلال التصرفات وتعابير الوجه. إن تركه وشأنه هو الطريق الأسهل، لكنه الأكثر خطأً. عليكِ أولًا أن تتعرفي إلى طفلكِ جيدًا. اكتشفي أكثر ما يثير اهتمامه: هل هي الأصوات؟ أم الألوان؟ أم الحركات؟ وأين وكيف يمكنكِ التواصل معه بأفضل صورة؟ إن إطالة وقت اللعب في كل مرة ثانية أو ثانيتين، وإضافة كلمة أو كلمتين إلى تواصلكما، سيساعدانه على عدم الابتعاد عنكِ وعن محيطه. ومع مرور الوقت، ستزداد رغبته في التواصل مع العالم الخارجي.') WHERE id = '8f9a38dd-ddb8-44a1-9282-56cb4da6e483';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يعرف معظمنا الأطعمة المفيدة التي ينبغي للأطفال تناولها، ولكن ما الذي يتبادر إلى ذهنكِ عند الحديث عن الأطعمة الخطرة؟ تأتي الوجبات السريعة بالطبع في مقدمة القائمة، فالدهون المتحولة الموجودة فيها ضارة جدًا بصحة الأطفال. وتشكل الأطعمة المقلية خطرًا أيضًا؛ إذ تسبب زيادة الوزن وتهدد صحة القلب والأوعية الدموية. كما أن المشروبات الغازية والملونة، فضلًا عن ضررها في تغذية الأطفال واحتوائها على سعرات حرارية غير ضرورية، لا تمد الجسم بأي فيتامينات أو معادن. وتُعد الحلويات والسكاكر، وهي مصدر آخر للسعرات الحرارية غير الضرورية، من الأطعمة الخطرة على الأطفال؛ لأنها تخل بتوازن سكر الدم. أما القهوة فهي من أكثر المشروبات خطورة على الأطفال؛ إذ قد تسبب مشكلات النوم وتسارع ضربات القلب واصفرار الأسنان. لذلك، فهي شديدة الضرر لجسم الطفل ويجب تجنبها.') WHERE id = '9049d2d7-4116-4517-a99a-80cecd0c0b9b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من أكثر الموضوعات التي يتردد كل والد في مناقشتها مع طفله مسألة كيفية مجيء الأطفال إلى العالم. كوني مستعدة مسبقًا حتى تتمكني من التعامل مع الموقف بسهولة عندما تحين تلك اللحظة. وحتى إن لم يسألكِ طفلكِ، فلا بد أن تتحدثي معه عن هذه الموضوعات يومًا ما. اقرئي عنها مسبقًا وحددي ما ستقولينه. واحرصي أنتِ والأب على الاستعداد لذلك معًا. وكما هي الحال في كل موضوع، من المهم أن تتخذا الموقف نفسه. فإذا أخبره أحدكما بأن طائر اللقلق هو الذي أحضره، بينما فرّ الآخر من الغرفة، فهذا يعني أن هناك مشكلة. :)') WHERE id = '1d121936-7622-4838-8d81-9a1fd3ca7851';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عادةً ما تبدأ عادة قضم الأظافر في سن ٣-٤ سنوات، وقد تخف بعد فترة ثم تعاود الظهور خلال مرحلة المراهقة. وعلى الرغم من أن الطفل قد يتعلم هذا السلوك عن طريق تقليد الآخرين، فإنه قد يكون أيضًا علامة على شعوره بعدم الأمان بسبب موقف يثير لديه القلق أو التوتر. ومن أمثلة ذلك تعرّض الطفل للنقد المستمر، أو الغيرة، أو السعي إلى الكمال، أو عدم حصوله على ما يكفي من الحب والاهتمام، أو خضوعه لتربية شديدة الضغط والتسلط. من المهم جدًا أن يحافظ الوالدان على هدوئهما تجاه مثل هذه السلوكيات وألا يبالغا في رد فعلهما. ورغم شيوع سلوكيات مثل قضم الأظافر ومص الأصابع والتبول اللاإرادي لدى كثير من الأطفال، فإنها تزول مع الوقت عند التعامل معها بطريقة صحيحة. وإدراك ذلك هو الخطوة الأولى والأهم.') WHERE id = '9f03c9c1-57bd-4be6-99b4-cf24c5f0befa';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هل كنتِ تعلمين أن طفلكِ قد يُصاب بالاكتئاب أيضًا؟ قد يصعب عليكِ فهم حالته من خلال كلامه، لأن تطور النطق والقدرة على التفكير المجرد لديه لم يكتمل بعد. وهنا تبرز أهمية قوة ملاحظتكِ. تُعد الشهية من أول الأمور التي ينبغي أن تنتبهي إليها؛ فكما هي الحال لدى البالغين، قد يؤدي الاكتئاب لدى الأطفال الصغار إلى فقدان الشهية أو الإفراط في تناول الطعام. ويُعد اضطراب النوم علامة أخرى؛ فقد يواجه الطفل صعوبة في الخلود إلى النوم، أو ينام طويلًا، أو يستيقظ مرارًا خلال نومه. كما تنخفض طاقة الطفل المصاب بالاكتئاب واهتمامه، ولا يرغب في اكتشاف أشياء جديدة. وإذا ساورتكِ الشكوك، فانتبهي أيضًا إلى تعابير وجه طفلكِ ونبرة صوته والألعاب التي يلعبها.') WHERE id = '8ef9e305-ba45-4f0f-bc21-05cb1835ea57';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لأن عضلات المثانة لا تزال غير قوية جدًا في هذه السن، فقد تقع بعض «الحوادث» أحيانًا حتى بعد اكتمال التدريب على استخدام المرحاض. ويُعد ذلك طبيعيًا حتى سن ٦ سنوات تقريبًا. ولا داعي للقلق فورًا، لا سيما إذا كان هناك استعداد عائلي لهذه الحالة. تحلّي أولًا بالصبر ولا تعاقبي طفلكِ. وركّزي اهتمامكِ على طفلكِ لا على الحادثة. وقد تُسهّل عليكِ الحفاضات وأغطية السرير عالية الامتصاص التعامل مع الأمر. كما يساعد اصطحاب الطفل إلى المرحاض أو تذكيره به في أوقات محددة على تقليل حالات التبول اللاإرادي. وإذا تكررت الحالة كثيرًا، فيُنصح بأن تستشيري طبيبًا أولًا للتحقق من الأسباب الجسدية، ثم اختصاصيًا نفسيًا إذا لم يكن السبب جسديًا.') WHERE id = '14f257f5-a3b7-4545-bf29-f1af120629f2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يعيش الأطفال ذوو الحساسية المفرطة وفقًا لمشاعرهم. وقد يواجهون في حياتهم المدرسية صعوبة في شرح الموضوع، لأنهم يبدأون من التفاصيل في كل شيء ويصعب عليهم الوصول إلى النتيجة العامة. ومن ناحية أخرى، قد يكونون شديدي الحساسية تجاه مشاعر الآخرين إلى درجة التوقف عند أدق التفاصيل في تعابير وجوههم. وحتى نظرة أحد الأصدقاء قد تسبب لهم مشكلة داخل الصف. وتنطبق الحساسية ذاتها على مشاعرهم أيضًا؛ فقد يعيشون أحاسيسهم بحدة شديدة، فيلقون بأنفسهم على الأرض عند الحزن، أو يركلون شخصًا ما عند الغضب. وبالطبع، ليست تربية طفل كهذا أمرًا سهلًا. إذا كان طفلكِ مفرط الحساسية، فعليكِ احترام مشاعره ومحاولة الاستعانة بأساليب مختلفة، مثل العلاج باللعب، لمساعدته على إدارة هذه المشاعر.') WHERE id = '284d154e-bcc2-4a5e-8f82-d1327b18c3dd';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ إعداد طاولة خاصة لطفلكِ في المنزل، مع صناديق أدوات يسهل عليه الوصول إليها. ويمكنكِ وضع مواد تجذب انتباهه داخل الصناديق، مثل أقلام التلوين والألوان المتنوعة والمقص والغراء والفرشاة والريش الملون والخرز والمواد اللامعة. يساعد استخدام المقص والغراء والفرشاة على تطوير التناسق بين اليد والعين لدى الطفل، وعلى التفكير في المفاهيم والمشكلات. يمكنه قص الورق المقوّى، ولصق الخرز، وإضفاء الحيوية على أعماله بالألوان الزاهية... وحتى إن عمّت بعض الفوضى في المكان، فعليكِ السماح له بالانشغال بمفرده مستخدمًا الأدوات المتاحة لديه. وكلما ازدادت خبرات طفلكِ، أصبحت أعماله أكثر تنوعًا وحيوية. ومن المهم أن يكتسب تجارب مختلفة لتوسيع آفاقه.') WHERE id = '587604c7-71d5-493d-8249-0631259082d6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'آمني من أعماق قلبكِ بقدرة طفلكِ على التغلب على مخاوفه وقلقه بنفسه. وابتعدي عن فكرة «لن يتمكن من فعل ذلك بمفرده». فالحماية المفرطة للطفل تؤدي إلى استمرار خوفه وقلقه. وإذا كانت البيئة مناسبة، فاسمحي له بالتصرف باستقلالية وعززي شجاعته. لا تحبطي حماس طفلكِ الذي يركض فوق العشب بأن تركضي خلفه خوفًا من سقوطه. أتيحي لطفلكِ فرصة عدم الهروب من مخاوفه ومواجهتها، ولكن لا تضغطي عليه تحت أي ظرف؛ فالضغط على الطفل قد يزيد الأمور صعوبة.') WHERE id = '77d921f8-2e0e-404d-a8d3-9897768c9c98';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'اللعب نشاط بالغ الأهمية للطفل. فمن خلاله يكتشف الأطفال أنفسهم والعالم الخارجي ويحاولون التعرف إليهما. وحتى نهاية مرحلة ما قبل المدرسة على وجه الخصوص، يُعد اللعب من أهم احتياجات الطفل الأساسية، تمامًا كالتغذية والنوم. ويكرر الأطفال أثناء اللعب ما يرونه ويتعلمونه، فيستخدمون إبداعهم ويبتكرون لأنفسهم قصصًا وعوالم مختلفة تمامًا، أما الألعاب فهي أدوات هذه العوالم. وليس من الضروري دائمًا شراؤها من متجر الألعاب؛ فخيال الأطفال قوي إلى درجة أنهم قد لا يحتاجون أحيانًا إلى أي لعبة في أثناء اللعب.') WHERE id = '47b06d03-5efa-4298-8f3b-6e73f0cf8e4e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يكون أسلوب الوالدين سببًا في كذب طفلكِ. فعندما يشعر الطفل بأنه لم يتمكن من إنجاز المهمة المطلوبة بالشكل الذي يريده والداه ذوا التوقعات العالية، قد يلجأ إلى الكذب حتى لا يخيب أملهما. وقد يتصرف بالطريقة نفسها لجذب انتباه أسرته إذا كان لا يحظى بما يكفي من الاهتمام والحب، أو إذا لم تعد الأسرة تخصص له الوقت نفسه بعد ولادة أخ أو أخت جديدين. وإذا كان الوالدان يعاقبانه بقسوة على أي خطأ يرتكبه، فقد يكذب لتجنب العقاب أو يحاول إلقاء اللوم على شخص آخر لينجو بنفسه. ويلجأ الأطفال أحيانًا إلى الكذب للخروج من الموقف عندما يعجزون عن تفسير سبب تصرفاتهم. وإذا أصبح الكذب سلوكًا مستمرًا رغم جميع التدابير والتدخلات، فمن المفيد طلب رأي مختص.') WHERE id = 'a0df7747-9080-47dd-b5f1-105b7749b644';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من خلال مراقبة طفلكِ منذ سنوات طفولته المبكرة، يمكنكِ تكوين فكرة عن المجالات التي تثير اهتمامه. ويمكنكِ أيضًا تشجيعه على تجربة مجالات مفيدة لنموه، ما يمنحكِ فرصة لاكتشاف اهتماماته. فعلى سبيل المثال، يمكنكِ توجيهه إلى الجمباز لتنمية التناسق الجسدي، والدراما الإبداعية للتعبير عن نفسه، والشطرنج لتعزيز التفكير الاستراتيجي والقدرة على الاستدلال، وكرة السلة أو أنشطة مشابهة لتنمية روح الفريق. وإذا كان يشارك بحماس ويستمتع بما يفعله، فيمكنكِ دعمه والبحث عن سبل تساعده على التطور في ذلك المجال. أما إذا كان طفلكِ يشتكي باستمرار ولا يبدو سعيدًا، فيمكنكِ التحدث معه وتقييم الوضع. وإذا لم يكن راضيًا، فاسأليه عما يود ممارسته وابحثا معًا عن خيارات أخرى. ولأن الطفل لا يمتلك في البداية خبرة في أي مجال، فعليكِ الاستمرار في إتاحة فرص جديدة له حتى يكتشف ما يثير اهتمامه.') WHERE id = '68f978ea-5a44-4322-bd40-20cb94d0fbc1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ قد رأى تساقط الثلج من قبل، فمن المرجح أنه أحبه كثيرًا. لكن قد لا يكون الطقس الثلجي متاحًا دائمًا. في هذه الحالة، يمكنكِ تنظيم معركة خيالية بكرات الثلج. اجمعي قصاصات الورق والإيصالات والصحف المستعملة، ثم كوّري جزءًا منها على شكل كرات ومزقي الجزء الآخر إلى قطع صغيرة. ستمثل كرات الورق كرات الثلج، والقطع الصغيرة رقاقات الثلج. اجتمعوا ذات مساء وارتدوا قفازاتكم. انثروا جميع قصاصات الورق كأنها ثلج متساقط، وخوضوا معركة بكرات الورق. نتمنى لكم وقتًا ممتعًا!') WHERE id = 'a9056ba4-a954-4bc7-956a-5a7bad300b83';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد فيتامين D مهمًا جدًا لنمو العظام والعضلات، ووظائف الدماغ، والجهاز المناعي. وتوفر أشعة الشمس 90-95% من احتياجات الجسم من فيتامين D، بينما يُحصَل على النسبة المتبقية من الطعام. ويكفي تعرض يدي طفلكِ ووجهه لأشعة الشمس مدة 10 دقائق فقط يوميًا في الحديقة للمساعدة على تصنيع فيتامين D. وقد تكون الزيادة على ذلك ضارة بطفلكِ. ويجب خصوصًا تجنب التعرض للشمس بين الساعة 10:00 و14:00، حين تكون أشعتها في أشدها، ومن الأفضل قضاء هذه الساعات في أماكن مغلقة.') WHERE id = '325b0b4a-e376-48f0-a0fe-eb9238a52843';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ دعم طفلكِ بألعاب متنوعة لتنشئته على أن يكون جزءًا من الحل لا من المشكلة. ويمكنكِ أن تلعبي معه لعبة “الحل عندي”، وهي لعبة بسيطة يمكن ممارستها حتى في أثناء التنقل بالسيارة. يتناوب الجميع على طرح مشكلة قد يواجهها أي شخص ثم يسألون: “ماذا ينبغي أن يفعل؟”. مثلًا: “ماذا ينبغي أن يفعل طفل ضل عن أمه في السوق؟” أو “خرجت من المنزل ثم اكتشفت أنني نسيت مفتاحي، ماذا أفعل؟”. والهدف الأساسي هنا هو محاولة اقتراح أكبر عدد ممكن من الحلول. وتساعد هذه اللعبة طفلكِ على إدراك أن “أي شخص، مهما كان عمره، قد يواجه مشكلة” وأن “لكل مشكلة أكثر من حل محتمل”.') WHERE id = 'cfd8fd4a-c967-4e98-ae2e-bee33b97219d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي لكِ تخصيص وقت لطفلكِ، والعثور على مواضيع متنوعة للتحدث معه، ومنحه فرصة التعبير عن رأيه كثيرًا. وأثناء الحديث، انظري في عينيه، وأنصتي إليه باهتمام، وأشعريه بأنكِ تقدّرين أفكاره. كلّفيه بمهام تناسب عمره، وقدّري نجاحاته، ولا تقلّلي من شأنه أمام الآخرين. تجنّبي مقارنته بالأطفال الآخرين أو انتقاده وإصدار الأحكام عليه. وشجّعيه على التحدث أمام الناس. كوني حساسة تجاه رغبات طفلكِ واحتياجاته، وأتيحي له فرصًا للنجاح، واحترمي أفكاره، وامتدحيه عندما يتخذ خطوات صحيحة. تذكّري أن مجرد تقديم النصائح أو محاولة إجباره على طاعة كلامكِ لا يُعدّ تواصلًا حقيقيًا؛ فالتواصل ينبغي أن يكون متبادلًا.') WHERE id = '089d3994-9ba4-466d-b069-c4fef620e5c6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نعتقد أحيانًا أن الأطفال لا يحبون القواعد، لكن الأطفال الذين يكبرون في ظل القواعد، أي الحدود، يكونون في الواقع أكثر سعادة. يحتاج الأطفال إلى معرفة إجابات أسئلة مثل: «ما الذي يمكنني فعله وإلى أي حد؟»، و«إلى أي مدى يمكنني الإلحاح عندما أريد شيئًا؟»، و«كيف أتحدث مع كل شخص، وكيف أتعامل معه؟»؛ أي إنهم يحتاجون إلى معرفة مواضع الحدود. ويتعلمون ذلك في المنزل من خلال القواعد التي يضعها الوالدان وكيفية تطبيقها. تساعد الحدود على تنمية ثقة الأطفال بأنفسهم وعلى إعدادهم ليصبحوا أفرادًا مسؤولين في المستقبل. وعندما لا يدرك الطفل مفهوم الحدود، قد تصبح سلوكياته غير منضبطة ويواجه المشكلات باستمرار. ويُعد وضع حدود مناسبة مهمًا، في المقام الأول، للحفاظ على سلامة الأطفال وشعورهم بالأمان. كما تعزز قواعد المنزل الترابط بين أفراد الأسرة، وتُنمّي لدى الأطفال شعور الانتماء الذي يحتاجون إليه.') WHERE id = '699e3b68-c7e4-4d03-b2e2-74df09355eb7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدءًا من عمر 2.5 سنة، يبدأ الأطفال بتقليد ما يرونه من أحداث وسلوكيات. ولعلكِ لاحظتِ ذلك بالفعل. فطفلكِ، الذي كان أكبر مقلّديكِ منذ يوم ولادته، يراقبكِ دائمًا. لكن عندما يشاهد التلفاز والرسوم المتحركة من حين إلى آخر، تصبح شخصيات الرسوم المتحركة من بين الشخصيات الأخرى التي يقلّدها. ويزداد تأثير الرسوم المتحركة بين عمر 3-6 سنوات، لأن الأطفال يبدؤون في فهم الأحداث التي يشاهدونها وتفسيرها. وبما أن الأطفال، ولا سيما من هم دون سن 6 سنوات، لا يستطيعون التمييز بوضوح بين الواقع والخيال، فقد تخيفهم بعض الشخصيات وتُخلّ بنظام نومهم. وقد يحاولون أحيانًا تقليد الجوانب المخيفة أو غير الملائمة في هذه الشخصيات. وكثيرًا ما نجد أن مخاوف الطفل الشديدة وسلوكياته السلبية ترجع إلى مشاهدته رسومًا متحركة لا تناسب عمره أو تحتوي على مضمون غير ملائم. كما أن قضاء وقت مفرط أمام الرسوم المتحركة قد يؤثر سلبًا في نمو الأطفال العقلي والعاطفي والإدراكي، وكذلك في قدرتهم على التفاعل الاجتماعي.') WHERE id = '204f1ab3-594f-4639-b9b4-a3571ef26185';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المهم جدًا وضع حدود معينة لضمان سلامة الأطفال وشعورهم بالأمان، وشرح أسباب وضع هذه الحدود لهم بوضوح. لكن ينبغي ألا يُقدَّم هذا الشرح في لحظة الأزمة، بل قبل وقوع الموقف أو بعد أن تهدئي أنتِ وطفلكِ. ينبغي أن يعرف، مثلًا، أن عليه النوم في الساعة 21:00 لكي ينمو ويتمكن من الركض بسرعة، أو أن عليه البدء بواجباته في الساعة 15:00 لكي يتوفر له وقت أطول لنفسه وتتمكنوا من تناول الطعام معًا كأسرة. وستسهّل كتابة القواعد عليكِ وعلى طفلكِ الالتزام بها. وعند وضع الحدود، تجنّبي التهديدات مثل «إذا لم تفعل ... فلن تتمكن من مشاهدة التلفاز»، وكذلك الصراخ وإصدار الأوامر مثل «اذهب إلى فراشك بسرعة». فمثل هذه العوائق في التواصل تزيد الموقف توترًا. وكما أن من المهم أن يفهم طفلكِ أسباب هذه الحدود، فمن المهم أيضًا أن تدركي أنتِ سبب أهميتها. ينبغي أن تهدف القواعد إلى حماية الأطفال، لا إلى تنفيذ رغباتنا لمجرد أننا الوالدان.') WHERE id = '581c4ace-4612-4470-a608-3338a8a27acc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ استخدام الألعاب الإبداعية لمساعدة طفلكِ على التعرّف إلى مشاعره. على سبيل المثال، أحضري مرآة واطلبي من طفلكِ التعبير عن أي شعور بتعابير وجهه، ثم حاولي أنتِ، بصفتكِ «المرآة»، تخمين ذلك الشعور. وقبل مساعدة الأطفال على فهم مشاعرهم، من المفيد تقييم مدى قدرتنا نحن على التعرّف إلى مشاعرنا. فالأطفال أكثر عفوية من البالغين في التعبير عن مشاعرهم. لذلك، كلما كنتِ أكثر صراحة وصدقًا معه، قلّت التساؤلات التي تدور في ذهنه. أتيحي لطفلكِ في كل موقف فرصة مشاركة مشاعره. وهكذا سيتعلم التعبير عما يشعر به في المواقف المختلفة.') WHERE id = '92b069a8-d682-4b32-84a6-aab5d12cd89b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبحت التكنولوجيا جزءًا لا يتجزأ من حياتنا. وينبغي أن يشبه تعاملنا معها أسلوب حمايتنا للأطفال من الجراثيم. فلا بد من اتخاذ التدابير اللازمة لتوفير حياة نظيفة وصحية لطفلكِ. لكن إذا بالغنا في الحذر أثناء تربيته ومنعناه من التعرّض لأي جراثيم أو بكتيريا، فسنعوق تقوية جهازه المناعي وقدرته على مكافحة الأمراض مستقبلًا. وبالمثل، فإن إبعاد الأطفال عن التكنولوجيا تمامًا يعني تركهم غير مستعدين للحياة المستقبلية. لذلك، يُنصح باستخدام التكنولوجيا بشكل محدود وتحت الإشراف. ويُقصد بالاستخدام الخاضع للإشراف ألا يُترك الطفل بمفرده مع أي جهاز إلكتروني على الإطلاق.') WHERE id = '728345bf-ef92-4c1c-af86-eddf7faece6d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لوجبة الإفطار أهمية كبيرة، لا سيما للأطفال، ولها فوائد عديدة لأجسامنا. فهي تعوّض الطاقة التي نفقدها بعد الاستيقاظ وتساعد على توازن سكر الدم. كما تسهم في تنظيم عملية الأيض، لذلك ينبغي عدم إهمالها مطلقًا. وتُعد الأطعمة الصحية التي يتناولها طفلكِ على الإفطار مصدرًا مهمًا للطاقة. كذلك تتمتع الفواكه والخضراوات التي يتناولها في هذا الوقت بقيمة غذائية كبيرة. وبالطبع، لا غنى عن الحليب؛ إذ ينبغي أن يكون حاضرًا على مائدة الإفطار لدعم نمو طفلكِ. وإذا كنتِ تتساءلين عمّا يمكنكِ تحضيره للإفطار، فيمكنكِ الاختيار من بين عدة خيارات، مثل الخبز المحمّص بجبن القشقوان، والعجة بأنواع مختلفة من الجبن، والبيض المسلوق، والمعجنات بالزيتون والجبن، وعصير الفاكهة الطازج، وشطيرة محضّرة بالطماطم والخضراوات الطازجة، والحليب الدافئ، والعسل والزبدة.') WHERE id = 'd0a45b88-13a0-4c9d-a3d1-ee5237e9d55c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يجد الأطفال الذين نصفهم بأنهم «انطوائيون» صعوبة في التعبير عن أفكارهم بالكلمات، وقد يتحدثون ببطء. فليس من السهل عليهم العثور على الكلمات التي تعبّر عمّا يفعلونه أو يشعرون به أو يريدونه. إذا كان طفلكِ انطوائيًا، فقد يكون الحديث معه عن يومه مرهقًا لكِ بعض الشيء. وقد تشعرين بأنكِ عاجزة عن تقديم أي شيء لطفلكِ المنغلق تجاهكِ وغير المتفاعل مع محيطه. فمن الصعب الاستمرار في محاولة الاهتمام بشخص لا يتجاوب معكِ. لكن طفلكِ يواجه ببساطة صعوبة في التكيّف مع العالم الخارجي، ويحتاج إلى دعمكِ كي يتمكن من التواصل معه بطريقة سليمة. يمكنكِ دعمه من خلال إجراء الكثير من الحوارات معه وإتاحة الفرصة له للوجود في بيئات مختلفة، من دون إجباره على شيء.') WHERE id = 'cc456fa9-05c6-4f38-af3f-116a66f4f31a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'حتى إذا لم تكن لدى طفلكِ أي شكوى أو مشكلة صحية، فإن خضوعه للفحوص الدورية بانتظام يؤدي دورًا مهمًا في التشخيص المبكر للأمراض وعلاجها. ومن المهم أن يخضع الأطفال الذين أُجريت لهم الفحوص الروتينية الشهرية وتلقّوا لقاحاتهم في مواعيدها خلال مرحلة الرضاعة لفحص صحي أيضًا قبل بدء المدرسة. وينبغي أن نولي اهتمامًا خاصًا للبصر والسمع وفقر الدم وصحة الفم والأسنان. كما يجب متابعة نمو الطفل عن كثب ومقارنته بمخططات النمو المعيارية، واكتشاف أي انحراف عن المعدلات الطبيعية مبكرًا والتعامل معه قبل أن يترك أثرًا دائمًا لدى الطفل. ويهدف فحص الطفل إلى الكشف عن أي مشكلات تتعلق بالتغذية أو النمو أو الصحة النفسية، بالإضافة إلى اكتشاف الوهن وفقدان الشهية وفقر الدم والعدوى والأمراض الطفيلية من خلال تحاليل البول والدم والبراز. تساعد هذه الفحوص على اكتشاف المشكلات سريعًا وتسريع علاجها خلال مرحلة النمو المتسارع لطفلكِ، ما ينعكس إيجابًا على نجاحه في المدرسة. وخلال الفحص، ينبغي إطلاع الطبيب على الأمراض التي أُصيب بها الطفل وعلى التاريخ المرضي للعائلة، مع الحرص على تقديم بطاقة التطعيمات.') WHERE id = 'cda4bc4e-2317-4abc-a999-700edd269e6b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'غالبًا ما لا يفهم طفلكِ مشاعره تمامًا، فيعبّر عنها بالطريقة الوحيدة التي يعرفها، أي من خلال سلوكياته. ساعديه على التعرّف إلى مشاعره والتعبير عن نفسه بصورة أفضل، من خلال توضيح كيفية التعامل معها. اشرحي له المشاعر بكلمات يسهل عليه فهمها، واستعيني بالكتب أو الأفلام أو الصور. وتحدّثي معه عن كيفية استجابته في المواقف التي يواجهها كثيرًا، مع ذكر أمثلة عليها. يمكنكِ أن تقولي مثلًا: «شعرتَ بالحزن أمس لأن أخاك لم يسمح لك باللعب بسيارته. ماذا يمكنك أن تفعل أيضًا عندما يحدث ذلك؟» وعندما يبدأ طفلكِ بالتحدث عن مشاعره، احرصي على الثناء عليه. وحاولي أيضًا أن تبيّني له من خلال سلوككِ أن الحديث عن مشاعرنا أمر طبيعي.') WHERE id = '89de6ef5-d3a0-485d-a9cf-b3777a44859f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في اليوم الذي ستجعلين فيه طفلكِ ينام في سريره الجديد للمرة الأولى، احرصي على أن تسير الأمور وفق الروتين المعتاد، وطبّقي طقوس النوم نفسها إن كانت لديكم طقوس ثابتة. يمكنكِ قراءة كتاب معه على أنغام موسيقى هادئة تساعده على الشعور بالنعاس، أو إعطاؤه قليلًا من الحليب. ينبغي ألا يتناول الطفل الطعام خلال الساعة السابقة للنوم، وأن يبتعد عن الأجهزة الإلكترونية إن أمكن. لا تستلقي بجوار طفلكِ في السرير، بل اجلسي عند رأسه في مكان يمكنه رؤيتكِ منه بسهولة، وربّتي برفق على ظهره أو امسحي على رأسه. وبعد أن ينام، يمكنكِ مغادرة الغرفة بهدوء. وكلما ناداكِ، اذهبي إليه، وإذا جاء إليكِ فأعيديه إلى سريره. وفي كل مرة تذهبين فيها إليه، تحدثي بصوت هادئ ومطمئن، ويمكنكِ أيضًا أن تغنّي له تهويدة. ومع مرور الوقت، سيقلّ مناداته لكِ.') WHERE id = 'b6382df9-f84f-4149-b53c-e70310da9e86';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ يخجل من التحدث عندما يكون محطّ الأنظار بين الناس، ويُظهر أشكالًا مشابهة من التردد والخجل، فقد يكون مصابًا بالرهاب الاجتماعي. لا تجبريه على فعل أي شيء، ولا تصفيه مطلقًا بكلمات مثل «جبان» أو «متردد» أو «خجول». وإذا استمر تردده، فلا تغضبي منه ولا تبالغي في التركيز على الموضوع. امنحيه وقتًا حتى يعتاد البيئة المحيطة. وقبل الذهاب إلى مكان جديد أو غير مألوف، هيّئي طفلكِ لذلك. إن تواصلكِ براحة مع الآخرين وعدم توتركِ نيابةً عنه سيقدمان له مثالًا جيدًا ويساعدانه على الشعور بالارتياح. أتيحي لطفلكِ خوض تجارب جديدة في بيئات آمنة، ثم انتقلي معه تدريجيًا إلى أماكن أكثر ازدحامًا. شجّعيه، لكن تجنّبي تحميله مسؤولية تفوق قدرته بعبارات مثل: «أنت قادر على ذلك، وأنا أثق بك!».') WHERE id = '6ec92942-7f5e-461d-a62e-0f93076b7c64';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'كلما كان التناسق الحركي لجسم طفلكِ أفضل، زاد احتمال أن تكون مهاراته اليدوية أفضل أيضًا. لذلك، فإن تنمية المهارات الحركية الكبرى المسؤولة عن تناسق حركة الجسم أمر بالغ الأهمية. وأولى التوصيات لتنمية هذه المهارات هي توفير البيئة والفرص المناسبة لطفلكِ كي يلعب ويركض ويتسلق ويقفز في الحديقة أو المتنزه. ويمكنكِ تشجيعه على قضاء الوقت في استخدام وسائل تساعد على تحسين التوازن، مثل الدراجة الهوائية والسكوتر والزلاجات ولوح التزلج. كما يمكنه ممارسة أنشطة مثل الوقوف على قدم واحدة، والتقاط غرض من الأرض أثناء الوقوف على قدم واحدة، والمشي على خط مستقيم، والمشي إلى الخلف، والمشي على أطراف الأصابع، والقفز بالحبل. ويمكن أيضًا ممارسة ألعاب تتطلب تنسيق الحركة مع الكرات المتحركة، مثل الكرة الطائرة وكرة السلة. كذلك تساهم الشقلبات الأمامية والخلفية في تنمية المهارات الحركية الكبرى. وعند جمع الألعاب، يمكنكِ إضفاء بعض المرح على المهمة بأن تطلبي منه استخدام قدميه الحافيتين بدلًا من يديه.') WHERE id = '726e9d06-259a-400d-a7f5-6b490b91ea18';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نظرًا إلى أننا لا نستطيع تربية أطفالنا في بيئة معزولة، فمن المفيد التعرّف إلى الأمراض الشائعة ومعرفة التدابير البسيطة التي يمكننا اتخاذها. ولأن أوبئة الإنفلونزا تنتشر غالبًا بين الأطفال في سن المدرسة، يوصى خصوصًا بالحصول على لقاح الإنفلونزا. لا تُستخدم المضادات الحيوية لعلاج الإنفلونزا، بل يُنصح بالإكثار من السوائل والراحة واستخدام المحلول الملحي لتخفيف احتقان الأنف. أما نزلة البرد فتكون أخف من الإنفلونزا، وغالبًا ما يصاحبها إفراز أنفي كثيف القوام. ويكون علاجها مماثلًا لعلاج الإنفلونزا، ولا تتطلب استخدام المضادات الحيوية.') WHERE id = '6412b307-c910-4c3a-9e90-d2cf441a49d0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عند إعداد وجبة الغداء لطفلكِ، يمكنكِ إعطاء الأولوية للخضروات ذات الألوان الزاهية، مثل البروكلي والطماطم والفلفل والجزر وغيرها. وينبغي أن تحتوي وجبة الغداء الصحية أيضًا على البروتين والفواكه والحبوب. اختاري الفاكهة الكاملة بدلًا من عصير الفاكهة، فبهذه الطريقة يمكن لطفلكِ تناول قشرتها أيضًا والحصول على فيتامينات إضافية. وإذا كان طفلكِ يختار وجبة غدائه بنفسه، فعليكِ تعليمه اختيار أطعمة صحية لا تحتوي على كميات كبيرة من الملح والدهون. وعندما تدعينه إلى تناول الغداء، قد يجيبكِ قائلًا: «أنا شبعان». في مثل هذه الأوقات، قد تكفي حتى حصة صغيرة ليحصل طفلكِ على الفيتامينات والمعادن التي يحتاج إليها.') WHERE id = '513df970-25cf-4dca-baaf-582abc429420';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تساعد إجراءات النظافة الشخصية على الوقاية من الكثير من الأمراض المعدية. وتُعد نظافة اليدين أكثر الوسائل فعالية في الوقاية من العدوى التي تسببها الكائنات الدقيقة. وتُظهر الدراسات أن غسل اليدين بطريقة صحيحة وحده يحمي الأطفال من العديد من الأمراض المعدية. وقد لوحظ أن استخدام الصابون والتثقيف بشأن نظافة اليدين يقللان التهابات الجلد بنسبة 34%، والأمراض المصحوبة بالإسهال بنسبة 55%، والالتهاب الرئوي بنسبة 50%. كما يساعد ذلك على تقصير مدة المرض. عليكِ تعويد طفلكِ على غسل يديه قبل كل وجبة وبعدها، وعند العودة من الخارج، وبعد استخدام المرحاض. اسمحي له بغسل يديه بنفسه، مع الحرص في الوقت نفسه على عدم هدر المياه.') WHERE id = '63c0a769-d0da-451c-88a4-2461e95014c4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يبدأ بعض الأطفال أحيانًا بالتبول اللاإرادي فجأة، رغم أنهم لم يعانوا هذه المشكلة من قبل. أي إن المشكلة تعود إلى الظهور بعد بقائهم جافين مدة طويلة. وإذا لم يكن السبب الكامن وراء ذلك جسديًا، فقد يكون نابعًا من رغبة الطفل في جذب الانتباه. وقد يلجأ إلى ذلك خصوصًا الأطفال الذين لا يحظون بالاهتمام المعتاد من والديهم بسبب تغيير طرأ على حياتهم، أو الذين يخشون ألا يحصلوا على ذلك الاهتمام. وقد يبدأون بالتبول اللاإرادي أحيانًا عن وعي، وأحيانًا من دون قصد. عليكِ أن تفهمي الرسالة التي يحاول طفلكِ إيصالها إليكِ بهذه الطريقة، مثل: «أنتِ لا تهتمين بي»، أو «لم أحب مدرستي الجديدة»، أو «لماذا لدي منزلان؟»، أو «أنا خائف جدًا من كلب الجيران»، وغيرها. وبناءً على ذلك، من المؤكد أن إجراء حوار داعم مع طفلكِ يخفف مخاوفه سيساعده.') WHERE id = '7891d564-4371-4763-ac8c-ce9411e6d6b6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لكي تبني علاقة وثيقة مع طفلكِ، عليكِ أن تستطيعي التفكير مثل الأطفال. حاولي أن تتذكري ما كنتِ تحبينه وما لم تكوني تحبينه عندما كنتِ في عمره، وما المواقف التي مررتِ بها. سيمنحكِ ذلك فكرة عن كيفية التقرب من طفلكِ. حددي الألعاب والأنشطة التي تستمتعين بها من بين ألعابه وأنشطته. أنصتي إلى طفلكِ باهتمام، وكوني واعية لما يفعله وما يقوله. لا توضحي له كيفية فعل شيء ما ما لم يسألكِ بنفسه، ولا تنجزي المهام نيابةً عنه ما لم يطلب منكِ ذلك. إن بناء علاقة متينة مع طفلكِ مهم جدًا ليستمتع بحياته ويصبح واثقًا بنفسه.') WHERE id = '95abd014-39f4-4997-bebe-7dc583d1e9d6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ترتبط الزيادة السريعة في انتشار الأمراض المزمنة في عصرنا بالوزن الزائد الناتج عن التغذية غير الصحية خلال مرحلتي الطفولة والمراهقة. وستسهم برامج التغذية الصحية في المدارس بفاعلية في تعزيز صحة طفلكِ الجسدية وقدرته على استيعاب الدروس. كما أن عادات التغذية الصحية والمتوازنة التي يكتسبها الطفل في هذه المرحلة تستمر معه حتى مرحلة البلوغ. ولمساعدة طفلكِ على اكتساب عادات غذائية سليمة، تابعي قوائم الوجبات إذا كانت المدرسة تقدم الطعام. وتحدثي معه يوميًا عما تناوله في المدرسة، وقدّمي له معلومات عن الأطعمة. ومن الضروري متابعة أنواع الطعام التي يميل إليها طفلكِ، وتعريفه بالأطعمة المفيدة والضارة، وتقديم الأطعمة الصحية التي لا يحبها بطريقة جذابة تناسب ذوقه.') WHERE id = '9f6d0d64-8534-4e87-96a0-bb91788dbecf';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'الطفل الذي يشعر بأنه قادر على حل المشكلات يتمتع بثقة عالية بالنفس وصورة ذاتية إيجابية. ولكي تربي طفلكِ على الميل إلى حل المشكلات، يمكنكِ أن توضحي له أن المواقف الصعبة فرص تساعد الإنسان على أن يصبح أقوى. وتذكّري أن أسلوبكِ في النظر إلى المشكلات يُعد نموذجًا لطفلكِ. وبما أن الحياة الخالية من المشكلات غير ممكنة، فركّزي على إيجاد حلول فعّالة بدلًا من القلق أو التوتر أو الشكوى عند مواجهة الصعوبات. وأتيحي لطفلكِ فرصة الاجتماع بأقرانه باستمرار حتى يواجه مواقف ومشكلات متنوعة. وهكذا سيتمكن، من خلال ملاحظة طرق أقرانه المختلفة في الحل وبإرشادكِ، من التعرّف إلى الأساليب الصحيحة والخاطئة. وعندما يشعر بأنه مستعد، سيبدأ باتخاذ خطوات لحل مشكلاته بصورة مستقلة.') WHERE id = '8e3ea6cd-c010-4704-bb9d-bc67237f7778';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بما أن اللعب مهم إلى هذا الحد في حياة طفلكِ، فلا تحرميه من زيارة متاجر الألعاب. فعندما تضعين قواعد محددة، وتشرحين أسبابها، وتتعاملين بلطف وحزم في الوقت نفسه، لن تتحول زيارة متجر الألعاب إلى كابوس. وهذا خيار أفضل من إبقاء الطفل أمام التلفاز أو الحاسوب. بل اختارا الألعاب معًا. ومن الطبيعي أن يكون توجيهكِ مهمًا، إذ ينبغي ألا تُختار الألعاب عشوائيًا. ويجب أن تكون ملائمة لعمر الطفل، علمًا بأن الفئة العمرية المناسبة تكون مذكورة على كثير من الألعاب. كذلك، يُفضّل تجنب الألعاب التي تشجع على العنف، مثل المسدسات والبنادق والسيوف.') WHERE id = '45bdf144-6065-4fb2-a745-392e89e7fa6e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يؤدي تعليم الفنون في مرحلة ما قبل المدرسة دورًا إيجابيًا في النمو النفسي لطفلكِ. فمن خلال الفن، يمكنكِ مساعدته على إدراك الخير والصواب والجمال، وتمكينه من إحراز تقدم كبير في طريقه نحو الاندماج الاجتماعي. ويحظى الطفل الذي يحقق الإشباع النفسي من خلال تعليم الفنون بفرصة لاكتساب نمو معنوي سليم وشخصية قوية. كما تساعد الأنشطة الفنية في هذه المرحلة طفلكِ على اكتساب مهارة العيش بسعادة مع الأطفال الآخرين. وهي فعّالة جدًا في تطوير قدرته على فهم الحياة وتفسيرها، وتعزيز إبداعه وطريقة تفكيره. فالأطفال الذين يتلقون تعليمًا فنيًا ثريًا يتطور لديهم الحس الجمالي والمهارات الفنية، كما يسهل عليهم فهم أسباب المشكلات التي يواجهونها. ومن خلال الفن، يتعرّف الطفل إلى العلاقة بين الطبيعة والإنسان، ويدرك ثراء الحياة، ويهيئ بتفكيره الإبداعي المتفرّد أساسًا لنموه الفكري في المستقبل.') WHERE id = 'a4e9140d-14c0-4a81-91a1-6495e44a4c8b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ باستخدام بضعة صناديق كبيرة وبطانيات أو ملاءات قديمة بناء مدينة أو مركبة فضائية أو ساحة سيرك. أفرغي مساحة داخل المنزل أو في الفناء، واجمعي البطانيات والأغطية القديمة. واستخدمي الأريكة أو الأرجوحة أو أثاث الحديقة والوسائد التي يمكن إسناد الأغطية إليها لإنشاء هياكل تشبه الخيام. وإذا كانت المواد المستخدمة مصنوعة من القماش، فيمكنكِ الاستعانة بالدبابيس لتثبيت الأغطية. بل يمكنكِ أيضًا قص أطراف الأغطية وربطها معًا بخيط أو شريط لصنع "قلعة" أكثر متانة. وبهذه الطريقة، يمكنكِ إنشاء مساحات لعب ممتعة مع طفلكِ والاستمتاع بالوقت الذي تقضيانه معًا.') WHERE id = '7549a661-8c38-4421-b89c-b22ed99e82d2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يتصرف الأطفال في هذه المرحلة بطرق تخالف تمامًا القوالب التي يصنفها المجتمع على أنها "سلوك للفتيات" أو "سلوك للفتيان". فعلى سبيل المثال، قد يرغب الفتيان في ارتداء التنانير، بينما قد ترغب الفتيات في اللعب بالسيارات. وهذه الرغبات طبيعية تمامًا، وغالبًا ما تظل كما هي بغض النظر عن تدخلكِ. والأهم ألا تقيّدي طفلكِ أو تعامليه بقسوة، فهو في الواقع يحاول اكتشاف حدوده من خلال تقليد سلوكيات الجنس الآخر. وتقل تجارب استكشاف الهوية الجنسية لدى معظم الأطفال بمرور الوقت. بل إنهم بعد هذه المرحلة قد ينتقلون إلى فترة أكثر تحفظًا لا يلعبون فيها إلا مع أطفال من الجنس نفسه. وباختصار، لا تستدعي تصرفات طفلكِ الهادفة إلى استكشاف الهوية الجنسية خلال مرحلة ما قبل المدرسة الخوف؛ فهذا الفضول سيتلاشى تلقائيًا مع تقدمه في العمر.') WHERE id = 'a65af59e-6078-49d9-b24e-e31adb692908';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'الدراما الإبداعية هي تجسيد موضوع ما داخل مجموعة، بالاستناد إلى تجارب الأطفال، باستخدام تقنيات مثل الارتجال ولعب الأدوار. وهي وسيلة تعليمية ممتازة تزيد وعي الطفل بذاته وبالآخرين وبالعالم، وتنمّي خياله. كما أنها نشاط جماعي يكتسب الأطفال من خلاله مهارات التفكير والتحدث والاستماع والفهم. وتتطور مهاراتهم اللغوية بصورة طبيعية نتيجة التواصل داخل المجموعة. ويتعلم الطفل التعاون والمشاركة والتضامن واحترام الآخرين. ومن خلال معايشة الأحداث وملاحظتها وابتكارها، يعزز الطفل أسس تواصله الاجتماعي. كما يتخلص من التوتر الداخلي بفضل إتاحة الفرصة له للتعبير عن مشاعره بحرية.') WHERE id = '320de852-acf0-404e-a2a3-5e05210f0a3c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين خلال هذه الأشهر تغيرات كثيرة في سلوك طفلكِ الاجتماعي. فقد أصبح الآن أكثر استقلالية مقارنة بالسنوات السابقة، وأقل احتياجًا إلى دعم البالغين. ويبدأ حس الفكاهة لديه بالتشكل، كما يكوّن صداقات وثيقة. ويستمتع بقضاء ساعات في ممارسة ألعاب تقمص الأدوار المختلفة مع أقرانه. وقد تنشأ بينهم خلافات من حين إلى آخر عندما تتعارض رغباتهم، إلا أن ذلك طبيعي. وتتطور في هذه المرحلة سريعًا مفاهيم المشاركة وانتظار الدور والتعاون.') WHERE id = '0b8e47f0-43bb-47d3-8d35-fa6211dcea40';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لدينا لعبة نقترح أن تمارسيها مع أفراد الأسرة! اختاري لونًا لبدء اللعبة. أخبري طفلكِ أنكم ستقيمون "حفلة اللون"، وارتدوا ملابس بهذا اللون. ثم انطلقوا في رحلة بحث داخل المنزل عن الأشياء التي تحمل اللون المختار. وعلى جميع أفراد الأسرة العثور خلال مدة محددة على أشياء بهذا اللون وجمعها في مكان واحد. وعند انتهاء الوقت، فليحسب كل شخص الأشياء التي وجدها. يفوز الشخص أو الفريق الذي جمع أكبر عدد من الأشياء. نتمنى لكم وقتًا ممتعًا!') WHERE id = '361e8279-e73c-4364-8803-b9d9b51e4324';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إن توقّع التفوق من طفلكِ في كل مجال سيُشعره بقلق وتوتر شديدين. تذكّري أن الأهم هو استمتاعه بالنشاط الذي يمارسه. نلاحظ أحيانًا أن بعض الآباء يقارنون أطفالهم بالآخرين. وفي هذه الحالة، لا يستطيع الطفل الاستمتاع بما يفعله، ولا يشعر بأنه قادر على إرضاء أسرته. وليس من الواقعي أن تتوقعي من طفلكِ أن يكون مثاليًا في كل مجال. فلكل طفل عالمه و"لونه" الخاص، ومهمة الوالدين والمعلمين هي اكتشاف هذا التفرد. ومع مرور الوقت، كلما تعرّف الطفل إلى ذاته وأُتيحت له الفرص، ستلاحظين أنه يتجه تلقائيًا نحو المجالات التي تتوافق مع اهتماماته.') WHERE id = '6f5f0110-056b-4dc9-95c9-abd1628f7493';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بما أن طفلكِ أصبح قادرًا على الكلام، يمكنكما اختيار الألعاب معًا. وإلى جانب الألعاب التي تدعم نموه الذهني، مثل الأحجيات ومكعبات الليغو وبطاقات المطابقة وغيرها، يمكنكِ شراء ألعاب تدعم نموه البدني أيضًا، مثل الكرة والبولينغ المصغّر والدراجة وعجينة اللعب وغيرها. كما يمكنكِ اختيار ألعاب ممتعة تناسب اهتماماته، مثل مجموعات أدوات التصليح أو أدوات الطبيب أو مجسمات الحيوانات. ولأن سن الرابعة تندرج ضمن مرحلة ما قبل المدرسة، يُنصح أكثر بأنشطة تلوين الخزف ونظم الخرز والآلات الموسيقية وألعاب البناء البسيطة. وستكون الألعاب الجماعية، مثل رمي السهام وسلة كرة السلة وغيرها، تجربة جديدة وممتعة للطفل. ويُنصح أيضًا بتخصيص وقت لألعاب الطاولة العائلية، فهي تعلّم الطفل الالتزام بالقواعد والمشاركة واحترام الآخرين.') WHERE id = '395f9c40-970b-4110-a92d-ee8b61745023';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد المحتوى أهم جانب في علاقة الطفل بالتكنولوجيا. ويجب إبعاد الأطفال في مرحلة ما قبل المدرسة تمامًا عن المحتوى العنيف، مثل ألعاب الحرب والقتال، بصرف النظر عن جنس الطفل. وينبغي أن تنتبهي جيدًا إلى الفئة العمرية التي صُممت لها اللعبة أو مقطع الفيديو. وحتى إن بدا أن الطفل قادر على التعامل مع هذا المحتوى، فإن عناصره في الواقع تفوق مستوى استيعابه. وقد يؤثر المحتوى العنيف سلبًا في نفسية الطفل، لأنه لا يستطيع فهم ما يراه فهمًا كاملًا.') WHERE id = '5bc28c8f-5d2f-46f3-b3e0-13090b0518ec';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ البدء باصطحاب طفلكِ، الذي أصبح يستمتع بالأنشطة الاجتماعية وتزداد قدرته على التكيف مع قواعد المجتمع، إلى مسارح الأطفال أو العروض الموسيقية. سيساعده ذلك على الاهتمام بالفعاليات الثقافية منذ سن مبكرة، وعلى اكتساب قيم جديدة من خلال هذه العروض. وقد يكون التجول معًا في متاجر الكتب ممتعًا جدًا أيضًا. في هذه المرحلة، تجذب انتباهه الموسوعات المطبوعة بخطوط كبيرة. لا تترددي في شراء موسوعات تتناول موضوعات التاريخ والفنون والثقافة. فحتى القراءة معًا والنظر إلى الصور سيزيدان اهتمامه. وكلما عززتِ اهتمام طفلكِ بالثقافة في هذه السن، انعكس ذلك بصورة أكثر إيجابية على مستقبله.') WHERE id = '50a2dfe1-2ca8-419f-a0a0-d061a2e569b7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تظهر لدى الأطفال علامات مختلفة لتشتت الانتباه أو نقصه. ومن أبرزها صعوبة اتباع تعليمات الوالدين أو المعلم. وقد يبدو الطفل ضجرًا أو غير مهتم في أثناء الدرس، أو يستغرق في أحلام اليقظة، أو يميل إلى النسيان. وتشمل العلامات أيضًا فقدان أغراضه في المنزل والمدرسة، وارتكاب أخطاء بسيطة، وعدم ترتيب طاولته المدرسية أو خزانته، ومواجهة صعوبات في العلاقات الاجتماعية. إذا لاحظتِ مثل هذه الحالات لدى طفلكِ، فعليكِ استشارة الطبيب لمعرفة سببها، إذ لا يمكن تشخيص كل طفل يُظهر هذه السلوكيات بالتشخيص نفسه. وحتى إذا كانت لدى الطفل علامات أكثر مما يُعرف بـ"النمط قليل الانتباه"، فلا بد من الحصول على رأي اختصاصي، لأن مصدر هذا الاضطراب قد يكون عصبيًا.') WHERE id = 'fc9707a2-8033-42a0-a859-2dccd4c84f58';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ البالغ من العمر 4 سنوات يرى أنه من المهم أن يُسمع رأيه داخل الأسرة. إن سؤاله عن رأيه في بعض الأمور والاهتمام بمعرفة سبب تفكيره بهذه الطريقة سيشعرانه بالتقدير داخل الأسرة ويعززان ثقته بنفسه. كما سيساعد ذلك على تطوير مهارات التفكير العليا لديه، مثل الاستدلال والمناقشة وتقييم أخطائه. وعندما يجتمع بأقرانه، ينبغي أن تتيحي له فرصة التحدث عن مشكلاته وحلها بنفسه. وبعد ذلك، يمكنكِ مناقشة الطريقة التي حل بها هذه المشكلات ضمن الأسرة. التواصل الأسري مهم للغاية؛ والاجتماع بانتظام والتحاور معًا سيعززان الروابط بين أفراد أسرتكِ.') WHERE id = '1e12d6d2-62b1-4db3-a264-b793ae07104a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يبدأ مفهوم الزمن لدى الأطفال بالتشكل عادةً في سن 4 سنوات تقريبًا. وبالطبع، لا يماثل هذا مفهوم التقويم كما يفهمه البالغون. فعلى سبيل المثال، قد يعرف طفلكِ أن اليوم هو الأحد، لكن هذا لا يعني أنه يعرف أن الأمس كان السبت وأن الغد سيكون الاثنين، أو أنه يعرف التاريخ الدقيق لذلك اليوم. فقد يظن ببساطة أن اليوم هو الأحد لأن والده موجود في المنزل. وبالمثل، فإن معرفته بأنه يبلغ 4 سنوات لا تعني أنه يدرك تمامًا أن الطفل البالغ 3 سنوات أصغر منه. فهو يعرف عمره لأنه يكرره كثيرًا، لكن إذا سألتِه: ''ماذا يعني أن يكون عمرك 5 سنوات؟'' فمن المرجح أن يكرر ببساطة أنه يبلغ 5 سنوات.') WHERE id = '692f9786-05ee-4a06-925c-e91c4c28f381';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد اللعب والألعاب من أهم الوسائل التي تدعم نمو الأطفال المعرفي والجسدي والاجتماعي والعاطفي خلال مرحلة النمو، وتثري مهاراتهم الإبداعية والتفكيرية. وبالنسبة إلى الأطفال في سن 4 سنوات، فإن حاجتهم الأساسية هي بالطبع وجود طفل من العمر نفسه ليلعبوا معه. لذلك، من المهم جدًا أن يقضي طفلكِ وقتًا مع أقرانه. وكما هو الحال في جميع الأعمار، يُعد الماء والرمل والصلصال من مواد اللعب ذات التأثير العاطفي العلاجي والقيمة التربوية الأعلى. وإلى جانب ذلك، يمكنكِ إتاحة الفرصة لطفلكِ لصنع أشياء جديدة باستخدام المواد الخام والمواد المستهلكة، وتعلّم الاستكشاف. ويصبح اللعب بهذه المواد أكثر متعة عند مشاركة أقرانه. كما أن عرض الأعمال التي أنجزها دون تدخل الكبار سيمنحه شعورًا كبيرًا بالفخر.') WHERE id = 'd24de719-13dc-42c4-a222-71b09555098c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ يعاني من نقص الانتباه، فأهم خطوة يمكنكِ اتخاذها هي أن توضحي له أن تشتت الانتباه شائع لدى كثير من الناس، وأنه ليس أمرًا يدعو إلى الخجل. ويمكنكِ فهم كثير من الجوانب بطرح أسئلة على طفلكِ مثل: “أعلم أنك تحاول التركيز، فما الذي تعتقد أنه قد يساعدك على التركيز بصورة أفضل؟” أو “ما الأشياء التي تشتت انتباهك؟”. ومن خلال سؤاله: “هل يوجد شيء يزعجك في المدرسة أو المنزل؟”، يمكنكِ العثور على مؤشرات توضح ما إذا كان القلق هو سبب تشتت انتباهه. لا تعطي طفلكِ مهام كثيرة متتالية، لأن الطفل الذي يعاني من تشتت الانتباه قد لا يتمكن من تذكرها كلها. وبدلًا من ذلك، تواصلي معه بصريًا وأعطيه مهمتين بحد أقصى في كل مرة. وحددي لطفلكِ فترة زمنية خاصة للتركيز. وهكذا سيعرف أنه مطالب بالتركيز خلال وقت محدد فقط، ما سيجعل الأمر أسهل بالنسبة إليه.') WHERE id = 'b6dbd0d2-966c-469b-a877-20ef3f5d6779';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'احرصي على ألا يتجاوز إجمالي الوقت الذي يقضيه طفلكِ أمام الكمبيوتر والتلفاز 45 دقيقة خلال مرحلة ما قبل المدرسة. ولأن الأطفال بين سن 4 و9 سنوات يميلون بشدة إلى تقليد شخصيات الرسوم المتحركة، شاهدي هذه الأعمال أولًا بنفسكِ، ثم اسمحي لطفلكِ بمشاهدتها إذا وجدتها مناسبة. راقبي أفلام الرسوم المتحركة التي يهتم بها، وتحدّثي معه عن مشاهد العنف والأحداث التي تتضمنها. ناقشي معه أن هذه السلوكيات مؤلمة في الحياة الواقعية والمشكلات التي قد تسبّبها. اشرحي له أن الاعتداء ليس "سهلًا" كما يبدو في الأفلام، وأنه قد يؤدي إلى الحزن وعواقب لا يمكن تداركها. حاولا معًا إيجاد حلول بديلة وسلمية للمشكلات التي تظهر في الرسوم المتحركة.') WHERE id = '5f57fd0b-030a-4208-a0d6-e6c994ab83de';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد تعلّم طفلكِ استخدام اللغة أحد أهم مؤشرات نموه. إن دعمه على التحدث في المراحل الأولى، وتهيئة بيئة مناسبة وغنية بالوسائل المتنوعة، وتنظيم أنشطة ممتعة له أمور تحفّز تطوره اللغوي. احرصي على علاج أي مشكلات صحية قد تؤثر في تطور اللغة لدى طفلكِ تحت إشراف الطبيب. ساعديه على إثراء حصيلته اللغوية، فمن المعروف أن الأطفال الذين يمتلكون حصيلة لغوية واسعة يحققون نجاحًا أكبر في نموهم العقلي. كوني محاوِرة جيدة لطفلكِ، وتحدّثي معه كثيرًا وباهتمام. تجنّبي السماح له بقضاء وقت غير محدود أمام الشاشات. فمن المعروف أن مشاهدة التلفاز لفترات طويلة، ولا سيما خلال السنوات الأربع الأولى، تؤثر سلبًا في تطور اللغة. شجّعيه على تعلّم عبارات التحدي اللفظي والأحاجي والأغاني.') WHERE id = '695f2126-31cf-4126-8efd-18188b066023';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذا العمر، يكون طفلكِ قد طوّر مهاراته في الرسم والتخطيط بدرجة ملحوظة. وأصبح قادرًا على رسم أشخاص مبسّطين لهم ذراعان وساقان ورأس. كما تصبح رسوماته لأشياء يمكن للبالغين فهمها والتعرّف إليها. ويستطيع ابتكار أعمال يدوية مختلفة من خلال قص الورق ولصقه وتلوينه. ويحاول نسخ الرسومات الأخرى بالنظر إليها. كما يمكنه رسم رموز بسيطة مثل X، V، H، T، O بالاستعانة بنموذج. ويتعرّف إلى الألوان الأساسية الأربعة والأشكال الهندسية البسيطة، ويطابق بينها، ويذكر أسماءها عند سؤاله عنها.') WHERE id = '611641cd-aa10-4e5b-8d69-e8204d31ef3b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا شعر طفلكِ بألم مفاجئ في الجزء السفلي الأيسر من بطنه، فقد يكون ذلك ناتجًا عن الغازات. اطلبي منه أولًا الذهاب إلى الحمام لمحاولة إخراج الغازات. إذا زال الألم، فيمكنكِ مراقبة حالته دون الحاجة إلى زيارة الطبيب؛ ويكفي الحرص على انتظام عادات دخول الحمام لديه. ولكن إذا بدأ القيء بالتزامن مع ألم البطن، أو ظهر ألم في الجزء السفلي الأيمن من البطن مصحوبًا بفقدان الشهية، فقد يكون ذلك التهابًا في الزائدة الدودية. لا تعطي طفلكِ أي مسكن للألم عند إصابته بألم البطن من دون استشارة الطبيب، لأن ذلك قد يعيق التشخيص المبكر للمرض. وإذا كان قيء طفلكِ أصفر مائلًا إلى الأخضر، فقد يكون علامة على مرض خطير.') WHERE id = 'ae78e1ed-f739-4d46-afb0-6ad241013fa8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عندما تلعبين مع طفلكِ، حاولي قدر الإمكان ألا تكوني أنتِ من يبدأ اللعب أو يوجّهه. ولا تتعمّدي الخسارة أمامه في الألعاب لمجرد إسعاده، بل كوني نزيهة. قدّري جهده بدلًا من النتيجة؛ فقولي له كثيرًا: “لقد بذلت جهدًا كبيرًا حقًا للقيام بذلك” بدلًا من “لقد فعلت ذلك بشكل رائع”. وبهذه الطريقة يمكنكِ تشجيعه حتى عندما لا ينجح في إنجاز شيء ما. احرصي على التزام الجميع بالقواعد؛ يمكن تغيير القواعد، لكن ما دام العمل بها قائمًا، فيجب أن تسري على الجميع. وكونكِ رفيقة لعب لطفلكِ لا يمنعكِ من وضع حدود عند الحاجة. فإذا قام بسلوك غير مقبول، احرصي على أن يتوقف عنه. خصّصي كل يوم نصف ساعة على الأقل للعب معه وحده.') WHERE id = '3d6d5afc-b0b7-45af-a0ab-f196aaca2127';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'خلال هذه المرحلة، يشعر طفلكِ بالفضول تجاه جسمه وجسم الجنس الآخر ويطرح الأسئلة. ويرغب في معرفة الفروق بين الفتيات والفتيان. ينبغي ألا يكون الحديث عن موضوعات النمو الجنسي من المحظورات بالنسبة إليكِ، بل يجب أن يكون موضوعًا يمكن مناقشته براحة. ومن المهم جدًا تعليم طفلكِ حدوده الشخصية. اشرحي له أن أعضاءه الخاصة لا يحق لأحد لمسها سواه، وأنها يجب أن تظل مغطاة أمام الآخرين. وأخبريه بأنه إذا حاول أي شخص التصرّف معه بهذه الطريقة، فعليه إخباركِ فورًا. ومن المهم عند مناقشة هذه الموضوعات أن تتحدثي معه بنبرة يومية طبيعية، من دون صراخ أو توبيخ.') WHERE id = '614d55f8-67cd-4224-a622-14041bad2022';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يرغب طفلكِ في سن الرابعة في أن يكون مثل أصدقائه. فهم يؤثرون في أفكاره وسلوكياته، ويحاول هو التشبه بهم. وعندما يكتشف أن لدى العائلات الأخرى قيمًا وقواعد مختلفة، يختبر هذه المعلومات الجديدة من خلال المطالبة ببعض الأمور في المنزل. فقد يرغب مثلًا في مشاهدة برامج ممنوعة أو تناول أطعمة غير مسموح بها في منزله. بالنسبة إلى الأطفال في سن الرابعة، يمثل الأصدقاء نماذج لأنماط حياة وسلوكيات مختلفة. وقد يدعو طفلكِ أصدقاءه إلى المنزل ليروا عائلته وألعابه وبيته. كما يحاول إرضاءهم ويُظهر سلوكيات جديدة تتوافق مع ذلك. وهو يولي أصدقاءه أهمية كبيرة ولا يحب البقاء بمفرده إطلاقًا.') WHERE id = '8d3e994b-abbd-4e43-bcfa-877fe6b1fa96';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع اقتراب طفلكِ من سن الرابعة، يتكوّن لديه مفهوم أخلاقي بسيط، ويحاول استكشاف مفهومي الصواب والخطأ. ويلتزم بالقواعد بجدية لإرضاء والديه وتجنب العقاب. فالنتائج أهم لديه من أي شيء آخر. وعندما يكسر شيئًا ثمينًا، قد يعتقد أنه طفل سيئ حتى لو حدث ذلك عن طريق الخطأ. عليكِ مساعدته على فهم الفرق بين التصرف غير المقصود والسلوك السيئ المتعمد. وهكذا لن يلوم نفسه على أفعاله وينغلق على ذاته.') WHERE id = 'd503315a-9bc7-4dae-b063-882f785b1c35';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يكون طفلكِ في هذه المرحلة متطلبًا أحيانًا ومتعاونًا أحيانًا أخرى. وقد أصبح قادرًا على التحكم في ردود فعله العاطفية غير المتوقعة، لكنه لا يزال يجد صعوبة في كبح مشاعر الاعتراض والعناد. وقد لا يلتزم بقواعد الأسرة، وربما يتحدث بوقاحة أو يسيء التصرف عمدًا لإزعاجكِ أو إزعاج من يتولى رعايته. وعلى عكس اختبار الحدود في الأعمار الأصغر، تصدر السلوكيات السيئة في هذه المرحلة بوعي أكبر. ورغم هذه التغيرات، لا يزال طفلكِ يحاول إرضاءكِ أو إرضاء الشخص الذي يعتني به. وهو يدرك أن عليه الالتزام بقواعد معينة والتصرف بطريقة سليمة لتحقيق ذلك.') WHERE id = 'aaab67cd-2783-4da3-a197-a84694c06429';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أتيحي لطفلكِ فرصًا لتعلم كلمات جديدة من أجل إثراء حصيلته اللغوية. وساعديه على تعلّم أسماء إخوته أو أصدقائه وألقابهم، وكذلك عنوان منزله. اطرحي عليه أسئلة واطلبي منه تكرار الإجابات. ويمكنكِ التحدث معه عن الأنشطة التي خططتِ لها خلال اليوم. فمثلًا، يمكنكِ إجراء حوار معه مثل: «لقد تحدثنا عما سنفعله بعد تناول الطعام، هل تتذكر؟ نعم، سنذهب اليوم إلى الحديقة. وكيف سنذهب إلى الحديقة؟». عززي ذاكرته بطرح أسئلة عن قصة قرأتماها من قبل، وشجعيه على تأمل صور الكتاب. وأظهري له مدى أهمية القراءة والكتابة في الحياة اليومية. وجّهي انتباهه إلى المواد المكتوبة من حوله، مثل اللافتات والملصقات، واشرحي له الغرض من كتابتها. شاهدا التلفاز معًا وتحدثا عما تشاهدانه. ولتشجيعه على حب الكتب، خصصي له رفًا للكتب على ارتفاع يستطيع الوصول إليه. ستساعد قراءة الكتب وغناء الأغاني وممارسة ألعاب الكلمات والتحدث كثيرًا مع طفلكِ بدرجة كبيرة على تنمية حصيلته اللغوية.') WHERE id = '87189795-ea46-436e-8cfa-53184b24452b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع دخول طفلكِ عامه الرابع، قد تنتظركِ مرحلة جديدة تُعرف بأزمة سن الرابعة. وخلال هذه المرحلة، قد تقع حوادث بسيطة عديدة غير مرغوب فيها، لأن الأطفال يرغبون بشدة في الاستقلالية في تصرفاتهم. وبدلًا من التعامل بسلبية مع رغبة طفلكِ في إنجاز الأمور بنفسه، أتيحي له فرصة ممارسة الأنشطة واللعب تحت إشرافكِ. فبهذه الطريقة وحدها يمكن أن تتطور مهاراته الحركية ونموه النفسي والأخلاقي بصورة إيجابية ومتكاملة. ولأنه يشعر بأنه قد كبر، سيبدأ بتقليدكِ. ونتيجة لذلك، قد يُظهر اهتمامًا أكبر باللعب بأدوات المطبخ. وإذا كان طفلكِ ولدًا، فقد يقلد والده ويتبنى سلوكياته، أما إذا كانت طفلتكِ بنتًا، فسيتركز اهتمامها أكثر على والدتها. وقد تظهر في هذه المرحلة أيضًا صعوبة في الانسجام مع أقرانه من الجنس الآخر.') WHERE id = 'cfed4a34-1a98-42d4-ad49-38a939cc4921';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تواجهين في هذا العمر صعوبات مختلفة عند انتقال طفلكِ إلى النوم. احرصي على أن ينام في الموعد نفسه كل ليلة، ولا تسمحي للأنشطة الأخرى بتعطيل موعد نومه. ضعي روتينًا ثابتًا قبل النوم، واتبعي كل ليلة الترتيب نفسه لعادات مثل تنظيف الأسنان واستخدام المرحاض وارتداء ملابس النوم. وتبادلي معه أحاديث لطيفة في السرير؛ اسأليه عما فعله خلال اليوم، وما أكثر شيء أسعده أو أحزنه. سيساعد ذلك على بناء رابطة تواصل آمنة بينكِ وبين طفلكِ. وانتبهي إلى الألعاب الموجودة في غرفته؛ فيمكنكِ إبعاد الألعاب الكبيرة جدًا أو التي قد تثير خوفه لبعض الوقت. قد يصعب على الطفل الذهاب إلى فراشه بينما لا يزال والداه مستيقظين والحياة مستمرة من حوله. لذلك، عند ترسيخ نظام النوم، يمكنكِ إطفاء أضواء المنزل وارتداء ملابس نومكِ كما لو كنتِ تستعدين للنوم أيضًا، لمساعدته وتشجيعه.') WHERE id = '3d6cfe38-d47f-4e23-9455-bc71c0715956';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هل تعلمين أن بعض الكلمات التي نقولها خلال اليوم بنية تشجيع أطفالنا قد تكون لها في الواقع آثار سلبية؟ تُظهر الأبحاث أن تكرار عبارات مثل «أحسنت» و«أنت رائع» عندما ينجز طفلكِ مهمة ما، قد يجعله يركز على نيل استحسانكِ بدلًا من تنمية دافعه الداخلي. لذلك، من الأفضل استخدام عبارات مدح محددة مثل: «أعجبني كثيرًا تناسق الألوان التي استخدمتها في الرسم»، فهذا يؤثر بصورة أفضل في نموه. كذلك، عندما تكونين على عجلة من أمركِ، قد تؤدي عبارات مثل «أسرع» و«هيا بسرعة» إلى توتر طفلكِ ودخوله في نوبات بكاء. ولتجنب التوتر، حوّلي الموقف إلى لعبة، كأن تقولي: «هيا نرَ من سينهي قطعة الجبن أولًا؟»، فمثل هذه الأساليب تجعل الأمر أكثر متعة.') WHERE id = 'ddd0692a-3a59-4255-984a-d8a0b7fa3830';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يميل الأطفال بين عمر سنتين و٦ سنوات إلى التفكير المتمحور حول الذات، ويتوقعون عادةً أن يكون كل ما حولهم في خدمتهم. خلال هذه المرحلة، قد لا يراعي طفلكِ أفكار الآخرين ومشاعرهم. ولأنه لم يتعلم المشاركة بعد، فقد لا يسمح لأحد باللعب بألعابه. وقد يرغب حتى في امتلاك أغراض الآخرين، رغم رفضه إعطاءهم أغراضه. لا تتوقعي من طفلكِ أن يتعلم المشاركة فجأة؛ فهي مهارة تُكتسب بمرور الوقت، ويجب منحه الوقت الكافي لتعلمها. ولأن البيئة التي ينشأ فيها كل طفل تختلف عن غيره، فقد تختلف أيضًا المدة اللازمة لاكتساب هذه المهارة.') WHERE id = '30d6a7c7-dd03-4c28-8bfd-4d04e2d06182';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُظهر الأبحاث أن متوسط الوقت المخصص لمشاهدة التلفاز يفوق الوقت الذي يُقضى في جميع الأنشطة الأخرى، باستثناء النوم والمدرسة. وقد تبيّن أن الأطفال الذين يقضون وقتًا طويلًا أمام التلفاز يعانون مشكلات في الوزن أكثر ممن يشاهدونه لفترات أقل. كما اتضح أن كثيرًا من الأطفال الذين يعانون مشكلات في تناول الطعام كانوا يُطعَمون أمام التلفاز خلال مرحلة الرضاعة. كذلك، تشجع الأطعمة الغنية بالدهون والسكريات التي تظهر في الإعلانات الأطفال على اتباع نمط غذائي غير صحي. ولا يؤثر التلفاز سلبًا في التغذية فحسب، بل في نظام النوم أيضًا؛ إذ لوحظ أن الأطفال الذين يشاهدونه قبل النوم يواجهون صعوبة في الاستغراق في النوم، وتكون جودة نومهم منخفضة. وللحفاظ على حدود واضحة، من المهم جدًا إزالة التلفاز من غرفة الأطفال.') WHERE id = '6c7a6bcb-ff6b-4874-bd17-f84276093048';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بصفتكِ أمًا، قد تشعرين بأنكِ لا تخصصين وقتًا كافيًا لطفلكِ أو أن لديكِ بعض جوانب التقصير. لكن عليكِ أن تعلمي أنه لا توجد معادلة دقيقة تحدد مقدار الوقت «الكافي». فالأهم في هذه الرحلة ليس مقدار الوقت الذي تقضينه مع طفلكِ، بل جودته. ولقضاء وقت أكثر فائدة معه، اختاري أنشطة تستمتعان بها معًا. عادةً ما يفقد الأطفال اهتمامهم بلعبة جديدة بعد 15-20 دقيقة من شرائها، لكنكِ ستلاحظين أن هذه المدة تزداد كثيرًا عندما تشاركين طفلكِ اللعب بها. فما يهم رضيعكِ ليس اللعبة التي يلعب بها، بل وجوده «معكِ» في تلك اللحظة.') WHERE id = 'c91fbfe5-d2ab-4e49-af9d-4a6651e84084';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عندما تلاحظين أن طفلكِ يتصرف بخجل، تكون طريقة استجابتكِ مهمة جدًا. فعلى سبيل المثال، إذا جاء ضيف واختبأ طفلكِ خلفكِ بدلًا من إلقاء التحية، يمكنكِ طمأنته بقولكِ: «يبدو أنك شعرت ببعض الخجل الآن، لا بأس. يمكنك إلقاء التحية عندما ترغب في ذلك»، بدلًا من أن تقولي للضيف: «عذرًا، إنه خجول قليلًا». كوني قدوة له في التواصل الاجتماعي؛ فطفلكِ يحب تقليد تصرفاتكِ، ورؤيتكِ تتحدثين بسهولة مع الآخرين ستخفف من مخاوفه. لا تجبريه على التواصل، وفي الوقت نفسه لا تبالغي في حمايته. إذا واجه صعوبة، فادعميه بقولكِ: «أنا بجانبك أيضًا»، لكن احرصي على ألا تتحدثي نيابةً عنه.') WHERE id = '654b2eea-2901-44dc-a0c2-15d66d812f41';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا بلغ طفلكِ سن 4 سنوات وما زال لا يستطيع القفز، أو يواجه صعوبة في الخربشة على الورق، أو لا يُظهر اهتمامًا بالألعاب التفاعلية، أو يتجاهل الأطفال الآخرين ولا يتحدث إلا مع أفراد أسرته، أو يرفض بعناد ارتداء ملابسه أو النوم أو الذهاب إلى المرحاض، أو لا يستطيع تنفيذ تعليمات بسيطة، أو لا يفهم مفهومي «المتشابه» و«المختلف»، أو لا يستطيع استخدام ضمائر مثل «أنا» و«أنت» و«نحن» استخدامًا صحيحًا، أو لم يعد قادرًا على أداء مهارات كان يتقنها سابقًا، فعليكِ بالتأكيد استشارة طبيب الأطفال. تابعي نمو طفلكِ عن كثب، وراجعي اختصاصيًا دون تأخير عند الحاجة.') WHERE id = 'c8e84d4c-705c-4807-8598-eeefbb760a42';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إلى جانب نمو طول الأطفال في سن 4 سنوات، تستمر مهاراتهم الحركية الكبرى والدقيقة في التطور أيضًا. يصبح طفلكِ أكثر إدراكًا للمكان من حوله، ويقل اصطدامه بالأشياء أو الأشخاص أثناء الحركة. تتحسن قدرته على الجري، ويستطيع ركل الكرة بقدمه ورميها بيده. كما يمكنه صعود الدرج ونزوله من دون مساعدة، والتسلق، والوقوف على قدم واحدة لفترة قصيرة، وارتداء ملابسه وخلعها بنفسه. وفي هذا العمر، يُفترض أن يكون التناسق بين اليد والعين قد تحسن. وبفضل هذا التطور، ينبغي أن يتمكن من ممارسة أنشطة مثل نظم الخرز في خيط، وتركيب الأحجيات، والتلوين داخل الخطوط. ويمكنه أيضًا نسخ المثلث والدائرة والمربع وغيرها من الأشكال، ورسم شخص بأجزاء جسمه، وتكديس 8-9 مكعبات فوق بعضها.') WHERE id = 'ed367477-46cb-4c06-b9d7-23d99cb4ee19';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ الآن قادرًا على مواصلة الحوار لفترة أطول، كما تتطور عمليات التفكير لديه. وإلى جانب قدرته المتزايدة على الإجابة عن الأسئلة البسيطة بسهولة ومنطقية أكبر، بات يستطيع التعبير عن مشاعره بصورة أفضل. وأصبح يفهم مفهوم الوقت ومواعيد الأنشطة اليومية بشكل أوضح؛ فعلى سبيل المثال، يعرف أن وجبة الإفطار تؤكل صباحًا، والغداء ظهرًا، والعشاء مساءً. كما تزداد مدة انتباهه، فيتمكن من التركيز على ما يفعله بصورة أفضل ولفترة أطول. وبدلًا من التعبير عن غضبه جسديًا، يبدأ بالتعبير عنه بالكلمات، وإن لم يفعل ذلك دائمًا. ويُظهر كذلك تقدمًا أكبر في حل المشكلات.') WHERE id = '49c8b800-b882-48a6-9f24-05e4d2f08e6f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يستطيع الأطفال في سن 4 سنوات عادةً العد حتى 10-20. ولتنمية مهارة العد لديه، يمكنكما أثناء التنزه في الخارج عد السيارات والأشجار وغيرها معًا. وعند تناول وجبات خفيفة مثل البسكويت، يمكنكما ممارسة ألعاب تقوم على معرفة عدد القطع المتبقية بعد تناول كل قطعة. ولتعزيز إدراكه للألوان والأشكال، يمكنكِ اختيار لون وطلب العثور على 4-5 أشياء بهذا اللون في المنزل وإحضارها. ضعي أقلام التلوين أمامه، واطلبي منه أن يربط كل لون بشعور معين، ثم يلوّن الورقة أو يرسم أشكالًا باستخدام الألوان التي تتوافق مع المشاعر التي يشعر بها أكثر في حياته. وبعد ذلك، يمكنكِ التحدث معه عن مشاعره من خلال الرسم الذي أنجزه. يعزز هذا النشاط فهم الألوان والأشكال، إلى جانب الوعي بالمشاعر والقدرة على التعبير عن الذات.') WHERE id = '98e7ba77-79e8-4221-9e64-49ca676c7cd8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع تطور قدرة طفلكِ على التعبير عن نفسه والتحكم في مشاعره، ستقل ردود أفعاله وعناده بمرور الوقت حتى تتلاشى. لكن أسلوب الوالدين خلال هذه المرحلة بالغ الأهمية، لأن الأطفال يتعلمون تهدئة أنفسهم والتعبير بطريقة سليمة في أوقات الضيق بمساعدة والديهم. في مثل هذه اللحظات، لا تحاولي تعليمه شيئًا أو تقديم تفسيرات منطقية، إذ يصعب عليه عادةً فهمكِ في تلك اللحظة، وقد يؤدي هذا الأسلوب إلى تفاقم نوبة الانفعال. إذا كنتما خارج المنزل، فحاولي الابتعاد عن الأجواء المتوترة والذهاب إلى مكان هادئ قدر الإمكان. وإذا كنتما في المنزل، فانتقلا إلى مكان يمكنه أن يهدأ فيه، مثل غرفته. تذكّري أن اللحظات التي يكون فيها طفلكِ في أشد حالات الحزن والضيق هي في الحقيقة أكثر اللحظات التي يحتاج إليكِ فيها. لا تستخدمي أساليب مثل "بساط العقاب" أو "كرسي التفكير"، لأنها قد تجعله يشعر بالرفض وسوء الفهم وانعدام القيمة.') WHERE id = 'fb77510f-fdfd-4080-9579-84655a9754fe';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد الغثيان والقيء من أكثر الشكاوى شيوعًا في مرحلة الطفولة. وعندما يصاحب القيءُ الغثيانَ، فقد يكون ذلك مرهقًا جدًا للطفل، ومن الطبيعي أن ترغبي في تحسن حالته فورًا. لكن الأدوية المستخدمة لهذه الحالات، التي يزول معظمها من تلقاء نفسه، قد لا تكون آمنة دائمًا. لذلك عليكِ التحلي بالصبر واستشارة طبيبكِ حتمًا. ومن أهم الأمور التي ينبغي الانتباه إليها الجفاف، إذ قد يصاب الأطفال بالجفاف أسرع من البالغين. شجعي طفلكِ على شرب السوائل، وليتناول كميات قليلة منها على فترات متقاربة. قدمي له وجبات صغيرة من أطعمة سهلة الهضم. ومع تراجع القيء، يمكنكِ زيادة كمية السوائل تدريجيًا.') WHERE id = '23ae0863-ca91-425e-9102-2694822c45d5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يكون اللعب أكثر فائدة عندما يمارسه الطفل مع أقرانه، إذ يساعد ذلك على تنمية مهاراته الاجتماعية. ومن خلال اللعب مع أقرانهم، يختبر الأطفال مشاعر الانضمام إلى مجموعة والقبول والانتماء إليها. كما أن اللعب مساحة يختبر فيها الأطفال مواقف الحياة؛ فتارةً يتعين على الطفل انتظار دوره، وتارةً يتعلم التعامل مع خيبة الأمل... ويجد الشجاعة للمحاولة مجددًا، ولا يستسلم، ويصل إلى هدفه، وبذلك يزداد تقديره لذاته وثقته بنفسه. كما يعبّر عن مشاعره، ويفهم مشاعر الآخرين، ويتعلم التعاطف معهم. نعلم أنكِ أفضل رفيقة لعب له، ومع ذلك سيكون تكوين صداقات جديدة في بيئات مختلفة أمرًا ممتعًا جدًا بالنسبة إليه. :)') WHERE id = 'cd983b90-05fa-4d49-84f1-0ca9941425d4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ تمرّين بمرحلة «متلازمة سن الرابعة»، فعليكِ أولًا أن تعرفي أنه أصبح بإمكانكِ التحدث إلى طفلكِ كما تتحدثين إلى شخص كبير. اشرحي له المواقف بلغة يفهمها، ووضّحي له بلطف عواقب تصرفاته. قد تلاحظين خلال هذه المرحلة عنادًا مستمرًا لدى طفلكِ واعتراضًا عليكِ. وقد يتصرف بهذه الطريقة بسبب غيرته من العلاقة بين أمه وأبيه. حاولي فهم طفلكِ لتقويم هذه السلوكيات. وتذكّري أن هذه المرحلة مؤقتة وتحلّي بالصبر؛ فصبركِ سيزيد ثقته بكِ. ولتشجيعه على التعاون، حاولي كسبه من خلال ألعاب ممتعة. فمثلًا، أنجزا مهمة بالتناوب: «تعالَ نرتب المائدة معًا وننقل الأغراض واحدًا تلو الآخر. هل تريد أن تبدأ أولًا؟»، أو حدّدا هدفًا: «تعالَ نرتب الغرفة قبل عودة أبيك/أمك إلى المنزل لنفاجئه/لنفاجئها». ومع نمو طفلكِ، يمكنكِ التحدث معه أكثر عن طرق حل المشكلات ومنحه مسؤوليات صغيرة تتعلق بحياته.') WHERE id = 'c36022d1-4912-4893-a17f-9e3be09bee79';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لكي نغرس في أطفالنا حب الطبيعة وننمّي لديهم الوعي البيئي، علينا تعريفهم بالطبيعة منذ سن مبكرة. ويقوم هذا النوع من التربية على حماية الطبيعة، وعدم الإضرار بموائل الكائنات الحية، والاهتمام بالبيئة. وبالنظر إلى فضول الأطفال الفطري تجاه الحيوانات والنباتات، ستكون هذه التجربة ممتعة جدًا لهم. فاللعب بالتراب، وتسلق الأشجار، واستكشاف النباتات المختلفة من أنشطتهم المفضلة. أتيحي لطفلكِ فرصًا للملاحظة كي يكتسب حب الطبيعة. فمثلًا، خذي معكِ عدسة مكبرة عند التنزه في الغابة، ودعيه يتفحص ما حوله. وكوني قدوة لطفلكِ من خلال شرح سبب كل تصرف تقومين به للحفاظ على البيئة.') WHERE id = '782daa87-3be8-4609-ae44-9ef72cd59434';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يواجه طفلكِ، الذي بدأ المدرسة حديثًا أو يستعد لبدئها، صعوبة في التأقلم. ومن الطبيعي أن تظهر مشكلات في التكيف رغم كل الاستعدادات والآمال. ونودّ، بصفتنا عائلة Anacan، أن نؤكد أنه يمكن اجتياز هذه المرحلة بصورة صحية من خلال اتباع الوالدين للنهج الصحيح. راقبي التوقيت والمكان اللذين تظهر فيهما المشكلة تحديدًا: هل في المنزل، أم عند الباب، أم وقت الوداع؟ قد تساعد الخطوات المتخذة قبل لحظة الاستعداد مباشرة على الحفاظ على توازن مشاعر الطفل. لا تضخّمي الأمر عندما يبكي للمرة الأولى أو يرتجف صوته، واطلبي من معلمته أو معلمه التحلي بالهدوء نفسه حتى لا يشعر بالذعر. إن بقاءكِ بالقرب من المدرسة خلال الأيام الأولى، وانتظاركِ في الفناء أو خارجه، سيطمئن صغيركِ. ويمكنكِ وضع صورة لكِ في جيب صغيركِ إذا قال إنه يشتاق إليكِ كثيرًا؛ فالنظر إليها عند اشتياقه سيمنحه القوة.') WHERE id = '19cc624e-7756-4818-b419-54e639b9f0af';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يؤثر التواصل السليم إيجابيًا في ثقة طفلكِ بنفسه. ولكي تفهمي أسباب سلوكياته، ينبغي أن تكوني على دراية بالتغيرات الخاصة بكل مرحلة عمرية. وعندما تتواصلين معه بالنزول إلى مستوى عالمه، تنشأ بينكما رابطة أقوى. تذكّري أن التواصل لا يقتصر على الكلام، بل يشمل فهم المشاعر أيضًا. قد لا يستطيع طفلكِ التعبير عن أفكاره بوضوح مثلكِ. ومن المهم أن تعرفيه جيدًا وأن تستشعري ما يشعر به من خلال لغة جسده. شاركيه ذكريات طفولتكِ، ولا تحدثيه عن نجاحاتكِ فحسب، بل أخبريه أيضًا بما تعلمتِه من الصعوبات. ولا تكتفي بشرح القيم له، بل علّميه إياها من خلال ألعاب بسيطة.') WHERE id = '02c1c3a8-5b3e-40d6-94fa-15af563477e1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي استخدام كلمة «لا» لإيقاف الطفل باعتدال وفي موضعها حتى لا تفقد تأثيرها. وبدلًا من توجيه تحذيرات متكررة ومقتضبة، ينبغي توضيح الموقف بعبارات موجزة، مع الحرص على عدم الإطالة في الشرح أيضًا. فمثلًا، بدلًا من قول: «لا، لا تفعل ذلك!»، من الأفضل أن تقولي: «إذا رميت الطبق على الأرض، فسيتناثر طعامنا وتتسخ الأرضية، لذلك يجب أن يبقى الطبق على المائدة». وبهذه الطريقة تعلّمينه أيضًا آداب المائدة. تذكّري أن الدماغ يستجيب دائمًا بصورة أفضل للعبارات الإيجابية. وعندما تريدين منعه من شيء، لا تركّزي على الفعل الذي تقولين له ألّا يفعله، بل أخبريه بالسلوك الذي تفضّلين أن يقوم به.') WHERE id = '7349c0d0-efa6-4d5a-8508-d577646dbb46';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'اعتاد رضيعكِ منذ ولادته أن يراكِ أنتِ، أمه، أكثر من أي شخص آخر، لكنه يحتاج أيضًا إلى الانخراط في بيئات اجتماعية متنوعة. يمكنكِ تخصيص أيام يقضيها مع جده أو أبيه أو عمه أو غيرهم من رجال العائلة. وهيئي الظروف ليقضي الآباء وقتًا مع أطفالهم، وشجّعيهم على الذهاب معًا في عطلات نهاية الأسبوع إلى السينما أو المسرح أو الحديقة. وشجّعي طفلكِ على مساعدة أبيه في المهام اليومية، مثل شراء حاجيات المنزل. ويمكنكما تخصيص وقت للقراءة معًا؛ فتقرأ الأم أحيانًا ويقرأ الأب أحيانًا أخرى، مما يجعل هذا الروتين أكثر متعة. ومن المهم جدًا أن تدعما بعضكما بعضًا من خلال تقاسم المسؤوليات المتعلقة باحتياجات الطفل ورعايته.') WHERE id = '697be98b-1f89-4c20-b93a-c838aed35dbc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المهم جدًا أن يكون الوقت الذي تقضينه مع طفلكِ ممتعًا لكليكما، خاصة إذا كان مخططًا له مسبقًا. وبدلًا من حشد الكثير من الأنشطة في وقت محدود، من الأفضل اختيار عدد قليل من الأنشطة الممتعة التي تستمتعان بها معًا. يمكنكِ التخطيط للوقت الذي تقضينه مع طفلكِ أو تركه يسير بعفوية. لكن تخصيص أيام محددة من الأسبوع لتكون وقتًا «خاصًا» سيجعل طفلكِ يشعر بأهميته ويقوّي الروابط الأسرية. وحتى إذا لم تتمكني من تخصيص وقت طويل خلال اليوم، فاستفيدي من الفرص الصغيرة. على سبيل المثال، إذا كنتِ بحاجة إلى شراء مستلزمات المنزل، فيمكنكِ اصطحاب طفلكِ معكِ، أو قد يكون شرب الحليب والقهوة معًا في نهاية يوم متعب لحظة جميلة. يساعد قضاء وقت ممتع وذي جودة مع طفلكِ أفراد الأسرة على فهم بعضهم بعضًا بصورة أفضل، ويسهم إيجابيًا في نمو الطفل الاجتماعي والعاطفي.') WHERE id = 'c6c8fb11-1f84-4d93-bc2b-bbdb69021b35';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحتاج طفلكِ إلى بعض الفيتامينات والمعادن لينمو بصحة جيدة. ويمكننا ذكر بعض منها على النحو الآتي: يساعد الكالسيوم على تقوية العظام والأسنان، ويدعم وظائف الأعصاب والعضلات. ويساعد أوميغا-3 وأوميغا-6 على تكوين الخلايا وتنظيم الجهاز العصبي، كما أنهما ضروريان لوظائف الدماغ والعينين. ويقوّي المغنيسيوم العظام، وينظم ضربات القلب، ويدعم جهاز المناعة. أما فيتامين A فهو مهم جدًا لصحة العينين ونمو العظام، ويحمي الجسم من العدوى. ويساعد فيتامين D الجسم على امتصاص الكالسيوم، وهو ضروري لقوة الأسنان. أما الزنك، فيدخل في تركيب عدد كبير من الإنزيمات الضرورية لعمليات الأيض، وله أهمية كبيرة في نمو طول الطفل.') WHERE id = '23a0fd1e-ea5f-49f5-aacf-24ca65d87de4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ قضاء وقت ممتع مع طفلكِ من خلال اللعب بالأقنعة. ارسمي بقلم على عدد من الأقنعة الموجودة في المنزل تعبيرات وجه مختلفة، مثل السعادة والحزن والغضب. وفي أثناء الرسم، يمكنكِ التحدث مع طفلكِ عن المشاعر. بعد ذلك، وزّعي الأقنعة على أفراد الأسرة. وبتوجيه من طفلكِ، اطرحي على كل شخص سؤال: «كيف تشعر؟». وليشرح الشخص الذي يرتدي القناع شعوره في جملة، كأن يقول مثلًا: «أشعر بالسعادة لأنني ذهبت إلى الحديقة اليوم». واصلوا اللعبة بالتناوب. نتمنى لكم، بصفتنا عائلة Anacan، الاستمتاع بهذه اللعبة المسلية التي يمكنكم لعبها معًا كأسرة.') WHERE id = 'e680b3c8-68d3-4b9f-bffd-d682fa74d0b9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لدعم النمو المعرفي لطفلكِ، يمكنكِ ابتكار ألعاب مرتبطة بالمفاهيم التي تعلّمها. على سبيل المثال، أنشئي جدولًا على لوحة واكتبي فيه اسمكِ واسم طفلكِ. ولترسيخ مفهومي الكبير والصغير، أعطيه تعليمات مثل: «ضع الكرة الكبيرة في الصندوق» أو «ضع السيارة الصغيرة على الطاولة». وعندما ينفّذ طفلكِ المهمة بصورة صحيحة، ضعي نجمة في الجدول. وهكذا تتدرّبان معًا على المفاهيم والعدّ. العبوا بالتناوب، لكن تجنّبي الخسارة عمدًا كي يفوز طفلكِ. فإذا لاحظ ذلك، فقد يطالب بالفوز دائمًا. فالمنافسة الحقيقية أكثر فائدة لنموه.') WHERE id = '41e1c28b-f6fa-4151-9135-15d7818fc948';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عندما يُظهر الأطفال سلوكًا غير مقبول، تُعد طريقة «الوقت المستقطع» من أكثر الأساليب استخدامًا لتوضيح أن هذا السلوك خاطئ. وفي هذه الطريقة، ينتظر الطفل بعد قيامه بالسلوك السلبي مدةً معينة من دون ممارسة أي نشاط، بمفرده في غرفة أو مكان مخصص لذلك، بوصفه نتيجة لسلوكه. وهكذا تصل إليه رسالة مفادها أن ما فعله غير مقبول. تحدثي أولًا مع طفلكِ عن معنى طريقة الوقت المستقطع. واشرحي له أنها فرصة للتفكير في تصرفه والهدوء وتعلّم طريقة جديدة للتصرف. حددي مسبقًا المكان والمدة التي سينتظر فيها، والسلوكيات التي تستدعي تطبيق الوقت المستقطع، ثم أخبريه بذلك. يجب أن يبقى طفلكِ بمفرده خلال هذه المدة، لذا لا تذهبي إليه كل دقيقتين. تذكّري أن تعلّم الطفل مهارة تهدئة نفسه هو أحد أهدافنا الأساسية.') WHERE id = '93d4efd0-8678-4cd0-b1ec-9612e7a0c85c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بصفتكِ أمًا، عليكِ أولًا مساعدة طفلكِ على التعرّف إلى مفهوم الملكية. فمن الصعب على الطفل الذي لا يفهم مفاهيم الملكية والانتماء والامتلاك أن ينتقل إلى سلوك أكثر تقدمًا مثل المشاركة. لذلك، ينبغي أولًا مساعدته على إدراك الأشياء التي تخصه وتنمية شعوره بملكيتها. بالنسبة إلى طفل في هذا العمر، فإن مشاركة لعبته أو أحد أغراضه مع شخص آخر تبدو وكأنها خسارة لذلك الشيء. فإذا لم تكن اللعبة في يده وتحت سيطرته، يظن أنه فقدها تمامًا. وهذا الخوف من الفقد هو تحديدًا ما يزعجه. سيساعد استخدام كلمات مثل «الإعارة» و«الاسترداد» و«المشاركة» و«الإرجاع» بصورة متكررة في حياتكِ اليومية، مع تجسيد معانيها من خلال تصرفاتكِ، طفلكِ على فهم هذه المفاهيم بسهولة أكبر.') WHERE id = 'c20ae6c1-3ea1-42a3-94ba-f3d5d43252dc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لدعم نمو طفلكِ، العبي معه لعبة تمثيل أدوار الأسرة والمنزل. دعيه يقود مجريات اللعبة وقلّدي ما يفعله. إذا كانت هناك مواقف تسبب التوتر لطفلكِ، مثل المبيت في منزل جدته أو بدء الذهاب إلى الحضانة، فحاولي مساعدته على التغلب على هذا الخوف من خلال اللعب. أتيحي له اتخاذ قرارات بسيطة بنفسه، مثل اختيار ما سيرتديه أو اللعبة التي سيلعبها. اسمحي له بمحاولة حل المشكلات التي تنشأ أثناء اللعب مع أصدقائه بنفسه، لكن راقبيه عن كثب فقد يحتاج إلى مساعدتكِ. ساعديه على فهم تسلسل الأحداث باستخدام كلمات تدل على الترتيب، مثل "لاحقًا" و"أولًا" و"في النهاية". احرصي على الإجابة عن أسئلته التي تبدأ بـ"لماذا؟". وإذا كنتِ لا تعرفين الإجابة، فابحثا عنها معًا في كتاب أو على الإنترنت. سمّيا معًا الألوان والأدوات كثيرة الاستخدام والأشياء التي تريانها في الصور.') WHERE id = '73787f75-075a-4741-af86-ccb8d137e83d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'سن الرابعة هو سن الاعتراض والعناد. فعندما تُرفض رغبات الطفل، قد يتحدث مع الكبار بأسلوب غير لائق وفظ، وقد يتشاجر مع رفاق اللعب. كما يختبر الحدود ويتحدى سلطة الكبار. وقد يضرب أو يركل عند استفزازه، ويرغب في مغادرة المكان الذي لا يشعر فيه بالسعادة. وقد يضحك بصخب ويبكي بصوت مرتفع، وتُلاحظ تقلبات حادة في مشاعره. وقد يستمتع باستخدام الكلمات البذيئة. وفي هذا العمر، يدخل الطفل في خلافات، لا سيما مع فرد من الأسرة من الجنس نفسه. وينبغي البدء في تعليمه مفهومي الصواب والخطأ. ويمكن عند الحاجة تطبيق عواقب تربوية بسيطة، مثل إرساله إلى غرفته لبعض الوقت أو منعه من مشاهدة برنامج تلفزيوني. لكن يجب أن يعرف طفلكِ بوضوح سبب هذه العاقبة؛ فهو يهتم بمعرفة سبب معاقبته، وإذا لم توضحيه له فقد يظن أنه يتعرض للظلم.') WHERE id = '032b690d-3849-44c8-ae6b-5cc63b6a8ddb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ يعبّر عن استيائه بالعبوس أو الامتناع عن الكلام، فلا تفعلي ما يريده عندما يتصرف بهذه الطريقة. فإذا لُبّيت رغباته بسبب هذا السلوك، فسيعتبره وسيلة ناجحة وسيصبح عادة لديه. وعندما يعبّر الطفل عن مشاعره وأفكاره، لا ينبغي الرد عليه بغضب؛ وإلا فقد يعود إلى العبوس عندما يعجز عن التعبير عن نفسه. اسمحي له بأن يشعر بمشاعره ويعبّر عنها. لكن الأطفال قد يتصرفون بهذه الطريقة أحيانًا لمجرد جذب الانتباه، وقد يفعلون ذلك من دون سبب واضح. وقد تعجبه أسئلة مثل "لماذا أنت منزعج؟ ماذا حدث؟"، وعندما يرى اهتمامكِ قد يحوّل هذا السلوك إلى عادة.') WHERE id = '64c55cb1-55ee-4499-904d-c4c1c752bd76';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحب الأطفال عادةً الأطعمة الملونة. لذلك، إذا كنتِ تجدين صعوبة في إقناع طفلكِ بتناول اللحوم، فيمكنكِ خلط كرات اللحم بالخضراوات وطهيها، أو تزيين طبقه بالفلفل الملون والجزر. تذكري أن الأطفال غالبًا ما يقتدون بالعادات الغذائية للأسرة. فعلى سبيل المثال، إذا أعددتِ له طبق الحمص باللحم على العشاء ثم قلتِ إنكِ لا تحبين هذا الطبق، فلن يأكله هو أيضًا. لذلك، احرصي على الجلوس إلى المائدة مع طفلكِ، ولا سيما إذا كان انتقائيًا في طعامه، وتناولي الطعام نفسه معه. قدّمي للجميع الطعام نفسه وشجعيه على تناوله. انتبهي إلى حجم الحصص، ولا تضعي في طبق طفلكِ كمية تفوق قدرته على تناولها.') WHERE id = '0821bceb-2f87-4c42-8bc9-c1a1e94cd15d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لعل مسابقات المعلومات التي نحبها جميعًا من أكثر الأنشطة المنزلية المفيدة للأطفال. لكن هناك نقطة مهمة ينبغي الانتباه إليها: لا تجعلي طفلكِ ينفر من اللعبة بسبب أسئلة شديدة الصعوبة. ضعي عمره ومستواه في الحسبان عند إعداد الأسئلة. قد تكون مسابقة المعلومات ممتعة لطفل في الرابعة من عمره، لكن يجب اختيار أسئلة ملائمة لهذا العمر. وفي الوقت نفسه، لا تقعي في خطأ طرح أسئلة مفرطة في السهولة، لأنه لن يشعر عندئذٍ بمتعة الوصول إلى الإجابة الصحيحة ولا بالتحدي. إن إعداد أسئلة يمكنه الإجابة عنها بعد التفكير لفترة قصيرة سيمنحه شعورًا بالنجاح. وبدلًا من الاكتفاء بأسئلة تختبر معلوماته، يمكنكِ أيضًا طرح أسئلة تساعده على تطوير مهاراته.') WHERE id = 'e164832a-dcb2-4221-994b-d1966e1702f1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لم تمنحي طفلكِ حرية اختيار ملابسه، فقد تظهر لديه مشكلات مثل ضعف الثقة بالنفس والخجل والانطواء والتردد وانتظار توجيهات الآخرين باستمرار. ينبغي إتاحة الفرصة للطفل لاختيار الملابس التي يريدها والاستمتاع بهذه الحرية. فبهذه الطريقة فقط يمكنه أن ينشأ مستقبلًا شخصًا واعيًا قادرًا على اتخاذ قراراته بنفسه ولا ينساق وراء تأثير المحيطين به. وحتى إن رأيتِ أن تنسيق الملابس الذي اختاره غير موفق، فلا تعبّري مطلقًا عن رأي سلبي. وإذا اختار الطفل ملابس غير ملائمة للمكان أو المناسبة، فقدّمي له بدائل واطلبي منه الاختيار من بينها. عندما يشعر طفلكِ بأنه يُمنح الفرصة، تزداد ثقته بنفسه وبوالديه. أما الأطفال الذين يُمنعون من كل خطوة ويتلقون تعليقات سلبية من والديهم، فقد لا يكتمل نموهم بصورة سليمة.') WHERE id = 'e0981ee6-c555-49e7-9bc4-ad0b8d24e258';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تأتي عيوب الإبصار مثل قِصر النظر وطول النظر، إضافةً إلى كسل العين والحَوَل، في مقدمة أمراض العيون الشائعة لدى الأطفال. ويسهم التشخيص المبكر في تسهيل العلاج بدرجة كبيرة. ينبغي للوالدين إخضاع طفلهما لفحص العين سنويًا بدءًا من عمر 1 سنة. فتمتّع طفلكِ بعينين أكثر صحة يعتمد على مدى اهتمامكِ. احرصي على أن يشاهد طفلكِ التلفاز من مسافة لا تقل عن 2-3 أمتار، وألّا يقضي وقتًا مفرطًا أمام الكمبيوتر والألعاب الإلكترونية. وتأكدي من أن تكون الغرفة مظلمة عند النوم. واحرصي على إخضاع طفلكِ لفحص العين خلال مرحلة ما قبل المدرسة.') WHERE id = '1c782aed-0528-4b86-ab5d-711c85f9c8ef';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحب بعض الأطفال كثيرًا المساعدة في الأعمال المنزلية، وعندما يحظون بالتقدير من والديهم تتحول هذه الأنشطة إلى متعة حقيقية بالنسبة إليهم. ويمكننا اعتبار نشر الملابس من أبسط الأعمال المنزلية وأكثرها فائدة للأطفال في عمر 4 سنوات. إذ يسهم هذا النشاط بصورة كبيرة في تنمية المهارات الحركية الكبرى لدى الطفل وتعزيز إحساسه بالمسؤولية. إذا كانت لديكِ مساحة كافية في المنزل، فيمكنكِ مدّ حبل بين كرسيين لتمنحي طفلكِ تجربة واقعية. وإذا لم يكن ذلك ممكنًا، فيمكنكِ أن تطلبي منه مناولتكِ مشابك الغسيل الملوّنة مع ذكر ألوانها أثناء نشركِ للملابس. ستساعده هذه الأعمال المنزلية البسيطة على الاستمتاع وقضاء وقته بصورة مفيدة في آنٍ واحد.') WHERE id = '2a191d55-3beb-4691-9233-97ec0fcde1ca';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نظرًا إلى استمرار عملية النمو لدى الأطفال، تكون حاجتهم إلى البروتين مرتفعة. وتؤدي البروتينات دورًا مهمًا في كثير من العمليات التي تحدث في الجسم أثناء النمو والتطور. وإذا لم يحصل الجسم على ما يكفي من البروتين، فلن تتمكن الخلايا من التجدد. وتختلف الحاجة إلى البروتين باختلاف الفئة العمرية. وينبغي أن تكون مصادر البروتين المتناولة من الأنواع التي يستطيع الجسم امتصاصها بسهولة. لذلك يجب أن يشتمل النظام الغذائي على البروتينات الحيوانية إلى جانب البروتينات النباتية. وقد يؤثر نقص البروتين سلبًا في زيادة طول الأطفال وتطورهم الذهني، كما قد يؤدي إلى مشكلات في النمو. وإضافةً إلى ذلك، وبالنظر إلى مشاركة البروتين في كثير من التفاعلات المهمة داخل الجسم، فقد يحدث خلل في هذه العمليات أيضًا.') WHERE id = '9cc989fa-9fcc-4747-9ab8-8d7ee4996fa1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مهما كان الأطفال اجتماعيين، فقد يشعرون أحيانًا بعدم الارتياح في الأماكن المزدحمة. وقد يبدو المكان المليء بالأطفال الذين يصرخون باستمرار أكثر إخافةً للطفل الخجول. لذلك، من الأفضل البدء بمجموعات صغيرة من الأصدقاء تتكون من 2-3 أطفال يشعر طفلكِ بالراحة معهم. وتُظهر الدراسات أن الأطفال الذين يجبرهم والداهم على الاختلاط بالآخرين يصبحون أكثر انطواءً. إذا كان طفلكِ لا يريد فعل شيء ما، فلا تجبريه عليه، بل تذكري أن وجودكِ إلى جانبه يساعده على الشعور بالأمان. ومن أهم الأسس التي تساعد الأطفال على النمو ليصبحوا أشخاصًا واثقين بأنفسهم، الرابطة المفعمة بالحب التي تجمعهم بوالديهم. إن معرفته بأنكِ إلى جانبه لمساعدته عند الحاجة ستجعله يشعر بمزيد من الراحة. لا تنسي أن تغمري طفلكِ بالعناق وأن تذكّريه دائمًا بأنكِ إلى جانبه.') WHERE id = '9e83e717-03f9-48ad-8599-e9b3f6b74810';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي أن تحتوي كتب مرحلة ما قبل المدرسة على الكثير من الصور والقليل من النصوص. ونظرًا إلى أن الأطفال في هذا العمر لا يعرفون القراءة والكتابة بعد، فمن المهم جدًا استخدام الصور بكثرة. وبذلك يستطيع طفلكِ تأليف قصته الخاصة من خلال النظر إلى الصور. وهكذا يمكنكِ التحدث مطولًا عن كل صفحة من صفحات الكتاب وتغذية خيال طفلكِ. وينبغي أن تصبح قراءة الكتب جزءًا من الروتين اليومي، وأن يعتاد طفلكِ عليها في أوقات محددة. كما أن وضع الكتب في مكان يستطيع طفلكِ الوصول إليه وإبقاؤها أمام ناظريه سيزيدان اهتمامه بها. تذكري أن الكتب من أهم الوسائل التي تثري عالم طفلكِ الخيالي.') WHERE id = '64e5e154-bafe-4ba9-8c71-d21bdc7456e5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'المرونة سمة جسدية فطرية لدى الأطفال، لكنها قد تتراجع مع مرور الوقت إذا لم تُمارس التمارين بانتظام. تساعد ممارسة الرياضة على زيادة خفة الحركة وتحسين نمو العضلات والمفاصل، ما يقي من المشكلات التي قد تظهر مستقبلًا. كما تساعد التمارين التي تعزز المرونة على الوقاية من أمراض القلب الناجمة عن نمط الحياة الخامل وقلة النشاط وسوء التغذية. وإذا أوليتِ هذا الأمر اهتمامًا منذ صغر طفلكِ، فيمكنكِ تحسين جودة حياته عندما يكبر بفضل احتفاظ جسمه بالمرونة. وإذا لم تُمارس التمارين في مرحلة الطفولة، فقد تُفقد هذه القدرة. لذلك، من المهم جدًا تشجيع طفلكِ على ممارسة الرياضة يوميًا.') WHERE id = '8daede29-43de-4cc2-b936-3eabf9151ee9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لدينا نشاط نقترحه عليكِ لقضاء وقت ممتع وقيّم مع طفلكِ! ستحتاجين إلى: قفاز شفاف، و5 كرات بوم بوم ملوّنة، وقلم. رقّمي أصابع القفاز بالترتيب من 1 إلى 5. ثم اطلبي من طفلكِ وضع الألوان التي اخترتِها وفقًا للأرقام (مثلًا: كرة بوم بوم صفراء في الإصبع الأول، وزرقاء في الإصبع الثاني، وهكذا). واطلبي منه أيضًا نطق أسماء الألوان بصوت عالٍ. يعزز هذا النشاط مهارات العدّ والتعرّف إلى الألوان لدى طفلكِ، كما ينمّي مهاراته اليدوية. ابقي إلى جانبه طوال النشاط، وفي نهايته شجّعيه وأكّدي له مدى نجاحه.') WHERE id = '7968b317-d8e5-40c3-af2c-ca78747307c5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين أن طفلكِ يكتسب سمات مختلفة، لا سيما خلال مراحله العمرية المختلفة. ومع كل مرحلة من مراحل النمو، تذكّري أن هناك الكثير من المفاهيم الجديدة التي ينبغي له استيعابها. وإلى جانب اكتساب مهارات جديدة، قد تواجهين متطلبات مختلفة تتعلق بأمور أساسية مثل نظام النوم والتغذية. "لا أريد النوم مبكرًا اليوم!"، "لا أريد تناول البيض اليوم!" – يبدو هذا مألوفًا، أليس كذلك؟ :) في مثل هذه المواقف، أفضل ما يمكنكِ فعله هو عدم القلق والحفاظ على هدوئكِ. إليكِ بعض النصائح… يمكنكِ اقتراح أن تقرآ قصة معًا لتشجيع طفلكِ الذي لا يريد النوم على الذهاب إلى فراشه. وعند نهاية القصة، ستبدأ عيناه بالانغلاق من تلقاء نفسيهما. ولإدراج الأطعمة الصحية في قائمة طعامه، يمكنكِ أن توضحي له بحركاتكِ مع كل لقمة مقدار القوة التي سيكتسبها عند تناولها. فقد تكون الوجبة الممتعة أكثر إقناعًا للطفل. :)') WHERE id = 'c24494e2-2c33-41c4-ac7a-276ef9b4a65c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُتوقع أن يبدأ الأطفال بعد سن 4 سنوات بإمساك القلم بثلاثة أصابع. وبالطبع، قد لا يكون الوقت قد حان بعد، أو قد لا يشعر الطفل بأنه مستعد لذلك. فما زالت أمامه سنوات طوييييلة سيمسك فيها القلم. :) لذلك، لا تقلقي إذا لم يبدأ طفلكِ بعد بإمساك القلم بثلاثة أصابع. فهناك الكثير مما يمكنكِ فعله لتقوية عضلاته! يمكنكِ رسم خطوط متقطعة على ورقة فارغة، ثم تطلبين منه وصل هذه الخطوط. من المفيد البدء بخطوط بسيطة رأسية أو أفقية، وتهنئته كلما نجح، فهذا سيحفّزه على الانتقال إلى المراحل التالية. بعد ذلك، ارسمي أشكالًا مثل الدائرة والمثلث والمربع بخطوط متقطعة، واطلبي منه وصلها. هذه طريقة فعّالة للغاية؛ فبعد فترة، ومع التوجيه الصحيح، ستلاحظين أن طفلكِ بدأ يمسك القلم بسهولة.') WHERE id = 'ab3ed8b9-4614-4f45-be6c-955b461e9cf3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'طفلكِ الذي أوشك على إتمام عامه الرابع يزداد حماسًا لاكتشاف نفسه يومًا بعد يوم! ويمكنكِ دعمه بتحويل بعض التمارين البسيطة إلى لعبة. لنعد قليلًا إلى الماضي ونعرّف طفلكِ إلى لعبة "الحجلة" التي ستعيد إليكِ ذكريات الطفولة الجميلة. يمكنكما لعبها داخل المنزل برسم مربعاتها على غطاء قديم، أو في الخارج برسمها على الأرض في مكان آمن إذا كان الطقس مناسبًا. تساعد حركات مثل الوقوف على قدم واحدة والقفز بقدم واحدة أو بكلتا القدمين على دعم نمو المهارات الحركية الكبرى لدى طفلكِ. وبالطبع، سيكون عليكِ تعليمه كيفية اللعب أولًا. :) تحلّي بالصبر، وحوّلي هذا الوقت الممتع والقيّم الذي تقضيانه معًا إلى مرح من دون التقيّد الشديد بالقواعد!') WHERE id = 'da851837-93b4-4189-a1f5-c7b4993f4df9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ها قد حلّ اليوم الكبير! طفلكِ يتم عامه الرابع! 😊 لقد أكمل طفلكِ الآن أربع سنوات من عمره. وسيكون هذا يومًا مبهجًا يقضيه مع أصدقائه وذكرى لا تُنسى. يمكنكِ تقديم هدية رائعة له من خلال تنظيم احتفال بعيد ميلاده يتيح له اللعب مع أقرانه والركض والمرح، بل والمشاركة في أنشطة متنوعة، بدءًا من الكاريوكي وصولًا إلى ورش العمل الإبداعية المختلفة. وإذا كان الطقس جميلًا، فسيترك الاحتفال في الهواء الطلق انطباعًا رائعًا لدى الجميع، وخصوصًا طفلكِ! كما أن التقاط الكثير من الصور في هذا اليوم الرائع سيصنع ذكريات جميلة للمستقبل. والأهم من كل شيء هو الجهد الذي بذلتِه حتى بلغ طفلكِ هذا العمر… أنتِ تحديدًا تستحقين أكبر تصفيق! لا تنسي أبدًا أنكِ أم رائعة! <3') WHERE id = 'e9115fcf-1d07-412a-b5e2-14fb5de565de';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي إعطاء لقاحات سن الرابعة وإجراء الفحوصات الطبية العامة. ويجب استكمال اللقاح المركب (الدفتيريا والكزاز والسعال الديكي وشلل الأطفال)، ولقاحات الحصبة والحصبة الألمانية والنكاف بين سن 4-6 سنوات. كما ينبغي إعطاء الجرعة الثانية من لقاح جدري الماء، الذي تُعطى جرعته الأولى بعد عمر سنة، بعد التشاور مع الأسرة. وبفضل استخدام التقنيات المتطورة في تصنيع اللقاحات، أصبحت الآثار الجانبية أقل بكثير مقارنة بالسنوات السابقة. وقد تشمل الآثار الجانبية العامة التي يمكن أن تظهر بعد التطعيم الحمى والانزعاج والاحمرار أو التصلب في موضع الحقن والطفح الجلدي. قد يبدو أن تطعيمات الطفولة تنتهي في سن 4-6 سنوات، لكن هذه العملية تستمر من خلال اللقاحات المخصصة لسن المدرسة والبالغين. ومن أجل صحتنا، علينا الحفاظ على هذا الاهتمام طوال حياتنا ومتابعة المستجدات والتطورات.') WHERE id = '14296ec3-0bb3-4c1d-b05b-6b38f4e1856a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من أكثر الأمور التي تُحزن الأمهات وتُقلقهن في هذه المرحلة العمرية ضعف شهية الأطفال ورفضهم تناول الطعام. فالطفل الذي يُعتقد أنه ضعيف الشهية قد لا يأكل في الواقع بسبب عدم انتظام نظامه الغذائي. ومن أبرز العوامل التي تؤثر في شهية الأطفال تناولهم أطعمة متنوعة غير صحية، كالوجبات الخفيفة والحلوى، بين الوجبات الرئيسية حتى يشعروا بالشبع. ونتيجة لذلك، سيرفض الطفل الشبعان الوجبات الرئيسية. كما أن إعطاءه قطعة شوكولاتة أو شريحة من الكعك قبل الوجبة الرئيسية لتهدئته سيُفقده شهيته ويدفعه إلى رفض الطعام الموجود على المائدة. يمكنكِ تقديم وجبات خفيفة صغيرة أو فواكه لطفلكِ بما يلبي احتياجاته بين الإفطار والغداء أو بين الغداء والعشاء. لكن ينبغي ألا تكون كمية هذه الوجبات الخفيفة كبيرة إلى حد إفقاده الشهية، وألا تُقدَّم في وقت قريب جدًا من موعد الوجبة الرئيسية.') WHERE id = 'ae163783-e98e-4f90-a211-90fa0def0173';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ معتادًا على العبوس وإظهار الاستياء، فحاولي في تلك اللحظات توجيه انتباهه إلى شيء آخر. وقد يصاحب ذلك البكاء ونوبات الغضب. وفي مثل هذه الحالات، يجب ألا تستجيبي أبدًا لما يريده الطفل. فإذا استطاع تحقيق رغباته بهذه الطريقة، فسيحوّلها إلى عادة دائمة، وستواجهين مواقف أصعب في المستقبل. وقد يبالغ في رد فعله إذا لم تتحقق حتى أبسط رغباته، فيبكي لساعات أو يؤذي نفسه. إذا تحليتِ بالصبر والثبات لبعض الوقت ولم تستجيبي لرغبته، فسيفهم الطفل أن هذا السلوك غير صحيح. ومن المهم جدًا أيضًا ألا يتدخل أفراد الأسرة الأكبر سنًا في هذه العملية.') WHERE id = '2d13d9c9-bb17-4082-9f50-12d59ae41bd4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ابتداءً من سن 4 سنوات، يدخل الأطفال مرحلة قد يتصرفون فيها بفظاظة مع الكبار وأقرانهم عند معارضة رغباتهم، ويجدون صعوبة في الالتزام بالقواعد. وينبع هذا التغير الكبير في السلوك خلال فترة قصيرة من ازدياد تواصل الطفل مع العالم الخارجي وسعيه إلى الاستقلال وتكوين شخصيته الفردية. يحتاج طفلكِ إلى حياة منتظمة، ويبدأ بالتعرف إلى القواعد في المنزل؛ لكن تذكري أنه قد يُبدي رد فعل سلبيًا تجاه القواعد إذا فُرضت عليه فجأة. لذلك، ينبغي تحديد قواعد المنزل مسبقًا. لا تنتظري أن يتصرف الطفل بشكل خاطئ حتى تضعي القواعد. والشرط الأساسي هو أن يتفق الوالدان على هذه القواعد ويلتزما بتطبيقها بثبات. وقد يحاول طفلكِ اختبار موقف والديه وخرق القواعد. وفي هذه الحالة، من المهم جدًا ألا تتنازلي وأن تحافظي على موقفكِ.') WHERE id = 'b1d3577e-af5f-48bb-808f-1582a526b07c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يشعر طفلكِ بالغضب أو الحزن عندما لا يرغب في مشاركة شيء يخصه في المنزل مع شخص آخر. في هذه الحالة، سيساعده تفهّم مشاعره والتحدث معه على الشعور بالراحة. فالطفل الذي يشعر بأنه مفهوم سيتخلى عن عناده ويعبّر عن مشاعره بسهولة أكبر. وعند الذهاب في زيارة، من المفيد أن تأخذي معكِ بعض ألعابه المفضلة لتجنب الأزمات التي قد تنشأ بسبب المشاركة. أما قبل استقبال الضيوف في منزلكِ، فيمكنكما جمع ألعابه المفضلة جدًا ووضعها بعيدًا معًا. لا تضغطي عليه للمشاركة، بل اسأليه عن رأيه مسبقًا. وإذا تشاجر الأطفال أثناء اللعب، فحاولي ألا تتدخلي ما لم يتفاقم الموقف كثيرًا.') WHERE id = '44edf3db-c049-4ceb-9fd5-20d650c22cef';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد مرحلة 4-5 سنوات، وهي مرحلة ما قبل المدرسة، فترة مهمة تُرسَّخ فيها أسس عادات التغذية السليمة لدى الأطفال. كما تؤثر العادات المكتسبة في هذه الفترة مباشرةً في حالتهم الصحية مستقبلًا. وينبغي للوالدين وكبار الأسرة أن يكونوا قدوة في هذا الشأن. يجب أن يتضمن النظام الغذائي اليومي للطفل منتجات الألبان واللحوم والخضراوات والفواكه والدهون والحبوب. وينبغي الاهتمام خصوصًا بترسيخ عادة تناول الإفطار. ويمكن أن تشمل قائمة الإفطار الجبن وخبز الحبوب الكاملة والزيتون ودبس الفاكهة أو العسل والحليب والبيض 2-3 مرات أسبوعيًا، إضافةً إلى الفواكه الطازجة أو كعك الفواكه المجففة المُحضَّر منزليًا. ولأن الأطفال في هذا العمر كثيرو النشاط، فهم يحتاجون إلى أطعمة مغذية يحبون تناولها أيضًا.') WHERE id = 'c755e705-bd03-47e3-bce9-e59e4c48f874';

